INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('vasic-digital/SuperAgent/ssh', 'community', 'vasic-digital', 'SuperAgent', 'vasic-digital/SuperAgent', 'ssh', 0, 0, 33, '2026-03-08T01:57:15.273Z', '2026-03-08T02:00:28.797Z', '02b94d8014244412cbac9ee93c1860ecd87ffdce8df95f4acb823c9075ca7366', '{"id":"vasic-digital/SuperAgent/ssh","name":"ssh","description":{"en":"The SSH skill enables developers to establish and manage secure SSH connections to remote machines, execute commands, and transfer files. It benefits developers and system administrators.","zh":"SSH 技术提供了建立和管理远程机器连接的功能，支持密码和密钥认证","ja":"SSH 技術は、リモート マシンへの接続を確立して管理する機能を提供し、パスワードと鍵認証をサポートします","ko":"SSH 기술은 원격 머신에 대한 연결을 설정하고 관리하는 기능을 제공하며 비밀번호 및 키 인증을 지원합니다","es":"El agente de AI para SSH ofrece capacidades para establecer y gestionar conexiones SSH a máquinas remotas de manera segura.","fr":"L''outil d''AI pour SSH propose des capacités pour établir et gérer des connexions SSH à des machines distantes de manière sécurisée","de":"Das AI-Tool für SSH bietet Funktionen zur sicheren Einrichtung und Verwaltung von SSH-Verbindungen zu Remote-Maschinen","pt":"O SSH é uma habilidade que fornece capacidades para estabelecer e gerenciar conexões SSH para máquinas remotas, com autenticação por senha ou chave.","ru":"ИИ Агенты для SSH предоставляют возможности для установления и управления соединениями SSH с удаленными машинами, используя аутентификацию по паролю или ключу.","ar":"المهارة SSH توفر إمكانيات لتأسيس وإدارة الاتصالات SSH مع الأجهزة البعيدة، باستخدام كلمات المرور أو المفاتيح."},"seo":{"title":{"en":"SSH Skill: Secure Remote Access Setup Guide | AI Agent","zh":"SSH setup guide: 使用密码或密钥认证","ja":"SSH セットアップ ガイド: パスワードまたは鍵認証","ko":"SSH 설정 가이드: 비밀번호 또는 키 인증","es":"Guía de configuración de SSH: Autenticación y gestión de ...","fr":"Guide de configuration SSH : Authentification et gestion ...","de":"SSH-Setup-Leitfaden: Authentifizierung und Verbindungsnut...","pt":"Guia de Configuração SSH: Autenticação e Gerenciamento","ru":"ИИ Агенты для Настройки SSH: Лучшие Практики","ar":"دليل إعداد SSH: تسجيل الدخول وأمان المفاتيح"},"description":{"en":"Unlock secure remote access with SSH skill. Learn how to establish connections, manage key pairs, and execute commands with ease. Get started now!","zh":"了解如何使用 SSH 技术建立和管理远程机器连接，实现安全的命令执行和文件传输","ja":"SSH 技術を使用してリモート マシンへの接続を確立して管理し、安全なコマンド実行とファイル転送を実現する方法について学びます","ko":"SSH 기술을 사용하여 원격 머신에 대한 연결을 설정하고 관리하여 보안 명령 실행 및 파일 전송을 구현하는 방법에 대해 알아보세요","es":"Aprende a configurar y gestionar conexiones SSH de manera segura con nuestro agente de AI, incluyendo autenticación por contraseña y clave","fr":"Découvrez comment configurer et gérer des connexions SSH de manière sécurisée avec notre outil d''AI, y compris l''authentification par mot de passe et par clé","de":"Erfahren Sie, wie Sie SSH-Verbindungen sicher mit unserem AI-Tool konfigurieren und verwalten, einschließlich Passwort- und Schlüsselauthentifizierung","pt":"Aprenda a configurar e gerenciar conexões SSH com autenticação por senha ou chave, transfira arquivos e execute comandos remotos","ru":"Настройте и управляйте соединениями SSH с помощью ИИ Агентов, используя аутентификацию по паролю или ключу","ar":"تعلم كيفية ضبط وتشغيل اتصالات SSH بأمان باستخدام كلمات المرور أو المفاتيح، ونقل الملفات وتشغيل الأوامر عن بعد"},"definition":{"en":"ssh is a secure protocol for remote access, allowing users to establish connections, manage key pairs, and execute commands on remote machines.","zh":"SSH 是一种安全的远程连接协议，用于建立和管理远程机器连接","ja":"SSH は、リモート マシンへの接続を確立して管理するための安全なプロトコルです","ko":"SSH는 원격 머신에 대한 연결을 설정하고 관리하기 위한 보안 프로토콜입니다","es":"SSH es un protocolo de comunicación seguro para acceder y gestionar máquinas remotas","fr":"SSH est un protocole de communication sécurisé pour accéder et gérer des machines distantes","de":"SSH ist ein sicheres Kommunikationsprotokoll zur Fernwartung und -verwaltung von Computern","pt":"SSH é um protocolo de rede que permite acessar e gerenciar máquinas remotas de forma segura","ru":"SSH - это сетевой протокол, который позволяет безопасно доступ и управлять удаленными машинами","ar":"SSH هو بروتوكول شبكة يسمح بالوصول والتحكم في الأجهزة البعيدة بأمان"},"features":{"en":["Establish SSH connections using password or key-based authentication","Generate and manage SSH key pairs","Configure SSH for easier connections","Execute commands on remote machines using bash","Transfer files between local and remote machines"],"zh":["支持密码和密钥认证","生成和管理 SSH 密钥对","配置 SSH 以便于连接","在远程机器上执行命令","在本地和远程机器之间传输文件","管理 SSH 配置和已知主机"],"ja":["パスワードと鍵認証をサポート","SSH 鍵のペアを生成して管理","SSH を簡単に接続できるように構成","リモート マシンでコマンドを実行","ローカルとリモート マシン間でファイルを転送","SSH 構成と既知のホストを管理"],"ko":["비밀번호 및 키 인증 지원","SSH 키 페어 생성 및 관리","SSH를 쉽게 연결할 수 있도록 구성","원격 머신에서 명령어 실행","로컬 및 원격 머신 간 파일 전송","SSH 구성 및 알려진 호스트 관리"],"es":["Autenticación por contraseña y clave","Generación y gestión de pares de claves SSH","Ejecución de comandos en máquinas remotas","Transferencia de archivos entre máquinas locales y remotas","Gestión de configuraciones SSH y hosts conocidos"],"fr":["Authentification par mot de passe et par clé","Génération et gestion de paires de clés SSH","Exécution de commandes sur des machines distantes","Transfert de fichiers entre machines locales et distantes","Gestion des configurations SSH et des hôtes connus"],"de":["Passwort- und Schlüsselauthentifizierung","Generierung und Verwaltung von SSH-Schlüsselpaaren","Ausführung von Befehlen auf Remote-Maschinen","Dateitransfer zwischen lokalen und Remote-Maschinen","Verwaltung von SSH-Konfigurationen und bekannten Hosts"],"pt":["Estabelecer conexões SSH com autenticação por senha ou chave","Gerar e gerenciar pares de chaves SSH","Configurar SSH para conexões mais fáceis","Executar comandos em máquinas remotas","Transferir arquivos entre máquinas locais e remotas","Gerenciar configurações SSH e hosts conhecidos"],"ru":["Установить соединения SSH с аутентификацией по паролю или ключу","Генерировать и управлять парами ключей SSH","Настроить SSH для более простых соединений","Выполнить команды на удаленных машинах","Передать файлы между локальными и удаленными машинами","Управлять конфигурациями SSH и известными хостами"],"ar":["إنشاء اتصالات SSH باستخدام كلمات المرور أو المفاتيح","توليد وإدارة أزواج مفاتيح SSH","ضبط SSH من أجل اتصالات أكثر سهولة","تشغيل أوامر على الأجهزة البعيدة","نقل الملفات بين الأجهزة المحلية والبعيدة","إدارة إعدادات SSH والمضيفين المعروفين"]},"keywords":{"en":["how to use ssh","ssh vs telnet","ssh install guide","ssh key pair management","what is ssh protocol","ssh alternative tools","ssh setup for remote access","ssh command line tutorial"],"zh":["SSH 技术","远程连接","密码认证","密钥认证","SSH 密钥对","SSH 配置","远程命令执行","文件传输","SSH 设置"],"ja":["SSH 技術","リモート接続","パスワード認証","鍵認証","SSH 鍵のペア","SSH 構成","リモート コマンド実行","ファイル転送","SSH セットアップ"],"ko":["SSH 기술","원격 연결","비밀번호 인증","키 인증","SSH 키 페어","SSH 구성","원격 명령어 실행","파일 전송","SSH 설정"],"es":["ssh agente de ai","configuración ssh","autenticación ssh","gestión de conexiones ssh","herramientas de ai para ssh","seguridad ssh","conexiones ssh seguras","ai para administración de servidores"],"fr":["agent ai ssh","configuration ssh","authentification ssh","gestion de connexions ssh","outils d''ai pour ssh","sécurité ssh","connexions ssh sécurisées","ai pour administration de serveurs"],"de":["ssh ai tool","ssh konfiguration","ssh authentifizierung","ssh verbindungsnutzung","ai tools für ssh","ssh sicherheit","sichere ssh verbindungen","ai für serververwaltung"],"pt":["ssh","autenticação ssh","gerenciamento ssh","conexões ssh","transferência de arquivos ssh","execução de comandos ssh","segurança ssh","configuração ssh"],"ru":["ssh","аутентификация ssh","управление ssh","соединения ssh","передача файлов ssh","выполнение команд ssh","безопасность ssh","настройка ssh","ИИ Агенты для ssh"],"ar":["ssh","تسجيل الدخول ssh","إدارة ssh","اتصالات ssh","نقل الملفات ssh","تشغيل الأوامر ssh","أمان ssh","ضبط ssh","أدوات الذكاء الاصطناعي ل ssh"]}},"owner":"vasic-digital","repo":"SuperAgent","repoPath":"vasic-digital/SuperAgent","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.273Z","topics":[],"category":"community","skillMd":{"name":"ssh","description":"Establish and manage SSH connections to remote machines, including key generation, configuration, and file transfers. Use when connecting to remote servers, executing remote commands, or transferring files via SCP.","bodyPreview":"# SSH Skill\n\nThis skill provides capabilities for establishing and managing SSH connections to remote machines.\n\n## Capabilities\n\n- Establish SSH connections using password or key-based authentication\n- Generate and manage SSH key pairs\n- Configure SSH for easier connections\n- Execute commands on remote machines\n- Transfer files between local and remote machines\n- Manage SSH configurations and known hosts\n\n## Authentication Methods\n\n### Password Authentication\n\n```bash\nssh username@hostname\n```","body":"# SSH Skill\n\nThis skill provides capabilities for establishing and managing SSH connections to remote machines.\n\n## Capabilities\n\n- Establish SSH connections using password or key-based authentication\n- Generate and manage SSH key pairs\n- Configure SSH for easier connections\n- Execute commands on remote machines\n- Transfer files between local and remote machines\n- Manage SSH configurations and known hosts\n\n## Authentication Methods\n\n### Password Authentication\n\n```bash\nssh username@hostname\n```\n\nWhen prompted, you should ask the user for their password or a private key.\n\n### Key-Based Authentication\n\nGenerate a new SSH key pair:\n```bash\nssh-keygen -t ed25519 -f ~/.ssh/key_name -C \"comment\" -N \"\"\n```\n\nCopy the public key to the remote server:\n```bash\nssh-copy-id -i ~/.ssh/key_name.pub username@hostname\n```\n\nConnect using the private key:\n```bash\nssh -i ~/.ssh/key_name username@hostname\n```\n\n## SSH Configuration\n\nCreate or edit the SSH config file for easier connections:\n```bash\nmkdir -p ~/.ssh\ncat > ~/.ssh/config << ''EOF''\nHost alias\n    HostName hostname_or_ip\n    User username\n    IdentityFile ~/.ssh/key_name\n    Port 22\n    ServerAliveInterval 60\nEOF\nchmod 600 ~/.ssh/config\n```\n\nThen connect using the alias:\n```bash\nssh alias\n```\n\n## Common SSH Options\n\n- `-p PORT`: Connect to a specific port\n- `-X`: Enable X11 forwarding\n- `-L local_port:remote_host:remote_port`: Set up local port forwarding\n- `-R remote_port:local_host:local_port`: Set up remote port forwarding\n- `-N`: Do not execute a remote command (useful for port forwarding)\n- `-f`: Run in background\n- `-v`: Verbose mode (add more v''s for increased verbosity)\n\n## File Transfer with SCP\n\nCopy a file to the remote server:\n```bash\nscp /path/to/local/file username@hostname:/path/to/remote/directory/\n```\n\nCopy a file from the remote server:\n```bash\nscp username@hostname:/path/to/remote/file /path/to/local/directory/\n```\n\nCopy a directory recursively:\n```bash\nscp -r /path/to/local/directory username@hostname:/path/to/remote/directory/\n```\n\n## SSH Agent\n\nStart the SSH agent:\n```bash\neval \"$(ssh-agent -s)\"\n```\n\nAdd a key to the agent:\n```bash\nssh-add ~/.ssh/key_name\n```\n\n## Troubleshooting\n\n- Check SSH service status on remote: `systemctl status sshd`\n- Verify SSH port is open: `nc -zv hostname 22`\n- Debug connection issues: `ssh -vvv username@hostname`\n- Check permissions: SSH private keys should have 600 permissions (`chmod 600 ~/.ssh/key_name`)\n- Verify known_hosts: If host key changed, remove the old entry with `ssh-keygen -R hostname`\n\n## Secure SSH Key Management\n\n### Local Storage with Proper Permissions\n\nThe most basic approach is to ensure proper file permissions:\n\n```bash\n# Set correct permissions for private keys\nchmod 600 ~/.ssh/id_ed25519\n# Set correct permissions for public keys\nchmod 644 ~/.ssh/id_ed25519.pub\n# Set correct permissions for SSH directory\nchmod 700 ~/.ssh\n```"},"lastSynced":"2026-03-08T02:00:28.797Z","agentAnalysis":{"suitability":{"en":"Ideal for System Administration Agents requiring secure remote access and file transfer capabilities via SSH protocol.","zh":"适用于需要通过SSH协议实现安全远程访问和文件传输功能的系统管理代理。","ja":"SSHプロトコルを介した安全なリモートアクセスおよびファイル転送機能を必要とするシステム管理エージェントに適しています。","ko":"SSH 프로토콜을 통해 안전한 원격 액세스 및 파일 전송 기능을 필요로 하는 시스템 관리 에이전트에 적합합니다.","es":"Ideal para Agentes de Administración de Sistema que requieren acceso remoto seguro y capacidades de transferencia de archivos a través del protocolo SSH.","fr":"Idéal pour les Agents d''Administration Système nécessitant un accès à distance sécurisé et des capacités de transfert de fichiers via le protocole SSH.","de":"Ideal für Systemadministration-Agenten, die sicheren Remote-Zugriff und Dateitransfer-Funktionen über das SSH-Protokoll erfordern.","pt":"Ideal para Agentes de Administração de Sistema que exigem acesso remoto seguro e capacidades de transferência de arquivos via protocolo SSH.","ru":"Идеально для агентов системного администрирования, требующих безопасного удаленного доступа и возможностей передачи файлов через протокол SSH.","ar":"مثالي لعمليات وكيل إدارة النظام التي تتطلب وصولًا عن بُعد آمنًا وقدرات نقل الملفات عبر بروتوكول SSH."},"recommendation":{"en":"Empowers agents to establish and manage secure SSH connections using password or key-based authentication, execute commands on remote machines, and transfer files between local and remote machines using protocols like SFTP.","zh":"赋予代理建立和管理安全的SSH连接的能力，使用基于密码或密钥的身份验证，执行远程机器上的命令，并使用SFTP等协议在本地和远程机器之间传输文件。","ja":"エージェントがパスワードまたはキーベースの認証を使用して安全なSSH接続を確立して管理し、リモートマシン上でコマンドを実行し、SFTPなどのプロトコルを使用してローカルおよびリモートマシン間でファイルを転送する機能を提供します。","ko":"에이전트가 비밀번호 또는 키 기반 인증을 사용하여 안전한 SSH 연결을 설정하고 관리하며, 원격 머신에서 명령을 실행하고 SFTP와 같은 프로토콜을 사용하여 로컬 및 원격 머신 간에 파일을 전송할 수 있는 기능을 제공합니다.","es":"Permite a los agentes establecer y gestionar conexiones SSH seguras utilizando autenticación basada en contraseña o clave, ejecutar comandos en máquinas remotas y transferir archivos entre máquinas locales y remotas utilizando protocolos como SFTP.","fr":"Permet aux agents d''établir et de gérer des connexions SSH sécurisées à l''aide d''une authentification basée sur le mot de passe ou la clé, d''exécuter des commandes sur des machines distantes et de transférer des fichiers entre des machines locales et distantes à l''aide de protocoles tels que SFTP.","de":"Ermöglicht es den Agenten, sichere SSH-Verbindungen mithilfe von passwort- oder schlüsselbasierter Authentifizierung herzustellen und zu verwalten, Befehle auf Remote-Maschinen auszuführen und Dateien zwischen lokalen und Remote-Maschinen mithilfe von Protokollen wie SFTP zu übertragen.","pt":"Permite que os agentes estabeleçam e gerenciem conexões SSH seguras usando autenticação baseada em senha ou chave, executem comandos em máquinas remotas e transfiram arquivos entre máquinas locais e remotas usando protocolos como SFTP.","ru":"Позволяет агентам устанавливать и управлять безопасными соединениями SSH с использованием парольной или ключевой аутентификации, выполнять команды на удаленных машинах и передавать файлы между локальными и удаленными машинами с использованием протоколов типа SFTP.","ar":"يمكن للوكلاء من خلاله إنشاء وتشغيل الاتصالات SSH الآمنة باستخدام مصادقة كلمة المرور أو المفتاح ، وتنفيذ الأوامر على أجهزة عن بعد ونقل الملفات بين الأجهزة المحلية والبعيدة باستخدام بروتوكول مثل SFTP."},"useCases":{"en":["Establishing secure connections to remote servers","Executing remote commands for automated tasks","Transferring files securely between machines"],"zh":["建立远程服务器的安全连接","执行远程命令以实现自动化任务","在机器之间安全地传输文件"],"ja":["リモートサーバーへの安全な接続の確立","リモートコマンドの実行による自動化タスク","マシン間のファイルの安全な転送"],"ko":["원격 서버에 대한 안전한 연결 설정","원격 명령의 실행을 통한 자동화된 작업","머신 간의 파일을 안전하게 전송"],"es":["Establecer conexiones seguras a servidores remotos","Ejecutar comandos remotos para tareas automatizadas","Transferir archivos de forma segura entre máquinas"],"fr":["Établir des connexions sécurisées à des serveurs distants","Exécuter des commandes distantes pour des tâches automatisées","Transférer des fichiers de manière sécurisée entre les machines"],"de":["Sichere Verbindungen zu Remote-Servern herstellen","Remote-Befehle für automatisierte Aufgaben ausführen","Dateien sicher zwischen Maschinen übertragen"],"pt":["Estabelecendo conexões seguras com servidores remotos","Executando comandos remotos para tarefas automatizadas","Transferring arquivos de forma segura entre máquinas"],"ru":["Установка безопасных соединений с удаленными серверами","Выполнение удаленных команд для автоматизированных задач","Передача файлов безопасно между машинами"],"ar":["إنشاء اتصالات آمنة مع الخواديم عن بُعد","تشغيل أوامر عن بُعد للأعمال المُتكَرَرة","نقل الملفات بشكل آمن بين الأجهزة"]},"limitations":{"en":["Requires SSH server setup and configuration","Dependent on network connectivity and firewall settings"],"zh":["需要SSH服务器设置和配置","依赖于网络连接和防火墙设置"],"ja":["SSHサーバーの設定と構成が必要","ネットワーク接続とファイアウォール設定に依存"],"ko":["SSH 서버 설정 및 구성이 필요","네트워크 연결 및 방화벽 설정에 의존"],"es":["Requiere configuración y setup del servidor SSH","Dependiente de la conectividad de red y la configuración del firewall"],"fr":["Nécessite la configuration et la mise en place du serveur SSH","Dépendante de la connectivité réseau et des paramètres du pare-feu"],"de":["Benötigt die Konfiguration und Einrichtung des SSH-Servers","Abhängig von der Netzwerkverbindung und der Firewall-Konfiguration"],"pt":["Requer configuração e instalação do servidor SSH","Dependente da conectividade de rede e configurações de firewall"],"ru":["Требует настройки и установки сервера SSH","Зависит от настройки сети и параметров брандмауэра"],"ar":["يتطلب إعداد وتثبيت خادم SSH","يعتمد على اتصال الشبكة وإعدادات جدار الحماية"]},"version":4},"contentHash":"02b94d8014244412cbac9ee93c1860ecd87ffdce8df95f4acb823c9075ca7366","qualityScore":33}');
