INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('vasic-digital/SuperAgent/ssh', 'ssh', 'vasic-digital', 'SuperAgent', 'community', 'ssh vasic-digital SuperAgent community The SSH skill enables developers to establish and manage secure SSH connections to remote machines, execute commands, and transfer files. It benefits developers and system administrators. SSH 技术提供了建立和管理远程机器连接的功能，支持密码和密钥认证 SSH 技術は、リモート マシンへの接続を確立して管理する機能を提供し、パスワードと鍵認証をサポートします SSH 기술은 원격 머신에 대한 연결을 설정하고 관리하는 기능을 제공하며 비밀번호 및 키 인증을 지원합니다 El agente de AI para SSH ofrece capacidades para establecer y gestionar conexiones SSH a máquinas remotas de manera segura. L''outil d''AI pour SSH propose des capacités pour établir et gérer des connexions SSH à des machines distantes de manière sécurisée Das AI-Tool für SSH bietet Funktionen zur sicheren Einrichtung und Verwaltung von SSH-Verbindungen zu Remote-Maschinen O SSH é uma habilidade que fornece capacidades para estabelecer e gerenciar conexões SSH para máquinas remotas, com autenticação por senha ou chave. ИИ Агенты для SSH предоставляют возможности для установления и управления соединениями SSH с удаленными машинами, используя аутентификацию по паролю или ключу. المهارة SSH توفر إمكانيات لتأسيس وإدارة الاتصالات SSH مع الأجهزة البعيدة، باستخدام كلمات المرور أو المفاتيح. how to use ssh ssh vs telnet ssh install guide ssh key pair management what is ssh protocol ssh alternative tools ssh setup for remote access ssh command line tutorial SSH 技术 远程连接 密码认证 密钥认证 SSH 密钥对 SSH 配置 远程命令执行 文件传输 SSH 设置 Establish SSH connections using password or key-based authentication Generate and manage SSH key pairs Configure SSH for easier connections Execute commands on remote machines using bash Transfer files between local and remote machines ssh is a secure protocol for remote access, allowing users to establish connections, manage key pairs, and execute commands on remote machines.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('antvis/GPT-Vis/chart-visualization', 'community', 'antvis', 'GPT-Vis', 'antvis/GPT-Vis', 'chart-visualization', 0, 0, 33, '2026-03-08T01:57:15.274Z', '2026-03-08T02:00:33.620Z', '2c81f8688cdc6c75d4d3a61056de7285d85c43b0d0a157e7b6b40c6bda8b3904', '{"id":"antvis/GPT-Vis/chart-visualization","name":"chart-visualization","description":{"en":"The chart-visualization skill assists AI agents in recommending and generating data visualizations based on user intent and data characteristics, benefiting developers and data analysts.","zh":"图表可视化技能提供数据可视化推荐和生成，包括时间序列、分类比较、比例分析和分布分析","ja":"チャート可視化スキルは、データ可視化の추천と生成を提供し、時間系列、カテゴリ比較、比率分析、分布分析を含む","ko":"차트 시각화 스킬은 데이터 시각화를 추천하고 생성하며, 시간 순차, 범주 비교, 비율 분석, 분포 분석 등을 포함","es":"La visualización de gráficos es una habilidad que ayuda a los asistentes de IA a recomendar y generar visualizaciones de datos adecuadas. Se utiliza AntV para la visualización","fr":"La visualisation de graphiques est une compétence qui aide les outils d''IA à recommander et à générer des visualisations de données appropriées. AntV est utilisé pour la visualisation","de":"Die Chart-Visualisierung ist eine Fähigkeit, die KI-Tools hilft, geeignete Datenvisualisierungen zu empfehlen und zu generieren. AntV wird für die Visualisierung verwendet","pt":"A habilidade de visualização de gráficos ajuda assistentes de IA a recomendar e gerar visualizações de dados apropriadas","ru":"Навык визуализации графиков помогает ИИ Агентам рекомендовать и генерировать соответствующие визуализации данных","ar":"مهارة تمثيل الرسوم البيانية تساعد أدوات الذكاء الاصطناعي على تقديم وإنشاء تمثيلات بيانات مناسبة"},"seo":{"title":{"en":"chart-visualization: Data Visualization Setup Guide | AI ...","zh":"图表可视化设置指南 - AI友好可视化工具","ja":"チャート可視化ベストプラクティス - AIエージェント向け","ko":"차트 시각화 설정 가이드 - AI 툴을 위한 데이터 시각화","es":"Guía de configuración de visualización de gráficos para A...","fr":"Guide de mise en place de la visualisation de graphiques ...","de":"Einrichtungsleitfaden für Chart-Visualisierung in KI-Tools","pt":"Guia de Configuração de Visualização de Gráficos com Ferr...","ru":"Настройка визуализации графиков с помощью ИИ Агентов","ar":"دليل إعداد تمثيلات الرسوم البيانية مع أدوات الذكاء الاصطناعي"},"description":{"en":"Discover how chart-visualization helps AI agents generate suitable data visualizations. Learn how to implement intent recognition and chart selection for you...","zh":"了解图表可视化的技术细节和工作流程，包括意图识别、图表选择和数据分析","ja":"チャート可視化の技術的側面とワークフローを学び、AIエージェントのためのデータ可視化を実現","ko":"차트 시각화의 기술적 세부 사항과 워크플로우를 살펴보고, AI 툴을 위한 데이터 시각화를 구현","es":"Aprende a implementar la visualización de gráficos en tus proyectos de Agentes de IA con AntV y recomendaciones de visualización generadas por IA","fr":"Découvrez comment mettre en œuvre la visualisation de graphiques dans vos projets d''outils d''IA avec AntV et des recommandations de visualisation générées pa...","de":"Erfahren Sie, wie Sie die Chart-Visualisierung in Ihren KI-Tool-Projekten mit AntV und von der KI generierten Visualisierungsempfehlungen umsetzen","pt":"Aprenda a configurar visualizações de gráficos com ferramentas de IA para melhorar a análise de dados","ru":"Узнайте, как настроить визуализацию графиков с помощью ИИ Агентов для улучшения анализа данных","ar":"تعلم كيفية إعداد تمثيلات الرسوم البيانية مع أدوات الذكاء الاصطناعي لتحسين تحليل البيانات"},"definition":{"en":"chart-visualization is a skill that enables AI assistants to recommend and generate appropriate data visualizations, such as line, area, column, and bar charts, based on user intent and data analysis.","zh":"图表可视化是指使用图表和图形来表示数据的过程，帮助用户理解和分析数据","ja":"チャート可視化は、グラフやチャートを使用してデータを表現するプロセスであり、ユーザーがデータを理解し分析することを助ける","ko":"차트 시각화는 차트와 그래프를 사용하여 데이터를 표현하는 과정으로, 사용자가 데이터를 이해하고 분석하는 것을 도와줌","es":"La visualización de gráficos es una técnica de visualización de datos que utiliza gráficos para representar información","fr":"La visualisation de graphiques est une technique de visualisation de données qui utilise des graphiques pour représenter des informations","de":"Die Chart-Visualisierung ist eine Technik zur Datenvisualisierung, die Grafiken verwendet, um Informationen darzustellen","pt":"Visualização de gráficos é uma habilidade que ajuda assistentes de IA a criar representações visuais de dados","ru":"Визуализация графиков - это навык, который помогает ИИ Агентам создавать визуальные представления данных","ar":"تمثيل الرسوم البيانية هو مهارة تساعد أدوات الذكاء الاصطناعي على إنشاء تمثيلات بصرية للبيانات"},"features":{"en":["Analyzes user intent and data characteristics to select suitable chart types","Supports time-series data visualization using Line and Area charts","Enables categorical comparison using Column and Bar charts","Facilitates proportion analysis using Pie charts","Generates distribution analysis using Histogram, Boxplot, and Violin charts"],"zh":["意图识别和图表选择","时间序列数据可视化（线图、面积图）","分类比较数据可视化（柱状图、条形图）","比例分析数据可视化（饼图）","分布分析数据可视化（直方图、箱线图、提琴图）"],"ja":["意図認識とチャート選択","時間系列データ可視化（線グラフ、面積グラフ）","カテゴリ比較データ可視化（柱状グラフ、棒グラフ）","比率分析データ可視化（パイチャート）","分布分析データ可視化（ヒストグラム、ボックスプロット、バイオリンプロット）"],"ko":["의도 인식과 차트 선택","시간 순차 데이터 시각화（선 그래프, 면적 그래프）","범주 비교 데이터 시각화（柱状 그래프, 막대 그래프）","비율 분석 데이터 시각화（파이 차트）","분포 분석 데이터 시각화（히스토그램, 박스 플롯, 바이올린 플롯）"],"es":["Reconocimiento de intención y selección de gráfico","Visualización de series temporales con gráficos de línea y área","Análisis de proporciones con gráficos de pie","Análisis de distribución con histogramas, gráficos de caja y gráficos de violín"],"fr":["Reconnaissance d''intention et sélection de graphique","Visualisation de séries temporelles avec des graphiques de ligne et de surface","Analyse de proportions avec des graphiques de pie","Analyse de distribution avec des histogrammes, des graphiques de boîte et des graphiques de violon"],"de":["Intent-Erkennung und Chart-Auswahl","Visualisierung von Zeitreihen mit Liniendiagrammen und Flächendiagrammen","Analyse von Anteilen mit Kreisdiagrammen","Analyse von Verteilungen mit Histogrammen, Boxplots und Violindigrammen"],"pt":["Reconhecimento de intenção e seleção de tipo de gráfico","Suporte a dados de série temporal com gráficos de linha e área","Análise de distribuição com histogramas, boxplots e gráficos de violino"],"ru":["Распознавание намерения и выбор типа графика","Поддержка временных рядов с линейными и площадными графиками","Анализ распределения с гистограммами, бокс-плотами и графиками скрипки"],"ar":["التعرف على النية واختيار نوع الرسم البياني","دعم البيانات الزمنية مع الرسوم البيانية الخطية والمنطقة","تحليل التوزيع مع الرسوم البيانية العمودية والمستطيلة والكمان"]},"keywords":{"en":["how to use chart-visualization","chart-visualization setup guide","chart-visualization alternative","chart-visualization vs AntV","chart-visualization install","what is chart-visualization","chart-visualization for AI agents","data visualization with chart-visualization","chart-visualization workflow"],"zh":["图表可视化","AI友好可视化工具","数据可视化","意图识别","图表选择","时间序列数据","分类比较数据","比例分析","分布分析"],"ja":["チャート可視化","AIエージェント向け可視化ツール","データ可視化","意図認識","チャート選択","時間系列データ","カテゴリ比較データ","比率分析","分布分析"],"ko":["차트 시각화","AI 툴을 위한 데이터 시각화","데이터 시각화","의도 인식","차트 선택","시간 순차 데이터","범주 비교 데이터","비율 분석","분포 분석"],"es":["visualización de gráficos","Agentes de IA","AntV","recomendaciones de visualización","visualización de datos","gráficos de línea","gráficos de área","gráficos de pie"],"fr":["visualisation de graphiques","outils d''IA","AntV","recommandations de visualisation","visualisation de données","graphiques de ligne","graphiques de surface","graphiques de pie"],"de":["Chart-Visualisierung","KI-Tools","AntV","Visualisierungsempfehlungen","Datenvisualisierung","Liniendiagramme","Flächendiagramme","Kreisdiagramme"],"pt":["visualização de gráficos","ferramentas de IA","análise de dados","gráficos de linha","gráficos de área","histogramas","boxplots","gráficos de violino"],"ru":["визуализация графиков","ИИ Агенты","анализ данных","линейные графики","площадные графики","гистограммы","бокс-плоты","графики скрипки"],"ar":["تمثيل الرسوم البيانية","أدوات الذكاء الاصطناعي","تحليل البيانات","الرسوم البيانية الخطية","الرسوم البيانية المنطقة","الرسوم البيانية العمودية","الرسوم البيانية المستطيلة","الرسوم البيانية الكمان"]}},"owner":"antvis","repo":"GPT-Vis","repoPath":"antvis/GPT-Vis","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.274Z","topics":[],"category":"community","skillMd":{"name":"chart-visualization","description":"Recommend and generate appropriate data visualizations using GPT-Vis syntax. Supports 20 chart types including statistical charts (line, column, bar, pie, area, scatter, dual-axes, histogram, boxplot, radar, funnel, waterfall, liquid, word-cloud, violin, venn, treemap), flow charts (sankey), and data display (table, summary). Provides workflow from intent recognition to chart selection, syntax generation, and code generation for HTML, React, or Vue.","bodyPreview":"# Chart Visualization Skill\n\n## Workflow\n\nThis skill helps AI assistants recommend and generate appropriate data visualizations. The workflow consists of three main steps:\n\n1. **Intent Recognition & Chart Selection**: Analyze the user''s intent and data characteristics to select the most suitable chart type\n   - Time-series data → Line, Area charts\n   - Categorical comparison → Column, Bar charts\n   - Proportion analysis → Pie chart\n   - Distribution analysis → Histogram, Boxplot, Violin charts","body":"# Chart Visualization Skill\n\n## Workflow\n\nThis skill helps AI assistants recommend and generate appropriate data visualizations. The workflow consists of three main steps:\n\n1. **Intent Recognition & Chart Selection**: Analyze the user''s intent and data characteristics to select the most suitable chart type\n   - Time-series data → Line, Area charts\n   - Categorical comparison → Column, Bar charts\n   - Proportion analysis → Pie chart\n   - Distribution analysis → Histogram, Boxplot, Violin charts\n   - Relationship/Flow → Sankey chart\n   - Multi-dimensional comparison → Radar chart\n   - Other specific needs → Funnel, Waterfall, Liquid, WordCloud, Treemap, Venn, etc.\n\n2. **Syntax Generation**: Generate GPT-Vis syntax based on the selected chart type and provided data\n\n3. **Code Generation**: Generate renderable code for the target framework (HTML, React, or Vue)\n\n## Supported Chart Types\n\n| 名称     | 别名       | 英文名          | 适用场景                   | 分析意图           |\n| -------- | ---------- | --------------- | -------------------------- | ------------------ |\n| 折线图   | 线图       | Line Chart      | 时间序列数据，展示趋势变化 | 趋势分析、对比     |\n| 柱形图   | 柱状图     | Column Chart    | 分类数据比较               | 对比、分布、排名   |\n| 条形图   | 横向柱状图 | Bar Chart       | 分类数据比较，标签较长     | 对比、分布、排名   |\n| 饼图     | 饼状图     | Pie Chart       | 显示部分占整体的比例       | 占比、成分         |\n| 面积图   | 区域图     | Area Chart      | 时间序列，强调趋势和总量   | 趋势分析、对比     |\n| 散点图   | -          | Scatter Chart   | 显示两个变量的关系         | 相关性分析、分布   |\n| 双轴图   | 组合图     | Dual-Axes Chart | 同时展示两个不同量级的数据 | 多维对比、趋势分析 |\n| 直方图   | -          | Histogram       | 显示数据分布               | 分布分析           |\n| 箱线图   | 盒须图     | Boxplot         | 显示数据分布和异常值       | 分布分析、异常检测 |\n| 雷达图   | 蜘蛛图     | Radar Chart     | 多维度数据对比             | 多维对比           |\n| 漏斗图   | -          | Funnel Chart    | 展示流程转化率             | 流程分析、转化分析 |\n| 瀑布图   | -          | Waterfall Chart | 显示累计效应               | 增减变化分析       |\n| 水波图   | 进度球     | Liquid Chart    | 显示百分比或进度           | 进度展示、占比     |\n| 词云图   | 词云       | Word Cloud      | 展示文本词频               | 词频分析、热点展示 |\n| 小提琴图 | -          | Violin Chart    | 显示数据分布密度           | 分布分析           |\n| 韦恩图   | 文氏图     | Venn Chart      | 显示集合关系               | 集合交并关系       |\n| 矩阵树图 | 树状图     | Treemap         | 显示层级数据占比           | 层级占比、结构分析 |\n| 桑基图   | -          | Sankey Chart    | 展示流量流向               | 流向分析           |\n| 表格     | 数据表     | Table           | 展示详细数据明细           | 数据展示、查找     |\n| 总结摘要 | -          | Summary         | 文本总结内容               | 内容总结           |\n\n## GPT-Vis Syntax\n\nGPT-Vis 使用简洁的类 Markdown 语法来描述图表配置，使 AI 更容易生成。基本结构如下：\n\n```\nvis [chart-type]\ndata\n  - [field1] [value1]\n    [field2] [value2]\n[optional-property] [value]\n```\n\n### Syntax 特点\n\n- **简洁易读**: 类 Markdown 的缩进语法，易于 AI 生成\n- **流式友好**: 支持逐 token 渲染，适合流式输出\n- **容错性强**: 能优雅处理不完整数据\n- **类型安全**: 每个图表有明确的数据结构\n\n## Framework Integration\n\nGPT-Vis 支持在 HTML、React 和 Vue 中使用，提供统一的 API 来渲染 Syntax。\n\n### HTML / Vanilla JavaScript\n\n```html\n<!DOCTYPE html>\n<html>\n  <head>\n    <script src=\"https://unpkg.com/@antv/gpt-vis/dist/umd/index.min.js\"></script>\n  </head>\n  <body>\n    <div id=\"container\"></div>\n    <script>\n      const gptVis = new GPTVis.GPTVis({\n        container: ''#container'',\n        width: 600,\n        height: 400,\n      });\n\n      const visSyntax = `\nvis line\ndata\n  - time 2020\n    value 100\n  - time 2021\n    value 120\n  - time 2022\n    value 150\ntitle 年度趋势\n`;\n\n      gptVis.render(visSyntax);\n    </script>\n  </body>\n</html>\n```\n\n### React\n\n```jsx\nimport { GPTVis } from ''@antv/gpt-vis'';\nimport { useEffect, useRef } from ''react'';\n\nfunction ChartComponent({ visSyntax }) {\n  const containerRef = useRef(null);\n  const gptVisRef = useRef(null);\n\n  useEffect(() => {\n    if (containerRef.current && !gptVisRef.current) {\n      gptVisRef.current = new GPTVis({\n        container: containerRef.current,\n        width: 600,\n        height: 400,\n      });\n    }\n  }, []);\n\n  useEffect(() => {\n    if (gptVisRef.current && visSyntax) {\n      gptVisRef.current.render(visSyntax);\n    }\n  }, [visSyntax]);\n\n  return <div ref={containerRef}></div>;\n}\n\n// 使用示例\nconst visSyntax = `\nvis column\ndata\n  - category A产品\n    value 30\n  - category B产品\n    value 50\ntitle 产品销量\n`;\n\n<ChartComponent visSyntax={visSyntax} />;\n```\n\n### Vue\n\n```vue\n<template>\n  <div ref=\"containerRef\"></div>\n</template>\n\n<script setup>\nimport { ref, onMounted, watch } from ''vue'';\nimport { GPTVis } from ''@antv/gpt-vis'';\n\nconst props = defineProps({\n  visSyntax: String,\n});\n\nconst containerRef = ref(null);\nlet gptVis = null;\n\nonMounted(() => {\n  gptVis = new GPTVis({\n    container: containerRef.value,\n    width: 600,\n    height: 400,\n  });\n\n  if (props.visSyntax) {\n    gptVis.render(props.visSyntax);\n  }\n});\n\nwatch(\n  () => props.visSyntax,\n  (newSyntax) => {\n    if (gptVis && newSyntax) {\n      gptVis.render(newSyntax);\n    }\n  },\n);\n</script>\n\n<!-- 使用示例 -->\n<ChartComponent :vis-syntax=\"visSyntax\" />\n```\n\n### 流式渲染支持\n\nGPT-Vis 天然支持流式渲染，可以逐步接收 AI 生成的 Syntax：\n\n```javascript\nimport { GPTVis, isVisSyntax } from ''@antv/gpt-vis'';\n\nconst gptVis = new GPTVis({\n  container: ''#container'',\n  width: 600,\n  height: 400,\n});\n\nlet buffer = '''';\n\n// 当 AI 流式输出 token 时\nfunction onToken(token) {\n  buffer += token;\n  if (isVisSyntax(buffer)) {\n    gptVis.render(buffer);\n  }\n}\n```\n\n## Syntax Examples\n\n### Line Chart (折线图)\n\n**适用场景**: 时间序列数据，展示趋势变化\n\n**Syntax 示例**:\n\n```\nvis line\ndata\n  - time 2020\n    value 100\n  - time 2021\n    value 120\n  - time 2022\n    value 150\ntitle 年度数据趋势\n```\n\n详细用法参考: [references/line.md](references/line.md)\n\n### Column Chart (柱形图)\n\n**适用场景**: 分类数据比较\n\n**Syntax 示例**:\n\n```\nvis column\ndata\n  - category A产品\n    value 30\n  - category B产品\n    value 50\n  - category C产品\n    value 20\ntitle 产品销量对比\n```\n\n详细用法参考: [references/column.md](references/column.md)\n\n### Bar Chart (条形图)\n\n**适用场景**: 分类数据比较，标签较长\n\n**Syntax 示例**:\n\n```\nvis bar\ndata\n  - category 产品类别A\n    value 30\n  - category 产品类别B\n    value 50\n  - category 产品类别C\n    value 20\n```\n\n详细用法参考: [references/bar.md](references/bar.md)\n\n### Pie Chart (饼图)\n\n**适用场景**: 显示部分占整体的比例\n\n**Syntax 示例**:\n\n```\nvis pie\ndata\n  - category 类别A\n    value 30\n  - category 类别B\n    value 50\n  - category 类别C\n    value 20\n```\n\n详细用法参考: [references/pie.md](references/pie.md)\n\n### Area Chart (面积图)\n\n**适用场景**: 时间序列，强调趋势和总量\n\n**Syntax 示例**:\n\n```\nvis area\ndata\n  - time 2020\n    value 100\n  - time 2021\n    value 120\n  - time 2022\n    value 150\n```\n\n详细用法参考: [references/area.md](references/area.md)\n\n### Scatter Chart (散点图)\n\n**适用场景**: 显示两个变量的关系\n\n**Syntax 示例**:\n\n```\nvis scatter\ndata\n  - x 1\n    y 2\n  - x 2\n    y 4\n  - x 3\n    y 3\n```\n\n详细用法参考: [references/scatter.md](references/scatter.md)\n\n### Dual-Axes Chart (双轴图)\n\n**适用场景**: 同时展示两个不同量级的数据\n\n**Syntax 示例**:\n\n```\nvis dual-axes\ndata\n  - category 1月\n    value 100\n    count 10\n  - category 2月\n    value 120\n    count 15\n  - category 3月\n    value 150\n    count 12\n```\n\n详细用法参考: [references/dual-axes.md](references/dual-axes.md)\n\n### Histogram (直方图)\n\n**适用场景**: 显示数据分布\n\n**Syntax 示例**:\n\n```\nvis histogram\ndata\n  - value 10\n  - value 12\n  - value 15\n  - value 18\n  - value 20\n```\n\n详细用法参考: [references/histogram.md](references/histogram.md)\n\n### Boxplot (箱线图)\n\n**适用场景**: 显示数据分布和异常值\n\n**Syntax 示例**:\n\n```\nvis boxplot\ndata\n  - category A\n    value 10\n  - category A\n    value 15\n  - category A\n    value 20\n  - category B\n    value 12\n  - category B\n    value 18\n```\n\n详细用法参考: [references/boxplot.md](references/boxplot.md)\n\n### Radar Chart (雷达图)\n\n**适用场景**: 多维度数据对比\n\n**Syntax 示例**:\n\n```\nvis radar\ndata\n  - dimension 维度1\n    value 80\n  - dimension 维度2\n    value 90\n  - dimension 维度3\n    value 70\n```\n\n详细用法参考: [references/radar.md](references/radar.md)\n\n### Funnel Chart (漏斗图)\n\n**适用场景**: 展示流程转化率\n\n**Syntax 示例**:\n\n```\nvis funnel\ndata\n  - stage 访问\n    value 1000\n  - stage 注册\n    value 500\n  - stage 购买\n    value 100\n```\n\n详细用法参考: [references/funnel.md](references/funnel.md)\n\n### Waterfall Chart (瀑布图)\n\n**适用场景**: 显示累计效应\n\n**Syntax 示例**:\n\n```\nvis waterfall\ndata\n  - category 初始\n    value 100\n  - category 增加\n    value 50\n  - category 减少\n    value -30\n```\n\n详细用法参考: [references/waterfall.md](references/waterfall.md)\n\n### Liquid Chart (水波图)\n\n**适用场景**: 显示百分比或进度\n\n**Syntax 示例**:\n\n```\nvis liquid\ndata\n  - value 0.65\n```\n\n详细用法参考: [references/liquid.md](references/liquid.md)\n\n### Word Cloud (词云图)\n\n**适用场景**: 展示文本词频\n\n**Syntax 示例**:\n\n```\nvis word-cloud\ndata\n  - word 数据\n    value 100\n  - word 可视化\n    value 80\n  - word 图表\n    value 60\n```\n\n详细用法参考: [references/word-cloud.md](references/word-cloud.md)\n\n### Violin Chart (小提琴图)\n\n**适用场景**: 显示数据分布密度\n\n**Syntax 示例**:\n\n```\nvis violin\ndata\n  - category A\n    value 10\n  - category A\n    value 15\n  - category A\n    value 20\n```\n\n详细用法参考: [references/violin.md](references/violin.md)\n\n### Venn Chart (韦恩图)\n\n**适用场景**: 显示集合关系\n\n**Syntax 示例**:\n\n```\nvis venn\ndata\n  - sets A\n    size 10\n  - sets B\n    size 8\n  - sets A,B\n    size 3\n```\n\n详细用法参考: [references/venn.md](references/venn.md)\n\n### Treemap (矩阵树图)\n\n**适用场景**: 显示层级数据占比\n\n**Syntax 示例**:\n\n```\nvis treemap\ndata\n  - category 分类A\n    value 30\n  - category 分类B\n    value 50\n  - category 分类C\n    value 20\n```\n\n详细用法参考: [references/treemap.md](references/treemap.md)\n\n### Sankey Chart (桑基图)\n\n**适用场景**: 展示流量流向\n\n**Syntax 示例**:\n\n```\nvis sankey\ndata\n  - source A\n    target B\n    value 10\n  - source B\n    target C\n    value 5\n  - source A\n    target C\n    value 5\n```\n\n详细用法参考: [references/sankey.md](references/sankey.md)\n\n### Table (表格)\n\n**适用场景**: 展示详细数据明细\n\n**Syntax 示例**:\n\n```\nvis table\ndata\n  - 姓名 张三\n    年龄 25\n    城市 北京\n  - 姓名 李四\n    年龄 30\n    城市 上海\n```\n\n详细用法参考: [references/table.md](references/table.md)\n\n### Summary (总结摘要)\n\n**适用场景**: 数据报告生成、洞察结论呈现、叙事性数据展示\n\n**Syntax 示例**:\n\n```\n# Q4 销售分析报告\n\n## 核心指标\n[2024 年 Q4](time_desc)，公司[销售额](metric_name)达到[¥523 万](metric_value, origin=5230000)，\n较上季度[增长 15.2%](ratio_value, origin=0.152, assessment=\"positive\")。\n\n## 关键发现\n- [新客户数](metric_name)：[1,234](metric_value, origin=1234)，环比增长[8.3%](ratio_value, origin=0.083)\n- [客户留存率](metric_name)：[89.5%](ratio_value, origin=0.895)\n- [平均订单金额](metric_name)：[¥4,567](metric_value, origin=4567)\n\n其中，[线上渠道](dim_value)贡献了[68%](contribute_ratio, origin=0.68)的销售额。\n```\n\n详细用法参考: [references/summary.md](references/summary.md)\n\n## Best Practices\n\n1. **选择合适的图表类型**\n   - 时间序列优先使用折线图或面积图\n   - 分类比较优先使用柱形图或条形图\n   - 占比分析使用饼图（分类不超过 5 个）\n   - 多维对比使用雷达图\n\n2. **数据要求**\n   - 确保数据字段与图表类型匹配\n   - 数值字段必须是数字类型\n   - 分类字段必须是文本类型\n\n3. **避免误用**\n   - 不要用饼图展示趋势\n   - 不要用折线图展示无序分类\n   - 不要在数据量过大时使用饼图\n\n## References\n\n详细的图表知识、使用方法、数据要求和更多示例，请参考 `references/` 目录中的各图表文档。每个文档包含：\n\n- 图表属性和基础概念\n- 适用和不适用场景\n- 详细的数据要求和类型定义\n- 多个实际使用示例\n"},"lastSynced":"2026-03-08T02:00:33.620Z","agentAnalysis":{"suitability":{"en":"Perfect for Data Analysis Agents needing advanced chart visualization capabilities for user intent and data characteristics.","zh":"适用于需要高级图表可视化功能的数据分析代理，用于用户意图和数据特征。","ja":"ユーザー意図とデータ特性の高度なチャート視覚化機能を必要とするデータ分析エージェントに適しています。","ko":"사용자 의도와 데이터 특성에 대한 고급 차트 시각화 기능이 필요한 데이터 분석 에이전트에 적합합니다.","es":"Perfecto para Agentes de Análisis de Datos que necesitan capacidades de visualización de gráficos avanzados para la intención del usuario y las características de los datos.","fr":"Parfait pour les Agents d''Analyse de Données ayant besoin de capacités de visualisation de graphiques avancées pour l''intention de l''utilisateur et les caractéristiques des données.","de":"Perfekt für Datenanalyse-Agents, die erweiterte Diagrammvisualisierungsfunktionen für Benutzerintent und Datenmerkmale benötigen.","pt":"Perfeito para Agentes de Análise de Dados que necessitam de capacidades de visualização de gráficos avançadas para intenção do usuário e características de dados.","ru":"Идеально подходит для агентов анализа данных, которым необходимы продвинутые возможности визуализации графиков для намерений пользователя и характеристик данных.","ar":"مثالي لعمليات تحليل البيانات التي تحتاج إلى إمكانيات متقدمة في تمثيل البيانات المرئية لنوايا المستخدم وخصائص البيانات."},"recommendation":{"en":"Empowers agents to generate informative data visualizations using suitable chart types such as Line, Area, Column, Bar, Pie, Histogram, Boxplot, and Violin charts, leveraging user intent and data characteristics for optimal representation, and supporting various data formats.","zh":"使代理能够生成具有代表性的数据可视化，使用适合的图表类型，例如线图、面积图、柱状图、条形图、饼图、直方图、箱线图和小提琴图，利用用户意图和数据特性进行最优表示，并支持多种数据格式。","ja":"エージェントがユーザー意図とデータ特性を利用して最適な表現を行い、Line、Area、Column、Bar、Pie、Histogram、Boxplot、Violin チャートなどの適切なチャートタイプを使用して情報豊富なデータ視覚化を生成し、様々なデータ形式をサポートできるようにします。","ko":"에이전트가 사용자 의도와 데이터 특성을 활용하여 최적의 표현을 수행하고, Line, Area, Column, Bar, Pie, Histogram, Boxplot, Violin 차트などの 적절한 차트 유형을 사용하여 정보가 풍부한 데이터 시각화를 생성하며, 다양한 데이터 형식을 지원할 수 있도록 합니다.","es":"Habilita a los agentes a generar visualizaciones de datos informativas utilizando tipos de gráficos adecuados como Línea, Área, Columna, Barra, Pastel, Histograma, Boxplot y gráficos de violín, aprovechando la intención del usuario y las características de los datos para una representación óptima, y admitiendo varios formatos de datos.","fr":"Permet aux agents de générer des visualisations de données informatives en utilisant des types de graphiques appropriés tels que Ligne, Zone, Colonne, Barre, Camembert, Histogramme, Boxplot et graphiques de violon, en exploitant l''intention de l''utilisateur et les caractéristiques des données pour une représentation optimale, et en prenant en charge divers formats de données.","de":"Ermächtigt Agents, informative Datenvisualisierungen zu generieren, indem geeignete Charttypen wie Linie, Fläche, Spalte, Balken, Kreis, Histogramm, Boxplot und Geigencharts verwendet werden, die Benutzerintent und Datenmerkmale für eine optimale Darstellung nutzen und verschiedene Datenformate unterstützen.","pt":"Habilita os agentes a gerar visualizações de dados informativas usando tipos de gráficos adequados, como Linha, Área, Coluna, Barra, Pizza, Histograma, Boxplot e gráficos Violin, aproveitando a intenção do usuário e as características de dados para uma representação ótima, e suportando vários formatos de dados.","ru":"Позволяет агентам генерировать информативные визуализации данных, используя подходящие типы графиков, такие как Линия, Площадь, Колонка, Столбец, Пирог, Гистограмма, Boxplot и графики Скрипичный ключ, используя намерения пользователя и характеристики данных для оптимального представления, и поддерживая различные форматы данных.","ar":"تمكّن الوكيل من توليد تصورات بيانات مُفيدة باستخدام أنواع مخططات مناسبة مثل الخط والمنطقة والعمود والشريط والفقاعة والمنحني والصندوق ومخططات الكمان، مستفيداً من نوايا المستخدم وخصائص البيانات من أجل تمثيل أمثل وداعم لتنسيقات بيانات متعددة."},"useCases":{"en":["Automating chart type selection for time-series data","Generating column charts for categorical comparisons","Creating pie charts for proportion analysis"],"zh":["时间序列数据的自动图表类型选择","生成柱状图用于分类比较","创建饼图用于比例分析"],"ja":["時系列データの自動チャートタイプ選択","カテゴリ比較のための柱状グラフの生成","比例分析のためのパイチャートの作成"],"ko":["시간 시리즈 데이터에 대한 자동 차트 유형 선택","분류 비교를 위한 열 차트 생성","비율 분석을 위한 파이 차트 생성"],"es":["Automatizar la selección del tipo de gráfico para datos de series temporales","Generar gráficos de columnas para comparaciones categóricas","Crear gráficos de pastel para análisis de proporciones"],"fr":["Automatiser la sélection du type de graphique pour les données de séries temporelles","Générer des graphiques à colonnes pour des comparaisons catégoriques","Créer des graphiques à camembert pour l''analyse de proportions"],"de":["Automatisieren der Auswahl des Charttyps für Zeitreihendaten","Generieren von Spaltencharts für kategorische Vergleiche","Erstellen von Kreisdiagrammen für Proportionsanalysen"],"pt":["Automatizar a seleção do tipo de gráfico para dados de séries temporais","Gerar gráficos de coluna para comparações categóricas","Criar gráficos de pizza para análise de proporções"],"ru":["Автоматизировать выбор типа графика для временных рядов данных","Генерировать столбчатые графики для категориальных сравнений","Создавать круговые диаграммы для анализа пропорций"],"ar":["تأتميم تحديد نوع المخطط للبيانات الزمنية","إنتاج مخططات عمودية للمقارنات التصنيفية","إنشاء مخططات دائرية لتحليل النسب"]},"limitations":{"en":["Requires data characteristics analysis","Limited to predefined chart types"],"zh":["需要数据特性分析","仅限于预定义的图表类型"],"ja":["データ特性分析の必要性","事前に定義されたチャートタイプのみのサポート"],"ko":["데이터 특성 분석의 필요성","사전에 정의된 차트 유형만 지원"],"es":["Requiere análisis de características de datos","Limitado a tipos de gráficos predefinidos"],"fr":["Nécessite une analyse des caractéristiques des données","Limité aux types de graphiques prédéfinis"],"de":["Benötigt Datenmerkmalsanalyse","Begrenzt auf vorgegebene Charttypen"],"pt":["Requer análise das características de dados","Limitado a tipos de gráficos predefinidos"],"ru":["Требует анализа характеристик данных","Ограничен предопределенными типами графиков"],"ar":["يتطلب تحليلاً لخصائص البيانات","محدود بالأنواع المُسبقة للمخططات"]},"version":4},"contentHash":"2c81f8688cdc6c75d4d3a61056de7285d85c43b0d0a157e7b6b40c6bda8b3904","qualityScore":33}');
