struct management Supports Layer 2 design choices for informed decision-making m09-domain is a Rust Developer AI Assistance System that utilizes meta-problem-driven knowledge indexing for domain modeling and design choices.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('analogjs/angular-skills/angular-di', 'community', 'analogjs', 'angular-skills', 'analogjs/angular-skills', 'angular-di', 0, 0, 33, '2026-03-08T01:57:15.275Z', '2026-03-08T02:00:40.401Z', 'fd379b252703f563e6d850b54667cc2ee72f41cbe4ded9d26646f04d82db51dc', '{"id":"analogjs/angular-skills/angular-di","name":"angular-di","description":{"en":"The angular-di skill enables Angular developers to configure and use dependency injection in Angular v20+ with inject() and providers. It benefits developers by simplifying dependency management.","zh":"Angular DI 是一个用于配置和使用依赖注入的技能，支持 Angular v20+ 中的 inject() 和提供者","ja":"Angular DI は、依存性注入を設定および使用するために使用されるスキルで、Angular v20+ の inject() とプロバイダーをサポートします","ko":"Angular DI는 의존성 주입을 설정하고 사용하기 위한 기술로 Angular v20+의 inject() 및 제공자를 지원합니다","es":"La inyección de dependencias de Angular es una característica clave para la gestión de dependencias en aplicaciones Angular","fr":"L''injection de dépendances Angular est une fonctionnalité clé pour la gestion des dépendances dans les applications Angular","de":"Die Abhängigkeitsinjektion von Angular ist eine wichtige Funktion für die Verwaltung von Abhängigkeiten in Angular-Anwendungen","pt":"Configure e use injeção de dependência no Angular v20+ com inject() e providers","ru":"Настройка и использование внедрения зависимостей в Angular v20+ с inject() и providers","ar":"تهيئة واستخدام الحقن التابعية في Angular v20+ مع inject() و providers"},"seo":{"title":{"en":"angular-di: Mastering Dependency Injection for Angular v2...","zh":"Angular DI 设置指南：使用 inject() 和提供者","ja":"Angular DI Setup Guide: inject() とプロバイダーを使用","ko":"Angular DI 설정 가이드: inject() 및 제공자 사용","es":"Guía de configuración de inyección de dependencias de Ang...","fr":"Guide de configuration de l''injection de dépendances Angular","de":"Einrichtungsleitfaden für Angular-Abhängigkeitsinjektion","pt":"Guia de Configuração do Angular DI","ru":"Настройка Angular DI: Лучшие Практики","ar":"إعداد Angular DI: دليل المستخدم"},"description":{"en":"Unlock efficient dependency management in Angular with angular-di. Learn how to configure and use inject() and providers for seamless development.","zh":"了解如何使用 Angular v20+ 中的 inject() 和提供者配置和使用依赖注入","ja":"Angular v20+ で inject() とプロバイダーを使用して依存性注入を設定および使用する方法について学びます","ko":"Angular v20+에서 inject() 및 제공자를 사용하여 의존성 주입을 설정하고 사용하는 방법에 대해 알아보세요","es":"Aprende a configurar y utilizar la inyección de dependencias en Angular v20+ con inject() y proveedores","fr":"Découvrez comment configurer et utiliser l''injection de dépendances dans Angular v20+ avec inject() et fournisseurs","de":"Erfahren Sie, wie Sie die Abhängigkeitsinjektion in Angular v20+ mit inject() und Anbietern konfigurieren und verwenden","pt":"Aprenda a configurar e usar injeção de dependência no Angular v20+ com inject() e providers","ru":"Используйте ИИ Агенты для настройки Angular DI с inject() и providers в Angular v20+","ar":"استخدم أدوات الذكاء الاصطناعي لتهيئة Angular DI مع inject() و providers في Angular v20+"},"definition":{"en":"angular-di is a skill for Angular developers to master dependency injection using inject() and providers in Angular v20+.","zh":"Angular DI 是 Angular 中用于管理依赖关系的机制","ja":"Angular DI は、Angular で依存関係を管理するために使用されるメカニズムです","ko":"Angular DI는 Angular에서 의존 관계를 관리하기 위한 메커니즘입니다","es":"La inyección de dependencias es un patrón de diseño que permite a los componentes de una aplicación obtener sus dependencias de manera flexible","fr":"L''injection de dépendances est un patron de conception qui permet aux composants d''une application d''obtenir leurs dépendances de manière flexible","de":"Die Abhängigkeitsinjektion ist ein Entwurfsmuster, das es Komponenten einer Anwendung ermöglicht, ihre Abhängigkeiten flexibel zu erhalten","pt":"Injeção de dependência no Angular é uma técnica para gerenciar dependências entre componentes","ru":"Внедрение зависимостей в Angular - это техника для управления зависимостями между компонентами","ar":"الحقن التابعية في Angular هو تقنية لإدارة التبعيات بين المكونات"},"features":{"en":["Configures dependency injection in Angular v20+ using inject()","Utilizes providers for efficient dependency management","Preferably uses inject() over constructor injection","Supports HttpClient and User services integration","Enables basic injection using the inject() function"],"zh":["使用 inject() 代替构造函数注入","支持 Angular v20+ 中的依赖注入","使用提供者管理依赖关系","在 Angular 组件中使用 inject()","使用 HttpClient 进行 HTTP 请求","支持 User 服务的依赖注入"],"ja":["inject() を使用してコンストラクター注入を置き換える","Angular v20+ の依存性注入をサポート","プロバイダーを使用して依存関係を管理","Angular コンポーネントで inject() を使用","HttpClient を使用して HTTP リクエストを実行","User サービスの依存性注入をサポート"],"ko":["inject()를 사용하여 생성자 주입을 대체","Angular v20+의 의존성 주입을 지원","제공자를 사용하여 의존 관계를 관리","Angular 컴포넌트에서 inject() 사용","HttpClient를 사용하여 HTTP 요청을 수행","User 서비스의 의존성 주입을 지원"],"es":["Configuración de la inyección de dependencias con inject()","Uso de proveedores para la gestión de dependencias","Compatibilidad con Angular v20+","Inyección de dependencias básica con inject()","Uso de la clase HttpClient para la gestión de solicitudes HTTP"],"fr":["Configuration de l''injection de dépendances avec inject()","Utilisation de fournisseurs pour la gestion des dépendances","Compatibilité avec Angular v20+","Injection de dépendances de base avec inject()","Utilisation de la classe HttpClient pour la gestion des requêtes HTTP"],"de":["Konfiguration der Abhängigkeitsinjektion mit inject()","Verwendung von Anbietern für die Verwaltung von Abhängigkeiten","Kompatibilität mit Angular v20+","Grundlegende Abhängigkeitsinjektion mit inject()","Verwendung der Klasse HttpClient für die Verwaltung von HTTP-Anfragen"],"pt":["Uso de inject() para injeção de dependência","Configuração de providers para gerenciar dependências","Suporte a Angular v20+","Melhoria da modularidade e reutilização de código","Simplificação da gestão de dependências"],"ru":["Использование inject() для внедрения зависимостей","Настройка providers для управления зависимостями","Поддержка Angular v20+","Улучшение модульности и повторного использования кода","Упрощение управления зависимостями"],"ar":["استخدام inject() للحقن التابعية","تهيئة providers لإدارة التبعيات","دعم Angular v20+","تحسين الإمكانية القابلة لإعادة الاستخدام واعادة الكتابة","تبسيط إدارة التبعيات"]},"keywords":{"en":["how to use angular-di","angular-di setup guide","what is angular-di","angular-di vs constructor injection","angular-di install","angular-di alternative","angular dependency injection best practices","using inject() in angular-di","angular-di providers"],"zh":["Angular DI","依赖注入","inject()","提供者","Angular v20+","依赖关系管理","Angular 组件","HttpClient","User 服务"],"ja":["Angular DI","依存性注入","inject()","プロバイダー","Angular v20+","依存関係管理","Angular コンポーネント","HttpClient","User サービス"],"ko":["Angular DI","의존성 주입","inject()","제공자","Angular v20+","의존 관계 관리","Angular 컴포넌트","HttpClient","User 서비스"],"es":["inyección de dependencias angular","angular di","configuración de inyección de dependencias","proveedores angular","inject() angular","angular v20+","gestión de dependencias en angular"],"fr":["injection de dépendances angular","angular di","configuration de l''injection de dépendances","fournisseurs angular","inject() angular","angular v20+","gestion des dépendances dans angular"],"de":["Abhängigkeitsinjektion angular","angular di","Konfiguration der Abhängigkeitsinjektion","Anbieter angular","inject() angular","angular v20+","Verwaltung von Abhängigkeiten in angular"],"pt":["angular di","injeção de dependência","inject()","providers","angular v20+","desenvolvimento de software","tecnologias web"],"ru":["angular di","внедрение зависимостей","inject()","providers","angular v20+","разработка программного обеспечения","веб-технологии","ИИ Агенты"],"ar":["angular di","الحقن التابعية","inject()","providers","angular v20+","تطوير البرمجيات","تكنولوجيا الويب","أدوات الذكاء الاصطناعي"]}},"owner":"analogjs","repo":"angular-skills","repoPath":"analogjs/angular-skills","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.275Z","topics":[],"category":"community","skillMd":{"name":"angular-di","description":"Implement dependency injection in Angular v20+ using inject(), injection tokens, and provider configuration. Use for service architecture, providing dependencies at different levels, creating injectable tokens, and managing singleton vs scoped services. Triggers on service creation, configuring providers, using injection tokens, or understanding DI hierarchy.","bodyPreview":"# Angular Dependency Injection\n\nConfigure and use dependency injection in Angular v20+ with `inject()` and providers.\n\n## Basic Injection\n\n### Using inject()\n\nPrefer `inject()` over constructor injection:\n\n```typescript\nimport { Component, inject } from ''@angular/core'';\nimport { HttpClient } from ''@angular/common/http'';\nimport { User } from ''./user.service'';\n\n@Component({\n  selector: ''app-user-list'',\n  template: `...`,\n})\nexport class UserList {\n  // Inject dependencies\n  private http = inject(H","body":"# Angular Dependency Injection\n\nConfigure and use dependency injection in Angular v20+ with `inject()` and providers.\n\n## Basic Injection\n\n### Using inject()\n\nPrefer `inject()` over constructor injection:\n\n```typescript\nimport { Component, inject } from ''@angular/core'';\nimport { HttpClient } from ''@angular/common/http'';\nimport { User } from ''./user.service'';\n\n@Component({\n  selector: ''app-user-list'',\n  template: `...`,\n})\nexport class UserList {\n  // Inject dependencies\n  private http = inject(HttpClient);\n  private userService = inject(User);\n  \n  // Can use immediately\n  users = this.userService.getUsers();\n}\n```\n\n### Injectable Services\n\n```typescript\nimport { Injectable, inject, signal } from ''@angular/core'';\nimport { HttpClient } from ''@angular/common/http'';\n\n@Injectable({\n  providedIn: ''root'', // Singleton at root level\n})\nexport class User {\n  private http = inject(HttpClient);\n  \n  private users = signal<User[]>([]);\n  readonly users$ = this.users.asReadonly();\n  \n  async loadUsers() {\n    const users = await firstValueFrom(\n      this.http.get<User[]>(''/api/users'')\n    );\n    this.users.set(users);\n  }\n}\n```\n\n## Provider Scopes\n\n### Root Level (Singleton)\n\n```typescript\n// Recommended: providedIn\n@Injectable({\n  providedIn: ''root'',\n})\nexport class Auth {}\n\n// Alternative: in app.config.ts\nexport const appConfig: ApplicationConfig = {\n  providers: [\n    Auth,\n  ],\n};\n```\n\n### Component Level (Instance per Component)\n\n```typescript\n@Component({\n  selector: ''app-editor'',\n  providers: [EditorState], // New instance for each component\n  template: `...`,\n})\nexport class Editor {\n  private editorState = inject(EditorState);\n}\n```\n\n### Route Level\n\n```typescript\nexport const routes: Routes = [\n  {\n    path: ''admin'',\n    providers: [Admin], // Shared within this route tree\n    children: [\n      { path: '''', component: AdminDashboard },\n      { path: ''users'', component: AdminUsers },\n    ],\n  },\n];\n```\n\n## Injection Tokens\n\n### Creating Tokens\n\n```typescript\nimport { InjectionToken } from ''@angular/core'';\n\n// Simple value token\nexport const API_URL = new InjectionToken<string>(''API_URL'');\n\n// Object token\nexport interface AppConfig {\n  apiUrl: string;\n  features: {\n    darkMode: boolean;\n    analytics: boolean;\n  };\n}\n\nexport const APP_CONFIG = new InjectionToken<AppConfig>(''APP_CONFIG'');\n\n// Token with factory (self-providing)\nexport const WINDOW = new InjectionToken<Window>(''Window'', {\n  providedIn: ''root'',\n  factory: () => window,\n});\n\nexport const LOCAL_STORAGE = new InjectionToken<Storage>(''LocalStorage'', {\n  providedIn: ''root'',\n  factory: () => localStorage,\n});\n```\n\n### Providing Token Values\n\n```typescript\n// app.config.ts\nexport const appConfig: ApplicationConfig = {\n  providers: [\n    { provide: API_URL, useValue: ''https://api.example.com'' },\n    {\n      provide: APP_CONFIG,\n      useValue: {\n        apiUrl: ''https://api.example.com'',\n        features: { darkMode: true, analytics: true },\n      },\n    },\n  ],\n};\n```\n\n### Injecting Tokens\n\n```typescript\n@Injectable({ providedIn: ''root'' })\nexport class Api {\n  private apiUrl = inject(API_URL);\n  private config = inject(APP_CONFIG);\n  private window = inject(WINDOW);\n  \n  getBaseUrl(): string {\n    return this.apiUrl;\n  }\n}\n```\n\n## Provider Types\n\n### useClass\n\n```typescript\n// Provide implementation\n{ provide: Logger, useClass: ConsoleLogger }\n\n// Conditional implementation\n{\n  provide: Logger,\n  useClass: environment.production\n    ? ProductionLogger\n    : ConsoleLogger,\n}\n```\n\n### useValue\n\n```typescript\n// Static values\n{ provide: API_URL, useValue: ''https://api.example.com'' }\n\n// Configuration objects\n{ provide: APP_CONFIG, useValue: { theme: ''dark'', language: ''en'' } }\n```\n\n### useFactory\n\n```typescript\n// Factory with dependencies\n{\n  provide: User,\n  useFactory: (http: HttpClient, config: AppConfig) => {\n    return new User(http, config.apiUrl);\n  },\n  deps: [HttpClient, APP_CONFIG],\n}\n\n// Async factory (not recommended - use provideAppInitializer)\n{\n  provide: CONFIG,\n  useFactory: () => fetch(''/config.json'').then(r => r.json()),\n}\n```\n\n### useExisting\n\n```typescript\n// Alias to existing provider\n{ provide: AbstractLogger, useExisting: ConsoleLogger }\n\n// Multiple tokens pointing to same instance\nproviders: [\n  ConsoleLogger,\n  { provide: Logger, useExisting: ConsoleLogger },\n  { provide: ErrorLogger, useExisting: ConsoleLogger },\n]\n```\n\n## Injection Options\n\n### Optional Injection\n\n```typescript\n@Component({...})\nexport class My {\n  // Returns null if not provided\n  private analytics = inject(Analytics, { optional: true });\n  \n  trackEvent(name: string) {\n    this.analytics?.track(name);\n  }\n}\n```\n\n### Self, SkipSelf, Host\n\n```typescript\n@Component({\n  providers: [Local],\n})\nexport class Parent {\n  // Only look in this component''s injector\n  private local = inject(Local, { self: true });\n}\n\n@Component({...})\nexport class Child {\n  // Skip this component, look in parent\n  private parentService = inject(ParentSvc, { skipSelf: true });\n\n  // Only look up to host component\n  private hostService = inject(Host, { host: true });\n}\n```\n\n## Multi Providers\n\nCollect multiple values for same token:\n\n```typescript\n// Token for multiple validators\nexport const VALIDATORS = new InjectionToken<Validator[]>(''Validators'');\n\n// Provide multiple values\nproviders: [\n  { provide: VALIDATORS, useClass: RequiredValidator, multi: true },\n  { provide: VALIDATORS, useClass: EmailValidator, multi: true },\n  { provide: VALIDATORS, useClass: MinLengthValidator, multi: true },\n]\n\n// Inject as array\n@Injectable()\nexport class Validation {\n  private validators = inject(VALIDATORS); // Validator[]\n  \n  validate(value: string): ValidationError[] {\n    return this.validators\n      .map(v => v.validate(value))\n      .filter(Boolean);\n  }\n}\n```\n\n### HTTP Interceptors (Multi Provider)\n\n```typescript\n// Interceptors use multi providers internally\nexport const appConfig: ApplicationConfig = {\n  providers: [\n    provideHttpClient(\n      withInterceptors([\n        authInterceptor,\n        loggingInterceptor,\n        errorInterceptor,\n      ])\n    ),\n  ],\n};\n```\n\n## App Initializers\n\nRun async code before app starts using `provideAppInitializer`:\n\n```typescript\nimport { provideAppInitializer, inject } from ''@angular/core'';\n\nexport const appConfig: ApplicationConfig = {\n  providers: [\n    Config,\n    provideAppInitializer(() => {\n      const configService = inject(Config);\n      return configService.loadConfig();\n    }),\n  ],\n};\n```\n\n### Multiple Initializers\n\n```typescript\nproviders: [\n  provideAppInitializer(() => {\n    const config = inject(Config);\n    return config.load();\n  }),\n  provideAppInitializer(() => {\n    const auth = inject(Auth);\n    return auth.checkSession();\n  }),\n]\n```\n\n## Environment Injector\n\nCreate injectors programmatically:\n\n```typescript\nimport { createEnvironmentInjector, EnvironmentInjector, inject } from ''@angular/core'';\n\n@Injectable({ providedIn: ''root'' })\nexport class Plugin {\n  private parentInjector = inject(EnvironmentInjector);\n  \n  loadPlugin(providers: Provider[]): EnvironmentInjector {\n    return createEnvironmentInjector(providers, this.parentInjector);\n  }\n}\n```\n\n## runInInjectionContext\n\nRun code with injection context:\n\n```typescript\nimport { runInInjectionContext, EnvironmentInjector, inject } from ''@angular/core'';\n\n@Injectable({ providedIn: ''root'' })\nexport class Utility {\n  private injector = inject(EnvironmentInjector);\n  \n  executeWithDI<T>(fn: () => T): T {\n    return runInInjectionContext(this.injector, fn);\n  }\n}\n\n// Usage\nutilityService.executeWithDI(() => {\n  const http = inject(HttpClient);\n  // Use http...\n});\n```\n\nFor advanced patterns, see [references/di-patterns.md](references/di-patterns.md).\n"},"lastSynced":"2026-03-08T02:00:40.401Z","agentAnalysis":{"suitability":{"en":"Ideal for Frontend Agents specializing in Angular development, seeking to streamline dependency management with inject() and providers.","zh":"适合专攻 Angular 开发的前端代理，旨在使用 inject() 和 providers 简化依赖管理。","ja":"Angular 開発を専門とするフロントエンド エージェントに適しています。inject() と providers を使用して依赖管理を簡素化することを目指しています。","ko":"Angular 개발을 전문으로 하는 프론트엔드 에이전트에게 적합합니다. inject()와 providers를 사용하여 의존성 관리를 간소화하려는 경우에 적합합니다.","es":"Ideal para Agentes de Frontend que se especializan en el desarrollo de Angular, que buscan simplificar la gestión de dependencias con inject() y providers.","fr":"Idéal pour les agents Frontend spécialisés dans le développement Angular, cherchant à rationaliser la gestion des dépendances avec inject() et providers.","de":"Ideal für Frontend-Agents, die sich auf die Entwicklung von Angular spezialisieren und die Abhängigkeitsverwaltung mit inject() und providers vereinfachen möchten.","pt":"Ideal para Agentes Frontend especializados em desenvolvimento Angular, buscando simplificar a gestão de dependências com inject() e providers.","ru":"Идеально для агентов фронтенда, специализирующихся на разработке Angular, стремящихся упростить управление зависимостями с помощью inject() и провайдеров.","ar":"مثالي لعميل واجهة المستخدم الأمامية المتخصص في تطوير Angular ، يسعى إلى简ification إدارة التبعيات مع inject() و providers."},"recommendation":{"en":"Empowers agents to simplify dependency injection in Angular v20+ using inject() and providers, enhancing code readability and maintainability with TypeScript and @angular/core libraries.","zh":"赋予代理简化 Angular v20+ 中的依赖注入的能力，使用 inject() 和 providers，并通过 TypeScript 和 @angular/core 库增强代码的可读性和可维护性。","ja":"エージェントに、inject() と providers を使用して Angular v20+ の依存性注入を簡素化する能力を与え、TypeScript と @angular/core ライブラリを使用してコードの可読性と保守性を向上させます。","ko":"에이전트가 inject()와 providers를 사용하여 Angular v20+의 의존성 주입을 단순화할 수 있는 능력을 부여하며, TypeScript와 @angular/core 라이브러리를 사용하여 코드의 가독성과 유지 보수성을 향상합니다.","es":"Empodera a los agentes para simplificar la inyección de dependencias en Angular v20+ utilizando inject() y providers, mejorando la legibilidad y mantenibilidad del código con las bibliotecas TypeScript y @angular/core.","fr":"Permet aux agents de simplifier l''injection de dépendances dans Angular v20+ en utilisant inject() et providers, améliorant la lisibilité et la maintenabilité du code avec les bibliothèques TypeScript et @angular/core.","de":"Ermächtigt die Agenten, die Abhängigkeitsinjektion in Angular v20+ mithilfe von inject() und providers zu vereinfachen, wodurch die Lesbarkeit und Wartbarkeit des Codes mit den Bibliotheken TypeScript und @angular/core verbessert werden.","pt":"Habilita os agentes a simplificar a injeção de dependências no Angular v20+ usando inject() e providers, melhorando a legibilidade e manutenção do código com as bibliotecas TypeScript e @angular/core.","ru":"Наделяет агентов возможностью упростить внедрение зависимостей в Angular v20+ с помощью inject() и провайдеров, улучшая читаемость и поддерживаемость кода с помощью библиотек TypeScript и @angular/core.","ar":"يمنح الوكيل القدرة على تبسيط حقن التبعيات في Angular v20+ باستخدام inject() و providers ، مما يعزز قراءة و صيانة الشفرة مع مكتبات TypeScript و @angular/core."},"useCases":{"en":["Configuring providers for services","Injecting dependencies with inject()","Simplifying constructor injection with modern Angular practices"],"zh":["为服务配置提供者","使用 inject() 注入依赖","使用现代 Angular 实践简化构造函数注入"],"ja":["サービス用のプロバイダーを構成する","inject() を使用して依存関係を注入する","最新の Angular プラクティスを使用してコンストラクターの注入を簡素化する"],"ko":["서비스를 위한 제공자를 구성하는 것","inject()를 사용하여 의존성을 주입하는 것","최신 Angular 관행을 사용하여 생성자 주입을 단순화하는 것"],"es":["Configuración de proveedores para servicios","Inyección de dependencias con inject()","Simplificación de la inyección de constructores con prácticas modernas de Angular"],"fr":["Configuration des fournisseurs pour les services","Injection de dépendances avec inject()","Simplification de l''injection de constructeurs avec les pratiques modernes d''Angular"],"de":["Konfiguration von Providern für Dienste","Injizierung von Abhängigkeiten mit inject()","Vereinfachung der Konstruktorinjektion mit modernen Angular-Praktiken"],"pt":["Configurando provedores para serviços","Injetando dependências com inject()","Simplificando injeção de construtor com práticas modernas do Angular"],"ru":["Настройка провайдеров для сервисов","Внедрение зависимостей с помощью inject()","Упрощение конструкторной инъекции с современными практиками Angular"],"ar":["تكوين مزودي الخدمات","حَقن التبعيات باستخدام inject()","تبسيط حقن المنشئ باستخدام ممارسات Angular الحديثة"]},"limitations":{"en":["Requires Angular v20+","Specific to Angular dependency injection"],"zh":["需要 Angular v20+","仅限于 Angular 依赖注入"],"ja":["Angular v20+ が必要","Angular 依存性注入のみに適用"],"ko":["Angular v20+가 필요","Angular 의존성 주입에만 적용"],"es":["Requiere Angular v20+","Específico para la inyección de dependencias de Angular"],"fr":["Nécessite Angular v20+","Spécifique à l''injection de dépendances d''Angular"],"de":["Erfordert Angular v20+","Spezifisch für die Abhängigkeitsinjektion von Angular"],"pt":["Exige Angular v20+","Específico para injeção de dependência do Angular"],"ru":["Требует Angular v20+","Специфичен для внедрения зависимостей Angular"],"ar":["يتطلب Angular v20+","محدد لحقن التبعيات في Angular"]},"version":4},"contentHash":"fd379b252703f563e6d850b54667cc2ee72f41cbe4ded9d26646f04d82db51dc","qualityScore":33}');
