INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('cloudposse/docs/docs-styles', 'docs-styles', 'cloudposse', 'docs', 'community', 'docs-styles cloudposse docs community docs-styles provides a set of CSS styles and color conventions for docs.cloudposse.com. docs-styles 提供了一套 CSS 样式和颜色约定，用于 docs.cloudposse.com。 docs-styles は、docs.cloudposse.com 用の CSS スタイルと色規約を提供します。 docs-styles 는 docs.cloudposse.com 용 CSS 스타일과 색상 규칙을 제공합니다. Estilos de documentación para Terraform, AWS, Datadog y GitHub Actions. Define paletas de colores y estilos CSS para docs.cloudposse.com Styles de documentation pour Terraform, AWS, Datadog et GitHub Actions. Définit des palettes de couleurs et des styles CSS pour docs.cloudposse.com Dokumentationsstile für Terraform, AWS, Datadog und GitHub Actions. Definiert Farbpaletten und CSS-Stile für docs.cloudposse.com O skill docs-styles fornece estilos de documentação para Terraform, Datadog e GitHub Actions, incluindo paleta de cores e convenções de CSS. Сkill docs-styles обеспечивает стили документации для Terraform, Datadog и GitHub Actions, включая цветовую палитру и соглашения CSS. المهارة docs-styles توفر أساليب وثائق لترافورم، داتادوغ وجيت هاب أكشنز، بما في ذلك لوحة الألوان وأساليب CSS. docs-styles CSS styles color conventions color palettes variable definitions Light mode Dark mode Terraform AWS Datadog GitHub Actions docs-styles CSS 样式 颜色约定 色板 变量定义 Light 模式 Dark 模式 AIエージェント Provides color palettes and variable definitions Supports Light and Dark modes Defines Primary, Hover, and Active state colors Uses CSS variables to define colors Compatible with docs.cloudposse.com docs-styles is a set of CSS styles and color conventions for docs.cloudposse.com');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('lylo/pagecord/ci', 'community', 'lylo', 'pagecord', 'lylo/pagecord', 'ci', 0, 0, 33, '2026-03-08T01:57:15.292Z', '2026-03-08T02:01:04.604Z', '53a042173d57d58c5c41bd709730865d55277fa3ef7c7a9421c114f1eed06149', '{"id":"lylo/pagecord/ci","name":"ci","description":{"en":"CI automates testing for developers, running security scans with Brakeman and style checks with Rubocop. It benefits developers by ensuring code quality and security.","zh":"CI 持续集成使得博客发布变得容易。通过 Brakeman、Rubocop、Importmap Audit 等工具进行安全扫描、风格检查和依赖检查","ja":"CI パイプラインをローカルで実行することで、ボグのようなエラーを事前に発見できます。Brakeman、Rubocop、Importmap Audit などを使用します","ko":"CI 설정을 통해 자동화된 테스트 및 보안 스캔을 수행할 수 있습니다. Unit Tests, System Tests, Importmap Audit 등 다양한工具을 지원합니다","es":"La integración continua (CI) es crucial para el desarrollo de software. Con esta guía, aprende a configurar tu pipeline de CI con herramientas como Brakeman y Rubocop.","fr":"L''intégration continue (CI) est essentielle pour le développement de logiciels. Avec ce guide, découvrez comment configurer votre pipeline de CI avec des outils tels que Brakeman et Rubocop.","de":"Die kontinuierliche Integration (CI) ist entscheidend für die Softwareentwicklung. Mit diesem Leitfaden erfahren Sie, wie Sie Ihre CI-Pipeline mit Tools wie Brakeman und Rubocop konfigurieren.","pt":"O CI é uma ferramenta que executa pipelines locais, incluindo verificações de segurança e estilo de código, para garantir a qualidade do código","ru":"ИИ Агент CI - это инструмент, который запускает местные пайплайны, включая проверки безопасности и стиля кода, для обеспечения качества кода","ar":"CI هو أداة تقوم بتشغيل أنابيب محلية، بما في ذلك فحوصات الأمان وأسلوب الكود، لضمان جودة الكود"},"seo":{"title":{"en":"CI: Automated Testing Setup Guide | AI Agent Skill","zh":"CI 持续集成设置指南","ja":"CI パイプラインのローカル実行 - AIエージェント","ko":"CI 설정 가이드 - 자동화된 테스트 및 보안 스캔","es":"Guía de Configuración de CI: Mejores Prácticas para el De...","fr":"Guide de Configuration de CI : Meilleures Pratiques pour ...","de":"CI-Setup-Leitfaden: Best Practices für die Entwicklung","pt":"Guia de Configuração CI: Executando Pipelines Locais","ru":"ИИ Агент CI: Руководство по Настройке Местных Пайплайнов","ar":"دليل إعداد CI: تشغيل أنابيب محلية"},"description":{"en":"Streamline your development workflow with CI, featuring Brakeman security scans and Rubocop style checks - learn how to set it up now!","zh":"了解 CI 持续集成的技术细节，包括 Brakeman 安全扫描、Rubocop 风格检查等","ja":"CI パイプラインをローカルで実行する方法を紹介。Brakeman、Rubocop、Importmap Audit など","ko":"CI 설정을 위한 기술 가이드. Unit Tests, System Tests, Importmap Audit 등 자동화된 테스트 및 보안 스캔","es":"Aprende a configurar tu pipeline de CI con Brakeman, Rubocop, Importmap Audit y pruebas unitarias para asegurar la calidad de tu código","fr":"Découvrez comment configurer votre pipeline de CI avec Brakeman, Rubocop, Importmap Audit et des tests unitaires pour assurer la qualité de votre code","de":"Erfahren Sie, wie Sie Ihre CI-Pipeline mit Brakeman, Rubocop, Importmap Audit und Unit-Tests für eine höhere Code-Qualität konfigurieren","pt":"Aprenda a executar pipelines CI locais com facilidade, incluindo verificações de segurança e estilo de código","ru":"Узнайте, как запускать местные пайплайны CI с легкостью, включая проверки безопасности и стиля кода","ar":"تعلم كيفية تشغيل أنابيب CI المحلية بسهولة، بما في ذلك فحوصات الأمان وأسلوب الكود"},"definition":{"en":"ci is a continuous integration tool that automates testing and security scans for developers, ensuring code quality and security.","zh":"CI 是一种持续集成的方法，通过自动化的测试和安全扫描来确保代码质量","ja":"CI は、継続的なインテグレーションを意味し、自動テストとセキュリティスキャンを使用してコード品質を確保します","ko":"CI는 지속적인 통합을 의미하며, 자동화된 테스트와 보안 스캔을 통해 코드 품질을 보장합니다","es":"La integración continua (CI) es una práctica de desarrollo de software que implica la integración automática de código en un repositorio centralizado","fr":"L''intégration continue (CI) est une pratique de développement de logiciels qui consiste à intégrer automatiquement du code dans un référentiel centralisé","de":"Die kontinuierliche Integration (CI) ist eine Praxis der Softwareentwicklung, bei der Code automatisch in ein zentrales Repository integriert wird","pt":"CI é uma ferramenta de integração contínua que executa pipelines locais para garantir a qualidade do código","ru":"ИИ Агент CI - это инструмент непрерывной интеграции, который запускает местные пайплайны для обеспечения качества кода","ar":"CI هو أداة تكامل مستمر تقوم بتشغيل أنابيب محلية لضمان جودة الكود"},"features":{"en":["Runs Brakeman security scans to identify vulnerabilities","Executes Rubocop style checks to enforce coding standards","Performs Importmap Audit for JavaScript dependency management","Runs Unit Tests with bin/rails test for code validation","Executes System Tests with bin/rails test:system for end-to-end validation"],"zh":["Brakeman 安全扫描","Rubocop 风格检查","Importmap Audit 依赖检查","Unit Tests 单元测试","System Tests 系统测试"],"ja":["Brakeman セキュリティスキャン","Rubocop スタイルチェック","Importmap Audit 依存関係チェック","Unit Tests ユニットテスト","System Tests システムテスト"],"ko":["Brakeman 보안 스캔","Rubocop 스타일 체크","Importmap Audit 의존성 체크","Unit Tests 유닛 테스트","System Tests 시스템 테스트"],"es":["Análisis de seguridad con Brakeman","Verificación de estilo con Rubocop","Análisis de dependencias de JavaScript con Importmap Audit","Ejecución de pruebas unitarias con bin/rails test","Ejecución de pruebas de sistema con bin/rails test:system"],"fr":["Analyse de sécurité avec Brakeman","Vérification de style avec Rubocop","Analyse de dépendances JavaScript avec Importmap Audit","Exécution de tests unitaires avec bin/rails test","Exécution de tests de système avec bin/rails test:system"],"de":["Sicherheitsanalyse mit Brakeman","Stilprüfung mit Rubocop","Analyse von JavaScript-Abhängigkeiten mit Importmap Audit","Ausführung von Unit-Tests mit bin/rails test","Ausführung von Systemtests mit bin/rails test:system"],"pt":["Verificação de segurança com Brakeman","Verificação de estilo de código com Rubocop","Análise de dependências JavaScript com Importmap Audit","Execução de testes unitários com Rails","Execução de testes de sistema com Rails"],"ru":["Проверка безопасности с помощью Brakeman","Проверка стиля кода с помощью Rubocop","Анализ зависимостей JavaScript с помощью Importmap Audit","Выполнение юнит-тестов с помощью Rails","Выполнение системных тестов с помощью Rails"],"ar":["فحص الأمان مع Brakeman","فحص أسلوب الكود مع Rubocop","تحليل الإعتماديات JavaScript مع Importmap Audit","تشغيل الاختبارات الوحدوية مع Rails","تشغيل الاختبارات النظامية مع Rails"]},"keywords":{"en":["how to use ci","ci setup guide","what is ci","ci vs jenkins","ci install","continuous integration tutorial","automated testing with ci","ci pipeline setup","ci alternative"],"zh":["CI 持续集成","Brakeman 安全扫描","Rubocop 风格检查","Importmap Audit 依赖检查","自动化测试","代码质量保证","AIエージェント"],"ja":["CI パイプライン","Brakeman セキュリティスキャン","Rubocop スタイルチェック","Importmap Audit 依存関係チェック","自動テスト","コード品質保証","AIエージェント"],"ko":["CI 설정","Brakeman 보안 스캔","Rubocop 스타일 체크","Importmap Audit 의존성 체크","자동화된 테스트","코드 품질 보장","AI 툴"],"es":["integración continua","desarrollo de software","Brakeman","Rubocop","Importmap Audit","pruebas unitarias","pruebas de sistema","CI pipeline","configuración de CI"],"fr":["intégration continue","développement de logiciels","Brakeman","Rubocop","Importmap Audit","tests unitaires","tests de système","pipeline de CI","configuration de CI"],"de":["kontinuierliche Integration","Softwareentwicklung","Brakeman","Rubocop","Importmap Audit","Unit-Tests","Systemtests","CI-Pipeline","CI-Konfiguration"],"pt":["ci","integração contínua","pipeline local","verificação de segurança","verificação de estilo de código","importmap audit","testes unitários","testes de sistema","rails"],"ru":["ИИ Агент CI","непрерывная интеграция","местный пайплайн","проверка безопасности","проверка стиля кода","importmap audit","юнит-тесты","системные тесты","rails"],"ar":["ci","تكامل مستمر","أنابيب محلية","فحص الأمان","فحص أسلوب الكود","importmap audit","اختبارات وحدوية","اختبارات نظامية","rails"]}},"owner":"lylo","repo":"pagecord","repoPath":"lylo/pagecord","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.292Z","topics":[],"category":"community","skillMd":{"name":"ci","description":"Run the CI pipeline locally (brakeman, rubocop, importmap audit, tests). Use when asked to run CI, check code quality, or verify code before pushing.","bodyPreview":"# CI\n\nRun the CI pipeline locally before pushing.\n\n## Steps\n\nRun these commands in sequence, stopping on first failure:\n\n1. **Brakeman** (security scan)\n   ```bash\n   bundle exec brakeman --quiet --no-pager --ensure-latest\n   ```\n\n2. **Rubocop** (style check)\n   ```bash\n   bundle exec rubocop\n   ```\n\n3. **Importmap Audit** (JS dependency check)\n   ```bash\n   bin/importmap audit\n   ```\n\n4. **Unit Tests**\n   ```bash\n   bin/rails test\n   ```\n\n5. **System Tests**\n   ```bash\n   bin/rails test:system","body":"# CI\n\nRun the CI pipeline locally before pushing.\n\n## Steps\n\nRun these commands in sequence, stopping on first failure:\n\n1. **Brakeman** (security scan)\n   ```bash\n   bundle exec brakeman --quiet --no-pager --ensure-latest\n   ```\n\n2. **Rubocop** (style check)\n   ```bash\n   bundle exec rubocop\n   ```\n\n3. **Importmap Audit** (JS dependency check)\n   ```bash\n   bin/importmap audit\n   ```\n\n4. **Unit Tests**\n   ```bash\n   bin/rails test\n   ```\n\n5. **System Tests**\n   ```bash\n   bin/rails test:system\n   ```\n\n## Behavior\n\n- Run all checks in sequence\n- Stop and report on first failure\n- Summarize results at the end as a table:\n\n| Step | Status |\n|------|--------|\n| Brakeman (security) | ✅ Passed |\n| Rubocop (style) | ✅ Passed |\n| Importmap Audit (JS deps) | ✅ Passed |\n| Unit Tests | ✅ X tests passed |\n| System Tests | ✅ X tests passed |\n\n- If all pass, confirm the code is ready to push\n"},"lastSynced":"2026-03-08T02:01:04.604Z","agentAnalysis":{"suitability":{"en":"Ideal for Development Agents requiring automated code quality and security checks using Brakeman and Rubocop.","zh":"适用于需要使用 Brakeman 和 Rubocop 进行自动化代码质量和安全检查的开发代理。","ja":"Brakeman と Rubocop を使用して自動化されたコード品質とセキュリティチェックを必要とする開発エージェントに適しています。","ko":"Brakeman과 Rubocop을 사용하여 자동화된 코드 품질 및 보안 검사를 필요한 개발 에이전트에 적합합니다.","es":"Ideal para agentes de desarrollo que requieren controles automáticos de calidad y seguridad de código utilizando Brakeman y Rubocop.","fr":"Idéal pour les agents de développement nécessitant des vérifications automatiques de la qualité et de la sécurité du code à l''aide de Brakeman et Rubocop.","de":"Ideal für Entwicklungsmittel, die automatisierte Code-Qualitäts- und Sicherheitsprüfungen mit Brakeman und Rubocop erfordern.","pt":"Ideal para Agentes de Desenvolvimento que requerem verificações automatizadas de qualidade e segurança de código usando Brakeman e Rubocop.","ru":"Идеально для агентов разработки, требующих автоматизированных проверок качества и безопасности кода с помощью Brakeman и Rubocop.","ar":"مثالي للوكلاء النموزجيون الذين يتطلبون فحص جودة و أمن شفرة آلي باستخدام Brakeman و Rubocop."},"recommendation":{"en":"Empowers agents to ensure code integrity by running security scans with Brakeman, style checks with Rubocop, and executing unit and system tests, all while utilizing Importmap for JS dependency audits and supporting protocols like bundle exec.","zh":"赋予代理人通过运行 Brakeman 的安全扫描、Rubocop 的样式检查和执行单元和系统测试来确保代码完整性，同时利用 Importmap 进行 JS 依赖项审计并支持诸如 bundle exec 之类的协议。","ja":"Brakeman のセキュリティスキャン、Rubocop のスタイルチェック、単体およびシステムテストの実行により、コードの完全性を確保するエージェントをEmpowerします。また、Importmap を使用した JS 依存関係の監査や bundle exec などのプロトコルのサポートも提供します。","ko":"Brakeman의 보안 스캔, Rubocop의 스타일 체크, 단위 및 시스템 테스트의 실행을 통해 코드의 완전성을 보장하는 에이전트를 Empower합니다. 또한 Importmap을 사용한 JS 종속성 감사 및 bundle exec와 같은 프로토콜 지원도 제공합니다.","es":"Habilita a los agentes a garantizar la integridad del código mediante la ejecución de análisis de seguridad con Brakeman, comprobaciones de estilo con Rubocop y la ejecución de pruebas unitarias y de sistema, todo mientras se utiliza Importmap para auditorías de dependencias de JS y se admiten protocolos como bundle exec.","fr":"Permet aux agents de garantir l''intégrité du code en exécutant des analyses de sécurité avec Brakeman, des vérifications de style avec Rubocop et en exécutant des tests unitaires et système, le tout en utilisant Importmap pour les audits de dépendances JS et en prenant en charge des protocoles comme bundle exec.","de":"Ermächtigt die Mittel, die Code-Integrität durch Ausführung von Sicherheitsprüfungen mit Brakeman, Stilprüfungen mit Rubocop und Ausführung von Einheits- und Systemtests sicherzustellen, und zwar unter Verwendung von Importmap für JS-Abhängigkeitsaudits und Unterstützung von Protokollen wie bundle exec.","pt":"Permite que os agentes garantam a integridade do código executando verificações de segurança com Brakeman, verificações de estilo com Rubocop e executando testes unitários e de sistema, tudo enquanto utiliza Importmap para auditorias de dependência JS e suporta protocolos como bundle exec.","ru":"Наделяет агентов возможностью обеспечить целостность кода, запуская сканирования безопасности с помощью Brakeman, проверки стилей с помощью Rubocop и выполняя модульные и системные тесты, все это при использовании Importmap для аудита зависимостей JS и поддержке протоколов như bundle exec.","ar":"يمنح الوكلاء ضمان سلامة الشفرة من خلال تشغيل فحوصات أمنية مع Brakeman، وفحوصات أسلوب مع Rubocop، وتنفيذ اختبارات الوحدة والنظام، كل ذلك أثناء استخدام Importmap لمحاسبة التبعيات JS ودعم البروتوكولات مثل bundle exec."},"useCases":{"en":["Automating code security audits with Brakeman","Enforcing coding standards with Rubocop","Validating JavaScript dependencies using Importmap","Executing unit and system tests for code reliability"],"zh":["使用 Brakeman 自动化代码安全审计","使用 Rubocop 强制编码标准","使用 Importmap 验证 JavaScript 依赖项","执行单元和系统测试以确保代码可靠性"],"ja":["Brakeman を使用したコードセキュリティ監査の自動化","Rubocop を使用したコード規約の適用","Importmap を使用した JavaScript 依存関係の検証","コードの信頼性を確保するための単体およびシステムテストの実行"],"ko":["Brakeman을 사용한 코드 보안 감사의 자동화","Rubocop을 사용한 코드 규약의 적용","Importmap을 사용한 JavaScript 종속성의 검증","코드의 신뢰성을 보장하기 위한 단위 및 시스템 테스트의 실행"],"es":["Automatización de auditorías de seguridad de código con Brakeman","Aplicación de normas de codificación con Rubocop","Validación de dependencias de JavaScript mediante Importmap","Ejecución de pruebas unitarias y de sistema para la confiabilidad del código"],"fr":["Automatisation des audits de sécurité de code avec Brakeman","Application des normes de codage avec Rubocop","Validation des dépendances JavaScript à l''aide d''Importmap","Exécution de tests unitaires et système pour la fiabilité du code"],"de":["Automatisierung von Code-Sicherheitsaudits mit Brakeman","Durchsetzung von Codierungsstandards mit Rubocop","Überprüfung von JavaScript-Abhängigkeiten mit Importmap","Ausführung von Einheits- und Systemtests für die Code-Zuverlässigkeit"],"pt":["Automatizar auditorias de segurança de código com Brakeman","Impor padrões de codificação com Rubocop","Validar dependências JavaScript usando Importmap","Executar testes unitários e de sistema para confiabilidade do código"],"ru":["Автоматизировать аудиты безопасности кода с помощью Brakeman","Внедрять стандарты кодирования с помощью Rubocop","Проверять зависимости JavaScript с помощью Importmap","Выполнять модульные и системные тесты для надежности кода"],"ar":["تأتمت hóa تدقيق أمان الشفرة مع Brakeman","تطبيق معايير الترميز مع Rubocop","تحقق من التبعيات جافا سكريبت باستخدام Importmap","تنفيذ اختبارات الوحدة والنظام لموثوقية الشفرة"]},"limitations":{"en":["Requires Ruby environment with bundle exec","Specific to Rails applications","Needs Brakeman and Rubocop installed"],"zh":["需要具有 bundle exec 的 Ruby 环境","特定于 Rails 应用程序","需要安装 Brakeman 和 Rubocop"],"ja":["bundle exec を持つ Ruby 環境が必要","Rails アプリケーションに特有","Brakeman と Rubocop のインストールが必要"],"ko":["bundle exec를 가진 Ruby 환경이 필요","Rails 애플리케이션에 특정","Brakeman과 Rubocop의 설치가 필요"],"es":["Requiere entorno de Ruby con bundle exec","Específico para aplicaciones Rails","Requiere Brakeman y Rubocop instalados"],"fr":["Nécessite un environnement Ruby avec bundle exec","Spécifique aux applications Rails","Nécessite l''installation de Brakeman et Rubocop"],"de":["Benötigt Ruby-Umgebung mit bundle exec","Spezifisch für Rails-Anwendungen","Benötigt die Installation von Brakeman und Rubocop"],"pt":["Requer ambiente Ruby com bundle exec","Específico para aplicações Rails","Necessita Brakeman e Rubocop instalados"],"ru":["Требует среды Ruby с bundle exec","Специфичен для приложений Rails","Требует установленного Brakeman и Rubocop"],"ar":["يتطلب بيئة Ruby مع bundle exec","محدد لتطبيقات Rails","يحتاج إلى تثبيت Brakeman و Rubocop"]},"version":4},"contentHash":"53a042173d57d58c5c41bd709730865d55277fa3ef7c7a9421c114f1eed06149","qualityScore":33}');
