INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('yxhpy/qcc_plus/qcc-git', 'qcc-git', 'yxhpy', 'qcc_plus', 'community', 'qcc-git yxhpy qcc_plus community qcc-git automates Git workflows for development teams, ensuring all work is done on the ''test'' branch and deploying to testing environments automatically. It benefits developers by simplifying the development and deployment process. qcc-git 是一个多租户、自动故障切换的 Git 工作流工具，提供 Web 管理界面 qcc-git はマルチテナントと自動フェイルオーバーの Git ワークフロー ツールで、Web 管理インターフェースを提供します qcc-git은 멀티 테넌트 및 자동 장애 조치 Git 작업 흐름 도구로 웹 관리 인터페이스를 제공합니다 qcc-git es un CLI que facilita la automatización de flujos de trabajo de Git, con características como la gestión de ramas y la implementación automática qcc-git est un CLI qui facilite l''automatisation des flux de travail Git, avec des fonctionnalités telles que la gestion de branches et le déploiement automatique qcc-git ist ein CLI, das die Automatisierung von Git-Arbeitsabläufen erleichtert, mit Funktionen wie Branch-Verwaltung und automatischer Bereitstellung O qcc-git é uma ferramenta de linha de comando que facilita o fluxo de trabalho de código com recursos como múltiplos branches e deploy automático qcc-git - это инструмент командной строки, который упрощает рабочий процесс кода с функциями, такими как несколько веток и автоматическое развертывание qcc-git هو أداة سطر الأوامر التي تسهل تدفق عمل الكود مع ميزات مثل الفروع المتعددة والتشغيل التلقائي how to use qcc-git qcc-git setup guide qcc-git vs gitflow automated git workflow git branch strategy qcc-git install git workflow automation tools qcc-git documentation git deployment automation qcc-git Git 工作流自动化 多租户 Git 自动故障切换 Web 管理界面 Git Tag 发布版本 强制分支策略 自动部署 Enforces a branch strategy with ''test'', ''main'', and ''prod'' branches Automatically deploys code to testing environments on ''test'' branch push Supports Git commands like ''git checkout'' and ''git merge'' for workflow management Automates tagging and releasing code on the ''main'' branch Deploys code to production servers on the ''prod'' branch Provides a web management interface for multi-tenant and fault-tolerant operations qcc-git is a Git workflow automation tool that enforces branch strategies and automates deployment to testing and production environments.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('finos/morphir/release-manager', 'community', 'finos', 'morphir', 'finos/morphir', 'release-manager', 0, 0, 33, '2026-03-08T01:57:15.295Z', '2026-03-08T02:01:11.817Z', '26039204c1d9fcf8fdc79e64ca92c93ce16a1164d27ecc006b66c029f21153e5', '{"id":"finos/morphir/release-manager","name":"release-manager","description":{"en":"The release-manager skill helps developers ensure smooth Morphir releases by automating pre-release verification, changelog management, and version coordination. It benefits development teams by reducing manual errors and increasing efficiency.","zh":"Release Manager Skill是一种Morphir发布管理助手，帮助确保发布的正确性和完整性","ja":"Release Manager SkillはMorphirのリリース管理アシスタントであり、リリースの正確性と完全性を確保するのに役立ちます","ko":"Release Manager Skill은 Morphir 릴리즈 관리 도구로서 릴리즈의 정확성과 완전성을 보장하는 데 도움이 됩니다","es":"Release Manager es una herramienta para verificar, documentar y coordinar lanzamientos de software, incluyendo verificación previa al lanzamiento y gestión de changelogs","fr":"Release Manager est un outil pour vérifier, documenter et coordonner les lancements de logiciels, y compris la vérification préalable au lancement et la gestion des changelogs","de":"Release Manager ist ein Tool zum Überprüfen, Dokumentieren und Koordinieren von Software-Veröffentlichungen, einschließlich der Überprüfung vor der Veröffentlichung und der Changelog-Verwaltung","pt":"O Release Manager é uma ferramenta especializada em gerenciar releases de software, garantindo a verificação, documentação e coordenação adequadas","ru":"Release Manager - это специализированный инструмент для управления релизами программного обеспечения, обеспечивающий проверку, документацию и координацию","ar":"إدارة الإصدار هي أداة متخصصة في إدارة إصدارات البرمجيات، مما يضمن التحقق والتوثيق والتنسيق المناسبين"},"seo":{"title":{"en":"release-manager: Automated Release Workflow Se