INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('finos/morphir/release-manager', 'release-manager', 'finos', 'morphir', 'community', 'release-manager finos morphir community The release-manager skill helps developers ensure smooth Morphir releases by automating pre-release verification, changelog management, and version coordination. It benefits development teams by reducing manual errors and increasing efficiency. Release Manager Skill是一种Morphir发布管理助手，帮助确保发布的正确性和完整性 Release Manager SkillはMorphirのリリース管理アシスタントであり、リリースの正確性と完全性を確保するのに役立ちます Release Manager Skill은 Morphir 릴리즈 관리 도구로서 릴리즈의 정확성과 완전성을 보장하는 데 도움이 됩니다 Release Manager es una herramienta para verificar, documentar y coordinar lanzamientos de software, incluyendo verificación previa al lanzamiento y gestión de changelogs Release Manager est un outil pour vérifier, documenter et coordonner les lancements de logiciels, y compris la vérification préalable au lancement et la gestion des changelogs Release Manager ist ein Tool zum Überprüfen, Dokumentieren und Koordinieren von Software-Veröffentlichungen, einschließlich der Überprüfung vor der Veröffentlichung und der Changelog-Verwaltung O Release Manager é uma ferramenta especializada em gerenciar releases de software, garantindo a verificação, documentação e coordenação adequadas Release Manager - это специализированный инструмент для управления релизами программного обеспечения, обеспечивающий проверку, документацию и координацию إدارة الإصدار هي أداة متخصصة في إدارة إصدارات البرمجيات، مما يضمن التحقق والتوثيق والتنسيق المناسبين how to use release-manager release-manager setup guide release-manager alternative release-manager vs morphir automated release workflow morphir release management Release Manager Morphir发布管理 AI工具 预发布验证 变更日志管理 版本管理 发布工作流管理 Runs pre-release verification checks to ensure release quality Generates and reviews changelogs for accurate release documentation Coordinates version bumps to maintain consistent versioning Manages the release workflow to reduce manual errors and increase efficiency release-manager is a specialized AI agent skill for coordinating and verifying Morphir releases, ensuring proper documentation and version management.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('marcglasberg/async_redux/asyncredux-persistence', 'community', 'marcglasberg', 'async_redux', 'marcglasberg/async_redux', 'asyncredux-persistence', 0, 0, 33, '2026-03-08T01:57:15.296Z', '2026-03-08T02:01:14.719Z', 'ac2c47d0f707b4154d017975f237601f43ff2093e2d0b078bfa67ee84bf3cc89', '{"id":"marcglasberg/async_redux/asyncredux-persistence","name":"asyncredux-persistence","description":{"en":"asyncredux-persistence provides state management for Flutter, enabling app state restoration between sessions. It benefits developers by maintaining state on disk using a persistor object.","zh":"AsyncRedux 提供了强大的状态管理功能，通过持久化实现应用状态的保存和恢复","ja":"AsyncRedux は強力な状態管理機能を提供し、永続化によりアプリ状態を保存および復元します","ko":"AsyncRedux는 강력한 상태 관리 기능을 제공하며 지속화 통해 애플리케이션 상태를 저장 및 복원합니다","es":"Asyncredux-persistence proporciona gestión de estado persistente para Flutter, manteniendo el estado de la aplicación en disco","fr":"Asyncredux-persistence offre une gestion d''état persistante pour Flutter, en conservant l''état de l''application sur disque","de":"Asyncredux-persistence bietet persistente Zustandverwaltung für Flutter, indem der Anwendungsstatus auf der Festplatte gespeichert wird","pt":"O asyncredux-persistence é uma ferramenta poderosa para gerenciamento de estado em Flutter, permitindo a persistência de dados entre sessões.","ru":"asyncredux-persistence - это мощный инструмент для управления состоянием в Flutter, обеспечивающий сохранение данных между сессиями.","ar":"asyncredux-persistence هو أداة قوية لإدارة الحالة في تطبيقات Flutter، مما يسمح بالاستمرارية بين الجلسات."},"seo":{"title":{"en":"asyncredux-persistence: State Management Setup Guide | AI...","zh":"AsyncRedux 持久化设置指南","ja":"AsyncRedux 永続化のベストプラクティス","ko":"AsyncRedux 지속성 설정 가이드","es":"Guía de configuración de asyncredux-persistence para Flutter","fr":"Guide de mise en place d''asyncredux-persistence pour Flutter","de":"Einrichtungsleitfaden für asyncredux-persistence in Flutter","pt":"Guia de Configuração do asyncredux-persistence para Geren...","ru":"Настройка asyncredux-persistence для управления состояние...","ar":"دليل إعداد asyncredux-persistence لإدارة الحالة في تطبيقا..."},"description":{"en":"Discover how to implement state persistence in Flutter with asyncredux-persistence. Learn how to initialize the store with a persistor object and restore app...","zh":"学习如何使用 AsyncRedux 实现 Flutter 应用的状态持久化，提高用户体验","ja":"AsyncRedux を使用して Flutter アプリの状態を永続化し、ユーザーエクスペリエンスを向上させる方法","ko":"AsyncRedux를 사용하여 Flutter 애플리케이션의 상태를 지속화하고 사용자 경험을 향상시키는 방법","es":"Aprende a implementar la persistencia de estado en Flutter con asyncredux-persistence y mejora la experiencia del usuario","fr":"Découvrez comment mettre en œuvre la persistance d''état dans Flutter avec asyncredux-persistence et améliorez l''expérience utilisateur","de":"Erfahren Sie, wie Sie die Zustandspersistenz in Flutter mit asyncredux-persistence implementieren und die Benutzererfahrung verbessern","pt":"Aprenda a configurar o asyncredux-persistence para gerenciar o estado da sua aplicação Flutter de forma eficaz","ru":"Узнайте, как настроить asyncredux-persistence для управления состоянием в ваших приложениях Flutter с помощью ИИ Агентов","ar":"تعرف على كيفية إعداد asyncredux-persistence لإدارة الحالة في تطبيقات Flutter بشكل فعال مع أدوات الذكاء الاصطناعي"},"definition":{"en":"asyncredux-persistence is a state management solution for Flutter that maintains app state on disk, enabling restoration between sessions using a persistor object.","zh":"AsyncRedux 持久化是指使用 AsyncRedux 库实现 Flutter 应用的状态持久化","ja":"AsyncRedux 永続化は、AsyncRedux ライブラリを使用して Flutter アプリの状態を永続化すること","ko":"AsyncRedux 지속성은 AsyncRedux 라이브러리를 사용하여 Flutter 애플리케이션의 상태를 지속화하는 것","es":"Asyncredux-persistence es una herramienta de gestión de estado para Flutter que mantiene el estado de la aplicación entre sesiones","fr":"Asyncredux-persistence est un outil de gestion d''état pour Flutter qui maintient l''état de l''application entre les sessions","de":"Asyncredux-persistence ist ein Zustandsverwaltungstool für Flutter, das den Anwendungsstatus zwischen den Sitzungen beibehält","pt":"O que é asyncredux-persistence? É uma biblioteca para gerenciamento de estado em Flutter que fornece persistência de dados.","ru":"Что такое asyncredux-persistence? Это библиотека для управления состоянием в Flutter, обеспечивающая сохранение данных.","ar":"ما هو asyncredux-persistence؟ هو مكتبة لإدارة الحالة في تطبيقات Flutter توفر استمرارية البيانات."},"features":{"en":["Initializes the store with a persistor object to maintain app state on disk","Restores app state between sessions using the persistor object","Creates default state if none exists on disk","Reads existing state from disk using the readState method","Supports state persistence using a custom persistor object"],"zh":["使用 persistor 对象实现应用状态的持久化","支持读取和写入应用状态","可以与 AsyncRedux 库集成使用","提供默认状态创建和初始化功能","支持状态恢复和保存"],"ja":["persistor オブジェクトを使用してアプリ状態を永続化","アプリ状態の読み取りと書き込みをサポート","AsyncRedux ライブラリとの統合が可能","デフォルト状態の作成と初期化機能を提供","状態の復元と保存をサポート"],"ko":["persistor 객체를 사용하여 애플리케이션 상태를 지속화","애플리케이션 상태의 읽기와 쓰기를 지원","AsyncRedux 라이브러리와의 통합이 가능","기본 상태 생성과 초기화 기능을 제공","상태 복원과 저장을 지원"],"es":["Gestión de estado persistente para Flutter","Mantiene el estado de la aplicación en disco","Restaura el estado de la aplicación entre sesiones","Incorpora un objeto persistor para inicializar la tienda","Permite la lectura y escritura de estado en disco"],"fr":["Gestion d''état persistante pour Flutter","Conserve l''état de l''application sur disque","Restaure l''état de l''application entre les sessions","Intègre un objet persistor pour initialiser la boutique","Permet la lecture et l''écriture de l''état sur disque"],"de":["Persistente Zustandverwaltung für Flutter","Speichert den Anwendungsstatus auf der Festplatte","Stellt den Anwendungsstatus zwischen den Sitzungen wieder her","Integriert ein Persistor-Objekt zur Initialisierung des Stores","Ermöglicht das Lesen und Schreiben von Zuständen auf der Festplatte"],"pt":["Persistência de estado entre sessões","Inicialização do store com persistor","Leitura e gravação de estado em disco","Criação de estado inicial se nenhum existir","Integração com a biblioteca AsyncRedux"],"ru":["Сохранение состояния между сессиями","Инициализация хранилища с persistor","Чтение и запись состояния на диск","Создание начального состояния, если его нет","Интеграция с библиотекой AsyncRedux"],"ar":["استمرارية الحالة بين الجلسات","ت 初ية المتجر مع persistor","قراءة وكتابة الحالة على القرص","إنشاء حالة أولية إذا لم تكن موجودة","التكامل مع مكتبة AsyncRedux"]},"keywords":{"en":["how to use asyncredux-persistence","asyncredux-persistence setup guide","asyncredux-persistence vs flutter_redux","asyncredux-persistence install","what is asyncredux-persistence","asyncredux-persistence documentation","asyncredux-persistence example","asyncredux-persistence flutter","asyncredux-persistence state management"],"zh":["AsyncRedux 持久化","Flutter 状态管理","持久化设置指南","AsyncRedux 教程","Flutter 应用开发","状态管理最佳实践"],"ja":["AsyncRedux 永続化","Flutter 状態管理","永続化設定ガイド","AsyncRedux チュートリアル","Flutter アプリ開発","状態管理ベストプラクティス"],"ko":["AsyncRedux 지속성","Flutter 상태 관리","지속성 설정 가이드","AsyncRedux 튜토리얼","Flutter 애플리케이션 개발","상태 관리 최고의 실践"],"es":["asyncredux-persistence","gestión de estado en Flutter","persistencia de estado en Flutter","herramientas de AI para desarrolladores","estado de la aplicación en Flutter","sesiones de usuario en Flutter"],"fr":["asyncredux-persistence","gestion d''état dans Flutter","persistance d''état dans Flutter","outils d''IA pour les développeurs","état de l''application dans Flutter","sessions utilisateur dans Flutter"],"de":["asyncredux-persistence","Zustandverwaltung in Flutter","Zustandspersistenz in Flutter","AI-Tools für Entwickler","Anwendungsstatus in Flutter","Benutzersitzungen in Flutter"],"pt":["asyncredux-persistence","gerenciamento de estado flutter","persistência de dados","estado da aplicação","configuração asyncredux","flutter state management","estado da aplicação flutter"],"ru":["asyncredux-persistence","управление состоянием flutter","сохранение данных","состояние приложения","настройка asyncredux","flutter state management","состояние приложения flutter","ИИ Агенты"],"ar":["asyncredux-persistence","إدارة الحالة في تطبيقات Flutter","استمرارية البيانات","حالة التطبيق","إعداد asyncredux","flutter state management","حالة التطبيق في Flutter","أدوات الذكاء الاصطناعي"]}},"owner":"marcglasberg","repo":"async_redux","repoPath":"marcglasberg/async_redux","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.296Z","topics":[],"category":"community","skillMd":{"name":"asyncredux-persistence","description":"Implement local state persistence using Persistor. Covers creating a custom Persistor class, implementing `readState()`, `persistDifference()`, `deleteState()`, using LocalPersist helper, throttling saves, and pausing/resuming persistence with app lifecycle.","bodyPreview":"## Overview\n\nAsyncRedux provides state persistence by passing a `persistor` object to the Store. This maintains app state on disk, enabling restoration between sessions.\n\n## Store Initialization with Persistor\n\nAt startup, read any existing state from disk, create default state if none exists, then initialize the store:\n\n```dart\nvar persistor = MyPersistor();\n\nvar initialState = await persistor.readState();\n\nif (initialState == null) {\n  initialState = AppState.initialState();\n  await persistor.","body":"## Overview\n\nAsyncRedux provides state persistence by passing a `persistor` object to the Store. This maintains app state on disk, enabling restoration between sessions.\n\n## Store Initialization with Persistor\n\nAt startup, read any existing state from disk, create default state if none exists, then initialize the store:\n\n```dart\nvar persistor = MyPersistor();\n\nvar initialState = await persistor.readState();\n\nif (initialState == null) {\n  initialState = AppState.initialState();\n  await persistor.saveInitialState(initialState);\n}\n\nvar store = Store<AppState>(\n  initialState: initialState,\n  persistor: persistor,\n);\n```\n\n## The Persistor Abstract Class\n\nThe `Persistor<St>` base class defines these methods:\n\n```dart\nabstract class Persistor<St> {\n  /// Read persisted state, or return null if none exists\n  Future<St?> readState();\n\n  /// Delete state from disk\n  Future<void> deleteState();\n\n  /// Save state changes. Provides both newState and lastPersistedState\n  /// so you can compare them and save only the difference.\n  Future<void> persistDifference({\n    required St? lastPersistedState,\n    required St newState\n  });\n\n  /// Convenience method for initial saves\n  Future<void> saveInitialState(St state) =>\n    persistDifference(lastPersistedState: null, newState: state);\n\n  /// Controls save frequency. Return null to disable throttling.\n  Duration get throttle => const Duration(seconds: 2);\n}\n```\n\n## Creating a Custom Persistor\n\nExtend the abstract class and implement the required methods:\n\n```dart\nclass MyPersistor extends Persistor<AppState> {\n\n  @override\n  Future<AppState?> readState() async {\n    // Read state from disk (e.g., from SharedPreferences, file, etc.)\n    return null;\n  }\n\n  @override\n  Future<void> deleteState() async {\n    // Delete state from disk\n  }\n\n  @override\n  Future<void> persistDifference({\n    required AppState? lastPersistedState,\n    required AppState newState,\n  }) async {\n    // Save state to disk.\n    // You can compare lastPersistedState with newState to save only changes.\n  }\n\n  @override\n  Duration get throttle => const Duration(seconds: 2);\n}\n```\n\n## Throttling\n\nThe `throttle` getter controls how often state is saved. All changes within the throttle window are collected and saved in a single call. The default is 2 seconds.\n\n```dart\n// Save at most every 5 seconds\n@override\nDuration get throttle => const Duration(seconds: 5);\n\n// Disable throttling (save immediately on every change)\n@override\nDuration? get throttle => null;\n```\n\n## Forcing Immediate Save\n\nDispatch `PersistAction()` to save immediately, bypassing the throttle:\n\n```dart\nstore.dispatch(PersistAction());\n```\n\n## Pausing and Resuming Persistence\n\nControl persistence with these store methods:\n\n```dart\nstore.pausePersistor();           // Pause saving\nstore.persistAndPausePersistor(); // Save current state, then pause\nstore.resumePersistor();          // Resume saving\n```\n\n## App Lifecycle Integration\n\nPause persistence when the app goes to background and resume when it becomes active. Create an `AppLifecycleManager` widget:\n\n```dart\nclass AppLifecycleManager extends StatefulWidget {\n  final Widget child;\n\n  const AppLifecycleManager({\n    Key? key,\n    required this.child,\n  }) : super(key: key);\n\n  @override\n  _AppLifecycleManagerState createState() => _AppLifecycleManagerState();\n}\n\nclass _AppLifecycleManagerState extends State<AppLifecycleManager>\n    with WidgetsBindingObserver {\n\n  @override\n  void initState() {\n    super.initState();\n    WidgetsBinding.instance.addObserver(this);\n  }\n\n  @override\n  void dispose() {\n    WidgetsBinding.instance.removeObserver(this);\n    super.dispose();\n  }\n\n  @override\n  void didChangeAppLifecycleState(AppLifecycleState lifecycle) {\n    store.dispatch(ProcessLifecycleChange_Action(lifecycle));\n  }\n\n  @override\n  Widget build(BuildContext context) => widget.child;\n}\n```\n\nCreate an action to handle lifecycle changes:\n\n```dart\nclass ProcessLifecycleChange_Action extends ReduxAction<AppState> {\n  final AppLifecycleState lifecycle;\n\n  ProcessLifecycleChange_Action(this.lifecycle);\n\n  @override\n  Future<AppState?> reduce() async {\n    if (lifecycle == AppLifecycleState.resumed ||\n        lifecycle == AppLifecycleState.inactive) {\n      store.resumePersistor();\n    } else if (lifecycle == AppLifecycleState.paused ||\n        lifecycle == AppLifecycleState.detached) {\n      store.persistAndPausePersistor();\n    } else {\n      throw AssertionError(lifecycle);\n    }\n    return null;\n  }\n}\n```\n\nWrap your app with the lifecycle manager:\n\n```dart\nStoreProvider<AppState>(\n  store: store,\n  child: AppLifecycleManager(\n    child: MaterialApp( ... ),\n  ),\n)\n```\n\n## LocalPersist Helper\n\nThe `LocalPersist` class simplifies disk operations for Android/iOS. It works with simple object structures containing only primitives, lists, and maps.\n\n```dart\nimport ''package:async_redux/local_persist.dart'';\n\n// Create instance with a file name\nvar persist = LocalPersist(\"myFile\");\n\n// Save data\nList<Object> simpleObjs = [\n  ''Hello'',\n  42,\n  true,\n  [100, 200, {\"name\": \"John\"}],\n];\nawait persist.save(simpleObjs);\n\n// Load data\nList<Object> loaded = await persist.load();\n\n// Append data\nList<Object> moreObjs = [''more'', ''data''];\nawait persist.save(moreObjs, append: true);\n\n// File operations\nint length = await persist.length();\nbool exists = await persist.exists();\nawait persist.delete();\n\n// JSON operations for single objects\nawait persist.saveJson(simpleObj);\nObject? simpleObj = await persist.loadJson();\n```\n\n**Note:** `LocalPersist` only supports simple objects. For complex nested structures or custom classes, you need to implement serialization yourself (e.g., using JSON encoding with `toJson`/`fromJson` methods).\n\n## References\n\nURLs from the documentation:\n- https://asyncredux.com/sitemap.xml\n- https://asyncredux.com/flutter/miscellaneous/persistence\n- https://asyncredux.com/flutter/basics/store\n- https://asyncredux.com/flutter/miscellaneous/database-and-cloud\n- https://asyncredux.com/flutter/intro\n- https://asyncredux.com/flutter/testing/mocking\n- https://asyncredux.com/flutter/advanced-actions/redux-action\n- https://asyncredux.com/flutter/about\n- https://asyncredux.com/flutter/testing/store-tester\n- https://asyncredux.com/flutter/miscellaneous/advanced-waiting\n"},"lastSynced":"2026-03-08T02:01:14.719Z","agentAnalysis":{"suitability":{"en":"Ideal for Flutter Agents requiring seamless state management and persistence across sessions.","zh":"适用于需要跨会话实现无缝状态管理和持久性的 Flutter Agent。","ja":"セッション間でシームレスな状態管理と永続性を必要とするFlutter Agentに適しています。","ko":"세션 간에 무결점 상태 관리 및 지속성을 요구하는 Flutter Agent에 적합합니다.","es":"Ideal para Agentes de Flutter que requieren una gestión de estado y persistencia perfecta entre sesiones.","fr":"Idéal pour les agents Flutter nécessitant une gestion d''état et une persistance sans faille entre sessions.","de":"Ideal für Flutter-Agents, die eine nahtlose Zustandsverwaltung und Persistenz über Sitzungen hinweg erfordern.","pt":"Ideal para Agentes Flutter que requerem gerenciamento de estado sem interrupções e persistência entre sessões.","ru":"Идеально для агентов Flutter, требующих бесшовного управления состоянием и сохранения между сессиями.","ar":"مثالي لعميل Flutter الذين يتطلبون إدارة الحالة دون انقطاع واستمرارية بين الجلسات."},"recommendation":{"en":"Empowers agents to maintain app state on disk using a persistor object, enabling restoration between sessions with AsyncRedux and Dart, while providing benefits like state persistence and automatic store initialization.","zh":"使代理能够使用持久化对象在磁盘上维护应用程序状态，实现使用AsyncRedux和Dart的会话间恢复，同时提供状态持久性和自动存储初始化等优点。","ja":"AsyncReduxとDartを使用して、セッション間で復元を可能にするディスク上でアプリケーションの状態を保持するために、永続化オブジェクトを使用するエージェントを可能にし、状態の永続性と自動ストア初期化などの利点を提供します。","ko":"AsyncRedux와 Dart를 사용하여 세션 간에 복원할 수 있도록 디스크에서 애플리케이션 상태를 유지할 수 있는 persistor 개체를 사용하여 에이전트를 활성화하여 상태 지속성 및 자동 저장소 초기화 등의 이점을 제공합니다.","es":"Habilita a los agentes a mantener el estado de la aplicación en disco mediante un objeto persistor, lo que permite la restauración entre sesiones con AsyncRedux y Dart, mientras ofrece beneficios como la persistencia del estado y la inicialización automática de la tienda.","fr":"Permet aux agents de maintenir l''état de l''application sur disque à l''aide d''un objet persistor, ce qui permet la restauration entre sessions avec AsyncRedux et Dart, tout en offrant des avantages tels que la persistance de l''état et l''initialisation automatique de la boutique.","de":"Ermächtigt Agenten, den Anwendungsstatus auf der Festplatte mithilfe eines Persistor-Objekts zu speichern, wodurch die Wiederherstellung zwischen Sitzungen mit AsyncRedux und Dart ermöglicht wird, während Vorteile wie Statuspersistenz und automatische Store-Initialisierung geboten werden.","pt":"Habilita os agentes a manter o estado do aplicativo no disco usando um objeto persistor, permitindo a restauração entre sessões com AsyncRedux e Dart, enquanto fornece benefícios como persistência de estado e inicialização automática da loja.","ru":"Наделяет агентов возможностью сохранять состояние приложения на диске с помощью объекта persistor, что позволяет восстанавливать состояние между сессиями с AsyncRedux и Dart, обеспечивая такие преимущества, как сохранение состояния и автоматическую инициализацию хранилища.","ar":"تمكن العميل من الحفاظ على حالة التطبيق على القرص باستخدام كائن مؤشر استمرارية، مما يسمح بالاستعادة بين الجلسات مع AsyncRedux و Dart، مع تقديم فوائد مثل استمرارية الحالة وتحديث المتجر التلقائي."},"useCases":{"en":["Initializing stores with persisted state","Restoring app state between sessions","Managing state persistence with custom persistor objects"],"zh":["使用持久化状态初始化存储","在会话间恢复应用程序状态","使用自定义持久化对象管理状态持久性"],"ja":["永続化された状態でストアを初期化する","セッション間でアプリケーションの状態を復元する","カスタム永続化オブジェクトを使用して状態の永続性を管理する"],"ko":["지속된 상태로 저장소를 초기화하는 것","세션 간에 애플리케이션 상태를 복원하는 것","사용자 지정 지속 객체를 사용하여 상태 지속성을 관리하는 것"],"es":["Inicializar tiendas con estado persistido","Restaurar el estado de la aplicación entre sesiones","Administrar la persistencia del estado con objetos persistor personalizados"],"fr":["Initialiser des magasins avec un état persistant","Rétablir l''état de l''application entre sessions","Gérer la persistance de l''état avec des objets persistor personnalisés"],"de":["Speichern initialisieren mit persistentem Status","Anwendungsstatus zwischen Sitzungen wiederherstellen","Statuspersistenz mit benutzerdefinierten Persistor-Objekten verwalten"],"pt":["Inicializar lojas com estado persistido","Restaurar estado do aplicativo entre sessões","Gerenciar persistência de estado com objetos persistor personalizados"],"ru":["Инициализация хранилищ со сохраненным состоянием","Восстановление состояния приложения между сессиями","Управление сохранением состояния с помощью пользовательских объектов persistor"],"ar":["ت 初ية المتاجر مع حالة مستمرة","استعادة حالة التطبيق بين الجلسات","إدارة استمرارية الحالة باستخدام كائنات مؤشر استمرارية مخصصة"]},"limitations":{"en":["Requires Dart and Flutter environment","Dependent on AsyncRedux library"],"zh":["需要Dart和Flutter环境","依赖于AsyncRedux库"],"ja":["DartとFlutterの環境が必要","AsyncReduxライブラリに依存する"],"ko":["Dart 및 Flutter 환경이 필요","AsyncRedux 라이브러리에 의존"],"es":["Requiere entorno de Dart y Flutter","Dependiente de la biblioteca AsyncRedux"],"fr":["Nécessite un environnement Dart et Flutter","Dépend de la bibliothèque AsyncRedux"],"de":["Benötigt Dart- und Flutter-Umgebung","Abhängig von der AsyncRedux-Bibliothek"],"pt":["Exige ambiente Dart e Flutter","Dependente da biblioteca AsyncRedux"],"ru":["Требует среды Dart и Flutter","Зависит от библиотеки AsyncRedux"],"ar":["يتطلب بيئة Dart و Flutter","يعتمد على مكتبة AsyncRedux"]},"version":4},"contentHash":"ac2c47d0f707b4154d017975f237601f43ff2093e2d0b078bfa67ee84bf3cc89","qualityScore":33}');
