INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Cantara/lib-electronic-components/cyntec', 'cyntec', 'Cantara', 'lib-electronic-components', 'community', 'cyntec Cantara lib-electronic-components community The cyntec skill enables developers to understand and work with cyntec''s MPN structure, facilitating efficient component selection and management. This skill benefits developers working with cyntec components. Cyntec 的 MPN 结构遵循特定的格式，包括系列、尺寸、类型等信息，开发者可以通过解析 MPN 来获取产品详细信息 Cyntec AIエージェントのMPN構造は、シリーズ、サイズ、タイプなどの情報を含み、開発者はMPNを解析して製品の詳細情報を取得できます Cyntec의 MPN 구조는 시리즈, 크기, 유형 등 정보를 포함하며, 개발자는 MPN을 해석하여 제품의 상세 정보를 얻을 수 있습니다 cyntec es un fabricante que utiliza una estructura de MPN única. Aprende a decodificarla para entender mejor sus productos cyntec est un fabricant qui utilise une structure de code MPN unique. Apprenez à la décoder pour mieux comprendre ses produits cyntec ist ein Hersteller, der eine einzigartige MPN-Struktur verwendet. Erfahren Sie, wie Sie diese entschlüsseln, um seine Produkte besser zu verstehen Cyntec é uma habilidade que permite decodificar os MPNs da Cyntec Corporation, entendendo a estrutura de seus produtos Cyntec - это навык, позволяющий расшифровывать MPN корпорации Cyntec, понимая структуру их продуктов Cyntec هو مهارة يسمح بفك شفرة MPNs لشركة Cyntec Corporation، ويفهم بنية منتجاتها cyntec MPN structure how to decode cyntec MPN cyntec component selection cyntec alternative cyntec vs competitor cyntec setup guide what is cyntec cyntec install cyntec tutorial Cyntec MPN 结构 电子元件 开发指南 MPN 解析 产品信息 开发效率 Decodes cyntec MPNs using a structured format: [SERIES][SIZE][TYPE]-[VALUE][TOLERANCE][PACK] Supports packaging type identification (N=Tape/Reel) Provides tolerance code identification (M=20%, K=10%) Enables inductance code extraction Allows type variant identification (T, S, etc.) cyntec is a manufacturer skill that provides a standardized structure for decoding and utilizing cyntec''s MPN, enabling efficient component selection and management.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('sanand0/scientific-research/matchms', 'community', 'sanand0', 'scientific-research', 'sanand0/scientific-research', 'matchms', 0, 0, 33, '2026-03-08T01:57:15.297Z', '2026-03-08T02:01:17.011Z', '159851a4767d12348bc41aa3e26b1a843776c4e86818ac198a2cc84d5080c129', '{"id":"sanand0/scientific-research/matchms","name":"matchms","description":{"en":"matchms is a Python library for mass spectrometry data processing and analysis, benefiting researchers and scientists. It enables importing and exporting data from various formats.","zh":"Matchms是一个开源的Python库，用于质谱数据处理和分析","ja":"Matchmsは、質量分析データの処理および分析に使用されるオープンソースのPythonライブラリです","ko":"Matchms는 질량 분석 데이터를 처리 및 분석하는 데 사용되는 오픈 소스 Python 라이브러리입니다","es":"Matchms es una biblioteca Python de código abierto para el procesamiento y análisis de datos de espectrometría de masas. Permite importar espectros de varios formatos y calcular similitudes espectrales","fr":"Matchms est une bibliothèque Python open-source pour le traitement et l''analyse de données de spectrométrie de masse. Elle permet d''importer des spectres à partir de plusieurs formats et de calculer des similitudes spectrales","de":"Matchms ist eine Open-Source-Python-Bibliothek zur Verarbeitung und Analyse von Massenspektrometrie-Daten. Sie ermöglicht das Importieren von Spektren aus verschiedenen Formaten und das Berechnen von spektralen Ähnlichkeiten","pt":"Matchms é uma biblioteca Python de código aberto para processar e analisar dados de espectrometria de massa. Carregue espectros de vários formatos e construa fluxos de trabalho analíticos reprodutíveis","ru":"Matchms - открытая библиотека Python для обработки и анализа данных масс-спектрометрии. Импортируйте спектры из различных форматов и создавайте воспроизводимые аналитические рабочие процессы","ar":"Matchms هي مكتبة Python مفتوحة المصدر لمعالجة وتحليل بيانات مطياف الكتلة. قم بتحميل الأطياف من صيغ مختلفة وابنِ عمليات工作 تحليلية قابلة للتكرار"},"seo":{"title":{"en":"matchms: Mass Spectrometry Data Processing Setup Guide | ...","zh":"MatchmsSetup Guide: Python AI工具","ja":"Matchms入門ガイド: Python AIエージェント","ko":"Matchms설치 가이드: Python AI 에이전트","es":"Guía de configuración de matchms para análisis de espectr...","fr":"Guide de mise en place de matchms pour l''analyse de spect...","de":"Einrichtungsleitfaden für matchms zur Massenspektrometrie...","pt":"Guia de Configuração do Matchms para Análise de Dados de ...","ru":"Настройка Matchms для Анализа Данных Масс-Спектрометрии: ...","ar":"دليل إعداد Matchms لتحليل بيانات مطياف الكتلة باستخدام أد..."},"description":{"en":"Unlock the power of matchms for mass spectrometry data analysis. Learn how to import spectra, filter peaks, and calculate similarities. Get started with matc...","zh":"使用Matchms进行质谱数据处理和分析，包括导入、过滤和计算相似性","ja":"Matchmsを使用して質量分析データを処理および分析する","ko":"Matchms를 사용하여 질량 분석 데이터를 처리 및 분석","es":"Aprende a utilizar la biblioteca Python matchms para procesar y analizar datos de espectrometría de masas de manera eficiente","fr":"Découvrez comment utiliser la bibliothèque Python matchms pour traiter et analyser les données de spectrométrie de masse de manière efficace","de":"Erfahren Sie, wie Sie die Python-Bibliothek matchms zur effizienten Verarbeitung und Analyse von Massenspektrometrie-Daten verwenden","pt":"Aprenda a processar e analisar dados de espectrometria de massa com o Matchms, uma biblioteca Python de código aberto para pesquisas científicas","ru":"Откройте для себя возможности Matchms, открытой библиотеки Python для обработки и анализа данных масс-спектрометрии в научных исследованиях с помощью ИИ Агентов","ar":"اكتشف كيفية معالجة وتحليل بيانات مطياف الكتلة باستخدام Matchms، مكتبة Python مفتوحة المصدر للبحوث العلمية مع أدوات الذكاء الاصطناعي"},"definition":{"en":"matchms is an open-source Python library for mass spectrometry data processing and analysis, providing functionalities for spectral similarity calculation and reproducible workflows.","zh":"Matchms是一个用于质谱数据处理和分析的Python库","ja":"Matchmsは質量分析データの処理および分析に使用されるPythonライブラリ","ko":"Matchms는 질량 분석 데이터를 처리 및 분석하는 Python 라이브러리","es":"Matchms es una biblioteca Python para el análisis de datos de espectrometría de masas","fr":"Matchms est une bibliothèque Python pour l''analyse de données de spectrométrie de masse","de":"Matchms ist eine Python-Bibliothek zur Analyse von Massenspektrometrie-Daten","pt":"Matchms é uma biblioteca Python para processar e analisar dados de espectrometria de massa","ru":"Matchms - библиотека Python для обработки и анализа данных масс-спектрометрии","ar":"Matchms هي مكتبة Python لمعالجة وتحليل بيانات مطياف الكتلة"},"features":{"en":["Imports spectra from multiple file formats, including MGF, MZML, and MSP","Exports processed data for further analysis","Filters peaks and calculates spectral similarities","Builds reproducible analytical workflows","Loads spectra using functions like load_from_mgf, load_from_mzml, and load_from_msp"],"zh":["导入和导出质谱数据","标准化元数据","过滤峰值","计算光谱相似性","构建可复制的分析工作流"],"ja":["質量分析データのインポートおよびエクスポート","メタデータの標準化","ピークのフィルタリング","スペクトルの類似性の計算","再現可能な分析ワークフローの構築"],"ko":["질량 분석 데이터의 가져오기 및 내보내기","메타데이터의 표준화","피크 필터링","스펙트럼 유사성 계산","재현 가능한 분석 워크플로우 구축"],"es":["Importación de espectros desde varios formatos","Cálculo de similitudes espectrales","Filtrado de picos","Exportación de datos procesados","Compatibilidad con formatos como MGF, MZML y MSP"],"fr":["Importation de spectres à partir de plusieurs formats","Calcul de similitudes spectrales","Filtrage de pics","Exportation de données traitées","Compatibilité avec des formats tels que MGF, MZML et MSP"],"de":["Importieren von Spektren aus verschiedenen Formaten","Berechnen von spektralen Ähnlichkeiten","Filtern von Peaks","Exportieren von verarbeiteten Daten","Kompatibilität mit Formaten wie MGF, MZML und MSP"],"pt":["Importação de espectros de vários formatos","Padronização de metadados","Filtragem de picos","Cálculo de similaridades espectrais","Construção de fluxos de trabalho analíticos reprodutíveis"],"ru":["Импорт спектров из различных форматов","Стандартизация метаданных","Фильтрация пиков","Расчет спектральных сходств","Создание воспроизводимых аналитических рабочих процессов"],"ar":["تحميل الأطياف من صيغ مختلفة","توحيد البيانات الوصفية","تصفية القمم","حساب التشابه الطيفي","بناء عمليات عمل تحليلية قابلة للتكرار"]},"keywords":{"en":["how to use matchms","matchms alternative","matchms install","matchms setup guide","what is matchms","matchms vs openms","mass spectrometry data analysis","matchms spectral similarity calculation","matchms reproducible workflows"],"zh":["Matchms","Python质谱数据处理","质谱数据分析","AI工具","Python库","质谱数据处理软件"],"ja":["Matchms","Python質量分析データ処理","質量分析データ分析","AIエージェント","Pythonライブラリ","質量分析データ処理ソフトウェア"],"ko":["Matchms","Python질량 분석 데이터 처리","질량 분석 데이터 분석","AI 에이전트","Python 라이브러리","질량 분석 데이터 처리 소프트웨어"],"es":["matchms","espectrometría de masas","análisis de datos","biblioteca Python","importación de espectros","cálculo de similitudes espectrales","filtrado de picos","exportación de datos"],"fr":["matchms","spectrométrie de masse","analyse de données","bibliothèque Python","importation de spectres","calcul de similitudes spectrales","filtrage de pics","exportation de données"],"de":["matchms","Massenspektrometrie","Datenanalyse","Python-Bibliothek","Importieren von Spektren","Berechnen von spektralen Ähnlichkeiten","Filtern von Peaks","Exportieren von Daten"],"pt":["Matchms","espectrometria de massa","processamento de dados","análise de dados","biblioteca Python","pesquisas científicas","ferramentas de análise de dados"],"ru":["Matchms","масс-спектрометрия","обработка данных","анализ данных","библиотека Python","научные исследования","инструменты анализа данных","ИИ Агенты"],"ar":["Matchms","مطياف الكتلة","معالجة البيانات","تحليل البيانات","مكتبة Python","البحوث العلمية","أدوات تحليل البيانات","أدوات الذكاء الاصطناعي"]}},"owner":"sanand0","repo":"scientific-research","repoPath":"sanand0/scientific-research","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.297Z","topics":[],"category":"community","skillMd":{"name":"matchms","description":"Mass spectrometry analysis. Process mzML/MGF/MSP, spectral similarity (cosine, modified cosine), metadata harmonization, compound ID, for metabolomics and MS data processing.","bodyPreview":"# Matchms\n\n## Overview\n\nMatchms is an open-source Python library for mass spectrometry data processing and analysis. Import spectra from various formats, standardize metadata, filter peaks, calculate spectral similarities, and build reproducible analytical workflows.\n\n## Core Capabilities\n\n### 1. Importing and Exporting Mass Spectrometry Data\n\nLoad spectra from multiple file formats and export processed data:\n\n```python\nfrom matchms.importing import load_from_mgf, load_from_mzml, load_from_msp,","body":"# Matchms\n\n## Overview\n\nMatchms is an open-source Python library for mass spectrometry data processing and analysis. Import spectra from various formats, standardize metadata, filter peaks, calculate spectral similarities, and build reproducible analytical workflows.\n\n## Core Capabilities\n\n### 1. Importing and Exporting Mass Spectrometry Data\n\nLoad spectra from multiple file formats and export processed data:\n\n```python\nfrom matchms.importing import load_from_mgf, load_from_mzml, load_from_msp, load_from_json\nfrom matchms.exporting import save_as_mgf, save_as_msp, save_as_json\n\n# Import spectra\nspectra = list(load_from_mgf(\"spectra.mgf\"))\nspectra = list(load_from_mzml(\"data.mzML\"))\nspectra = list(load_from_msp(\"library.msp\"))\n\n# Export processed spectra\nsave_as_mgf(spectra, \"output.mgf\")\nsave_as_json(spectra, \"output.json\")\n```\n\n**Supported formats:**\n- mzML and mzXML (raw mass spectrometry formats)\n- MGF (Mascot Generic Format)\n- MSP (spectral library format)\n- JSON (GNPS-compatible)\n- metabolomics-USI references\n- Pickle (Python serialization)\n\nFor detailed importing/exporting documentation, consult `references/importing_exporting.md`.\n\n### 2. Spectrum Filtering and Processing\n\nApply comprehensive filters to standardize metadata and refine peak data:\n\n```python\nfrom matchms.filtering import default_filters, normalize_intensities\nfrom matchms.filtering import select_by_relative_intensity, require_minimum_number_of_peaks\n\n# Apply default metadata harmonization filters\nspectrum = default_filters(spectrum)\n\n# Normalize peak intensities\nspectrum = normalize_intensities(spectrum)\n\n# Filter peaks by relative intensity\nspectrum = select_by_relative_intensity(spectrum, intensity_from=0.01, intensity_to=1.0)\n\n# Require minimum peaks\nspectrum = require_minimum_number_of_peaks(spectrum, n_required=5)\n```\n\n**Filter categories:**\n- **Metadata processing**: Harmonize compound names, derive chemical structures, standardize adducts, correct charges\n- **Peak filtering**: Normalize intensities, select by m/z or intensity, remove precursor peaks\n- **Quality control**: Require minimum peaks, validate precursor m/z, ensure metadata completeness\n- **Chemical annotation**: Add fingerprints, derive InChI/SMILES, repair structural mismatches\n\nMatchms provides 40+ filters. For the complete filter reference, consult `references/filtering.md`.\n\n### 3. Calculating Spectral Similarities\n\nCompare spectra using various similarity metrics:\n\n```python\nfrom matchms import calculate_scores\nfrom matchms.similarity import CosineGreedy, ModifiedCosine, CosineHungarian\n\n# Calculate cosine similarity (fast, greedy algorithm)\nscores = calculate_scores(references=library_spectra,\n                         queries=query_spectra,\n                         similarity_function=CosineGreedy())\n\n# Calculate modified cosine (accounts for precursor m/z differences)\nscores = calculate_scores(references=library_spectra,\n                         queries=query_spectra,\n                         similarity_function=ModifiedCosine(tolerance=0.1))\n\n# Get best matches\nbest_matches = scores.scores_by_query(query_spectra[0], sort=True)[:10]\n```\n\n**Available similarity functions:**\n- **CosineGreedy/CosineHungarian**: Peak-based cosine similarity with different matching algorithms\n- **ModifiedCosine**: Cosine similarity accounting for precursor mass differences\n- **NeutralLossesCosine**: Similarity based on neutral loss patterns\n- **FingerprintSimilarity**: Molecular structure similarity using fingerprints\n- **MetadataMatch**: Compare user-defined metadata fields\n- **PrecursorMzMatch/ParentMassMatch**: Simple mass-based filtering\n\nFor detailed similarity function documentation, consult `references/similarity.md`.\n\n### 4. Building Processing Pipelines\n\nCreate reproducible, multi-step analysis workflows:\n\n```python\nfrom matchms import SpectrumProcessor\nfrom matchms.filtering import default_filters, normalize_intensities\nfrom matchms.filtering import select_by_relative_intensity, remove_peaks_around_precursor_mz\n\n# Define a processing pipeline\nprocessor = SpectrumProcessor([\n    default_filters,\n    normalize_intensities,\n    lambda s: select_by_relative_intensity(s, intensity_from=0.01),\n    lambda s: remove_peaks_around_precursor_mz(s, mz_tolerance=17)\n])\n\n# Apply to all spectra\nprocessed_spectra = [processor(s) for s in spectra]\n```\n\n### 5. Working with Spectrum Objects\n\nThe core `Spectrum` class contains mass spectral data:\n\n```python\nfrom matchms import Spectrum\nimport numpy as np\n\n# Create a spectrum\nmz = np.array([100.0, 150.0, 200.0, 250.0])\nintensities = np.array([0.1, 0.5, 0.9, 0.3])\nmetadata = {\"precursor_mz\": 250.5, \"ionmode\": \"positive\"}\n\nspectrum = Spectrum(mz=mz, intensities=intensities, metadata=metadata)\n\n# Access spectrum properties\nprint(spectrum.peaks.mz)           # m/z values\nprint(spectrum.peaks.intensities)  # Intensity values\nprint(spectrum.get(\"precursor_mz\")) # Metadata field\n\n# Visualize spectra\nspectrum.plot()\nspectrum.plot_against(reference_spectrum)\n```\n\n### 6. Metadata Management\n\nStandardize and harmonize spectrum metadata:\n\n```python\n# Metadata is automatically harmonized\nspectrum.set(\"Precursor_mz\", 250.5)  # Gets harmonized to lowercase key\nprint(spectrum.get(\"precursor_mz\"))   # Returns 250.5\n\n# Derive chemical information\nfrom matchms.filtering import derive_inchi_from_smiles, derive_inchikey_from_inchi\nfrom matchms.filtering import add_fingerprint\n\nspectrum = derive_inchi_from_smiles(spectrum)\nspectrum = derive_inchikey_from_inchi(spectrum)\nspectrum = add_fingerprint(spectrum, fingerprint_type=\"morgan\", nbits=2048)\n```\n\n## Common Workflows\n\nFor typical mass spectrometry analysis workflows, including:\n- Loading and preprocessing spectral libraries\n- Matching unknown spectra against reference libraries\n- Quality filtering and data cleaning\n- Large-scale similarity comparisons\n- Network-based spectral clustering\n\nConsult `references/workflows.md` for detailed examples.\n\n## Installation\n\n```bash\nuv pip install matchms\n```\n\nFor molecular structure processing (SMILES, InChI):\n```bash\nuv pip install matchms[chemistry]\n```\n\n## Reference Documentation\n\nDetailed reference documentation is available in the `references/` directory:\n- `filtering.md` - Complete filter function reference with descriptions\n- `similarity.md` - All similarity metrics and when to use them\n- `importing_exporting.md` - File format details and I/O operations\n- `workflows.md` - Common analysis patterns and examples\n\nLoad these references as needed for detailed information about specific matchms capabilities.\n"},"lastSynced":"2026-03-08T02:01:17.011Z","agentAnalysis":{"suitability":{"en":"Perfect for Scientific Analysis Agents needing advanced mass spectrometry data processing capabilities.","zh":"非常适合需要高级质谱数据处理能力的科学分析代理","ja":"科学分析エージェントが高度なマススペクトロメトリー データ処理機能を必要とする場合に最適","ko":"고급 질량 분석 데이터 처리 기능이 필요한 과학 분석 에이전트에게 적합","es":"Perfecto para agentes de análisis científico que necesitan capacidades avanzadas de procesamiento de datos de espectrometría de masas.","fr":"Parfait pour les agents d''analyse scientifique ayant besoin de capacités avancées de traitement de données de spectrométrie de masse.","de":"Perfekt für wissenschaftliche Analyseagenten, die erweiterte Massenspektrometrie-Datenaufbereitungs-Funktionen benötigen.","pt":"Perfeito para Agentes de Análise Científica que necessitam de capacidades avançadas de processamento de dados de espectrometria de massa.","ru":"Идеально для научных аналитических агентов, которым необходимы расширенные возможности обработки данных масс-спектрометрии.","ar":"مثالي للوكلاء التحليلية العلمية الذين يحتاجون إلى إمكانيات متقدمة لمعالجة بيانات مطياف الكتلة."},"recommendation":{"en":"Empowers agents to import and export mass spectrometry data from various formats such as MGF, MZML, and MSP, standardize metadata, filter peaks, and calculate spectral similarities using the matchms library.","zh":"启用代理从各种格式（如MGF、MZML和MSP）导入和导出质谱数据，标准化元数据，过滤峰值，并使用matchms库计算光谱相似性","ja":"エージェントがさまざまな形式（MGF、MZML、MSPなど）からマススペクトロメトリー データをインポートおよびエクスポートし、メタデータを標準化し、ピークをフィルタリングし、matchmsライブラリを使用してスペクトル類似性を計算することを可能にします","ko":"에이전트가 다양한 형식(MGF, MZML, MSP 등)에서 질량 분석 데이터를 가져오고 내보내고 메타데이터를 표준화하고 피크를 필터링하고 matchms 라이브러리를 사용하여 스펙트럼 유사성을 계산하는 것을 가능하게 함","es":"Permite a los agentes importar y exportar datos de espectrometría de masas desde varios formatos como MGF, MZML y MSP, estandarizar metadatos, filtrar picos y calcular similitudes espectrales utilizando la biblioteca matchms.","fr":"Permet aux agents d''importer et d''exporter des données de spectrométrie de masse à partir de divers formats tels que MGF, MZML et MSP, de normaliser les métadonnées, de filtrer les pics et de calculer des similitudes spectrales à l''aide de la bibliothèque matchms.","de":"Ermöglicht es Agenten, Massenspektrometrie-Daten aus verschiedenen Formaten wie MGF, MZML und MSP zu importieren und zu exportieren, Metadaten zu standardisieren, Peaks zu filtern und spektrale Ähnlichkeiten mit der Bibliothek matchms zu berechnen.","pt":"Permite que os agentes importem e exportem dados de espectrometria de massa de vários formatos, como MGF, MZML e MSP, padronizem metadados, filtrem picos e calculem semelhanças espectrais usando a biblioteca matchms.","ru":"Позволяет агентам импортировать и экспортировать данные масс-спектрометрии из различных форматов, таких как MGF, MZML и MSP, стандартизировать метаданные, фильтровать пики и вычислять спектральные сходства с помощью библиотеки matchms.","ar":"يمكن للوكلاء استيراد وتصدير بيانات مطياف الكتلة من مختلف التنسيقات مثل MGF و MZML و MSP، وتوحيد البيانات الوصفية، وتصفية القمم، و حساب التشابه الطيفي باستخدام مكتبة matchms."},"useCases":{"en":["Importing mass spectrometry data from multiple file formats","Standardizing metadata for reproducible analytical workflows","Calculating spectral similarities for advanced data analysis"],"zh":["从多个文件格式导入质谱数据","为可复现的分析工作流标准化元数据","计算光谱相似性以进行高级数据分析"],"ja":["複数のファイル形式からのマススペクトロメトリー データのインポート","再現可能な分析ワークフロー用のメタデータの標準化","高度なデータ分析のためのスペクトル類似性の計算"],"ko":["여러 파일 형식에서 질량 분석 데이터 가져오기","재현 가능한 분석 워크플로우를 위한 메타데이터 표준화","고급 데이터 분석을 위한 스펙트럼 유사성 계산"],"es":["Importar datos de espectrometría de masas desde múltiples formatos de archivo","Estandarizar metadatos para flujos de trabajo analíticos reproducibles","Calcular similitudes espectrales para un análisis de datos avanzado"],"fr":["Importer des données de spectrométrie de masse à partir de plusieurs formats de fichiers","Normaliser les métadonnées pour des flux de travail analytiques reproductibles","Calculer des similitudes spectrales pour une analyse de données avancée"],"de":["Importieren von Massenspektrometrie-Daten aus mehreren Dateiformaten","Standardisieren von Metadaten für reproduzierbare analytische Workflows","Berechnen von spektralen Ähnlichkeiten für eine erweiterte Datenanalyse"],"pt":["Importação de dados de espectrometria de massa de vários formatos de arquivo","Padronização de metadados para fluxos de trabalho analíticos reprodutíveis","Cálculo de semelhanças espectrais para análise de dados avançada"],"ru":["Импорт данных масс-спектрометрии из нескольких форматов файлов","Стандартизация метаданных для воспроизводимых аналитических рабочих процессов","Расчет спектральных сходств для расширенного анализа данных"],"ar":["استيراد بيانات مطياف الكتلة من تنسيقات الملفات المتعددة","توحيد البيانات الوصفية لتدفقات العمل التحليلية القابلة للتكرار","حساب التشابه الطيفي للتحليل المتقدم للبيانات"]},"limitations":{"en":["Requires Python environment","Limited to mass spectrometry data processing and analysis"],"zh":["需要Python环境","仅限于质谱数据处理和分析"],"ja":["Python環境が必要","マススペクトロメトリー データ処理および分析に限定"],"ko":["Python 환경 필요","질량 분석 데이터 처리 및 분석에 한정"],"es":["Requiere entorno Python","Limitado al procesamiento y análisis de datos de espectrometría de masas"],"fr":["Nécessite un environnement Python","Limité au traitement et à l''analyse de données de spectrométrie de masse"],"de":["Benötigt Python-Umgebung","Begrenzt auf die Verarbeitung und Analyse von Massenspektrometrie-Daten"],"pt":["Requer ambiente Python","Limitado ao processamento e análise de dados de espectrometria de massa"],"ru":["Требуется среда Python","Ограничен обработкой и анализом данных масс-спектрометрии"],"ar":["يتطلب بيئة Python","محدود بمعالجة وتحليل بيانات مطياف الكتلة"]},"version":4},"contentHash":"159851a4767d12348bc41aa3e26b1a843776c4e86818ac198a2cc84d5080c129","qualityScore":33}');
