INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('sanand0/scientific-research/matchms', 'matchms', 'sanand0', 'scientific-research', 'community', 'matchms sanand0 scientific-research community matchms is a Python library for mass spectrometry data processing and analysis, benefiting researchers and scientists. It enables importing and exporting data from various formats. Matchms是一个开源的Python库，用于质谱数据处理和分析 Matchmsは、質量分析データの処理および分析に使用されるオープンソースのPythonライブラリです Matchms는 질량 분석 데이터를 처리 및 분석하는 데 사용되는 오픈 소스 Python 라이브러리입니다 Matchms es una biblioteca Python de código abierto para el procesamiento y análisis de datos de espectrometría de masas. Permite importar espectros de varios formatos y calcular similitudes espectrales Matchms est une bibliothèque Python open-source pour le traitement et l''analyse de données de spectrométrie de masse. Elle permet d''importer des spectres à partir de plusieurs formats et de calculer des similitudes spectrales Matchms ist eine Open-Source-Python-Bibliothek zur Verarbeitung und Analyse von Massenspektrometrie-Daten. Sie ermöglicht das Importieren von Spektren aus verschiedenen Formaten und das Berechnen von spektralen Ähnlichkeiten Matchms é uma biblioteca Python de código aberto para processar e analisar dados de espectrometria de massa. Carregue espectros de vários formatos e construa fluxos de trabalho analíticos reprodutíveis Matchms - открытая библиотека Python для обработки и анализа данных масс-спектрометрии. Импортируйте спектры из различных форматов и создавайте воспроизводимые аналитические рабочие процессы Matchms هي مكتبة Python مفتوحة المصدر لمعالجة وتحليل بيانات مطياف الكتلة. قم بتحميل الأطياف من صيغ مختلفة وابنِ عمليات工作 تحليلية قابلة للتكرار how to use matchms matchms alternative matchms install matchms setup guide what is matchms matchms vs openms mass spectrometry data analysis matchms spectral similarity calculation matchms reproducible workflows Matchms Python质谱数据处理 质谱数据分析 AI工具 Python库 质谱数据处理软件 Imports spectra from multiple file formats, including MGF, MZML, and MSP Exports processed data for further analysis Filters peaks and calculates spectral similarities Builds reproducible analytical workflows Loads spectra using functions like load_from_mgf, load_from_mzml, and load_from_msp matchms is an open-source Python library for mass spectrometry data processing and analysis, providing functionalities for spectral similarity calculation and reproducible workflows.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('ddempsey/co2injection/doublet', 'community', 'ddempsey', 'co2injection', 'ddempsey/co2injection', 'doublet', 0, 0, 33, '2026-03-08T01:57:15.299Z', '2026-03-08T02:01:26.951Z', 'eed393a6cfc118933434288287ede697d628cb02824e19e399131dd1f8313c68', '{"id":"ddempsey/co2injection/doublet","name":"doublet","description":{"en":"The doublet skill provides physics knowledge for the 2-D doublet model, solving problems along circular streamlines in a potential flow field, benefiting developers and engineers working with streamline methods.","zh":"Doublet 技术提供流线方法的物理知识，解决二维双曲线模型中的对流-反应-扩散问题","ja":"Doublet 技術は流線方法を使用して2次元の双曲線モデルにおける対流-反応-拡散問題を解決します","ko":"Doublet 기술은 流線 방법을 사용하여 2차원 이중곡선 모델의 대류-반응-확산 문제를 해결합니다","es":"Doublet es un modelo que resuelve problemas de advección-reacción-difusión utilizando métodos de corrientes","fr":"Doublet est un modèle qui résout des problèmes d''advection-réaction-diffusion en utilisant des méthodes de lignes de courant","de":"Doublet ist ein Modell, das Probleme der Advektion-Reaktion-Diffusion mithilfe von Stromlinienmethoden löst","pt":"O modelo Doublet resolve problemas de advecção-reacção-dispersão em campos de fluxo potencial usando métodos de linha de corrente","ru":"Модель Doublet решает задачи адвекции-реакции-дисперсии в потенциальном потоке с помощью методов линии тока","ar":"ينموذج Doublet مشاكل الادفيكشن-التفاعل-التشتت في مجال الجريان المحتمل باستخدام طرق dòng الجريان"},"seo":{"title":{"en":"Doublet: Streamline Model Physics Knowledge for AI Agents","zh":"Doublet Setup Guide - 流线方法物理知识","ja":"Doublet のベストプラクティス - AIエージェントによる流線方法","ko":"Doublet 구현 가이드 - 流線 방법을 위한 물리학 지식","es":"Guía de configuración de doublet para modelado de física","fr":"Guide de mise en œuvre de doublet pour la modélisation de...","de":"Einrichtungsleitfaden für doublet zur Modellierung physik...","pt":"Guia de Configuração do Doublet para Modelagem de Física","ru":"ИИ Агент Doublet: Руководство по Настройке для Физических...","ar":"دليل إعداد Doublet لنمذجة الفيزياء"},"description":{"en":"Unlock the power of doublet with this AI agent skill, solving advection-reaction-dispersion problems and modifying streamline geometry calculations - learn m...","zh":"了解 Doublet 技术的详细信息，包括流线方法和物理知识的应用","ja":"Doublet を使用した流線方法の物理学的知識の詳細を学ぶ","ko":"Doublet 기술에 대한 정보를 확인하세요. 流線 방법 및 물리학 지식 포함","es":"Aprende a utilizar doublet para resolver problemas de advección-reacción-difusión en campos de flujo potencial","fr":"Découvrez comment utiliser doublet pour résoudre des problèmes d''advection-réaction-diffusion dans des champs de flux potentiels","de":"Erfahren Sie, wie Sie doublet verwenden, um Probleme der Advektion-Reaktion-Diffusion in Potentialströmungsfeldern zu lösen","pt":"Aprenda a configurar o modelo Doublet para resolver problemas de advecção-reacção-dispersão em campos de fluxo potencial","ru":"Узнайте, как настроить модель Doublet для решения задач адвекции-реакции-дисперсии в потенциальном потоке","ar":"تعرف على كيفية إعداد نموذج Doublet لحل مشاكل الادفيكشن-التفاعل-التشتت في مجال الجريان المحتمل"},"definition":{"en":"Doublet is a physics knowledge model using streamline methods to solve advection-reaction-dispersion problems in a potential flow field.","zh":"Doublet 是一种提供流线方法物理知识的技术，用于解决二维双曲线模型中的对流-反应-扩散问题","ja":"Doublet は流線方法を使用して2次元の双曲線モデルにおける対流-反応-拡散問題を解決する技術です","ko":"Doublet는 流線 방법을 사용하여 2차원 이중곡선 모델의 대류-반응-확산 문제를 해결하는 기술입니다","es":"Doublet es un modelo de física que utiliza corrientes circulares en un campo de flujo potencial","fr":"Doublet est un modèle de physique qui utilise des lignes de courant circulaires dans un champ de flux potentiels","de":"Doublet ist ein physikalisches Modell, das kreisförmige Stromlinien in einem Potentialströmungsfeld verwendet","pt":"O Doublet é um modelo de física que resolve problemas de advecção-reacção-dispersão em campos de fluxo potencial","ru":"Doublet - это физическая модель, решающая задачи адвекции-реакции-дисперсии в потенциальном потоке","ar":"Doublet هو نموذج فيزيائي لحل مشاكل الادفيكشن-التفاعل-التشتت في مجال الجريان المحتمل"},"features":{"en":["Solves advection-reaction-dispersion problems along circular streamlines","Modifies streamline geometry calculations using bipolar coordinates","Changes transport solvers, including hydrodynamic, chemical, and thermal","Implements or modifies breakthrough curve integration","Works with potential flow fields"],"zh":["流線方法的物理知识","二维双曲线模型的对流-反应-扩散问题解决","双曲线坐标的修改","传输求解器的更改（hydrodynamic, chemical, thermal）","突破曲线积分的实现或修改"],"ja":["流線方法の物理学的知識","2次元双曲線モデルの対流-反応-拡散問題の解決","双曲線座標の修正","伝送解析器の変更（hydrodynamic, chemical, thermal）","突破曲線積分の実装または修正"],"ko":["流線 方法의 물리학 지식","2차원 이중곡선 모델의 대류-반응-확산 문제 해결","이중곡선 좌표의 수정","전송 해석기의 변경（hydrodynamic, chemical, thermal）","돌파 곡선积分의 구현 또는 수정"],"es":["Modificación de cálculos de geometría de corrientes","Cambio de solvers de transporte","Implementación de curvas de integración de avance","Uso de coordenadas bipolares"],"fr":["Modification des calculs de géométrie de lignes de courant","Changement de solveurs de transport","Mise en œuvre de courbes d''intégration de percée","Utilisation de coordonnées bipolaires"],"de":["Modifizierung von Geometrieberechnungen für Stromlinien","Änderung der Transportlöser","Implementierung von Integrationskurven für Durchbruch","Verwendung von bipolaren Koordinaten"],"pt":["Modificação da geometria da linha de corrente","Alteração dos solvers de transporte","Implementação da curva de avanço","Resolução de problemas de advecção-reacção-dispersão","Uso de coordenadas bipolares"],"ru":["Модификация геометрии линии тока","Изменение солверов транспорта","Реализация кривой прорыва","Решение задач адвекции-реакции-дисперсии","Использование биполярных координат"],"ar":["تعديل هندسة dòng الجريان","تغيير محلات النقل","تنفيذ منحنى الكسر","حل مشاكل الادفيكشن-التفاعل-التشتت","استخدام إحداثيات ثنائية القطب"]},"keywords":{"en":["how to use doublet","what is doublet","doublet alternative","doublet vs other models","doublet install guide","doublet setup for AI agents","streamline model physics","advection-reaction-dispersion problems","bipolar coordinates in doublet"],"zh":["Doublet 技术","流線方法","物理知识","二维双曲线模型","对流-反应-扩散问题","双曲线坐标","传输求解器","突破曲线积分"],"ja":["Doublet 技術","流線方法","物理学的知識","2次元双曲線モデル","対流-反応-拡散問題","双曲線座標","伝送解析器","突破曲線積分"],"ko":["Doublet 기술","流線 方法","물리학 지식","2차원 이중곡선 모델","대류-반응-확산 문제","이중곡선 좌표","전송 해석기","돌파 곡선积分"],"es":["doublet","modelado de física","corrientes circulares","advección-reacción-difusión","coordenadas bipolares","Herramientas de AI para física"],"fr":["doublet","modélisation de la physique","lignes de courant circulaires","advection-réaction-diffusion","coordonnées bipolaires","Outils d''IA pour la physique"],"de":["doublet","physikalische Modellierung","kreisförmige Stromlinien","Advektion-Reaktion-Diffusion","bipolare Koordinaten","KI-Tools für Physik"],"pt":["modelo doublet","física de fluidos","advecção-reacção-dispersão","linha de corrente","coordenadas bipolares","solvers de transporte","curva de avanço"],"ru":["модель doublet","физика жидкостей","адвекция-реакция-дисперсия","линия тока","биполярные координаты","солверы транспорта","кривая прорыва"],"ar":["نموذج دبلت","فيزياء السوائل","ادفيكشن-تفاعل-تشتت","دòng الجريان","إحداثيات ثنائية القطب","محلات النقل","منحنى الكسر"]}},"owner":"ddempsey","repo":"co2injection","repoPath":"ddempsey/co2injection","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.299Z","topics":[],"category":"community","skillMd":{"name":"doublet","description":"Validates code and provides physics reasoning for the 2-D injection-production doublet model using streamline methods. Use when modifying streamline geometry, transport calculations (hydrodynamic, chemical, thermal), breakthrough curves, or Greens function kernels. Also use when debugging simulation behavior or explaining physics concepts.","bodyPreview":"# Doublet Streamline Model Physics Knowledge\n\nThis skill provides physics knowledge for the 2-D doublet (injection-production well pair) model using streamline methods. The model solves advection-reaction-dispersion problems along circular streamlines in a potential flow field.\n\n## When This Skill Applies\n\n- Modifying streamline geometry calculations (bipolar coordinates)\n- Changing transport solvers (hydrodynamic, chemical, thermal)\n- Implementing or modifying breakthrough curve integration\n- W","body":"# Doublet Streamline Model Physics Knowledge\n\nThis skill provides physics knowledge for the 2-D doublet (injection-production well pair) model using streamline methods. The model solves advection-reaction-dispersion problems along circular streamlines in a potential flow field.\n\n## When This Skill Applies\n\n- Modifying streamline geometry calculations (bipolar coordinates)\n- Changing transport solvers (hydrodynamic, chemical, thermal)\n- Implementing or modifying breakthrough curve integration\n- Working with Green''s function kernels for thermal transport\n- Debugging unexpected breakthrough behavior\n- Planning changes to physics-related code\n- Explaining why the model behaves a certain way\n\n## Core Physics Reference\n\nThe model tracks transport in a 2-D potential flow field between an injector (+a, 0) and producer (-a, 0):\n\n| Module | Transport Type | Solution Method |\n|--------|----------------|-----------------|\n| Hydrodynamic | Pure advection | Time-of-flight along streamlines |\n| Chemical | Advection + capacity-limited reaction | Logistic traveling wave |\n| Thermal | Advection + fluid-matrix exchange | Bessel-function Green''s kernel |\n\nKey state variables:\n\n| Variable | Symbol | Meaning | Units |\n|----------|--------|---------|-------|\n| Take-off angle | β | Angle at which streamline leaves injector | rad |\n| Time-of-flight | τ(β) | Travel time from injector to producer | s |\n| Arc position | φ | Angle along circular streamline | rad |\n| Concentration | C(φ,t) | Solute mass fraction | kg/kg |\n| Capacity | S(φ,t) | Remaining reaction capacity | kg/kg |\n| Fluid temperature | Tf(φ,t) | Fluid temperature along streamline | °C |\n| Matrix temperature | Tm(φ,t) | Rock matrix temperature | °C |\n\nFor detailed equations, see [EQUATIONS.md](EQUATIONS.md).\nFor symbol definitions and units, see [SYMBOLS.md](SYMBOLS.md).\nFor derivation logic, see [DERIVATIONS.md](DERIVATIONS.md).\nFor edge cases and sanity checks, see [SANITY_CHECKS.md](SANITY_CHECKS.md).\n\n---\n\n## Workflow A: Physics Validation\n\nUse this workflow when reviewing or planning code changes.\n\n### Step 1: Identify affected transport type\n\nDetermine which transport physics is affected:\n- **Hydrodynamic**: Streamline geometry, time-of-flight, velocity field\n- **Chemical**: Capacity-limited reaction, logistic traveling wave\n- **Thermal**: Fluid-matrix exchange, Bessel function kernel\n\n### Step 2: Check coordinate system consistency\n\nThe model uses multiple coordinate systems:\n- Cartesian (x, y) for plotting\n- Bipolar (ξ, β) for streamline parameterization\n- Polar about streamline center (R, φ) for local calculations\n\nVerify transformations are applied correctly.\n\n### Step 3: Verify breakthrough integration\n\nBreakthrough curves integrate over all streamlines:\n```\nC_prod(t) = (1/π) ∫_0^π C(β, t) dβ\n```\n\nCheck that:\n- Integration weights are correct (trapezoidal or custom)\n- β limits span [0, π] (or arrived streamlines only)\n- Singularities at β → 0, π are handled\n\n### Step 4: Check Green''s function stability (thermal)\n\nFor thermal transport, the Bessel kernel G(τ, t) can overflow:\n- Verify exponent recentering is applied\n- Check that i1e (scaled Bessel I1) is used instead of i1\n- Verify prefix integrals use cumulative_trapezoid\n\n### Step 5: Report findings\n\nSummarize:\n- Which transport type is affected\n- Any coordinate transformation issues\n- Any integration boundary issues\n- Any numerical stability concerns\n- Recommendations for correction\n\n---\n\n## Workflow B: Physics Reasoning\n\nUse this workflow when explaining behavior, debugging, or proposing solutions.\n\n### For explaining physics concepts:\n\n1. Identify the relevant equations and parameters\n2. State the physical interpretation\n3. Explain cause-and-effect relationships\n4. Use the derivation steps from [DERIVATIONS.md](DERIVATIONS.md) to show connections\n\n### For debugging simulation issues:\n\n1. Identify which transport type shows unexpected behavior\n2. Check if the issue relates to:\n   - Breakthrough timing (τ calculation)\n   - Front retardation (reaction capacity)\n   - Thermal lag (fluid-matrix exchange rates)\n3. Trace through the analytical solution\n4. Check edge cases against [SANITY_CHECKS.md](SANITY_CHECKS.md)\n\n### For proposing physics-consistent changes:\n\n1. Identify which equations are affected\n2. Show how new terms integrate into the transport equations\n3. Demonstrate that mass/energy balance is preserved\n4. Identify any new sanity checks needed\n\n---\n\n## Quick Reference: Module Structure\n\n| Module | Purpose | Key Functions |\n|--------|---------|---------------|\n| `doublet.py` | Main model (streamlines, chemical, thermal) | `Tf`, `Ctf`, `Cxf`, `Ttf`, `Txf`, `breakthrough` |\n| `streamlines.py` | Bipolar coordinate streamlines | `streamline_bipolar`, `streamtube_width` |\n| `diffusion.py` | Green''s kernel solver with diffusion | `solve_kernel_capacity`, `cxfD`, `ctDf` |\n| `thermal.py` | Thermal kernel (alternative impl.) | `thermal_kernel_Tf_Tm_xvec_t` |\n| `thermal2.py` | Optimized thermal solver | `G_grid_efficient`, `run_breakthrough`, `Tprodf` |\n| `notebook_widgets.py` | Interactive Jupyter visualizations | `visualize_*` functions |\n\n---\n\n## Key Physical Constraints\n\nThese must always hold:\n\n1. **Streamline geometry**: Streamlines are circular arcs through (±a, 0)\n2. **Travel time bounds**: T(β=0) = 4πna²/(3Q) is minimum arrival time\n3. **Velocity singularity**: v → ∞ at wells (handled by coordinate transformation)\n4. **Conservation**: Integrated flux across all streamlines equals Q\n5. **Retardation**: Chemical front travels at speed v·C_inj/(C_inj + S_0)\n6. **Thermal equilibrium**: As t → ∞, Tf → Tm → T_inj (behind the front)\n\n---\n\n## Transport Type Classification\n\n| Transport | Governing Equation | Solution Type |\n|-----------|-------------------|---------------|\n| Hydrodynamic | ∂C/∂t + v·∇C = 0 | Method of characteristics |\n| Chemical (no diffusion) | ∂C/∂t + v·∇C = -kCS | Logistic traveling wave |\n| Chemical (with diffusion) | ∂C/∂t + v·∇C = D∇²C - kCS | Green''s function convolution |\n| Thermal | ∂Tf/∂t + v·∇Tf = -γ(Tf - Tm) | Bessel kernel (Eq. 47) |\n| Matrix | ∂Tm/∂t = β(Tf - Tm) | Exponential convolution (Eq. 48) |\n\n---\n\n## Dimensionless Groups\n\n| Group | Definition | Physical Meaning |\n|-------|------------|------------------|\n| Retardation R | (C_inj + S_0)/C_inj | Front slowdown factor |\n| Damköhler Da | k·τ | Reaction extent over travel time |\n| Péclet Pe | v·L/D | Advection vs diffusion |\n| β·τ | (exchange rate)·(travel time) | Matrix equilibration extent |\n| γ·τ | (exchange rate)·(travel time) | Fluid cooling extent |\n"},"lastSynced":"2026-03-08T02:01:26.951Z","agentAnalysis":{"suitability":{"en":"Ideal for Physics-based Agents requiring advanced 2-D doublet modeling and potential flow field analysis.","zh":"适用于需要高级2-D双极模型和势流场分析的基于物理的代理。","ja":"物理ベースのエージェントが高度な2-D双極モデルとポテンシャル流動場分析を必要とする場合に適しています。","ko":"고급 2-D 쌍극 모델 및 전위 흐름 필드 분석이 필요한 물리 기반 에이전트에 적합합니다.","es":"Ideal para agentes basados en física que requieren modelado de doblete avanzado 2-D y análisis de campo de flujo potencial.","fr":"Idéal pour les agents basés sur la physique nécessitant un modèle de doublet 2D avancé et une analyse de champ de flux potentiel.","de":"Ideal für physikbasierte Agenten, die ein erweitertes 2-D-Doppelfeldmodell und eine Potentialflussfeldanalyse erfordern.","pt":"Ideal para agentes baseados em Física que requerem modelagem de duplo avançado 2-D e análise de campo de fluxo potencial.","ru":"Идеально подходит для агентов, основанных на физике, требующих передовой двойной 2-D моделирования и потенциального потока поля анализа.","ar":"مثالي لعميل الفيزياء الذي يتطلب نمذجة ثنائي متقدمة 2-D وتحليل مجال تدفق إمكاني."},"recommendation":{"en":"Empowers agents to solve advection-reaction-dispersion problems along circular streamlines using bipolar coordinates and streamline methods, facilitating transport solver integration for hydrodynamic, chemical, and thermal applications.","zh":"赋予代理使用双极坐标和流线方法沿圆形流线解决对流-反应-扩散问题的能力，促进水力学、化学和热应用中的运输求解器集成。","ja":"双極座標と流線法を使用して円形の流れ線に沿って対流-反応-拡散問題を解決するエージェントの能力を提供し、水力学、化学、熱などのアプリケーションにおける輸送ソルバの統合を促進します。","ko":"이중극 좌표와 흐름선 방법을 사용하여 원형 흐름선에 따라 대류-반응-확산 문제를 해결하는 에이전트의 능력을 부여하여 수력학, 화학 및 열 등의 애플리케이션에서 수송 솔버 통합을 촉진합니다.","es":"Habilita a los agentes a resolver problemas de advección-reacción-difusión a lo largo de líneas de corriente circulares utilizando coordenadas bipolares y métodos de línea de corriente, lo que facilita la integración del solucionador de transporte para aplicaciones hidrodinámicas, químicas y térmicas.","fr":"Permet aux agents de résoudre des problèmes d''advection-réaction-dispersion le long de lignes de courant circulaires en utilisant des coordonnées bipolaires et des méthodes de ligne de courant, facilitant ainsi l''intégration du solveur de transport pour les applications hydrodynamiques, chimiques et thermiques.","de":"Ermöglicht es Agenten, Advektions-Reaktions-Dispersionsprobleme entlang kreisförmiger Stromlinien unter Verwendung bipolarer Koordinaten und Stromlinienmethoden zu lösen, wodurch die Integration des Transportsolvers für hydrodynamische, chemische und thermische Anwendungen erleichtert wird.","pt":"Habilita agentes a resolver problemas de advecção-reacção-dispersão ao longo de linhas de corrente circulares usando coordenadas bipolares e métodos de linha de corrente, facilitando a integração do solucionador de transporte para aplicações hidrodinâmicas, químicas e térmicas.","ru":"Наделяет агентов способностью решать проблемы адвекции-реакции-распределения вдоль круговых потоков с использованием биполярных координат и методов потока, облегчая интеграцию транспортного решателя для гидродинамических, химических и тепловых приложений.","ar":"يمنح العميل khảية حل مشاكل الحمل-التفاعل-الت散沿 خطوط الدفق الدائرية باستخدام إحداثيات ثنائية القطب وأساليب خط الدفق، مما يسهل تكامل محلل النقل لتطبيقات الديناميكا الهيدروليكية والكيميائية والحرارية."},"useCases":{"en":["Modifying streamline geometry calculations","Implementing breakthrough curve integration","Changing transport solvers for hydrodynamic and chemical applications"],"zh":["修改流线几何计算","实现突破曲线集成","更改水力学和化学应用的运输求解器"],"ja":["流線幾何計算の変更","突破曲線統合の実装","水力学および化学アプリケーションの輸送ソルバの変更"],"ko":["흐름선 기하 계산 수정","돌파 곡선 통합 구현","수력학 및 화학 애플리케이션의 수송 솔버 변경"],"es":["Modificar cálculos de geometría de línea de corriente","Implementar integración de curva de avance","Cambiar solvers de transporte para aplicaciones hidrodinámicas y químicas"],"fr":["Modifier les calculs de géométrie de ligne de courant","Mettre en œuvre l''intégration de la courbe de percée","Changer les solveurs de transport pour les applications hydrodynamiques et chimiques"],"de":["Ändern von Stromlinien-Geometrieberechnungen","Implementierung von Durchbruchskurvenintegration","Ändern von Transportsolvern für hydrodynamische und chemische Anwendungen"],"pt":["Modificar cálculos de geometria de linha de corrente","Implementar integração de curva de avanço","Alterar solucionadores de transporte para aplicações hidrodinâmicas e químicas"],"ru":["Модифицировать расчеты геометрии линии потока","Реализовать интеграцию кривой прорыва","Изменить транспортные решатели для гидродинамических и химических приложений"],"ar":["تعديل حسابات هندسة خط الدفق","تنفيذ تكامل منحنى الكسر","تغيير محللي النقل لتطبيقات الديناميكا الهيدروليكية والكيميائية"]},"limitations":{"en":["Requires knowledge of potential flow fields","Limited to 2-D doublet models","Streamline method dependency"],"zh":["需要势流场的知识","仅限2-D双极模型","流线法依赖性"],"ja":["ポテンシャル流動場の知識が必要","2-D双極モデルに限られる","流線法依存性"],"ko":["전위 흐름 필드에 대한 지식이 필요","2-D 쌍극 모델로 제한됨","흐름선 방법 의존성"],"es":["Requiere conocimiento de campos de flujo potencial","Limitado a modelos de doblete 2-D","Dependencia del método de línea de corriente"],"fr":["Nécessite des connaissances sur les champs de flux potentiel","Limité aux modèles de doublet 2D","Dépendance de la méthode de ligne de courant"],"de":["Benötigt Kenntnisse über Potentialflussfelder","Begrenzt auf 2-D-Doppelfeldmodelle","Abhängigkeit von der Stromlinienmethode"],"pt":["Requer conhecimento de campos de fluxo potencial","Limitado a modelos de duplo 2-D","Dependência do método de linha de corrente"],"ru":["Требует знания потенциальных полей потока","Ограничен двойными моделями 2-D","Зависимость от метода линии потока"],"ar":["يتطلب معرفة بحقول التدفق الإمكاني","محدود بنماذج ثنائي 2-D","اعتماد على طريقة خط الدفق"]},"version":4},"contentHash":"eed393a6cfc118933434288287ede697d628cb02824e19e399131dd1f8313c68","qualityScore":33}');
