INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('SyedaNabila559/phase2-3-todo-full-web-with-ai-chatbot/sqlmodel-task-models', 'sqlmodel-task-models', 'SyedaNabila559', 'phase2-3-todo-full-web-with-ai-chatbot', 'community', 'sqlmodel-task-models SyedaNabila559 phase2-3-todo-full-web-with-ai-chatbot community sqlmodel-task-models provides guidance on defining robust database schemas using SQLModel for Todo applications, ensuring scalability and high performance with Neon PostgreSQL. SQLModel 任务模型是一个使用 SQLModel 定义强大的数据库模式的解决方案，支持 Todo 应用的高性能和可扩展性 SQLModel タスクモデルは、SQLModel を使用して Todo アプリケーションの強力なデータベース スキーマを定義するためのソリューションです SQLModel Task Model은 SQLModel을 사용하여 Todo 애플리케이션의 강력한 데이터베이스 스키마를 정의하는 솔루션입니다 SQLModel Task Models es una habilidad para definir esquemas de base de datos robustos y seguros para aplicaciones de tareas con Next.js y Python. SQLModel Task Models est une compétence pour définir des schémas de base de données robustes et sécurisés pour les applications de tâches avec Next.js et Python. SQLModel Task Models ist eine Fähigkeit, um robuste und sichere Datenbankschemata für Aufgabenanwendungen mit Next.js und Python zu definieren. O SQLModel Task Models fornece orientação sobre a definição de um esquema de banco de dados robusto e seguro para aplicativos Todo SQLModel Task Models предоставляет руководство по определению прочной и безопасной схемы базы данных для приложений Todo يوفر نموذج مهام SQLModel إرشادات لتعريف مخطط قاعدة بيانات قوي وآمن لتطبيقات Todo how to use sqlmodel-task-models sqlmodel-task-models setup guide sqlmodel-task-models vs prisma sqlmodel-task-models install what is sqlmodel-task-models sqlmodel-task-models alternative sqlmodel-task-models and postgresql sqlmodel-task-models tutorial sqlmodel-task-models documentation SQLModel 任务模型 数据库模式 Todo 应用 高性能 可扩展性 PostgreSQL AI 工具 AI 开发 User Model schema aligned with Better Auth requirements Task Model with full CRUD capability and relational mapping to Users Relational Integrity for robust database interactions Compatibility with Better Auth for secure user authentication Optimized for PostgreSQL using Neon for high performance sqlmodel-task-models is a skill providing guidance on defining robust, type-safe, and async-compatible database schemas using SQLModel for Todo applications.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('huifer/Claude-Code-KnowCraft/knowledge-manager', 'community', 'huifer', 'Claude-Code-KnowCraft', 'huifer/Claude-Code-KnowCraft', 'knowledge-manager', 0, 0, 33, '2026-03-08T01:57:15.308Z', '2026-03-08T02:02:22.164Z', '1c8f7b5218208a1d399427e720477269f9b3db39ac5af4bd4e015d43441645b6', '{"id":"huifer/Claude-Code-KnowCraft/knowledge-manager","name":"knowledge-manager","description":{"en":"The Knowledge-Manager skill is an AI-powered personal knowledge management system that automates knowledge base optimization using natural language interface and spaced repetition learning, benefiting developers and knowledge workers.","zh":"知识管理助手是AI-powered的个人知识管理系统，具有自然语言接口和间隔重复学习功能","ja":"知識管理ツールは、AIエージェントを搭載した個人用知識管理システムで、自然言語インターフェースと間隔反復学習機能を備えています","ko":"지식 관리 도구는 AI를搭載한 개인 지식 관리 시스템으로 자연어 인터페이스와 간격 반복 학습 기능을 제공합니다","es":"Knowledge Manager es un sistema de gestión de conocimiento con interfaz de lenguaje natural y repetición espaciada que ayuda a los usuarios a organizar y mejorar la calidad de sus conocimientos","fr":"Knowledge Manager est un système de gestion des connaissances avec interface de langage naturel et répétition espacée qui aide les utilisateurs à organiser et à améliorer la qualité de leurs connaissances","de":"Knowledge Manager ist ein KI-gestütztes Wissensmanagementsystem mit natürlicher Sprachsteuerung und zeitlich gestaffelter Wiederholung, das Benutzern hilft, ihre Kenntnisse zu organisieren und zu verbessern","pt":"O Knowledge Manager é um sistema de gerenciamento de conhecimento com interface de linguagem natural e repetição espaçada. Ele fornece sugestões de tags, associações e categorias para ajudar a organizar o seu conhecimento","ru":"ИИ Агент Knowledge Manager - это инструмент управления знаниями с естественным интерфейсом и повторением с интервалом. Он предоставляет предложения по тегам, связям и категориям для помощи в организации ваших знаний","ar":"مدير المعرفة هو نظام إدارة المعرفة باللغة الطبيعية مع إعادة التكرار المكانية. يقدم اقتراحات بالوسوم والارتباطات والفئات لمساعدتك في تنظيم معرفتك"},"seo":{"title":{"en":"Knowledge-Manager: AI-Powered Knowledge Base Optimization...","zh":"知识管理助手设置指南：自动标签和关联建议","ja":"AIエージェントの知識管理ツール：自動タグ付けと関連付けのベストプラクティス","ko":"지식 관리 도구 설정 가이드: 자동 태그와 연관 제안","es":"Guía de configuración de Knowledge Manager: sistema de ge...","fr":"Guide de mise en place de Knowledge Manager: système de g...","de":"Einrichtungsleitfaden für Knowledge Manager: KI-gestützte...","pt":"Guia de Configuração do Knowledge Manager: Sistema de Ger...","ru":"Настройка ИИ Агента Knowledge Manager: Инструмент Управле...","ar":"دليل إعداد مدير المعرفة: نظام إدارة المعرفة باللغة الطبيع..."},"description":{"en":"Unlock the full potential of your knowledge base with Knowledge-Manager. Discover how to automate tagging, linking, and organization with this AI-powered ski...","zh":"使用知识管理助手自动分析和优化知识库结构，实现智能标签建议和关联建议","ja":"AIエージェントの知識管理ツールを使用して、自動タグ付けと関連付けを実現し、知識ライブラリを最適化します","ko":"지식 관리 도구를 사용하여 지식 라이브러리를 최적화하고 자동 태그 및 연관 제안을 구현합니다","es":"Descubre cómo configurar Knowledge Manager, un sistema de gestión de conocimiento con interfaz de lenguaje natural y repetición espaciada para mejorar la org...","fr":"Découvrez comment configurer Knowledge Manager, un système de gestion des connaissances avec interface de langage naturel et répétition espacée pour améliore...","de":"Erfahren Sie, wie Sie Knowledge Manager einrichten, ein KI-gestütztes Wissensmanagementsystem mit natürlicher Sprachsteuerung und zeitlich gestaffelter Wiede...","pt":"Aprenda a configurar o Knowledge Manager, um sistema de gerenciamento de conhecimento com interface de linguagem natural e repetição espaçada para melhorar a...","ru":"Узнайте, как настроить ИИ Агент Knowledge Manager, инструмент управления знаниями с естественным интерфейсом и повторением с интервалом для улучшения организ...","ar":"تعلم كيفية إعداد مدير المعرفة، نظام إدارة المعرفة باللغة الطبيعية مع إعادة التكرار المكانية لتحسين تنظيم معرفتك"},"definition":{"en":"Knowledge-Manager is an AI-powered personal knowledge management system that automates knowledge base structure analysis and optimization.","zh":"知识管理助手是一种自动触发的智能工具，帮助用户自动标签和关联建议","ja":"知識管理ツールは、自動的にトリガーされるAIエージェントで、ユーザーが自動タグ付けと関連付けを実現するのに役立ちます","ko":"지식 관리 도구는 자동으로 트리거되는 지능형 도구로 사용자가 자동 태그와 연관 제안을 구현하는 데 도움을 줍니다","es":"Knowledge Manager es un sistema de gestión de conocimiento que utiliza inteligencia artificial para analizar y optimizar la estructura de la base de conocimientos","fr":"Knowledge Manager est un système de gestion des connaissances qui utilise l''intelligence artificielle pour analyser et optimiser la structure de la base de connaissances","de":"Knowledge Manager ist ein Wissensmanagementsystem, das künstliche Intelligenz verwendet, um die Struktur der Wissensbasis zu analysieren und zu optimieren","pt":"O Knowledge Manager é um sistema de gerenciamento de conhecimento que utiliza inteligência artificial para organizar e otimizar a estrutura do conhecimento","ru":"ИИ Агент Knowledge Manager - это инструмент управления знаниями, который использует искусственный интеллект для организации и оптимизации структуры знаний","ar":"مدير المعرفة هو نظام إدارة المعرفة الذي يستخدم الذكاء الاصطناعي لتنظيم وتحسين هيكل المعرفة"},"features":{"en":["Automates tag suggestions based on content using natural language processing","Suggests links between related entries using machine learning algorithms","Performs automatic category detection for each entry","Identifies and merges duplicate entries using fuzzy matching","Evaluates entry completeness and quality using predefined criteria"],"zh":["自动标签建议","自动关联建议","分类检测","智能组织","质量评估"],"ja":["自動タグ付け","自動関連付け","カテゴリ検出","スマートな組織","品質評価"],"ko":["자동 태그 제안","자동 연관 제안","분류 감지","지능형 조직","품질 평가"],"es":["Sugerencias de etiquetas automáticas basadas en contenido","Sugerencias de enlaces automáticas entre artículos relacionados","Detección de categorías para artículos","Organización inteligente para identificar artículos duplicados o aislados","Evaluación de la calidad de los artículos"],"fr":["Suggestions de balises automatiques basées sur le contenu","Suggestions de liens automatiques entre les articles liés","Détection de catégories pour les articles","Organisation intelligente pour identifier les articles en double ou isolés","Évaluation de la qualité des articles"],"de":["Automatische Vorschläge für Tags basierend auf Inhalten","Automatische Vorschläge für Verknüpfungen zwischen verwandten Artikeln","Kategorien-Erkennung für Artikel","Intelligente Organisation, um doppelte oder isolierte Artikel zu identifizieren","Qualitätsbewertung von Artikeln"],"pt":["Sugestões de tags automáticas com base no conteúdo","Sugestões de associações para identificar entradas relacionadas","Detecção de categorias para determinar a categoria certa para cada entrada","Organização inteligente para identificar entradas duplicadas, isoladas ou que precisam de integração","Avaliação de qualidade para avaliar a completude e qualidade das entradas"],"ru":["Автоматические предложения по тегам на основе содержания","Предложения по связям для выявления связанных записей","Обнаружение категорий для определения правильной категории для каждой записи","Интеллектуальная организация для выявления дубликатов, изолированных или требующих интеграции записей","Оценка качества для оценки полноты и качества записей"],"ar":["اقتراحات تلقائية بالوسوم على أساس المحتوى","اقتراحات بالارتباطات لتحديد المدخلات المرتبطة","كشف الفئات لتحديد الفئة الصحيحة لكل مدخل","تنظيم ذكي لتحديد المدخلات المكررة أو المعزولة أو التي تحتاج إلى دمج","تقييم الجودة لتقييم اكتمال و جودة المدخلات"]},"keywords":{"en":["how to use knowledge-manager","knowledge-manager setup guide","knowledge-manager alternative","knowledge-manager vs wiki","knowledge-manager install","what is knowledge-manager","knowledge-manager tutorial","knowledge-manager for developers","knowledge-manager AI-powered"],"zh":["知识管理助手","AI知识管理","自动标签","自动关联","间隔重复学习","自然语言接口","知识库优化"],"ja":["AIエージェント","知識管理ツール","自動タグ付け","自動関連付け","間隔反復学習","自然言語インターフェース","知識ライブラリ最適化"],"ko":["지식 관리 도구","AI 지식 관리","자동 태그","자동 연관","간격 반복 학습","자연어 인터페이스","지식 라이브러리 최적화"],"es":["Knowledge Manager","sistema de gestión de conocimiento","interfaz de lenguaje natural","repetición espaciada","inteligencia artificial","organización de conocimientos","calidad de conocimientos","Herramientas de IA para desarrolladores"],"fr":["Knowledge Manager","système de gestion des connaissances","interface de langage naturel","répétition espacée","intelligence artificielle","organisation des connaissances","qualité des connaissances","Outils d''IA pour les développeurs"],"de":["Knowledge Manager","Wissensmanagementsystem","natürliche Sprachsteuerung","zeitlich gestaffelte Wiederholung","künstliche Intelligenz","Organisation von Kenntnissen","Qualität von Kenntnissen","KI-Tools für Entwickler"],"pt":["Knowledge Manager","gerenciamento de conhecimento","inteligência artificial","interface de linguagem natural","repetição espaçada","sugestões de tags","associações","categorização","organização de conhecimento"],"ru":["ИИ Агент Knowledge Manager","управление знаниями","искусственный интеллект","естественный интерфейс","повторение с интервалом","предложения по тегам","связи","категоризация","организация знаний"],"ar":["مدير المعرفة","إدارة المعرفة","الذكاء الاصطناعي","الواجهة الطبيعية","إعادة التكرار المكانية","اقتراحات بالوسوم","الارتباطات","التصنيف","تنظيم المعرفة"]}},"owner":"huifer","repo":"Claude-Code-KnowCraft","repoPath":"huifer/Claude-Code-KnowCraft","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.308Z","topics":[],"category":"community","skillMd":{"name":"knowledge-manager","description":"智能知识管理助手,自动分析、组织和优化知识库","bodyPreview":"# Knowledge Manager Skill\n\n智能知识管理助手,自动分析和优化知识库结构。\n\n## 功能概述\n\nKnowledge Manager 是一个自动触发的智能助手,帮助用户:\n\n1. **自动标签建议**: 基于内容智能推荐标签\n2. **自动关联建议**: 识别相关条目并建议链接\n3. **分类检测**: 自动判断条目应该属于哪个分类\n4. **智能组织**: 识别重复、孤立和需要整合的条目\n5. **质量评估**: 评估条目的完整性和质量\n\n## 触发条件\n\n### 自动触发\n\n1. **添加知识后** (`on_add: true`)\n   - 用户执行 `/kb-add` 后自动触发\n   - 分析新添加的条目\n   - 建议标签、分类和关联\n\n2. **编辑知识后** (`on_edit: true`)\n   - 用户执行 `/kb-edit` 后自动触发\n   - 检查编辑后的内容\n   - 更新建议和关联\n\n### 手动触发\n\n用户可以通过以下方式手动触发:\n- \"帮我整理知识\"\n- \"优化知识库\"\n- \"分析标签使用情况\"\n- \"查找重复条目\"\n- \"","body":"# Knowledge Manager Skill\n\n智能知识管理助手,自动分析和优化知识库结构。\n\n## 功能概述\n\nKnowledge Manager 是一个自动触发的智能助手,帮助用户:\n\n1. **自动标签建议**: 基于内容智能推荐标签\n2. **自动关联建议**: 识别相关条目并建议链接\n3. **分类检测**: 自动判断条目应该属于哪个分类\n4. **智能组织**: 识别重复、孤立和需要整合的条目\n5. **质量评估**: 评估条目的完整性和质量\n\n## 触发条件\n\n### 自动触发\n\n1. **添加知识后** (`on_add: true`)\n   - 用户执行 `/kb-add` 后自动触发\n   - 分析新添加的条目\n   - 建议标签、分类和关联\n\n2. **编辑知识后** (`on_edit: true`)\n   - 用户执行 `/kb-edit` 后自动触发\n   - 检查编辑后的内容\n   - 更新建议和关联\n\n### 手动触发\n\n用户可以通过以下方式手动触发:\n- \"帮我整理知识\"\n- \"优化知识库\"\n- \"分析标签使用情况\"\n- \"查找重复条目\"\n- \"建议知识关联\"\n\n## 执行流程\n\n### 1. 内容分析\n\n```markdown\n## 分析新添加的条目\n\n当用户添加知识时:\n\n1. **提取关键词**\n   - 从标题中提取核心概念\n   - 从正文中识别技术术语\n   - 提取专有名词和缩写\n\n2. **主题识别**\n   - 判断讨论的主要主题\n   - 识别技术栈和工具\n   - 检测应用场景\n\n3. **质量评估**\n   - 检查内容完整性\n   - 评估是否有代码示例\n   - 判断是否需要补充信息\n```\n\n### 2. 标签建议\n\n```markdown\n## 智能标签推荐\n\n基于内容分析推荐标签:\n\n1. **现有标签匹配**\n   - 查找 tags.json 中相似的标签\n   - 推荐使用现有标签体系\n\n2. **新标签建议**\n   - 识别内容中的关键概念\n   - 建议新的标签名称\n   - 避免标签冗余\n\n3. **标签层级**\n   - 建议主标签和副标签\n   - 保持标签体系的一致性\n\n输出格式:\n```\n建议标签:\n  主标签: react, hooks\n  相关标签: frontend, javascript, useState\n\n说明:\n  - react: React 框架相关内容\n  - hooks: React Hooks 特性\n  - frontend: 前端开发通用\n  - javascript: JavaScript 语言\n\n是否应用这些标签? (yes/no/edit)\n```\n```\n\n### 3. 分类建议\n\n```markdown\n## 分类推荐\n\n分析内容并建议分类:\n\n**code 分类特征**:\n- 代码片段\n- API 文档\n- 技术实现细节\n\n**projects 分类特征**:\n- 项目文档\n- 开发日志\n- 技术决策记录\n\n**learning 分类特征**:\n- 学习笔记\n- 概念解释\n- 教程和指南\n\n**personal 分类特征**:\n- 个人思考\n- 经验总结\n- 反思和感悟\n\n输出格式:\n```\n建议分类: learning\n\n置信度: 高 (85%)\n\n理由:\n  - 包含概念解释\n  - 有学习笔记特征\n  - 包含理解过程\n\n是否应用此分类? (yes/no)\n```\n```\n\n### 4. 关联建议\n\n```markdown\n## 智能关联推荐\n\n识别可能相关的知识条目:\n\n1. **标题相似度**\n   - 计算与现有条目标题的相似度\n   - 识别同义词和相关词\n\n2. **标签重叠度**\n   - Jaccard 相似系数\n   - 标签重叠越多,关联性越强\n\n3. **内容引用**\n   - 检测是否提及了其他条目的 ID\n   - 识别标题或内容中提到的其他概念\n\n4. **时间邻近性**\n   - 近期创建的相关条目\n   - 同一时期学习的内容\n\n输出格式:\n```\n发现 3 个可能相关的条目:\n\n1. [2025-01-03-102015] React 基础概念\n   相关度: 95% (高)\n   关联类型: references\n   理由: 标题和内容都有 \"React\" 关键词\n\n2. [2025-01-02-084530] 函数组件\n   相关度: 82% (中高)\n   关联类型: builds-on\n   理由: Hooks 是在函数组件基础上构建的\n\n3. [2025-01-01-120000] JavaScript 闭包\n   相关度: 45% (低)\n   关联类型: related\n   理由: 都涉及前端开发\n\n是否创建这些关联? (all/select/none)\n```\n```\n\n### 5. 知识组织分析\n\n```markdown\n## 组织结构分析\n\n定期分析知识库的组织状况:\n\n1. **重复检测**\n   - 查找标题或内容相似的条目\n   - 建议合并或建立关联\n\n2. **孤立条目检测**\n   - 没有链接的条目\n   - 没有反向链接的条目\n   - 建议创建关联\n\n3. **标签分析**\n   - 统计标签使用频率\n   - 识别过度使用或很少使用的标签\n   - 建议标签优化\n\n4. **分类分布**\n   - 分析各分类的条目数量\n   - 识别不平衡的分类\n\n输出格式:\n```\n知识库组织分析报告:\n\n📊 总体统计\n  总条目: 45 个\n  总标签: 32 个\n  总链接: 23 个\n\n🔍 重复检测\n  发现 2 对相似条目:\n  - [2025-01-01-100000] React Hooks\n    [2025-01-03-150000] React Hooks 详解\n    相似度: 78%\n    建议: 建立关联或合并\n\n🏝️  孤立条目\n  5 个条目没有链接:\n  - [2025-01-02-120000] CSS Grid\n  - [2025-01-04-090000] TypeScript 基础\n  ...\n\n🏷️  标签分析\n  最常用标签:\n  1. react (12 次)\n  2. javascript (8 次)\n  3. hooks (6 次)\n\n  很少使用的标签:\n  - debugging (1 次)\n  - optimization (1 次)\n\n📁 分类分布\n  code: 15 个 (33%)\n  learning: 18 个 (40%)\n  projects: 8 个 (18%)\n  personal: 4 个 (9%)\n\n💡 优化建议\n  1. 为孤立条目创建关联\n  2. 合并相似的 React Hooks 条目\n  3. 考虑合并 debugging 和 optimization 标签\n```\n```\n\n## 智能建议示例\n\n### 场景 1: 用户添加 React Hooks 笔记\n\n```markdown\n用户执行: /kb-add --type=learning-note\n标题: React Hooks 学习笔记\n\n[用户输入内容后]\n\nKnowledge Manager 自动触发:\n\n✨ 内容分析完成!\n\n建议标签:\n  主标签: react, hooks\n  相关标签: frontend, functional-components\n  理由: 内容主要讨论 React Hooks 和函数组件\n\n建议分类: learning\n置信度: 高 (92%)\n理由: 学习笔记格式,包含概念解释\n\n发现相关条目:\n  1. [2025-01-03-102015] React 基础概念 (相关度: 88%)\n     建议: references - 引用了 React 基础概念\n\n  2. [2025-01-02-084530] 函数组件 (相关度: 75%)\n     建议: builds-on - 在函数组件基础上讨论\n\n是否应用这些建议?\n输入选项:\n  - apply all: 应用所有建议\n  - select: 选择性应用\n  - skip: 跳过,稍后手动处理\n\n用户选择: apply all\n\n✅ 已应用所有建议!\n标签已更新: react, hooks, frontend, functional-components\n分类已更新: learning\n关联已创建:\n  → references: 2025-01-03-102015\n  → builds-on: 2025-01-02-084530\n```\n\n### 场景 2: 用户请求知识库分析\n\n```markdown\n用户输入: 帮我分析知识库的组织情况\n\nKnowledge Manager 执行:\n\n📊 知识库组织分析报告\n\n=== 总体概况 ===\n  总条目数: 45 个\n  总标签数: 32 个\n  总链接数: 23 个\n  平均每个条目链接数: 0.51 个\n\n=== 重复检测 ===\n  发现 3 对可能重复的条目:\n\n  1. React Hooks 相关 (相似度: 82%)\n     [2025-01-01-100000] React Hooks 入门\n     [2025-01-03-150000] React Hooks 详解\n     建议: 建立关联 (builds-on)\n\n  2. JavaScript 异步 (相似度: 75%)\n     [2025-01-02-110000] Promise 和 async/await\n     [2025-01-04-120000] JavaScript 异步编程\n     建议: 合并为一个条目\n\n  3. CSS Flexbox (相似度: 68%)\n     [2025-01-05-090000] Flexbox 布局\n     [2025-01-06-100000] Flexbox 完整指南\n     建议: 保留较新的版本\n\n=== 孤立条目 ===\n  8 个条目没有任何链接:\n\n  1. [2025-01-02-120000] CSS Grid 布局\n     建议关联: [2025-01-05-090000] Flexbox 布局 (related)\n\n  2. [2025-01-04-090000] TypeScript 基础\n     建议关联: [2025-01-01-100000] React Hooks (related)\n\n  ... (其余 6 个)\n\n=== 标签分析 ===\n  使用频率分布:\n    高频 (>10次): react (12), javascript (8)\n    中频 (5-10次): hooks (6), async (5)\n    低频 (<5次): 其余 28 个标签\n\n  标签优化建议:\n    1. 合并相似标签:\n       - js → javascript\n       - ts → typescript\n\n    2. 拆分宽泛标签:\n       - frontend → react, vue, angular\n\n=== 分类分布 ===\n  code: 15 个 (33%) ⚖️  平衡\n  learning: 18 个 (40%) ⚖️  平衡\n  projects: 8 个 (18%) ⚖️  偏低\n  personal: 4 个 (9%) ⚠️  过低\n\n  建议: 增加项目和反思类内容的记录\n\n=== 质量评估 ===\n  高质量条目 (>500字): 12 个 (27%)\n  中等质量 (200-500字): 23 个 (51%)\n  低质量条目 (<200字): 10 个 (22%)\n\n  建议: 丰富低质量条目的内容\n\n💡 行动建议:\n  1. 立即处理: 合并重复的 JavaScript 异步条目\n  2. 本周完成: 为孤立条目创建关联\n  3. 持续优化: 增加项目和反思类内容\n  4. 标签整理: 统一 js 和 javascript 标签\n\n是否需要我帮你执行这些建议?\n```\n\n## 技术实现\n\n### 1. 相似度计算\n\n```javascript\n// Jaccard 相似系数 (标签重叠度)\nfunction jaccardSimilarity(tags1, tags2) {\n  const intersection = tags1.filter(tag => tags2.includes(tag));\n  const union = [...new Set([...tags1, ...tags2])];\n  return intersection.length / union.length;\n}\n\n// 文本相似度 (简单的词频统计)\nfunction textSimilarity(text1, text2) {\n  const words1 = tokenize(text1);\n  const words2 = tokenize(text2);\n  const common = words1.filter(word => words2.includes(word));\n  return common.length / Math.max(words1.length, words2.length);\n}\n```\n\n### 2. 标签推荐算法\n\n```\n1. 提取内容中的关键词\n2. 与 tags.json 中的现有标签匹配\n3. 计算每个相关标签的权重\n4. 推荐权重最高的 3-5 个标签\n```\n\n### 3. 分类判断\n\n```\n1. 统计内容中的特征词\n2. 每个分类有对应的特征词列表\n3. 计算内容与每个分类的匹配度\n4. 选择匹配度最高的分类\n```\n\n## 配置选项\n\n### 自动应用阈值\n\n```json\n{\n  \"autoApply\": {\n    \"tags\": {\n      \"confidence\": 0.9,\n      \"minMatches\": 2\n    },\n    \"category\": {\n      \"confidence\": 0.85\n    },\n    \"links\": {\n      \"minSimilarity\": 0.8\n    }\n  }\n}\n```\n\n### 分析频率\n\n```json\n{\n  \"analysis\": {\n    \"onAdd\": true,\n    \"onEdit\": true,\n    \"scheduled\": \"weekly\"\n  }\n}\n```\n\n## 注意事项\n\n1. **用户控制**: 所有建议都需要用户确认,不自动修改\n2. **性能优化**: 大量条目时使用缓存和增量分析\n3. **隐私保护**: 分析过程仅在本地进行,不上传数据\n4. **可配置性**: 允许用户自定义分析规则和阈值\n\n## 未来扩展\n\n1. **语义分析**: 使用 NLP 技术进行更深入的语义理解\n2. **自动摘要**: 为长内容生成简洁的摘要\n3. **知识图谱**: 可视化知识网络\n4. **智能问答**: 基于知识库内容回答问题\n5. **学习路径**: 自动推荐学习顺序和关联内容\n"},"lastSynced":"2026-03-08T02:02:22.164Z","agentAnalysis":{"suitability":{"en":"Perfect for AI Agents like Cursor, Windsurf, and Claude Code needing advanced knowledge base optimization and automation capabilities.","zh":"非常适合像Cursor、Windsurf和Claude Code这样的AI代理，它们需要高级知识库优化和自动化能力。","ja":"Cursor、Windsurf、Claude CodeのようなAIエージェントに適しています。高度なナレッジベースの最適化と自動化機能が必要です。","ko":"Cursor, Windsurf, Claude Code와 같은 AI 에이전트에게 적합합니다. 고급 지식베이스 최적화 및 자동화 기능이 필요합니다.","es":"Perfecto para agentes de IA como Cursor, Windsurf y Claude Code que necesitan una optimización y automatización avanzada de la base de conocimientos.","fr":"Parfait pour les agents IA comme Cursor, Windsurf et Claude Code ayant besoin d''une optimisation et d''une automatisation avancées de la base de connaissances.","de":"Perfekt für KI-Agents wie Cursor, Windsurf und Claude Code, die eine erweiterte Optimierung und Automatisierung der Wissensbasis benötigen.","pt":"Perfeito para AI Agents como Cursor, Windsurf e Claude Code que necessitam de capacidades avançadas de otimização e automação de base de conhecimento.","ru":"Идеально подходит для AI Agents, таких как Cursor, Windsurf и Claude Code, которым требуются расширенные возможности оптимизации и автоматизации базы знаний.","ar":"مثالي لوكلاء الذكاء الاصطناعي مثل Cursor وWindsurf وClaude Code التي تحتاج إلى قدرات متقدمة لتحسين قاعدة المعرفة والأتمتة."},"recommendation":{"en":"Empowers agents to automate knowledge base optimization using natural language interfaces, spaced repetition learning, and intelligent suggestions for tagging, categorization, and association, leveraging techniques like automatic label suggestion and quality assessment.","zh":"赋予代理使用自然语言接口、间隔重复学习和智能标签、分类和关联建议来自动化知识库优化的能力，利用自动标签建议和质量评估等技术。","ja":"エージェントに自然言語インターフェイス、間隔反復学習、およびタグ付け、分類、関連付けのためのインテリジェントな提案を使用してナレッジベースの最適化を自動化する力を与え、自動ラベル提案や品質評価などの手法を利用します。","ko":"에이전트에게 자연어 인터페이스, 간격 반복 학습 및 태그付け, 분류, 연관성에 대한 지능형 제안을 사용하여 지식베이스 최적화를 자동화하는 능력을 부여하며, 자동 레이블 제안 및 품질 평가와 같은 기술을 활용합니다.","es":"Habilita a los agentes a automatizar la optimización de la base de conocimientos utilizando interfaces de lenguaje natural, aprendizaje de repetición espaciada y sugerencias inteligentes para etiquetado, categorización y asociación, aprovechando técnicas como la sugerencia automática de etiquetas y evaluación de calidad.","fr":"Permet aux agents d''automatiser l''optimisation de la base de connaissances en utilisant des interfaces de langage naturel, un apprentissage par répétition espacée et des suggestions intelligentes pour le étiquetage, la catégorisation et l''association, en exploitant des techniques comme la suggestion automatique d''étiquettes et l''évaluation de la qualité.","de":"Ermöglicht es Agenten, die Optimierung der Wissensbasis zu automatisieren, indem sie natürliche Sprachinterfaces, Lernen durch zeitlich verteilte Wiederholung und intelligente Vorschläge für Tagging, Kategorisierung und Assoziation nutzen, wobei Techniken wie automatische Labelvorschläge und Qualitätsbewertung eingesetzt werden.","pt":"Capacita os agentes a automatizar a otimização da base de conhecimento usando interfaces de linguagem natural, aprendizado por repetição espaçada e sugestões inteligentes para etiquetagem, categorização e associação, aproveitando técnicas como sugestão automática de rótulos e avaliação de qualidade.","ru":"Позволяет агентам автоматизировать оптимизацию базы знаний с использованием интерфейсов естественного языка, обучения с интервальным повторением и интеллектуальных предложений по тегированию, категоризации и ассоциации, используя такие методы, как автоматическое предложение меток и оценка качества.","ar":"يمكّن الوكلاء من أتمتة تحسين قاعدة المعرفة باستخدام واجهات اللغة الطبيعية، وتعلم التكرار المتباعد، والاقتراحات الذكية لوضع العلامات والتصنيف والارتباط، مع الاستفادة من تقنيات مثل الاقتراح التلقائي للعلامات والتقييم النوعي."},"useCases":{"en":["Automating knowledge base organization and structuring","Generating intelligent tag suggestions for new knowledge entries","Identifying and linking related knowledge articles","Detecting and merging duplicate entries to maintain data integrity","Evaluating the completeness and quality of knowledge base entries"],"zh":["自动化知识库的组织和结构化","为新知识条目生成智能标签建议","识别和链接相关知识文章","检测和合并重复条目以维护数据完整性","评估知识库条目的完整性和质量"],"ja":["ナレッジベースの組織化と構造化を自動化する","新しいナレッジエントリに対するインテリジェントなタグの提案を生成する","関連するナレッジ記事を識別してリンクする","重複したエントリを検出してマージしてデータの完全性を維持する","ナレッジベースエントリの完全性と品質を評価する"],"ko":["지식베이스의 조직화와 구조화를 자동화한다","새로운 지식 항목에 대한 지능형 태그 제안을 생성한다","관련 지식 기사를 식별하고 연결한다","중복된 항목을检测하고 병합하여 데이터 무결성을 유지한다","지식베이스 항목의 완전성과 품질을 평가한다"],"es":["Automatizar la organización y estructuración de la base de conocimientos","Generar sugerencias inteligentes de etiquetas para nuevas entradas de conocimiento","Identificar y enlazar artículos de conocimiento relacionados","Detectar y fusionar entradas duplicadas para mantener la integridad de los datos","Evaluar la complejidad y la calidad de las entradas de la base de conocimientos"],"fr":["Automatiser l''organisation et la structuration de la base de connaissances","Générer des suggestions intelligentes d''étiquettes pour de nouvelles entrées de connaissances","Identifier et relier des articles de connaissances liés","Détecter et fusionner des entrées en double pour maintenir l''intégrité des données","Évaluer l''exhaustivité et la qualité des entrées de la base de connaissances"],"de":["Automatisieren der Organisation und Strukturierung der Wissensbasis","Generieren intelligenter Tagvorschläge für neue Wissenseinträge","Identifizieren und Verknüpfen verwandter Wissensartikel","Erkennen und Zusammenführen doppelter Einträge, um die Datenintegrität zu gewährleisten","Bewerten der Vollständigkeit und Qualität der Wissenseinträge"],"pt":["Automatizando a organização e estruturação da base de conhecimento","Gerando sugestões inteligentes de tags para novas entradas de conhecimento","Identificando e vinculando artigos de conhecimento relacionados","Detectando e mesclando entradas duplicadas para manter a integridade dos dados","Avaliando a completude e qualidade das entradas da base de conhecimento"],"ru":["Автоматизация организации и структурирования базы знаний","Генерация интеллектуальных предложений тегов для новых записей знаний","Выявление и связывание связанных статей базы знаний","Обнаружение и слияние дублирующихся записей для поддержания целостности данных","Оценка полноты и качества записей базы знаний"],"ar":["أتمتة تنظيم وهيكلة قاعدة المعرفة","إنشاء اقتراحات ذكية للعلامات لإدخالات المعرفة الجديدة","تحديد وربط مقالات المعرفة ذات الصلة","الكشف عن الإدخالات المكررة ودمجها للحفاظ على سلامة البيانات","تقييم اكتمال وجودة إدخالات قاعدة المعرفة"]},"limitations":{"en":["Requires user interaction for initial knowledge entry or editing","Limited to text-based knowledge entries","Dependent on the quality and consistency of user-inputted data"],"zh":["需要用户交互来进行初始知识条目或编辑","仅限于基于文本的知识条目","依赖于用户输入数据的质量和一致性"],"ja":["初期のナレッジエントリまたは編集にはユーザーの интерактивが必要","テキストベースのナレッジエントリのみに限定される","ユーザー入力データの品質と一貫性に依存する"],"ko":["초기 지식 항목 또는 편집에는 사용자 상호작용이 필요합니다","텍스트 기반 지식 항목만으로 제한됩니다","사용자 입력 데이터의 품질 및 일관성에 의존합니다"],"es":["Requiere interacción del usuario para la entrada o edición inicial de conocimiento","Limitado a entradas de conocimiento basadas en texto","Dependiente de la calidad y la coherencia de los datos ingresados por el usuario"],"fr":["Nécessite une interaction de l''utilisateur pour l''entrée ou l''édition initiale des connaissances","Limité aux entrées de connaissances basées sur le texte","Dépend de la qualité et de la cohérence des données saisies par l''utilisateur"],"de":["Benötigt Benutzereingriff für die anfängliche Erfassung oder Bearbeitung von Wissen","Begrenzt auf textbasierte Wissenseinträge","Abhängig von der Qualität und Konsistenz der vom Benutzer eingegebenen Daten"],"pt":["Requer interação do usuário para a entrada ou edição inicial do conhecimento","Limitado a entradas de conhecimento baseadas em texto","Dependente da qualidade e consistência dos dados inseridos pelo usuário"],"ru":["Требует взаимодействия с пользователем для первоначального ввода или редактирования знаний","Ограничивается текстовыми записями знаний","Зависит от качества и согласованности данных, введенных пользователем"],"ar":["يتطلب تفاعل المستخدم للإدخال أو التحرير الأولي للمعرفة","يقتصر على إدخالات المعرفة المستندة إلى النص","يعتمد على جودة واتساق البيانات المدخلة من قبل المستخدم"]},"version":4},"contentHash":"1c8f7b5218208a1d399427e720477269f9b3db39ac5af4bd4e015d43441645b6","qualityScore":33}');
