INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('huifer/Claude-Code-KnowCraft/knowledge-manager', 'knowledge-manager', 'huifer', 'Claude-Code-KnowCraft', 'community', 'knowledge-manager huifer Claude-Code-KnowCraft community The Knowledge-Manager skill is an AI-powered personal knowledge management system that automates knowledge base optimization using natural language interface and spaced repetition learning, benefiting developers and knowledge workers. 知识管理助手是AI-powered的个人知识管理系统，具有自然语言接口和间隔重复学习功能 知識管理ツールは、AIエージェントを搭載した個人用知識管理システムで、自然言語インターフェースと間隔反復学習機能を備えています 지식 관리 도구는 AI를搭載한 개인 지식 관리 시스템으로 자연어 인터페이스와 간격 반복 학습 기능을 제공합니다 Knowledge Manager es un sistema de gestión de conocimiento con interfaz de lenguaje natural y repetición espaciada que ayuda a los usuarios a organizar y mejorar la calidad de sus conocimientos Knowledge Manager est un système de gestion des connaissances avec interface de langage naturel et répétition espacée qui aide les utilisateurs à organiser et à améliorer la qualité de leurs connaissances Knowledge Manager ist ein KI-gestütztes Wissensmanagementsystem mit natürlicher Sprachsteuerung und zeitlich gestaffelter Wiederholung, das Benutzern hilft, ihre Kenntnisse zu organisieren und zu verbessern O Knowledge Manager é um sistema de gerenciamento de conhecimento com interface de linguagem natural e repetição espaçada. Ele fornece sugestões de tags, associações e categorias para ajudar a organizar o seu conhecimento ИИ Агент Knowledge Manager - это инструмент управления знаниями с естественным интерфейсом и повторением с интервалом. Он предоставляет предложения по тегам, связям и категориям для помощи в организации ваших знаний مدير المعرفة هو نظام إدارة المعرفة باللغة الطبيعية مع إعادة التكرار المكانية. يقدم اقتراحات بالوسوم والارتباطات والفئات لمساعدتك في تنظيم معرفتك how to use knowledge-manager knowledge-manager setup guide knowledge-manager alternative knowledge-manager vs wiki knowledge-manager install what is knowledge-manager knowledge-manager tutorial knowledge-manager for developers knowledge-manager AI-powered 知识管理助手 AI知识管理 自动标签 自动关联 间隔重复学习 自然语言接口 知识库优化 Automates tag suggestions based on content using natural language processing Suggests links between related entries using machine learning algorithms Performs automatic category detection for each entry Identifies and merges duplicate entries using fuzzy matching Evaluates entry completeness and quality using predefined criteria Knowledge-Manager is an AI-powered personal knowledge management system that automates knowledge base structure analysis and optimization.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('AztecProtocol/aztec-packages/updating-changelog', 'community', 'AztecProtocol', 'aztec-packages', 'AztecProtocol/aztec-packages', 'updating-changelog', 0, 0, 33, '2026-03-08T01:57:15.308Z', '2026-03-08T02:02:24.216Z', '8fc6db2a486a74c027ba003c21a6433918677de24609662f597d65d90ceb11a0', '{"id":"AztecProtocol/aztec-packages/updating-changelog","name":"updating-changelog","description":{"en":"The updating-changelog skill helps developers manage changelog files by determining target files and analyzing branch changes. It benefits Aztec contract developers and Node operators.","zh":"更新变更日志涉及读取.release-please-manifest.json文件和运行git diff命令。使用AIエージェント可以简化此过程","ja":"更新履歴の更新には、.release-please-manifest.jsonの読み取りとgit diffの実行が含まれます。AIエージェントを使用してこのプロセスを簡素化します","ko":"변경 기록을 업데이트하는 것은 .release-please-manifest.json 파일을 읽고 git diff 명령을 실행하는 것을 포함합니다. AI 에이전트를 사용하면 이 프로세스를 단순화할 수 있습니다","es":"Actualiza el changelog de manera eficiente utilizando .release-please-manifest.json y git diff. Aprende a determinar los archivos objetivo y analizar los cambios en la rama.","fr":"Mettez à jour le changelog de manière efficace en utilisant .release-please-manifest.json et git diff. Découvrez comment déterminer les fichiers cibles et analyser les modifications de la branche.","de":"Aktualisieren Sie das Changelog effizient mit .release-please-manifest.json und git diff. Lernen Sie, wie man die Zieldateien bestimmt und die Änderungen im Branch analysiert.","pt":"Atualize o changelog com facilidade, seguindo os passos para determinar arquivos-alvo e analisar alterações no branch","ru":"Обновите чейнджлог легко, следуя шагам для определения целевых файлов и анализа изменений в ветке","ar":"قم بتحديث سجل التغيير بسهولة، باتباع الخطوات لتحديد الملفات المستهدفة وتحليل التغييرات في الفرع"},"seo":{"title":{"en":"Updating-Changelog: Changelog Management Setup Guide | AI...","zh":"更新变更日志 Setup Guide - AIエージェント","ja":"更新履歴の更新方法 - AIエージェント Setup Guide","ko":"변경 기록 업데이트 가이드 - AI 에이전트","es":"Guía de Actualización de Changelog con Herramientas de AI","fr":"Mise à Jour de Changelog avec les Outils d''Agents IA","de":"Changelog-Update-Anleitung mit KI-Tools","pt":"Guia de Atualização do Changelog: Melhores Práticas","ru":"Обновление Чейнджлога: Руководство по Настройке ИИ Агентов","ar":"دليل تحديث سجل التغيير: إرشادات الإعداد لأدوات الذكاء الا..."},"description":{"en":"Learn how to update changelogs efficiently with this AI agent skill. Discover the steps and commands to manage your changelog files effectively.","zh":"了解更新变更日志的步骤，包括读取.release-please-manifest.json和运行git diff命令，使用AIエージェント","ja":"更新履歴を更新するための手順をご紹介します。.release-please-manifest.jsonの読み取りやgit diffの実行など、AIエージェントを使用した方法","ko":"변경 기록을 업데이트 하는 방법을 알아보세요. .release-please-manifest.json 읽기 및 git diff 명령 실행 등 AI 에이전트를 사용합니다","es":"Aprende a actualizar el changelog con las mejores prácticas y herramientas de AI. Descubre cómo utilizar .release-please-manifest.json y git diff para una ac...","fr":"Découvrez comment mettre à jour le changelog avec les meilleures pratiques et les outils d''Agents IA. Utilisez .release-please-manifest.json et git diff pour...","de":"Erfahren Sie, wie Sie das Changelog mit den besten Praktiken und KI-Tools aktualisieren. Lernen Sie, wie man .release-please-manifest.json und git diff für e...","pt":"Aprenda a atualizar o changelog com eficácia, utilizando o arquivo .release-please-manifest.json e comandos Git","ru":"Узнайте, как обновить чейнджлог, используя файл .release-please-manifest.json и команды Git, с помощью ИИ Агентов","ar":"تعلم كيفية تحديث سجل التغيير بفعالية، باستخدام ملف .release-please-manifest.json وأوامر Git، مع أدوات الذكاء الاصطناعي"},"definition":{"en":"Updating-changelog is a skill that automates the process of updating changelog files by reading release manifests and analyzing Git branch changes.","zh":"更新变更日志是指更新项目的变更记录，包括读取.release-please-manifest.json文件和运行git diff命令","ja":"更新履歴の更新とは、プロジェクトの変更履歴を更新することを指し、.release-please-manifest.jsonの読み取りやgit diffの実行が含まれます","ko":"변경 기록 업데이트는 프로젝트의 변경 기록을 업데이트하는 것을 의미하며, .release-please-manifest.json 파일을 읽고 git diff 명령을 실행하는 것을 포함합니다","es":"La actualización de changelog es el proceso de actualizar el registro de cambios en un proyecto utilizando herramientas de AI como .release-please-manifest.json y git diff.","fr":"La mise à jour de changelog est le processus de mise à jour du registre des modifications dans un projet en utilisant des outils d''Agents IA tels que .release-please-manifest.json et git diff.","de":"Die Aktualisierung des Changelogs ist der Prozess der Aktualisierung des Änderungsprotokolls in einem Projekt mit KI-Tools wie .release-please-manifest.json und git diff.","pt":"Atualização do changelog é o processo de registro de alterações em um projeto","ru":"Обновление чейнджлога - это процесс регистрации изменений в проекте","ar":"تحديث سجل التغيير هو عملية تسجيل التغييرات في مشروع"},"features":{"en":["Reads `.release-please-manifest.json` files to determine version updates","Edits `v{major}.md` files based on version changes","Runs `git diff` commands to analyze branch changes","Supports Aztec contract developers and Node operators with specific target files","Updates `docs/docs-developers/docs/resources/migration_notes.md` and `docs/docs-operate/operators/reference/changelog/v{major}.md` files"],"zh":["读取.release-please-manifest.json文件","运行git diff命令","支持Aztec合约开发者和Node操作员","生成变更日志文件（例如v4.md）","支持多个目标文件（例如docs/docs-developers/docs/resources/migration_notes.md）"],"ja":[".release-please-manifest.jsonの読み取り","git diffの実行","Aztecコントラクト開発者とNodeオペレーターのサポート","変更履歴ファイル（例：v4.md）の生成","複数の対象ファイル（例：docs/docs-developers/docs/resources/migration_notes.md）のサポート"],"ko":[".release-please-manifest.json 파일 읽기","git diff 명령 실행","Aztec 계약 개발자 및 노드 운영자 지원","변경 기록 파일 생성（예：v4.md）","여러 대상 파일 지원（예：docs/docs-developers/docs/resources/migration_notes.md）"],"es":["Determinar archivos objetivo con .release-please-manifest.json","Analizar cambios en la rama con git diff","Actualizar el changelog para desarrolladores de contrato Aztec","Actualizar el changelog para operadores de nodo y desarrolladores de contrato Ethereum","Utilizar git diff para obtener una visión general de los cambios","Utilizar git diff para obtener detalles de los cambios"],"fr":["Déterminer les fichiers cibles avec .release-please-manifest.json","Analyser les modifications de la branche avec git diff","Mettre à jour le changelog pour les développeurs de contrat Aztec","Mettre à jour le changelog pour les opérateurs de nœud et les développeurs de contrat Ethereum","Utiliser git diff pour obtenir une vue d''ensemble des modifications","Utiliser git diff pour obtenir des détails sur les modifications"],"de":["Bestimmen der Zieldateien mit .release-please-manifest.json","Analysieren der Änderungen im Branch mit git diff","Aktualisieren des Changelogs für Aztec-Vertragsentwickler","Aktualisieren des Changelogs für Node-Operatoren und Ethereum-Vertragsentwickler","Verwenden von git diff für eine Übersicht der Änderungen","Verwenden von git diff für Details der Änderungen"],"pt":["Leitura do arquivo .release-please-manifest.json para determinar a versão","Utilização de comandos Git, como git diff, para analisar alterações","Atualização de arquivos-alvo, como docs/docs-developers/docs/resources/migration_notes.md","Suporte a múltiplos arquivos de changelog, como v{major}.md","Análise de alterações no branch com git diff next...HEAD --stat"],"ru":["Чтение файла .release-please-manifest.json для определения версии","Использование команд Git, таких как git diff, для анализа изменений","Обновление целевых файлов, таких как docs/docs-developers/docs/resources/migration_notes.md","Поддержка нескольких файлов чейнджлога, таких как v{major}.md","Анализ изменений в ветке с помощью git diff next...HEAD --stat"],"ar":["قراءة ملف .release-please-manifest.json لتحديد الإصدار","استخدام أوامر Git، مثل git diff، لتحليل التغييرات","تحديث الملفات المستهدفة، مثل docs/docs-developers/docs/resources/migration_notes.md","دعم ملفات سجل التغيير المتعددة، مثل v{major}.md","تحليل التغييرات في الفرع باستخدام git diff next...HEAD --stat"]},"keywords":{"en":["how to update changelog","updating-changelog setup guide","changelog management best practices","git diff commands for changelog","updating-changelog alternative","updating-changelog vs manual changelog update","install updating-changelog","updating-changelog for AI agents","what is updating-changelog"],"zh":["更新变更日志","AIエージェント","变更记录","git diff","release-please-manifest.json","Aztec合约开发","Node操作"],"ja":["更新履歴の更新","AIエージェント","変更履歴","git diff","release-please-manifest.json","Aztecコントラクト開発","Nodeオペレーション"],"ko":["변경 기록 업데이트","AI 에이전트","변경 기록","git diff","release-please-manifest.json","Aztec 계약 개발","노드 운영"],"es":["actualización de changelog","herramientas de AI","release-please-manifest.json","git diff","desarrollo de contrato Aztec","operadores de nodo","desarrollo de contrato Ethereum","mejores prácticas de changelog"],"fr":["mise à jour de changelog","outils d''Agents IA","release-please-manifest.json","git diff","développement de contrat Aztec","opérateurs de nœud","développement de contrat Ethereum","meilleures pratiques de changelog"],"de":["Aktualisierung des Changelogs","KI-Tools","release-please-manifest.json","git diff","Entwicklung von Aztec-Verträgen","Node-Operatoren","Entwicklung von Ethereum-Verträgen","beste Praktiken für Changelog"],"pt":["atualização do changelog","guia de atualização","melhores práticas de changelog","utilização de Git","arquivo .release-please-manifest.json","comandos Git","desenvolvimento de software"],"ru":["обновление чейнджлога","руководство по обновлению","лучшие практики чейнджлога","использование Git","файл .release-please-manifest.json","команды Git","разработка программного обеспечения","ИИ Агенты"],"ar":["تحديث سجل التغيير","دليل التحديث","أفضل الممارسات لسجل التغيير","استخدام Git","ملف .release-please-manifest.json","أوامر Git","تطوير البرمجيات","أدوات الذكاء الاصطناعي"]}},"owner":"AztecProtocol","repo":"aztec-packages","repoPath":"AztecProtocol/aztec-packages","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.308Z","topics":[],"category":"community","skillMd":{"name":"updating-changelog","description":"Updates changelog documentation for contract developers and node operators by analyzing branch changes relative to next. Use when preparing a PR, updating migration notes, documenting breaking changes, or when asked to update changelog/release notes.","bodyPreview":"# Updating Changelog\n\n## Steps\n\n### 1. Determine Target Files\n\nRead `.release-please-manifest.json` to get the version (e.g., `{\".\" : \"4.0.0\"}` → edit `v4.md`).\n\n**Target files:**\n\n- Aztec contract developers: `docs/docs-developers/docs/resources/migration_notes.md`\n- Node operators and Ethereum contract developers: `docs/docs-operate/operators/reference/changelog/v{major}.md`\n\n### 2. Analyze Branch Changes\n\nRun `git diff next...HEAD --stat` for overview, then `git diff next...HEAD` for details.","body":"# Updating Changelog\n\n## Steps\n\n### 1. Determine Target Files\n\nRead `.release-please-manifest.json` to get the version (e.g., `{\".\" : \"4.0.0\"}` → edit `v4.md`).\n\n**Target files:**\n\n- Aztec contract developers: `docs/docs-developers/docs/resources/migration_notes.md`\n- Node operators and Ethereum contract developers: `docs/docs-operate/operators/reference/changelog/v{major}.md`\n\n### 2. Analyze Branch Changes\n\nRun `git diff next...HEAD --stat` for overview, then `git diff next...HEAD` for details.\n\n**Categorize changes:**\n\n- Breaking changes (API modifications, removals, renames)\n- New features (APIs, CLI flags, configuration)\n- Deprecations\n- Configuration changes (CLI flags, environment variables)\n\n### 3. Generate Draft Entries\n\nPresent draft entries for review BEFORE editing files. Match the formatting conventions by reading existing entries in each file.\n\n### 4. Edit Documentation\n\nAfter approval, add entries to the appropriate files.\n\n## Migration Notes Format\n\n**File:** `docs/docs-developers/docs/resources/migration_notes.md`\n\nAdd entries under `## TBD` section:\n\n````markdown\n### [Component] Brief description\n\nExplanation of what changed.\n\n**Migration:**\n\n```diff\n- old code\n+ new code\n```\n````\n\n**Impact**: Effect on existing code.\n\n**Component tags:** `[Aztec.nr]`, `[Aztec.js]`, `[PXE]`, `[Aztec Node]`, `[AVM]`, `[L1 Contracts]`, `[CLI]`\n\n## Node Operator Changelog Format\n\n**File:** `docs/docs-operate/operators/reference/changelog/v{major}.md`\n\n**Breaking changes:**\n````markdown\n### Feature Name\n\n**v{previous}:**\n```bash\n--old-flag <value>                    ($OLD_ENV_VAR)\n```\n\n**v{current}:**\n```bash\n--new-flag <value>                    ($NEW_ENV_VAR)\n```\n\n**Migration**: How to migrate.\n````\n\n**New features:**\n````markdown\n### Feature Name\n\n```bash\n--new-flag <value>                    ($ENV_VAR)\n```\n\nDescription of the feature.\n````\n\n**Changed defaults:** Use table format with Flag, Environment Variable, Previous, New columns.\n"},"lastSynced":"2026-03-08T02:02:24.216Z","agentAnalysis":{"suitability":{"en":"Perfect for Version Control Agents needing automated changelog management capabilities.","zh":"非常适合需要自动化变更日志管理功能的版本控制代理。","ja":"バージョン管理エージェントが自動化された変更ログ管理機能を必要とする場合に最適です。","ko":"自動화된 변경 로그 관리 기능이 필요한 버전 제어 에이전트에 적합합니다.","es":"Perfecto para agentes de control de versiones que necesitan capacidades de gestión de registros de cambios automatizados.","fr":"Parfait pour les agents de contrôle de version nécessitant des capacités de gestion de journaux de modifications automatisées.","de":"Perfekt für Version Control Agents, die automatisierte Änderungsprotokoll-Verwaltungsfunktionen benötigen.","pt":"Perfeito para Agentes de Controle de Versão que precisam de capacidades de gerenciamento de changelog automatizado.","ru":"Идеально подходит для агентов контроля версий, требующих автоматизированных возможностей управления журналом изменений.","ar":"مثالي للوكلاء الذين يحتاجون إلى إمكانيات إدارة سجل التغييرات الآلي"},"recommendation":{"en":"Empowers agents to analyze Git branch changes and update changelog files using `.release-please-manifest.json` and `git diff` commands, streamlining the development process for Aztec contract developers and Node operators.","zh":"赋予代理分析 Git 分支更改并使用 `.release-please-manifest.json` 和 `git diff` 命令更新更改日志文件的能力，简化 Aztec 合约开发人员和 Node 操作员的开发流程。","ja":"エージェントが Git ブランチの変更を分析し、`.release-please-manifest.json` と `git diff` コマンドを使用して変更ログファイルを更新する能力を付与し、Aztec コントラクト開発者と Node オペレーターの開発プロセスを簡素化します。","ko":"에이전트가 Git 브랜치의 변경 사항을 분석하고 `.release-please-manifest.json` 및 `git diff` 명령을 사용하여 변경 로그 파일을 업데이트할 수 있는 기능을 부여하여 Aztec 계약 개발자와 노드 운영자들의 개발 프로세스를 간소화합니다.","es":"Habilita a los agentes a analizar los cambios de la rama Git y actualizar los archivos de registro de cambios utilizando `.release-please-manifest.json` y comandos `git diff`, simplificando el proceso de desarrollo para desarrolladores de contratos Aztec y operadores de Node.","fr":"Permet aux agents d''analyser les modifications de la branche Git et de mettre à jour les fichiers de journal des modifications en utilisant `.release-please-manifest.json` et des commandes `git diff`, simplifiant ainsi le processus de développement pour les développeurs de contrats Aztec et les opérateurs de Node.","de":"Ermächtigt Agenten, Git-Zweig-Änderungen zu analysieren und Änderungsprotokoll-Dateien mithilfe von `.release-please-manifest.json` und `git diff`-Befehlen zu aktualisieren, wodurch der Entwicklungsprozess für Aztec-Vertragsentwickler und Node-Operatoren gestreamt wird.","pt":"Habilita os agentes a analisar alterações de branch do Git e atualizar arquivos de changelog usando `.release-please-manifest.json` e comandos `git diff`, simplificando o processo de desenvolvimento para desenvolvedores de contrato Aztec e operadores de Node.","ru":"Позволяет агентам анализировать изменения веток Git и обновлять файлы журнала изменений с помощью `.release-please-manifest.json` и команд `git diff`, оптимизируя процесс разработки для разработчиков контрактов Aztec и операторов Node.","ar":"تمكّن الوكلاء من تحليل التغييرات في فروع جيت و تحديث ملفات سجل التغييرات باستخدام `.release-please-manifest.json` و أوامر `git diff`، و يُبسط عملية التطوير لمطوري عقد أزتك و مشغلي نود"},"useCases":{"en":["Automating changelog updates for new releases","Analyzing branch changes using `git diff` commands","Generating changelog entries for Node operators and Ethereum contract developers"],"zh":["自动化新版本的变更日志更新","使用 `git diff` 命令分析分支更改","为 Node 操作员和 Ethereum 合约开发人员生成变更日志条目"],"ja":["新しいリリースの変更ログの自動更新","`git diff` コマンドを使用してブランチの変更を分析","Node オペレータと Ethereum コントラクト開発者のために変更ログエントリを生成"],"ko":["새 릴리스의 변경 로그 자동 업데이트","`git diff` 명령을 사용하여 브랜치의 변경 사항을 분석","노드 운영자 및 이더리움 계약 개발자를 위한 변경 로그 항목 생성"],"es":["Automatizar las actualizaciones del registro de cambios para nuevas versiones","Analizar los cambios de la rama utilizando comandos `git diff`","Generar entradas de registro de cambios para operadores de Node y desarrolladores de contratos Ethereum"],"fr":["Automatiser les mises à jour du journal des modifications pour les nouvelles versions","Analyser les modifications de la branche en utilisant des commandes `git diff`","Générer des entrées de journal des modifications pour les opérateurs de Node et les développeurs de contrats Ethereum"],"de":["Automatisieren von Änderungsprotokoll-Aktualisierungen für neue Versionen","Analysieren von Zweig-Änderungen mithilfe von `git diff`-Befehlen","Generieren von Änderungsprotokoll-Einträgen für Node-Operatoren und Ethereum-Vertragsentwickler"],"pt":["Automatizar atualizações de changelog para novas versões","Analizar alterações de branch usando comandos `git diff`","Gerar entradas de changelog para operadores de Node e desenvolvedores de contrato Ethereum"],"ru":["Автоматизировать обновления журнала изменений для новых релизов","Анализировать изменения веток с помощью команд `git diff`","Генерировать записи журнала изменений для операторов Node и разработчиков контрактов Ethereum"],"ar":["توفير تحديثات سجل التغييرات آلياً للنسخ الجديدة","تحليل التغييرات في الفروع باستخدام أوامر `git diff`","генерировать مدخلات سجل التغييرات لمشغلي نود و مطوري عقود إيثريوم"]},"limitations":{"en":["Requires access to Git repository","Limited to specific file formats (e.g., `.release-please-manifest.json`, `v{major}.md`)","Designed for Aztec contract developers and Node operators"],"zh":["需要访问 Git 仓库","仅限于特定文件格式（例如 `.release-please-manifest.json`、`v{major}.md`）","仅适用于 Aztec 合约开发人员和 Node 操作员"],"ja":["Git リポジトリへのアクセスが必要","特定のファイル形式（例：`.release-please-manifest.json`、`v{major}.md`）に限定される","Aztec コントラクト開発者と Node オペレーターのみを対象としています"],"ko":["Git 리포지토리에 대한 액세스가 필요","특정 파일 형식（예: `.release-please-manifest.json`、`v{major}.md`）으로 제한","Aztec 계약 개발자 및 노드 운영자를 위한 것으로 설계"],"es":["Requiere acceso al repositorio Git","Limitado a formatos de archivo específicos (por ejemplo, `.release-please-manifest.json`, `v{major}.md`)","Diseñado para desarrolladores de contratos Aztec y operadores de Node"],"fr":["Nécessite un accès au référentiel Git","Limité à des formats de fichiers spécifiques (par exemple, `.release-please-manifest.json`, `v{major}.md`)","Conçu pour les développeurs de contrats Aztec et les opérateurs de Node"],"de":["Erfordert Zugriff auf das Git-Repository","Begrenzt auf bestimmte Dateiformate (z. B. `.release-please-manifest.json`, `v{major}.md`)","Entworfen für Aztec-Vertragsentwickler und Node-Operatoren"],"pt":["Requer acesso ao repositório Git","Limitado a formatos de arquivo específicos (por exemplo, `.release-please-manifest.json`, `v{major}.md`)","Projetado para desenvolvedores de contrato Aztec e operadores de Node"],"ru":["Требует доступа к репозиторию Git","Ограничен конкретными форматами файлов (например, `.release-please-manifest.json`, `v{major}.md`)","Разработан для разработчиков контрактов Aztec и операторов Node"],"ar":["يتطلب الوصول إلى مستودع جيت","محدود بتنسيقات الملفات المحددة (على سبيل المثال `.release-please-manifest.json` و `v{major}.md`)","تم تصميمه لمطوري عقد أزتك و مشغلي نود"]},"version":4},"contentHash":"8fc6db2a486a74c027ba003c21a6433918677de24609662f597d65d90ceb11a0","qualityScore":33}');
