INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('AztecProtocol/aztec-packages/updating-changelog', 'updating-changelog', 'AztecProtocol', 'aztec-packages', 'community', 'updating-changelog AztecProtocol aztec-packages community The updating-changelog skill helps developers manage changelog files by determining target files and analyzing branch changes. It benefits Aztec contract developers and Node operators. 更新变更日志涉及读取.release-please-manifest.json文件和运行git diff命令。使用AIエージェント可以简化此过程 更新履歴の更新には、.release-please-manifest.jsonの読み取りとgit diffの実行が含まれます。AIエージェントを使用してこのプロセスを簡素化します 변경 기록을 업데이트하는 것은 .release-please-manifest.json 파일을 읽고 git diff 명령을 실행하는 것을 포함합니다. AI 에이전트를 사용하면 이 프로세스를 단순화할 수 있습니다 Actualiza el changelog de manera eficiente utilizando .release-please-manifest.json y git diff. Aprende a determinar los archivos objetivo y analizar los cambios en la rama. Mettez à jour le changelog de manière efficace en utilisant .release-please-manifest.json et git diff. Découvrez comment déterminer les fichiers cibles et analyser les modifications de la branche. Aktualisieren Sie das Changelog effizient mit .release-please-manifest.json und git diff. Lernen Sie, wie man die Zieldateien bestimmt und die Änderungen im Branch analysiert. Atualize o changelog com facilidade, seguindo os passos para determinar arquivos-alvo e analisar alterações no branch Обновите чейнджлог легко, следуя шагам для определения целевых файлов и анализа изменений в ветке قم بتحديث سجل التغيير بسهولة، باتباع الخطوات لتحديد الملفات المستهدفة وتحليل التغييرات في الفرع how to update changelog updating-changelog setup guide changelog management best practices git diff commands for changelog updating-changelog alternative updating-changelog vs manual changelog update install updating-changelog updating-changelog for AI agents what is updating-changelog 更新变更日志 AIエージェント 变更记录 git diff release-please-manifest.json Aztec合约开发 Node操作 Reads `.release-please-manifest.json` files to determine version updates Edits `v{major}.md` files based on version changes Runs `git diff` commands to analyze branch changes Supports Aztec contract developers and Node operators with specific target files Updates `docs/docs-developers/docs/resources/migration_notes.md` and `docs/docs-operate/operators/reference/changelog/v{major}.md` files Updating-changelog is a skill that automates the process of updating changelog files by reading release manifests and analyzing Git branch changes.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('METR/inspect-action/monitoring', 'community', 'METR', 'inspect-action', 'METR/inspect-action', 'monitoring', 0, 0, 33, '2026-03-08T01:57:15.310Z', '2026-03-08T02:02:28.422Z', '5950685d81ae6b07ceb7a2e013b675dabc10f09c130d82b223872bb7ae5c60c7', '{"id":"METR/inspect-action/monitoring","name":"monitoring","description":{"en":"The monitoring skill allows developers to track running or completed Hawk jobs using specific commands. It benefits AI agent developers who need to monitor job status and logs.","zh":"Hawk Job 监控允许您监控运行或完成的 Hawk 作业，包括查看日志和状态。使用 `hawk logs` 和 `hawk status` 命令来监控您的作业","ja":"Hawk Job モニタリングを使用すると、実行中または完了した Hawk ジョブを監視できます。`hawk logs` と `hawk status` コマンドを使用してジョブを監視します","ko":"Hawk Job 모니터링을 사용하여 실행 중 또는 완료된 Hawk 작업을 모니터링할 수 있습니다. `hawk logs`와 `hawk status` 명령을 사용하여 작업을 모니터링합니다","es":"Monitorear trabajos de Hawk con comandos como ''hawk logs'' y ''hawk status'' para supervisar el progreso y los registros","fr":"Surveiller les tâches Hawk avec des commandes comme ''hawk logs'' et ''hawk status'' pour contrôler l''avancement et les journaux","de":"Überwachen Sie Hawk-Jobs mit Befehlen wie ''hawk logs'' und ''hawk status'', um den Fortschritt und die Protokolle zu überwachen","pt":"O monitoramento de trabalhos Hawk permite visualizar logs e status de trabalhos em execução ou concluídos. Utilize comandos como `hawk logs` e `hawk status` para acompanhar o progresso.","ru":"Мониторинг задач Hawk позволяет просматривать журналы и статус запущенных или завершенных задач. Используйте команды, такие как `hawk logs` и `hawk status`, чтобы отслеживать прогресс.","ar":"مراقبة مهام Hawk تسمح بمشاهدة السجلات وحالة المهام التي يتم تشغيلها أو إكمالها. استخدم أوامر مثل `hawk logs` و `hawk status` لتتبع التقدم."},"seo":{"title":{"en":"Monitoring: Setup Guide for AI Agents | AI Agent Skill","zh":"AIエージェント监控设置指南 - Hawk Job 监控","ja":"AIエージェントの監視設定ガイド - Hawk Job モニタリング","ko":"AI 에이전트 모니터링 설정 가이드 - Hawk Job 모니터링","es":"Guía de configuración de monitoreo de trabajos Hawk","fr":"Guide de surveillance des tâches Hawk","de":"Leitfaden zur Überwachung von Hawk-Jobs","pt":"Monitoramento de Trabalhos Hawk: Guia de Configuração","ru":"Мониторинг задач Hawk: Лучшие практики","ar":"مراقبة مهام Hawk: دليل الإعداد"},"description":{"en":"Discover how to monitor Hawk jobs with ease. Learn to use hawk logs and hawk status commands to streamline your workflow. Get started now!","zh":"了解如何使用 Hawk Job 监控命令监控运行或完成的 Hawk 作业，包括查看日志和状态","ja":"Hawk Job モニタリング コマンドを使用して実行中または完了した Hawk ジョブを監視する方法を学びます","ko":"Hawk Job 모니터링 명령을 사용하여 실행 중 또는 완료된 Hawk 작업을 모니터링하는 방법을 알아보세요","es":"Aprenda a monitorear trabajos en ejecución o completados con Hawk utilizando comandos como ''hawk logs'' y ''hawk status''","fr":"Découvrez comment surveiller les tâches en cours ou terminées avec Hawk en utilisant des commandes comme ''hawk logs'' et ''hawk status''","de":"Erfahren Sie, wie Sie laufende oder abgeschlossene Jobs mit Hawk mithilfe von Befehlen wie ''hawk logs'' und ''hawk status'' überwachen","pt":"Aprenda a monitorar trabalhos Hawk em execução ou concluídos usando comandos CLI como `hawk logs` e `hawk status`","ru":"Откройте для себя, как отслеживать запущенные или завершенные задачи Hawk с помощью команд CLI, таких как `hawk logs` и `hawk status`","ar":"تعرف على كيفية مراقبة مهام Hawk التي يتم تشغيلها أو إكمالها باستخدام أوامر CLI مثل `hawk logs` و `hawk status`"},"definition":{"en":"Monitoring is the process of tracking and managing Hawk jobs using commands like hawk logs and hawk status, providing real-time insights into job execution.","zh":"Hawk Job 监控是指使用 Hawk Job 命令来监控和管理 Hawk 作业的过程","ja":"Hawk Job モニタリングとは、Hawk Job コマンドを使用して Hawk ジョブを監視および管理するプロセスです","ko":"Hawk Job 모니터링은 Hawk Job 명령을 사용하여 Hawk 작업을 모니터링 및 관리하는 프로세스입니다","es":"Monitoreo de trabajos Hawk: supervisión de trabajos en ejecución o completados utilizando comandos de línea de comandos","fr":"Surveillance des tâches Hawk : supervision des tâches en cours ou terminées à l''aide de commandes en ligne de commande","de":"Überwachung von Hawk-Jobs: Überwachung von laufenden oder abgeschlossenen Jobs mithilfe von Kommandozeilenbefehlen","pt":"Monitoramento de trabalhos Hawk é a capacidade de visualizar e acompanhar o progresso de trabalhos em execução ou concluídos","ru":"Мониторинг задач Hawk - это возможность просматривать и отслеживать прогресс запущенных или завершенных задач","ar":"مراقبة مهام Hawk هي القدرة على مشاهدة وتتبع تقدم المهام التي يتم تشغيلها أو إكمالها"},"features":{"en":["Uses hawk logs command to show last 100 logs of all types","Utilizes hawk status subcommands to monitor job status","Supports JOB_ID parameter for specific job tracking","Allows omission of JOB_ID for default last eval set ID usage","Enables viewing of logs with shorthand commands"],"zh":["使用 `hawk logs` 命令查看日志","使用 `hawk status` 命令查看作业状态","支持查看最后 100 条日志","支持使用 JOB_ID 参数指定作业 ID","支持查看所有类型的日志"],"ja":["『hawk logs』コマンドを使用してログを表示","『hawk status』コマンドを使用してジョブの状態を表示","最後の 100 件のログを表示","JOB_ID パラメータを使用してジョブ ID を指定","すべてのタイプのログを表示"],"ko":["『hawk logs』명령을 사용하여 로그를 표시","『hawk status』명령을 사용하여 작업 상태를 표시","마지막 100개의 로그를 표시","JOB_ID 매개 변수를 사용하여 작업 ID를 지정","모든 유형의 로그를 표시"],"es":["Visualización de registros con ''hawk logs''","Verificación del estado de los trabajos con ''hawk status''","Utilización del parámetro ''JOB_ID'' para identificar trabajos específicos","Omisión del parámetro ''JOB_ID'' para utilizar el último ID de conjunto de evaluación","Supervisión de trabajos en ejecución o completados","Uso de comandos de línea de comandos para la supervisión"],"fr":["Affichage des journaux avec ''hawk logs''","Vérification de l''état des tâches avec ''hawk status''","Utilisation du paramètre ''JOB_ID'' pour identifier des tâches spécifiques","Omission du paramètre ''JOB_ID'' pour utiliser le dernier ID de jeu de données","Surveillance des tâches en cours ou terminées","Utilisation de commandes en ligne de commande pour la surveillance"],"de":["Anzeige von Protokollen mit ''hawk logs''","Überprüfung des Status von Jobs mit ''hawk status''","Verwendung des Parameters ''JOB_ID'' zur Identifizierung von bestimmten Jobs","Weglassen des Parameters ''JOB_ID'' zur Verwendung der letzten Auswertungs-ID","Überwachung von laufenden oder abgeschlossenen Jobs","Verwendung von Kommandozeilenbefehlen zur Überwachung"],"pt":["Visualização de logs de trabalhos em execução ou concluídos","Utilização do comando `hawk logs` para exibir logs","Utilização do comando `hawk status` para exibir status de trabalhos","Possibilidade de especificar o ID do trabalho para monitoramento","Utilização do parâmetro `JOB_ID` para identificar trabalhos","Compatibilidade com trabalhos em execução ou concluídos"],"ru":["Просмотр журналов запущенных или завершенных задач","Использование команды `hawk logs` для отображения журналов","Использование команды `hawk status` для отображения статуса задач","Возможность указать ID задачи для мониторинга","Использование параметра `JOB_ID` для идентификации задач","Совместимость с запущенными или завершенными задачами"],"ar":["مشاهدة سجلات المهام التي يتم تشغيلها أو إكمالها","استخدام الأمر `hawk logs` لعرض السجلات","استخدام الأمر `hawk status` لعرض حالة المهام","السماح بتحديد معرف المهام لمراقبتها","استخدام المعامل `JOB_ID` لتحديد المهام","التوافق مع المهام التي يتم تشغيلها أو إكمالها"]},"keywords":{"en":["how to use monitoring","what is monitoring","monitoring setup guide","hawk logs command","hawk status subcommands","monitoring alternative","monitoring vs hawk","monitoring install","job tracking with hawk"],"zh":["Hawk Job 监控","AIエージェント监控","监控设置指南","Hawk Job 命令","日志查看","作业状态查看","JOB_ID 参数"],"ja":["Hawk Job モニタリング","AIエージェントの監視","監視設定ガイド","Hawk Job コマンド","ログ表示","ジョブの状態表示","JOB_ID パラメータ"],"ko":["Hawk Job 모니터링","AI 에이전트 모니터링","모니터링 설정 가이드","Hawk Job 명령","로그 표시","작업 상태 표시","JOB_ID 매개 변수"],"es":["monitoreo de trabajos Hawk","comandos de línea de comandos","hawk logs","hawk status","JOB_ID","supervisión de trabajos","trabajos en ejecución","trabajos completados","Herramientas de monitoreo de AI"],"fr":["surveillance des tâches Hawk","commandes en ligne de commande","hawk logs","hawk status","JOB_ID","supervision des tâches","tâches en cours","tâches terminées","Outils de surveillance d''IA"],"de":["Überwachung von Hawk-Jobs","Kommandozeilenbefehle","hawk logs","hawk status","JOB_ID","Überwachung von Jobs","laufende Jobs","abgeschlossene Jobs","AI-Überwachungstools"],"pt":["monitoramento de trabalhos Hawk","CLI Hawk","comandos Hawk","logs de trabalhos","status de trabalhos","JOB_ID","eval_set_id","scan_run_id","desenvolvimento de software","ferramentas de desenvolvimento"],"ru":["Мониторинг задач Hawk","CLI Hawk","команды Hawk","журналы задач","статус задач","JOB_ID","eval_set_id","scan_run_id","разработка программного обеспечения","инструменты разработки"],"ar":["مراقبة مهام Hawk","CLI Hawk","أوامر Hawk","سجلات المهام","حالة المهام","JOB_ID","eval_set_id","scan_run_id","تطوير البرمجيات","أدوات التطوير"]}},"owner":"METR","repo":"inspect-action","repoPath":"METR/inspect-action","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.310Z","topics":[],"category":"community","skillMd":{"name":"monitoring","description":"Monitor Hawk job status, view logs, and diagnose issues. Use when the user wants to check job progress, view error logs, debug a failing job, or generate a monitoring report for a Hawk evaluation run.","bodyPreview":"# Hawk Job Monitoring\n\nMonitor running or completed Hawk jobs using the `hawk logs` command or `hawk status` subcommands.\n\n## Job ID\n\nThe `JOB_ID` parameter is the **eval_set_id** or **scan_run_id** from when the job was submitted.\n\n**JOB_ID is optional.** If omitted, uses the last eval set ID that was used or received.\n\n## Available Commands\n\n### 1. View Logs (Shorthand)\n\nThe `hawk logs` command shows logs:\n\n```bash\nhawk logs                             # Show last 100 logs (all types)\nhawk log","body":"# Hawk Job Monitoring\n\nMonitor running or completed Hawk jobs using the `hawk logs` command or `hawk status` subcommands.\n\n## Job ID\n\nThe `JOB_ID` parameter is the **eval_set_id** or **scan_run_id** from when the job was submitted.\n\n**JOB_ID is optional.** If omitted, uses the last eval set ID that was used or received.\n\n## Available Commands\n\n### 1. View Logs (Shorthand)\n\nThe `hawk logs` command shows logs:\n\n```bash\nhawk logs                             # Show last 100 logs (all types)\nhawk logs <JOB_ID>                    # Show last 100 logs for job\nhawk logs -n 50                       # Show last 50 lines\n```\n\n**Options:**\n- `-n, --lines N` - Number of lines to show (default: 100)\n\n**Note:** Do NOT use the `-f/--follow` flag - it blocks indefinitely and is intended for interactive terminal use only.\n\n### 2. View status\n\nGenerate a full monitoring report with logs, metrics, and other details:\n\n```bash\nhawk status                           # Use last job ID\nhawk status <JOB_ID>                  # Print report to stdout\nhawk status <JOB_ID> > report.json      # Save to file\n```\n\n**Options:**\n- `--hours {hours}` - Fetch logs from last N hours (default: 24 hours)\n\n## Common Workflows\n\n### Check job progress\n```bash\nhawk logs\n```\n\n### Generate full report for analysis\n```bash\nhawk status > report.status\n```\n"},"lastSynced":"2026-03-08T02:02:28.422Z","agentAnalysis":{"suitability":{"en":"Ideal for AI Agent Developers needing real-time job status tracking and log analysis.","zh":"适合需要实时作业状态跟踪和日志分析的AI Agent开发人员。","ja":"リアルタイムのジョブ状態追跡とログ分析が必要なAIエージェント開発者に最適です。","ko":"실시간 작업 상태 추적 및 로그 분석이 필요한 AI 에이전트 개발자를 위한 최적의 솔루션입니다.","es":"Ideal para desarrolladores de Agentes de IA que necesitan seguimiento del estado del trabajo en tiempo real y análisis de registros.","fr":"Idéal pour les développeurs d''agents IA qui ont besoin d''un suivi de l''état de travail en temps réel et d''analyse de journaux.","de":"Ideal für AI-Agent-Entwickler, die eine Echtzeit-Auftragsstatusverfolgung und Log-Analyse benötigen.","pt":"Ideal para desenvolvedores de Agentes de IA que necessitam de rastreamento de status de trabalho em tempo real e análise de logs.","ru":"Идеально для разработчиков агентов ИИ, которым требуется отслеживание статуса работы в реальном времени и анализ журналов.","ar":"مثالية لمطوري وكلاء الذكاء الاصطناعي الذين يحتاجون إلى تتبع حالة العمل في الوقت الفعلي وتحليل السجلات."},"recommendation":{"en":"Empowers agents to track Hawk job status and logs using specific commands like `hawk logs` and `hawk status`, providing critical insights into job execution and performance, while supporting parameters like `JOB_ID` for customized monitoring.","zh":"赋予代理跟踪Hawk作业状态和日志的能力，使用特定的命令如`hawk logs`和`hawk status`，提供对作业执行和性能的关键见解，同时支持像`JOB_ID`这样的参数以实现自定义监控。","ja":"エージェントがHawkジョブの状態とログを特定のコマンド(`hawk logs`、`hawk status`)で追跡できるようにし、ジョブの実行とパフォーマンスに関する重要な洞察を提供する，同时、`JOB_ID`などのパラメータをサポートして、カスタマイズされた監視を実現します。","ko":"에이전트가 Hawk 작업 상태 및 로그를 특정 명령(`hawk logs`, `hawk status`)으로 추적할 수 있도록 하며, 작업 실행 및 성능에 대한 중요한 통찰력을 제공하면서 `JOB_ID`와 같은 매개 변수를 지원하여 사용자 정의 모니터링을 가능하게 합니다.","es":"Habilita a los agentes a realizar un seguimiento del estado del trabajo de Hawk y los registros utilizando comandos específicos como `hawk logs` y `hawk status`, proporcionando información crítica sobre la ejecución y el rendimiento del trabajo, y admitiendo parámetros como `JOB_ID` para un monitoreo personalizado.","fr":"Permet aux agents de suivre l''état de travail Hawk et les journaux à l''aide de commandes spécifiques comme `hawk logs` et `hawk status`, fournissant des informations critiques sur l''exécution et les performances du travail, tout en prenant en charge des paramètres comme `JOB_ID` pour un suivi personnalisé.","de":"Ermöglicht es Agenten, den Hawk-Auftragsstatus und die Protokolle mithilfe spezifischer Befehle wie `hawk logs` und `hawk status` zu verfolgen, wodurch kritische Einblicke in die Auftragsausführung und -leistung gewonnen werden, und unterstützt Parameter wie `JOB_ID` für ein maßgeschneidertes Monitoring.","pt":"Habilita os agentes a rastrear o status do trabalho Hawk e logs usando comandos específicos como `hawk logs` e `hawk status`, fornecendo insights críticos sobre a execução do trabalho e o desempenho, ao mesmo tempo em que suporta parâmetros como `JOB_ID` para monitoramento personalizado.","ru":"Наделяет агентов возможностью отслеживать статус работы Hawk и журналы с помощью конкретных команд, таких как `hawk logs` и `hawk status`, обеспечивая критически важные сведения об выполнении работы и производительности, а также поддерживает параметры, такие как `JOB_ID`, для настраиваемого мониторинга.","ar":"تمكّن الوكلاء من تتبع حالة عمل Hawk وسجلات باستخدام أوامر محددة مثل `hawk logs` و `hawk status` ، وتقديم رؤى حاسمة حول تنفيذ العمل والأداء ، مع دعم 매개่งขثل `JOB_ID` لرصد مخصص."},"useCases":{"en":["Monitoring running Hawk jobs for real-time status updates","Analyzing logs of completed jobs for debugging and optimization","Tracking job execution using `JOB_ID` for targeted monitoring"],"zh":["实时监控运行中的Hawk作业以获取状态更新","分析已完成作业的日志以进行调试和优化","使用`JOB_ID`跟踪作业执行以进行有针对性的监控"],"ja":["実行中のHawkジョブをリアルタイムで監視して状態の更新を取得する","完了したジョブのログを分析してデバッグと最適化を実行する","`JOB_ID`を使用してジョブの実行を追跡してターゲットを絞った監視を実行する"],"ko":["실행 중인 Hawk 작업을 실시간으로 모니터링하여 상태 업데이트를 얻는 것","완료된 작업의 로그를 분석하여 디버깅 및 최적화를 수행하는 것","`JOB_ID`를 사용하여 작업 실행을 추적하고 대상 모니터링을 수행하는 것"],"es":["Seguimiento de trabajos de Hawk en ejecución para obtener actualizaciones de estado en tiempo real","Análisis de registros de trabajos completados para depuración y optimización","Seguimiento de la ejecución del trabajo utilizando `JOB_ID` para un monitoreo dirigido"],"fr":["Suivi des travaux Hawk en cours pour obtenir des mises à jour de l''état en temps réel","Analyse des journaux de travaux terminés pour le débogage et l''optimisation","Suivi de l''exécution du travail en utilisant `JOB_ID` pour un suivi ciblé"],"de":["Überwachung von laufenden Hawk-Aufträgen für Echtzeit-Status-Updates","Analyse von Protokollen abgeschlossener Aufträge für Fehlerbehebung und Optimierung","Verfolgung der Auftragsausführung unter Verwendung von `JOB_ID` für gezieltes Monitoring"],"pt":["Monitorar trabalhos Hawk em execução para atualizações de status em tempo real","Analizar logs de trabalhos concluídos para depuração e otimização","Rastrear execução de trabalho usando `JOB_ID` para monitoramento direcionado"],"ru":["Мониторинг запущенных работ Hawk для обновлений статуса в реальном времени","Анализ журналов завершенных работ для отладки и оптимизации","Отслеживание выполнения работы с помощью `JOB_ID` для целевого мониторинга"],"ar":["مراقبة عمليات تشغيل Hawk التي يتم تشغيلها لحصول على تحديثات حالة في الوقت الفعلي","تحليل سجلات عمليات التشغيل المكتملة لتصحيح الأخطاء والتحسين","تتبع تنفيذ العمل باستخدام `JOB_ID` لرصد موجه"]},"limitations":{"en":["Requires Hawk job submission to function","Limited to tracking Hawk jobs only","`JOB_ID` parameter is optional but required for specific job monitoring"],"zh":["需要Hawk作业提交才能功能","仅限跟踪Hawk作业","`JOB_ID`参数是可选的，但需要用于特定作业监控"],"ja":["機能するにはHawkジョブの提出が必要","Hawkジョブのみを追跡","`JOB_ID`パラメータはオプションですが、特定のジョブの監視には必要"],"ko":["기능을 사용하려면 Hawk 작업 제출이 필요합니다.","Hawk 작업만을 추적합니다.","`JOB_ID` 매개 변수는 선택 사항이지만 특정 작업 모니터링에는 필요합니다."],"es":["Requiere la presentación de un trabajo de Hawk para funcionar","Limitado a la seguimiento de trabajos de Hawk solo","El parámetro `JOB_ID` es opcional pero se requiere para la supervisión de trabajos específicos"],"fr":["Nécessite la soumission d''un travail Hawk pour fonctionner","Limité au suivi des travaux Hawk uniquement","Le paramètre `JOB_ID` est facultatif mais requis pour la surveillance de travaux spécifiques"],"de":["Benötigt die Einreichung eines Hawk-Auftrags, um zu funktionieren","Begrenzt auf die Nachverfolgung von Hawk-Aufträgen nur","Der Parameter `JOB_ID` ist optional, aber für die Überwachung bestimmter Aufträge erforderlich"],"pt":["Exige a submissão de trabalhos Hawk para funcionar","Limitado ao rastreamento de trabalhos Hawk apenas","O parâmetro `JOB_ID` é opcional, mas necessário para monitoramento de trabalho específico"],"ru":["Требует отправки работ Hawk для функционирования","Ограничен только отслеживанием работ Hawk","Параметр `JOB_ID` является необязательным, но необходим для мониторинга конкретной работы"],"ar":["يتطلب تقديم عمليات تشغيل Hawk للعمل","محدود بالرصد عمليات تشغيل Hawk فقط","معامل `JOB_ID` اختياري ولكن مطلوب لرصد عمل محدد"]},"version":4},"contentHash":"5950685d81ae6b07ceb7a2e013b675dabc10f09c130d82b223872bb7ae5c60c7","qualityScore":33}');
