INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('METR/inspect-action/monitoring', 'monitoring', 'METR', 'inspect-action', 'community', 'monitoring METR inspect-action community The monitoring skill allows developers to track running or completed Hawk jobs using specific commands. It benefits AI agent developers who need to monitor job status and logs. Hawk Job 监控允许您监控运行或完成的 Hawk 作业，包括查看日志和状态。使用 `hawk logs` 和 `hawk status` 命令来监控您的作业 Hawk Job モニタリングを使用すると、実行中または完了した Hawk ジョブを監視できます。`hawk logs` と `hawk status` コマンドを使用してジョブを監視します Hawk Job 모니터링을 사용하여 실행 중 또는 완료된 Hawk 작업을 모니터링할 수 있습니다. `hawk logs`와 `hawk status` 명령을 사용하여 작업을 모니터링합니다 Monitorear trabajos de Hawk con comandos como ''hawk logs'' y ''hawk status'' para supervisar el progreso y los registros Surveiller les tâches Hawk avec des commandes comme ''hawk logs'' et ''hawk status'' pour contrôler l''avancement et les journaux Überwachen Sie Hawk-Jobs mit Befehlen wie ''hawk logs'' und ''hawk status'', um den Fortschritt und die Protokolle zu überwachen O monitoramento de trabalhos Hawk permite visualizar logs e status de trabalhos em execução ou concluídos. Utilize comandos como `hawk logs` e `hawk status` para acompanhar o progresso. Мониторинг задач Hawk позволяет просматривать журналы и статус запущенных или завершенных задач. Используйте команды, такие как `hawk logs` и `hawk status`, чтобы отслеживать прогресс. مراقبة مهام Hawk تسمح بمشاهدة السجلات وحالة المهام التي يتم تشغيلها أو إكمالها. استخدم أوامر مثل `hawk logs` و `hawk status` لتتبع التقدم. how to use monitoring what is monitoring monitoring setup guide hawk logs command hawk status subcommands monitoring alternative monitoring vs hawk monitoring install job tracking with hawk Hawk Job 监控 AIエージェント监控 监控设置指南 Hawk Job 命令 日志查看 作业状态查看 JOB_ID 参数 Uses hawk logs command to show last 100 logs of all types Utilizes hawk status subcommands to monitor job status Supports JOB_ID parameter for specific job tracking Allows omission of JOB_ID for default last eval set ID usage Enables viewing of logs with shorthand commands Monitoring is the process of tracking and managing Hawk jobs using commands like hawk logs and hawk status, providing real-time insights into job execution.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('vallafederico/webflow-dev-setup/webflow-editor-integration', 'community', 'vallafederico', 'webflow-dev-setup', 'vallafederico/webflow-dev-setup', 'webflow-editor-integration', 0, 0, 33, '2026-03-08T01:57:15.311Z', '2026-03-08T02:02:31.215Z', '4787faff4b01b74817109f80380653211a4bbb498a9e6d28a0aeb3c3f62fda18', '{"id":"vallafederico/webflow-dev-setup/webflow-editor-integration","name":"webflow-editor-integration","description":{"en":"The webflow-editor-integration skill ensures custom code compatibility with Webflow Designer/Editor, providing full functionality on published sites for developers.","zh":"Webflow 编辑器集成允许您优化自定义代码，以便在发布站点上提供全功能，同时在 Webflow Designer/Editor 中禁用交互","ja":"Webflow エディター統合により、カスタムコードを最適化して、公開サイトでフル機能を提供し、Webflow デザイナー/エディターではインタラクションを無効にします","ko":"Webflow 에디터 통합을 통해 사용자 지정 코드를 최적화하여 게시된 사이트에서 전체 기능을 제공하고 Webflow 디자이너/에디터에서 상호 작용을 비활성화할 수 있습니다","es":"La integración de Webflow Editor permite ejecutar código personalizado en el sitio publicado sin afectar el diseñador","fr":"L''intégration de Webflow Editor permet d''exécuter du code personnalisé sur le site publié sans affecter le concepteur","de":"Die Integration von Webflow Editor ermöglicht die Ausführung von benutzerdefiniertem Code auf der veröffentlichten Website ohne den Designer zu beeinträchtigen","pt":"A integração do Editor Webflow permite que você use código personalizado sem interferir no Designer/Editor, garantindo a funcionalidade no site publicado","ru":"Интеграция с Webflow Editor позволяет использовать индивидуальный код без нарушения работы дизайнера, сохраняя функциональность на опубликованном сайте","ar":"تتيح لك أداة التكامل مع محرر الويب فلوي استخدام التعليمات البرمجية المخصصة دون التداخل مع التصميم / المحرر والحفاظ على الوظيفة على الموقع المنشور"},"seo":{"title":{"en":"webflow-editor-integration: Setup Guide for Seamless Webf...","zh":"Webflow 编辑器集成设置指南 - AIエージェント工具","ja":"Webflow エディター統合ベストプラクティス - AIエージェント","ko":"Webflow 에디터 통합 가이드 - AI 에이전트 도구","es":"Guía de Integración de Webflow Editor","fr":"Guide d''intégration de Webflow Editor","de":"Webflow Editor Integration Leitfaden","pt":"Guia de Integração do Editor Webflow","ru":"ИИ Агенты: Настройка Интеграции с Webflow Editor","ar":"إعداد أداة التكامل مع محرر الويب فلوي"},"description":{"en":"Learn how to integrate custom code with Webflow Designer/Editor without interference. Get the setup guide and master webflow-editor-integration today!","zh":"了解如何使用 Webflow 编辑器集成来优化您的自定义代码，确保在 Designer 模式下禁用交互","ja":"Webflow エディター統合を使用してカスタムコードを最適化し、デザイナー モードでインタラクションを無効にする方法を学びます","ko":"Webflow 에디터 통합을 사용하여 사용자 지정 코드를 최적화하고 디자이너 모드에서 상호 작용을 비활성화하는 방법에 대해 알아보세요","es":"Aprende a integrar tu código personalizado con Webflow Editor sin interferir con el diseñador","fr":"Découvrez comment intégrer votre code personnalisé avec Webflow Editor sans perturber le concepteur","de":"Erfahren Sie, wie Sie Ihren benutzerdefinierten Code mit Webflow Editor integrieren, ohne den Designer zu stören","pt":"Aprenda a integrar seu código personalizado com o Editor Webflow sem interferir no Designer/Editor e mantenha a funcionalidade no site publicado","ru":"Узнайте, как настроить интеграцию с Webflow Editor, не мешая работе дизайнера и сохраняя функциональность на опубликованном сайте с помощью ИИ Агентов","ar":"تعرف على كيفية دمج التعليمات البرمجية المخصصة مع محرر الويب فلوي دون التداخل مع التصميم / المحرر والحفاظ على الوظيفة على الموقع المنشور"},"definition":{"en":"webflow-editor-integration is a technique for detecting and adapting to Webflow''s Designer/Editor mode, enabling smooth custom code execution on published websites.","zh":"Webflow 编辑器集成是一种技术，用于检测 Webflow Designer/Editor 并禁用交互，以优化自定义代码","ja":"Webflow エディター統合は、Webflow デザイナー/エディターを検出してインタラクションを無効にする技術であり、カスタムコードを最適化します","ko":"Webflow 에디터 통합은 Webflow 디자이너/에디터를 감지하고 상호 작용을 비활성화하여 사용자 지정 코드를 최적화하는 기술입니다","es":"La integración de Webflow Editor es una técnica para evitar interferencias con el diseñador","fr":"L''intégration de Webflow Editor est une technique pour éviter les interférences avec le concepteur","de":"Die Integration von Webflow Editor ist eine Technik, um Interferenzen mit dem Designer zu vermeiden","pt":"A integração do Editor Webflow é uma técnica que permite usar código personalizado no Editor Webflow sem interferir no Designer/Editor","ru":"Интеграция с Webflow Editor - это метод, позволяющий использовать индивидуальный код в редакторе Webflow без нарушения работы дизайнера","ar":"أداة التكامل مع محرر الويب فلوي هي تقنية تسمح باستخدام التعليمات البرمجية المخصصة في محرر الويب فلوي دون التداخل مع التصميم / المحرر"},"features":{"en":["Imports handleEditor from @webflow/detect-editor for Editor detection","Uses TypeScript for handling Editor mode","Disables interaction in Designer Mode for seamless integration","Provides full functionality on published sites","Utilizes DOMStringMap for dataset handling","Exports a default function for handling Editor mode"],"zh":["使用 @webflow/detect-editor 库检测 Webflow Designer/Editor","禁用交互以优化自定义代码","提供全功能的发布站点","支持 TypeScript 和 JavaScript","易于集成和使用"],"ja":["Webflow デザイナー/エディターを検出する @webflow/detect-editor ライブラリを使用","インタラクションを無効にしてカスタムコードを最適化","公開サイトでフル機能を提供","TypeScript と JavaScript をサポート","簡単に統合して使用"],"ko":["Webflow 디자이너/에디터를 감지하는 @webflow/detect-editor 라이브러리를 사용","상호 작용을 비활성화하여 사용자 지정 코드를 최적화","게시된 사이트에서 전체 기능을 제공","TypeScript 및 JavaScript를 지원","쉽게 통합하고 사용"],"es":["Detección del modo de diseñador con @webflow/detect-editor","Desactivación de la interacción en modo de diseñador","Compatibilidad con código personalizado en el sitio publicado","Uso de la función handleEditor para detectar el modo de diseñador","Integración con Webflow Designer/Editor"],"fr":["Détection du mode concepteur avec @webflow/detect-editor","Désactivation de l''interaction en mode concepteur","Compatibilité avec du code personnalisé sur le site publié","Utilisation de la fonction handleEditor pour détecter le mode concepteur","Intégration avec Webflow Designer/Editor"],"de":["Erkennung des Designer-Modus mit @webflow/detect-editor","Deaktivierung der Interaktion im Designer-Modus","Kompatibilität mit benutzerdefiniertem Code auf der veröffentlichten Website","Verwendung der Funktion handleEditor zur Erkennung des Designer-Modus","Integration mit Webflow Designer/Editor"],"pt":["Detecção do Editor Webflow","Uso de código personalizado no Editor Webflow","Manutenção da funcionalidade no site publicado","Integração com a biblioteca @webflow/detect-editor","Suporte a TypeScript"],"ru":["Обнаружение редактора Webflow","Использование индивидуального кода в редакторе Webflow","Сохранение функциональности на опубликованном сайте","Интеграция с библиотекой @webflow/detect-editor","Поддержка TypeScript"],"ar":["اكتشاف محرر الويب فلوي","استخدام التعليمات البرمجية المخصصة في محرر الويب فلوي","الحفاظ على الوظيفة على الموقع المنشور","التكامل مع مكتبة @webflow/detect-editor","دعم TypeScript"]},"keywords":{"en":["how to use webflow-editor-integration","webflow-editor-integration setup guide","webflow-editor-integration vs custom code","webflow-editor-integration install","what is webflow-editor-integration","webflow-editor-integration alternative","webflow-editor-integration tutorial","webflow-editor-integration best practices","webflow-editor-integration for AI agents"],"zh":["Webflow 编辑器集成","AIエージェント工具","自定义代码优化","Webflow Designer/Editor","TypeScript","JavaScript","发布站点优化"],"ja":["Webflow エディター統合","AIエージェント","カスタムコード最適化","Webflow デザイナー/エディター","TypeScript","JavaScript","公開サイト最適化"],"ko":["Webflow 에디터 통합","AI 에이전트 도구","사용자 지정 코드 최적화","Webflow 디자이너/에디터","TypeScript","JavaScript","게시된 사이트 최적화"],"es":["integración de Webflow Editor","diseñador de Webflow","código personalizado","sitio publicado","detección de modo de diseñador","handleEditor","Webflow API","desarrollo web","Herramientas de AI para desarrolladores"],"fr":["intégration de Webflow Editor","concepteur de Webflow","code personnalisé","site publié","détection du mode concepteur","handleEditor","Webflow API","développement web","Outils d''IA pour les développeurs"],"de":["Integration von Webflow Editor","Webflow-Designer","benutzerdefinierter Code","veröffentlichte Website","Erkennung des Designer-Modus","handleEditor","Webflow-API","Webentwicklung","KI-Tools für Entwickler"],"pt":["integração webflow editor","código personalizado webflow","detecção editor webflow","typescript webflow","desenvolvimento webflow","ferramentas webflow","bibliotecas webflow","guias webflow"],"ru":["ИИ Агенты интеграция с Webflow Editor","индивидуальный код Webflow","обнаружение редактора Webflow","typescript Webflow","разработка на Webflow","инструменты Webflow","библиотеки Webflow","руководства Webflow"],"ar":["أدوات التكامل مع محرر الويب فلوي","التعليمات البرمجية المخصصة لمحرر الويب فلوي","اكتشاف محرر الويب فلوي","دعم TypeScript لمحرر الويب فلوي","تطوير محرر الويب فلوي","أدوات محرر الويب فلوي","مكتبات محرر الويب فلوي","دلائل محرر الويب فلوي"]}},"owner":"vallafederico","repo":"webflow-dev-setup","repoPath":"vallafederico/webflow-dev-setup","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.311Z","topics":[],"category":"community","skillMd":{"name":"webflow-editor-integration","description":"Handle Webflow Designer/Editor mode vs Published site behavior. Use when detecting the editor, disabling custom animations in the designer, or managing features based on the environment.","bodyPreview":"# Webflow Editor Integration\n\nThis skill explains how to ensure your custom code doesn''t interfere with the Webflow Designer/Editor while providing full functionality on the published site.\n\n## Editor Detection\n\nImport `handleEditor` from `@webflow/detect-editor`:\n\n```typescript\nimport { handleEditor } from \"@webflow/detect-editor\";\n\nexport default function (element: HTMLElement, dataset: DOMStringMap) {\n  handleEditor((isEditor) => {\n    if (isEditor) {\n      // Designer Mode: disable interacti","body":"# Webflow Editor Integration\n\nThis skill explains how to ensure your custom code doesn''t interfere with the Webflow Designer/Editor while providing full functionality on the published site.\n\n## Editor Detection\n\nImport `handleEditor` from `@webflow/detect-editor`:\n\n```typescript\nimport { handleEditor } from \"@webflow/detect-editor\";\n\nexport default function (element: HTMLElement, dataset: DOMStringMap) {\n  handleEditor((isEditor) => {\n    if (isEditor) {\n      // Designer Mode: disable interactions, reset animations\n      element.style.pointerEvents = \"none\";\n      element.style.transform = \"none\";\n      element.style.opacity = \"1\";\n    } else {\n      // Published Mode: enable functionality\n      element.style.pointerEvents = \"auto\";\n    }\n  });\n}\n```\n"},"lastSynced":"2026-03-08T02:02:31.215Z","agentAnalysis":{"suitability":{"en":"Perfect for Frontend Agents needing seamless Webflow Designer/Editor integration with custom code compatibility","zh":"非常适合需要与自定义代码兼容的Webflow Designer/Editor无缝集成的前端代理","ja":"カスタムコードとの兼容性があるWebflow Designer/Editorとのシームレスな統合が必要なフロントエンドエージェントに最適","ko":"커스텀 코드와의 호환성을 가진 Webflow Designer/Editor와의无缝한 통합이 필요한 프론트엔드 에이전트에 적합","es":"Perfecto para agentes Frontend que necesitan una integración fluida de Webflow Designer/Editor con compatibilidad de código personalizado","fr":"Parfait pour les agents Frontend nécessitant une intégration transparente de Webflow Designer/Editor avec une compatibilité de code personnalisé","de":"Perfekt für Frontend-Agents, die eine nahtlose Integration von Webflow Designer/Editor mit benutzerdefinierter Code-Kompatibilität benötigen","pt":"Perfeito para Agentes Frontend que precisam de integração perfeita do Webflow Designer/Editor com compatibilidade de código personalizado","ru":"Идеально подходит для фронтенд-агентов, которым требуется бесшовная интеграция с Webflow Designer/Editor и совместимость с пользовательским кодом","ar":"مثالي للوكلاء الأماميين الذين يحتاجون إلى دمج متوافق مع محرر/مصمم Webflow مع توافق شفرة مخصص"},"recommendation":{"en":"Empowers agents to detect Webflow Editor mode using the @webflow/detect-editor library, ensuring custom code functionality on published sites while preventing interference with the Webflow Designer/Editor, utilizing handleEditor for editor detection and providing full functionality on published sites for developers","zh":"赋予代理检测Webflow Editor模式的能力，使用@webflow/detect-editor库，确保在发布的站点上自定义代码的功能性，同时防止与Webflow Designer/Editor的干扰，利用handleEditor进行编辑器检测，并为开发人员在发布的站点上提供完全的功能性","ja":"@webflow/detect-editorライブラリを使用して、Webflow Editorモードを検出するエージェントの能力を提供し、公開されたサイトでのカスタムコードの機能性を確保し、Webflow Designer/Editorとの干渉を防ぎ、handleEditorを使用してエディターの検出を実行し、開発者が公開されたサイトで完全な機能性を提供する","ko":"@webflow/detect-editor 라이브러리를 사용하여 Webflow Editor 모드를 감지하는 에이전트의 능력을 부여하여,公開된 사이트에서의 커스텀 코드의 기능성을 보장하고, Webflow Designer/Editor와의 간섭을 방지하며, handleEditor를 사용하여 에디터 감지를 수행하고, 개발자가 공개된 사이트에서 완전한 기능성을 제공","es":"Habilita a los agentes a detectar el modo del editor de Webflow utilizando la biblioteca @webflow/detect-editor, garantizando la funcionalidad de código personalizado en sitios publicados mientras evita interferencias con Webflow Designer/Editor, utilizando handleEditor para la detección del editor y proporcionando una funcionalidad completa en sitios publicados para los desarrolladores","fr":"Permet aux agents de détecter le mode éditeur Webflow en utilisant la bibliothèque @webflow/detect-editor, garantissant la fonctionnalité du code personnalisé sur les sites publiés tout en évitant les interférences avec Webflow Designer/Editor, en utilisant handleEditor pour la détection de l''éditeur et en fournissant une fonctionnalité complète sur les sites publiés pour les développeurs","de":"Ermächtigt die Agenten, den Webflow-Editor-Modus mithilfe der @webflow/detect-editor-Bibliothek zu erkennen, wodurch die Funktionalität benutzerdefinierter Code auf veröffentlichten Seiten sichergestellt wird, während eine Störung von Webflow Designer/Editor verhindert wird, unter Verwendung von handleEditor für die Editor-Erkennung und Bereitstellung der vollen Funktionalität auf veröffentlichten Seiten für Entwickler","pt":"Habilita agentes a detectar o modo do Editor Webflow usando a biblioteca @webflow/detect-editor, garantindo a funcionalidade do código personalizado em sites publicados enquanto evita interferências com o Webflow Designer/Editor, utilizando handleEditor para detecção do editor e fornecendo funcionalidade completa em sites publicados para desenvolvedores","ru":"Позволяет агентам обнаруживать режим редактора Webflow с помощью библиотеки @webflow/detect-editor, обеспечивая функциональность пользовательского кода на опубликованных сайтах, а также предотвращая干涉 с Webflow Designer/Editor, используя handleEditor для обнаружения редактора и предоставляя полную функциональность на опубликованных сайтах для разработчиков","ar":"تمكين الوكلاء من الكشف عن وضع محرر Webflow باستخدام مكتبة @webflow/detect-editor، ضمانا للوظائف الشفرة المخصصة على المواقع المنشورة مع منع التداخل مع مصمم/محرر Webflow، استخدام handleEditor للكشف عن المحرر وتوفير الوظائف الكاملة على المواقع المنشورة للمطورين"},"useCases":{"en":["Detecting Webflow Editor mode for custom code optimization","Preventing custom code interference with Webflow Designer/Editor","Ensuring full functionality on published Webflow sites"],"zh":["检测Webflow Editor模式以优化自定义代码","防止自定义代码与Webflow Designer/Editor干扰","确保在发布的Webflow站点上提供完全的功能性"],"ja":["Webflow Editorモードを検出してカスタムコードを最適化する","カスタムコードがWebflow Designer/Editorと干渉しないようにする","公開されたWebflowサイトで完全な機能性を提供する"],"ko":["Webflow Editor 모드를 감지하여 커스텀 코드를 최적화","커스텀 코드가 Webflow Designer/Editor와 간섭하지 않도록","公開된 Webflow 사이트에서 완전한 기능성을 제공"],"es":["Detección del modo del editor de Webflow para la optimización de código personalizado","Prevención de interferencias de código personalizado con Webflow Designer/Editor","Garantía de funcionalidad completa en sitios Webflow publicados"],"fr":["Détection du mode éditeur Webflow pour l''optimisation de code personnalisé","Prévention des interférences de code personnalisé avec Webflow Designer/Editor","Garantie d''une fonctionnalité complète sur les sites Webflow publiés"],"de":["Erkennung des Webflow-Editor-Modus für die Optimierung benutzerdefinierter Code","Verhinderung von Interferenzen benutzerdefinierter Code mit Webflow Designer/Editor","Sicherstellung der vollen Funktionalität auf veröffentlichten Webflow-Seiten"],"pt":["Detecção do modo do Editor Webflow para otimização de código personalizado","Prevenção de interferência de código personalizado com o Webflow Designer/Editor","Garantia de funcionalidade completa em sites Webflow publicados"],"ru":["Обнаружение режима редактора Webflow для оптимизации пользовательского кода","Предотвращение взаимодействия пользовательского кода с Webflow Designer/Editor","Обеспечение полной функциональности на опубликованных сайтах Webflow"],"ar":["اكتشاف وضع محرر Webflow لتحسين الشفرة المخصصة","منع تداخل الشفرة المخصصة مع مصمم/محرر Webflow","ضمان الوظائف الكاملة على المواقع المنشورة في Webflow"]},"limitations":{"en":["Requires @webflow/detect-editor library import","Webflow Designer/Editor specific functionality"],"zh":["需要导入@webflow/detect-editor库","特定于Webflow Designer/Editor的功能性"],"ja":["@webflow/detect-editorライブラリのインポートが必要","Webflow Designer/Editor特有の機能性"],"ko":["@webflow/detect-editor 라이브러리의导入가 필요","Webflow Designer/Editor 특有的 기능성"],"es":["Requiere la importación de la biblioteca @webflow/detect-editor","Funcionalidad específica de Webflow Designer/Editor"],"fr":["Nécessite l''importation de la bibliothèque @webflow/detect-editor","Fonctionnalité spécifique de Webflow Designer/Editor"],"de":["Erfordert die Importierung der @webflow/detect-editor-Bibliothek","Webflow Designer/Editor-spezifische Funktionalität"],"pt":["Requer importação da biblioteca @webflow/detect-editor","Funcionalidade específica do Webflow Designer/Editor"],"ru":["Требуется импорт библиотеки @webflow/detect-editor","Функциональность, специфичная для Webflow Designer/Editor"],"ar":["يتطلب استيراد مكتبة @webflow/detect-editor","وظائف محددة لمصمم/محرر Webflow"]},"version":4},"contentHash":"4787faff4b01b74817109f80380653211a4bbb498a9e6d28a0aeb3c3f62fda18","qualityScore":33}');
