INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('vallafederico/webflow-dev-setup/webflow-editor-integration', 'webflow-editor-integration', 'vallafederico', 'webflow-dev-setup', 'community', 'webflow-editor-integration vallafederico webflow-dev-setup community The webflow-editor-integration skill ensures custom code compatibility with Webflow Designer/Editor, providing full functionality on published sites for developers. Webflow 编辑器集成允许您优化自定义代码，以便在发布站点上提供全功能，同时在 Webflow Designer/Editor 中禁用交互 Webflow エディター統合により、カスタムコードを最適化して、公開サイトでフル機能を提供し、Webflow デザイナー/エディターではインタラクションを無効にします Webflow 에디터 통합을 통해 사용자 지정 코드를 최적화하여 게시된 사이트에서 전체 기능을 제공하고 Webflow 디자이너/에디터에서 상호 작용을 비활성화할 수 있습니다 La integración de Webflow Editor permite ejecutar código personalizado en el sitio publicado sin afectar el diseñador L''intégration de Webflow Editor permet d''exécuter du code personnalisé sur le site publié sans affecter le concepteur Die Integration von Webflow Editor ermöglicht die Ausführung von benutzerdefiniertem Code auf der veröffentlichten Website ohne den Designer zu beeinträchtigen A integração do Editor Webflow permite que você use código personalizado sem interferir no Designer/Editor, garantindo a funcionalidade no site publicado Интеграция с Webflow Editor позволяет использовать индивидуальный код без нарушения работы дизайнера, сохраняя функциональность на опубликованном сайте تتيح لك أداة التكامل مع محرر الويب فلوي استخدام التعليمات البرمجية المخصصة دون التداخل مع التصميم / المحرر والحفاظ على الوظيفة على الموقع المنشور how to use webflow-editor-integration webflow-editor-integration setup guide webflow-editor-integration vs custom code webflow-editor-integration install what is webflow-editor-integration webflow-editor-integration alternative webflow-editor-integration tutorial webflow-editor-integration best practices webflow-editor-integration for AI agents Webflow 编辑器集成 AIエージェント工具 自定义代码优化 Webflow Designer/Editor TypeScript JavaScript 发布站点优化 Imports handleEditor from @webflow/detect-editor for Editor detection Uses TypeScript for handling Editor mode Disables interaction in Designer Mode for seamless integration Provides full functionality on published sites Utilizes DOMStringMap for dataset handling Exports a default function for handling Editor mode webflow-editor-integration is a technique for detecting and adapting to Webflow''s Designer/Editor mode, enabling smooth custom code execution on published websites.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('crmagz/cdk-constructs-library/naming-conventions', 'community', 'crmagz', 'cdk-constructs-library', 'crmagz/cdk-constructs-library', 'naming-conventions', 0, 0, 33, '2026-03-08T01:57:15.311Z', '2026-03-08T02:02:31.536Z', '0f9d00c1ecf47545fe26d42ffb402cf9fe0592567663032debdb812934dba59f', '{"id":"crmagz/cdk-constructs-library/naming-conventions","name":"naming-conventions","description":{"en":"The naming-conventions skill provides a comprehensive library for AWS CDK, enabling developers to follow type-driven development principles and apply consistent naming conventions to their infrastructure-as-code constructs.","zh":"命名约定是 AWS CDK 代码库的核心，提供 Type Naming 和 camelCase 的使用指南","ja":"ネーミング規約は AWS CDK ライブラリの重要な概念です。Type Naming と camelCase の使用方法を紹介します","ko":"네이밍 규칙은 AWS CDK 인프라스트럭처의 핵심입니다. Type Naming과 camelCase의 사용법을 가이드합니다","es":"La convención de nomenclatura es crucial en el desarrollo de infraestructura como código. Nuestra guía te ayudará a establecer convenciones de nomenclatura efectivas para tus proyectos AWS CDK.","fr":"La convention de nommage est cruciale dans le développement d''infrastructures en tant que code. Notre guide vous aidera à établir des conventions de nommage efficaces pour vos projets AWS CDK.","de":"Die Namenskonvention ist entscheidend für die Entwicklung von Infrastrukturen als Code. Unser Leitfaden hilft Ihnen, effektive Namenskonventionen für Ihre AWS-CDK-Projekte zu etablieren.","pt":"Conheça as convenções de nomenclatura para desenvolvedores, com foco em type declarations e camelCase, para melhorar a legibilidade do código","ru":"Ознакомьтесь с конвенциями именования для разработчиков, с фокусом на type declarations и camelCase, для улучшения читаемости кода","ar":"تعرف على اتفاقيات التسمية للمطورين، مع التركيز على إعلانات النوع و camelCase، لتحسين قراءة الكود"},"seo":{"title":{"en":"naming-conventions: Best Practices for AWS CDK Developmen...","zh":"命名约定设置指南 - AWS CDK 代码库","ja":"ネーミング規約のベストプラクティス - AWS CDK ライブラリ","ko":"네이밍 규칙 설정 가이드 - AWS CDK 인프라스트럭처","es":"Guía de configuración de convenciones de nomenclatura par...","fr":"Guide de mise en place des conventions de nommage pour AW...","de":"Einrichtungsleitfaden für Namenskonventionen in AWS CDK","pt":"Guia de Configuração de Convenções de Nomenclatura para D...","ru":"Настройка ИИ Агентов: Руководство по Конвенциям Именования","ar":"إعداد أدوات الذكاء الاصطناعي: دليل أفضل الممارسات لاتفاقي..."},"description":{"en":"Discover how to implement consistent naming conventions in your AWS Cloud Development Kit projects, boost code readability, and simplify collaboration - get ...","zh":"了解命名约定在 AWS CDK 代码库中的重要性，掌握 Type Naming 和 camelCase 的使用方法","ja":"AWS CDK ライブラリにおけるネーミング規約の重要性を学び、Type Naming と camelCase の使い方をマスターしてください","ko":"AWS CDK 인프라스트럭처에서 네이밍 규칙의 중요성을 알아보고 Type Naming과 camelCase의 사용법을 익혀보세요","es":"Aprende a implementar convenciones de nomenclatura efectivas en tus proyectos AWS CDK con nuestra guía paso a paso","fr":"Découvrez comment mettre en place des conventions de nommage efficaces dans vos projets AWS CDK avec notre guide étape par étape","de":"Erfahren Sie, wie Sie effektive Namenskonventionen in Ihren AWS-CDK-Projekten implementieren können, mit unserer Schritt-für-Schritt-Anleitung","pt":"Aprenda sobre as convenções de nomenclatura para desenvolvedores, incluindo type declarations e camelCase, para melhorar a legibilidade do código","ru":"Узнайте о конвенциях именования для разработчиков, включая type declarations и camelCase, для улучшения читаемости кода с помощью ИИ Агентов","ar":"تعرف على اتفاقيات التسمية للمطورين، بما في ذلك إعلانات النوع و camelCase، لتحسين قراءة الكود باستخدام أدوات الذكاء الاصطناعي"},"definition":{"en":"naming-conventions is a set of guidelines for AWS Cloud Development Kit developers to follow type-driven development principles and apply consistent naming conventions to their code","zh":"命名约定是指在编程中为变量、函数和类型命名的规则和规范","ja":"ネーミング規約とは、プログラミングで変数、関数、タイプに名前を付けるための規則と規範です","ko":"네이밍 규칙은 변수, 함수, 타입에 이름을 붙일 때 따르는 규칙과 표준입니다","es":"Convenciones de nomenclatura para AWS CDK: reglas y pautas para nombrar tipos, funciones y variables en proyectos de infraestructura como código","fr":"Conventions de nommage pour AWS CDK : règles et directives pour nommer des types, des fonctions et des variables dans des projets d''infrastructure en tant que code","de":"Namenskonventionen für AWS CDK: Regeln und Richtlinien für die Benennung von Typen, Funktionen und Variablen in Infrastruktur-als-Code-Projekten","pt":"Convenções de nomenclatura são regras para nomear tipos, funções e variáveis em código","ru":"Конвенции именования - это правила для именования типов, функций и переменных в коде","ar":"اتفاقيات التسمية هي قواعد لتسمية الأنواع والدوال والمتغيرات في الكود"},"features":{"en":["Uses `type` declarations instead of `interface` for type-driven development","Applies PascalCase convention to Types and Enums, such as `EnvironmentConfig` and `CodeArtifactStackProps`","Employs camelCase convention for Functions and Variables","Provides a comprehensive library for AWS CDK infrastructure-as-code constructs","Supports consistent naming conventions for AWS applications","Follows established conventions for `BucketProps` and other AWS resources"],"zh":["Type Naming 使用 PascalCase","函数和变量使用 camelCase","支持 AWS CDK 代码库","提供 infrastructure-as-code 构建","支持 Type-driven development"],"ja":["Type Naming で PascalCase を使用","関数と変数で camelCase を使用","AWS CDK ライブラリをサポート","infrastructure-as-code 構築を提供","Type-driven development をサポート"],"ko":["Type Naming에서 PascalCase 사용","함수와 변수에서 camelCase 사용","AWS CDK 인프라스트럭처 지원","infrastructure-as-code 구축 제공","Type-driven development 지원"],"es":["Uso de declaraciones de tipo en lugar de interfaces","Convenciones de nomenclatura para tipos y enumerados en PascalCase","Convenciones de nomenclatura para funciones y variables en camelCase","Compatibilidad con el desarrollo de infraestructura como código en AWS CDK","Mejora de la legibilidad y mantenibilidad del código"],"fr":["Utilisation de déclarations de type au lieu d''interfaces","Conventions de nommage pour les types et les énumérations en PascalCase","Conventions de nommage pour les fonctions et les variables en camelCase","Compatibilité avec le développement d''infrastructures en tant que code dans AWS CDK","Amélioration de la lisibilité et de la maintenabilité du code"],"de":["Verwendung von Typdeklarationen anstelle von Schnittstellen","Namenskonventionen für Typen und Aufzählungen in PascalCase","Namenskonventionen für Funktionen und Variablen in camelCase","Kompatibilität mit der Entwicklung von Infrastrukturen als Code in AWS CDK","Verbesserung der Lesbarkeit und Wartbarkeit des Codes"],"pt":["Uso de type declarations em vez de interface","Nomenclatura em PascalCase para tipos e enums","Nomenclatura em camelCase para funções e variáveis","Compatibilidade com AWS Cloud Development Kit (CDK)","Melhoria da legibilidade do código com convenções de nomenclatura"],"ru":["Использование type declarations вместо interface","Именование в PascalCase для типов и enums","Именование в camelCase для функций и переменных","Совместимость с AWS Cloud Development Kit (CDK)","Улучшение читаемости кода с помощью конвенций именования"],"ar":["استخدام إعلانات النوع بدلاً من الواجهة","التسمية بترميز PascalCase للأنواع والenumerations","التسمية بترميز camelCase للدوال والمتغيرات","التوافق مع حزمة تطوير السحابة من Amazon (CDK)","تحسين قراءة الكود باستخدام اتفاقيات التسمية"]},"keywords":{"en":["how to use naming-conventions in AWS CDK","naming-conventions best practices for AWS developers","what is naming-conventions in AWS Cloud Development Kit","naming-conventions vs other coding standards","naming-conventions setup guide for AWS CDK projects","naming-conventions install for AWS Cloud Development Kit"],"zh":["命名约定","AWS CDK","Type Naming","camelCase","infrastructure-as-code","Type-driven development","AWS CDK 代码库","命名规则"],"ja":["ネーミング規約","AWS CDK","Type Naming","camelCase","infrastructure-as-code","Type-driven development","AWS CDK ライブラリ","AIエージェント"],"ko":["네이밍 규칙","AWS CDK","Type Naming","camelCase","infrastructure-as-code","Type-driven development","AWS CDK 인프라스트럭처","AI Tools"],"es":["convenciones de nomenclatura","AWS CDK","infraestructura como código","tipos y enumerados","funciones y variables","PascalCase","camelCase","desarrollo de software","mejora de la legibilidad"],"fr":["conventions de nommage","AWS CDK","infrastructure en tant que code","types et énumérations","fonctions et variables","PascalCase","camelCase","développement de logiciels","amélioration de la lisibilité"],"de":["Namenskonventionen","AWS CDK","Infrastruktur als Code","Typen und Aufzählungen","Funktionen und Variablen","PascalCase","camelCase","Softwareentwicklung","Verbesserung der Lesbarkeit"],"pt":["convenções de nomenclatura","type declarations","camelCase","PascalCase","AWS CDK","desenvolvimento de software","legibilidade do código","melhores práticas de codificação"],"ru":["конвенции именования","type declarations","camelCase","PascalCase","AWS CDK","разработка программного обеспечения","читаемость кода","лучшие практики кодирования","ИИ Агенты"],"ar":["اتفاقيات التسمية","إعلانات النوع","camelCase","PascalCase","AWS CDK","تطوير البرمجيات","قراءة الكود","أفضل الممارسات للتدوين","أدوات الذكاء الاصطناعي"]}},"owner":"crmagz","repo":"cdk-constructs-library","repoPath":"crmagz/cdk-constructs-library","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.311Z","topics":[],"category":"community","skillMd":{"name":"naming-conventions","description":"Naming conventions for types, functions, files, and resources. Use when creating new code or reviewing naming patterns. Emphasizes type-driven development.","bodyPreview":"# Naming Conventions\n\n## Type Naming\n\n**Use `type` declarations, not `interface`.** This codebase follows type-driven development.\n\n| Type                 | Convention           | Example                                                      |\n| -------------------- | -------------------- | ------------------------------------------------------------ |\n| Types, Enums         | PascalCase           | `EnvironmentConfig`, `CodeArtifactStackProps`, `BucketProps` |\n| Functions, Variables | camelCase","body":"# Naming Conventions\n\n## Type Naming\n\n**Use `type` declarations, not `interface`.** This codebase follows type-driven development.\n\n| Type                 | Convention           | Example                                                      |\n| -------------------- | -------------------- | ------------------------------------------------------------ |\n| Types, Enums         | PascalCase           | `EnvironmentConfig`, `CodeArtifactStackProps`, `BucketProps` |\n| Functions, Variables | camelCase            | `createBucket`, `bucketName`                                 |\n| AWS Resource Names   | kebab-case           | `my-bucket-dev-use1`                                         |\n| Enum Values          | SCREAMING_SNAKE_CASE | `Account.PROD`, `Region.US_EAST_1`                           |\n\n**Type Naming Pattern:**\n\n```typescript\n// CORRECT - Use type declarations\nexport type BucketProps = {\n    bucketName: string;\n    env: EnvironmentConfig[''env''];\n};\n\nexport type EnvironmentConfig = {\n    name: string;\n    region: string;\n    account: string;\n};\n\n// INCORRECT - Don''t use interface\nexport interface BucketProps {\n    // ❌\n    bucketName: string;\n}\n```\n\n## Resource Naming Pattern\n\nInclude environment and region to prevent naming collisions:\n\n```typescript\n// Resource naming pattern\n`${resourceName}-${props.env.name}-${props.env.region}`\n// Examples\n`aurora-cluster-dev-use1``api-gateway-prod-use1``waf-acl-staging-use1`;\n```\n\n## Function Naming\n\nUse `verbNoun` pattern for function names:\n\n```typescript\n// CORRECT\nexport const createBucket = () => {};\nexport const getVpcConfig = () => {};\nexport const updateSecurityGroup = () => {};\n\n// INCORRECT\nexport const bucketCreate = () => {};\nexport const VpcConfigGet = () => {};\n```\n\n## File Naming\n\n- Constructs: `kebab-case.ts` (e.g., `api-gateway.ts`)\n- Types: `kebab-case-type.ts` or `kebab-case.ts` in types directory\n- Enums: `kebab-case-enum.ts` or `kebab-case.ts` in enum directory\n- Utilities: `kebab-case.ts` in util directory\n\n## Export Patterns\n\n- Each package exports from `src/index.ts`\n- Root package exports from `src/index.ts`\n- Use named exports, avoid default exports where possible\n"},"lastSynced":"2026-03-08T02:02:31.536Z","agentAnalysis":{"suitability":{"en":"Perfect for Infrastructure-as-Code Agents needing consistent naming conventions for AWS CDK constructs.","zh":"适合于需要一致命名约定的基础设施即代码代理，用于AWS CDK构造。","ja":"AWS CDK 構築物の一貫した命名規則を必要とするインフラストラクチャー即コードエージェントに最適。","ko":"일관된 명명 규칙이 필요한 인프라스트럭처 코드 에이전트에게 적합합니다. AWS CDK 구성에 사용됩니다.","es":"Perfecto para Agentes de Infraestructura como Código que necesitan convenciones de nomenclatura coherentes para constructores de AWS CDK.","fr":"Parfait pour les agents Infrastructure-as-Code qui nécessitent des conventions de dénomination cohérentes pour les constructeurs AWS CDK.","de":"Perfekt für Infrastructure-as-Code-Agents, die konsistente Benennungskonventionen für AWS CDK-Konstrukte benötigen.","pt":"Perfeito para Agentes de Infraestrutura-Como-Código que necessitam de convenções de nomenclatura consistentes para construtos do AWS CDK.","ru":"Идеально подходит для агентов Инфраструктуры-как-Код, требующих последовательных соглашений об именовании для конструкций AWS CDK.","ar":"مثالي لعميل البنية ك_codigo الذي يحتاج إلى اتفاقيات تسمية متسقة لمكونات AWS CDK."},"recommendation":{"en":"Empowers agents to enforce type-driven development principles, utilizing PascalCase for types and enums, and camelCase for functions and variables, ensuring consistent naming conventions across infrastructure-as-code projects with AWS CDK.","zh":"赋予代理人强制执行基于类型的开发原则的能力，使用PascalCase表示类型和枚举，使用camelCase表示函数和变量，确保跨具有AWS CDK的基础设施即代码项目的一致命名约定。","ja":"エージェントに、PascalCase を型と列挙型に、camelCase を関数と変数に使用して、一貫した命名規則を保証することで、型ベースの開発原則を強制的に適用する能力を付与します。AWS CDK を使用したインフラストラクチャー即コードプロジェクトでの一貫した命名規則を確保します。","ko":"에이전트가 PascalCase를 사용하여 유형 및 열거형, camelCase를 사용하여 함수 및 변수를 강제 적용하여 일관된 명명 규칙을 보장하는 유형 기반 개발 원칙을 적용할 수 있도록 합니다. AWS CDK를 사용한 인프라스트럭처 코드 프로젝트에서 일관된 명명 규칙을 보장합니다.","es":"Habilita a los agentes a aplicar principios de desarrollo dirigido por tipos, utilizando PascalCase para tipos y enums, y camelCase para funciones y variables, garantizando convenciones de nomenclatura coherentes en proyectos de infraestructura como código con AWS CDK.","fr":"Permet aux agents d''appliquer les principes de développement piloté par les types, en utilisant PascalCase pour les types et les enums, et camelCase pour les fonctions et les variables, garantissant ainsi des conventions de dénomination cohérentes sur les projets d''infrastructure-as-code avec AWS CDK.","de":"Ermächtigt die Agenten, typgetriebene Entwicklungsprinzipien durchzusetzen, indem PascalCase für Typen und Enums und camelCase für Funktionen und Variablen verwendet wird, um konsistente Benennungskonventionen in Infrastructure-as-Code-Projekten mit AWS CDK sicherzustellen.","pt":"Habilita os agentes a impor princípios de desenvolvimento orientado a tipo, utilizando PascalCase para tipos e enums, e camelCase para funções e variáveis, garantindo convenções de nomenclatura consistentes em projetos de infraestrutura-kódigo com AWS CDK.","ru":"Наделяет агентов возможностью обеспечивать соблюдение принципов разработки, основанных на типах, используя PascalCase для типов и перечислений, и camelCase для функций и переменных, обеспечивая последовательные соглашения об именовании в проектах инфраструктуры-как-кода с AWS CDK.","ar":"يُمكن العميل من فرض مبادئ التطوير الموجهة بالنوع، باستخدام PascalCase للأصناف والتوابل، وcamelCase للأدوات والمتغيرات، مما يضمن اتفاقيات تسمية متسقة عبر مشاريع البنية ك_codigo مع AWS CDK."},"useCases":{"en":["Enforcing consistent naming conventions for AWS CDK projects","Generating type declarations for infrastructure-as-code constructs","Validating naming conventions for compliance with type-driven development principles"],"zh":["强制执行AWS CDK项目的一致命名约定","生成基础设施即代码构造的类型声明","验证命名约定以确保遵守基于类型的开发原则"],"ja":["AWS CDK プロジェクトの一貫した命名規則を適用する","インフラストラクチャー即コード構築物の型宣言を生成する","型ベースの開発原則への準拠を保証するために命名規則を検証する"],"ko":["AWS CDK 프로젝트에 대한 일관된 명명 규칙 적용","인프라스트럭처 코드 구성의 유형 선언 생성","유형 기반 개발 원칙 준수를 보장하기 위한 명명 규칙 검증"],"es":["Aplicar convenciones de nomenclatura coherentes para proyectos de AWS CDK","Generar declaraciones de tipo para constructores de infraestructura como código","Validar convenciones de nomenclatura para el cumplimiento de los principios de desarrollo dirigido por tipos"],"fr":["Mettre en œuvre des conventions de dénomination cohérentes pour les projets AWS CDK","Générer des déclarations de type pour les constructeurs d''infrastructure-as-code","Valider les conventions de dénomination pour la conformité aux principes de développement piloté par les types"],"de":["Konsistente Benennungskonventionen für AWS CDK-Projekte durchsetzen","Typdeklarationen für Infrastructure-as-Code-Konstrukte generieren","Benennungskonventionen für die Einhaltung typgetriebener Entwicklungsprinzipien validieren"],"pt":["Impor convenções de nomenclatura consistentes para projetos do AWS CDK","Gerar declarações de tipo para construtos de infraestrutura-kódigo","Validar convenções de nomenclatura para cumprimento com princípios de desenvolvimento orientado a tipo"],"ru":["Обеспечить последовательные соглашения об именовании для проектов AWS CDK","Генерировать объявления типов для конструкций инфраструктуры-как-кода","Проверять соглашения об именовании на соответствие принципам разработки, основанных на типах"],"ar":["فرض اتفاقيات تسمية متسقة لمشاريع AWS CDK","توليد إعلانات النوع لمكونات البنية ك_codigo","التحقق من اتفاقيات التسمية للامتثال لمبادئ التطوير الموجهة بالنوع"]},"limitations":{"en":["Requires AWS CDK integration","Limited to type-driven development principles"],"zh":["需要AWS CDK集成","仅限于基于类型的开发原则"],"ja":["AWS CDK 統合が必要","型ベースの開発原則のみに限定"],"ko":["AWS CDK 통합 필요","유형 기반 개발 원칙에만 제한"],"es":["Requiere integración con AWS CDK","Limitado a principios de desarrollo dirigido por tipos"],"fr":["Nécessite une intégration avec AWS CDK","Limité aux principes de développement piloté par les types"],"de":["Erfordert Integration mit AWS CDK","Begrenzt auf typgetriebene Entwicklungsprinzipien"],"pt":["Requer integração com o AWS CDK","Limitado a princípios de desenvolvimento orientado a tipo"],"ru":["Требует интеграции с AWS CDK","Ограничен принципами разработки, основанных на типах"],"ar":["يتطلب تكاملًا مع AWS CDK","محدود بمبادئ التطوير الموجهة بالنوع"]},"version":4},"contentHash":"0f9d00c1ecf47545fe26d42ffb402cf9fe0592567663032debdb812934dba59f","qualityScore":33}');
