INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('orient-bot/orient/atlassian-mcp', 'atlassian-mcp', 'orient-bot', 'orient', 'community', 'atlassian-mcp orient-bot orient community The atlassian-mcp skill provides direct access to JIRA and Confluence from coding agents like Cursor or Claude Code. It enables developers to access Atlassian data seamlessly. Atlassian MCP 服务器提供了对 JIRA 和 Confluence 的直接访问，支持 Cursor 或 Claude Code 的开发 Atlassian MCP サーバーは、JIRA と Confluence に直接アクセスするためのサポートを提供する Atlassian MCP 서버는 JIRA 및 Confluence에 직접 액세스할 수 있는 지원을 제공합니다 El servidor Atlassian MCP proporciona acceso directo a JIRA y Confluence desde agentes de codificación como Cursor o Claude Code Le serveur Atlassian MCP offre un accès direct à JIRA et Confluence à partir d''agents de codage tels que Cursor ou Claude Code Der Atlassian-MCP-Server bietet direkten Zugriff auf JIRA und Confluence von Codierungsagenten wie Cursor oder Claude Code O Atlassian MCP Server fornece acesso direto ao JIRA e Confluence para agentes de codificação Сервер Atlassian MCP предоставляет прямой доступ к JIRA и Confluence для кодирующих агентов خادم Atlassian MCP يوفر الوصول المباشر إلى جيرا وكونفلونس لوكلاء التشفير how to use atlassian-mcp atlassian-mcp setup guide atlassian-mcp alternative atlassian-mcp vs cursor atlassian-mcp install what is atlassian-mcp atlassian-mcp configuration atlassian-mcp for AI agents Atlassian MCP 服务器 JIRA 数据访问 Confluence 数据访问 Cursor 开发 Claude Code 开发 AI 工具 JSON 配置 Provides direct access to JIRA and Confluence from coding agents Supports configuration via `~/.cursor/mcp.json` file Enables access to Atlassian data from Cursor or Claude Code Allows for global configuration of the Atlassian MCP Server Supports JSON format for configuration settings atlassian-mcp is a server that provides direct access to JIRA and Confluence from coding agents, allowing for streamlined development and integration.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('miyakawa2449/KiroBookmark/mac-appstore-prep', 'community', 'miyakawa2449', 'KiroBookmark', 'miyakawa2449/KiroBookmark', 'mac-appstore-prep', 0, 0, 33, '2026-03-08T01:57:15.313Z', '2026-03-08T02:02:40.927Z', 'dcdbcdce920f2351575f3f6bf9894288248c9c4cd6a351c72cf90e75e0e0aed6', '{"id":"miyakawa2449/KiroBookmark/mac-appstore-prep","name":"mac-appstore-prep","description":{"en":"The mac-appstore-prep skill helps developers prepare their apps for Mac App Store submission by configuring sandbox settings, entitlements, and Info.plist files. It benefits developers who need to ensure their apps meet Apple''s requirements.","zh":"本指南介绍了 Mac App Store 申請準備的技术细节，包括 Sandbox 和 Info.plist 设置","ja":"本ガイドでは，Mac App Store 申請準備の技術的詳細，Sandbox と Info.plist 設定を含む","ko":"이 가이드는 Mac App Store 준비의 기술적인 세부 정보를介绍합니다, Sandbox와 Info.plist 설정 포함","es":"La guía de configuración mac-appstore-prep te ayuda a preparar tus aplicaciones para la Mac App Store, cubriendo aspectos como sandbox y permisos de Info.plist.","fr":"Le guide de configuration mac-appstore-prep vous aide à préparer vos applications pour la Mac App Store, en couvrant des aspects tels que le sandbox et les autorisations Info.plist.","de":"Der Konfigurationsleitfaden mac-appstore-prep hilft Ihnen, Ihre Anwendungen für den Mac App Store vorzubereiten, einschließlich Sandbox und Info.plist-Berechtigungen.","pt":"O mac-appstore-prep é uma ferramenta de desenvolvimento que ajuda a preparar aplicativos para a Mac App Store, incluindo configuração de sandbox e permissões do Info.plist.","ru":"ИИ Агенты mac-appstore-prep - это инструмент разработки, который помогает подготовить приложения для Mac App Store, включая настройку sandbox и разрешения Info.plist.","ar":"mac-appstore-prep هو أداة تطوير تساعد في إعداد التطبيقات لمتجر تطبيقات Mac، بما في ذلك إعداد sandbox وسمات Info.plist."},"seo":{"title":{"en":"mac-appstore-prep: Mac App Store Submission Setup Guide |...","zh":"Mac App Store 准备指南：Sandbox 和 Info.plist 设置","ja":"Mac App Store 申請準備ガイド：Sandbox と Info.plist 設定","ko":"Mac App Store 준비 가이드: 산드박스와 Info.plist 설정","es":"Guía de configuración para mac-appstore-prep: Preparación...","fr":"Guide de configuration mac-appstore-prep : Préparation de...","de":"Konfigurationsleitfaden für mac-appstore-prep: Vorbereitu...","pt":"Guia de Configuração para mac-appstore-prep","ru":"ИИ Агенты: Настройка mac-appstore-prep","ar":"إعداد mac-appstore-prep: دليل المستخدم"},"description":{"en":"Get ready for Mac App Store submission with our expert guide. Learn how to prepare your app with sandbox setup, entitlements, and Info.plist configuration.","zh":"了解 Mac App Store 申請準備的必須チェック項目，包括 Sandbox 和 Info.plist 设置","ja":"Mac App Store 申請準備の必須チェック項目を理解する，Sandbox と Info.plist 設定を含む","ko":"Mac App Store 준비를 위한 필수 체크 항목을 알아보세요, Sandbox와 Info.plist 설정 포함","es":"Aprende a preparar tus aplicaciones para la Mac App Store con nuestra guía de configuración mac-appstore-prep, incluyendo sandbox y permisos de Info.plist","fr":"Découvrez comment préparer vos applications pour la Mac App Store avec notre guide de configuration mac-appstore-prep, y compris le sandbox et les autorisati...","de":"Erfahren Sie, wie Sie Ihre Anwendungen für den Mac App Store mit unserer Konfigurationsanleitung mac-appstore-prep vorbereiten, einschließlich Sandbox und In...","pt":"Aprenda a configurar o mac-appstore-prep com nossa guia passo a passo, incluindo sandbox e permissões do Info.plist","ru":"Настройте mac-appstore-prep с помощью нашей пошаговой инструкции, включая sandbox и разрешения Info.plist","ar":"تعلم كيفية تهيئة mac-appstore-prep باستخدام دليلنا خطوة بخطوة، بما في ذلك sandbox وسمات Info.plist"},"definition":{"en":"mac-appstore-prep is a skill that assists in preparing macOS applications for submission to the Mac App Store, focusing on sandbox setup and Info.plist configuration.","zh":"Mac App Store 准备是指为 Mac 应用程序准备提交 App Store 的过程","ja":"Mac App Store 申請準備とは，Mac アプリケーションを App Store に提出するための準備プロセス","ko":"Mac App Store 준비는 Mac 애플리케이션을 App Store에 제출하기 위한 준비 과정입니다","es":"mac-appstore-prep es una herramienta de AI que ayuda a los desarrolladores a preparar sus aplicaciones para la Mac App Store","fr":"mac-appstore-prep est un outil d''IA qui aide les développeurs à préparer leurs applications pour la Mac App Store","de":"mac-appstore-prep ist ein AI-Tool, das Entwicklern hilft, ihre Anwendungen für den Mac App Store vorzubereiten","pt":"O que é mac-appstore-prep? É uma ferramenta de desenvolvimento que ajuda a preparar aplicativos para a Mac App Store.","ru":"Что такое mac-appstore-prep? Это инструмент разработки, который помогает подготовить приложения для Mac App Store.","ar":"ما هو mac-appstore-prep؟ هو أداة تطوير تساعد في إعداد التطبيقات لمتجر تطبيقات Mac."},"features":{"en":["Configures com.apple.security.app-sandbox entitlement for Mac App Store compatibility","Removes unnecessary entitlements for a streamlined submission process","Prepares Temporary Exception Entitlements descriptions for Apple review","Sets up NSCameraUsageDescription, NSMicrophoneUsageDescription, and other necessary usage descriptions in Info.plist","Supports NSAppleEventsUsageDescription and NSSystemAdministrationUsageDescription configurations"],"zh":["Sandbox 必須設定：com.apple.security.app-sandbox = true","Info.plist 権限説明：NSCameraUsageDescription，NSMicrophoneUsageDescription 等","Temporary Exception Entitlements の説明を準備","不需要的 Entitlements を削除","管理者権限使用時：NSSystemAdministrationUsageDescription","デスクトップアクセス時：NSDesktopFolderUsageDescription"],"ja":["Sandbox 必須設定：com.apple.security.app-sandbox = true","Info.plist 権限説明：NSCameraUsageDescription，NSMicrophoneUsageDescription 等","Temporary Exception Entitlements の説明を準備","不需要的 Entitlements を削除","管理者権限使用時：NSSystemAdministrationUsageDescription","デスクトップアクセス時：NSDesktopFolderUsageDescription"],"ko":["Sandbox 필수 설정: com.apple.security.app-sandbox = true","Info.plist 권한 설명: NSCameraUsageDescription, NSMicrophoneUsageDescription 등","Temporary Exception Entitlements 설명 준비","필요하지 않은 Entitlements 삭제","관리자 권한 사용 시: NSSystemAdministrationUsageDescription","데스크톱 액세스 시: NSDesktopFolderUsageDescription"],"es":["Configuración de sandbox con com.apple.security.app-sandbox = true","Eliminación de permisos de Entitlements innecesarios","Preparación de permisos de Info.plist para macOS","Soporte para NSCameraUsageDescription, NSMicrophoneUsageDescription y otros permisos","Preparación de Temporary Exception Entitlements","Compatibilidad con AppleScript y administración de sistemas"],"fr":["Configuration du sandbox avec com.apple.security.app-sandbox = true","Suppression des autorisations d''Entitlements inutiles","Préparation des autorisations d''Info.plist pour macOS","Prise en charge de NSCameraUsageDescription, NSMicrophoneUsageDescription et d''autres autorisations","Préparation des Temporary Exception Entitlements","Compatibilité avec AppleScript et l''administration des systèmes"],"de":["Konfiguration des Sandboxes mit com.apple.security.app-sandbox = true","Entfernen unnötiger Entitlements-Berechtigungen","Vorbereitung von Info.plist-Berechtigungen für macOS","Unterstützung für NSCameraUsageDescription, NSMicrophoneUsageDescription und andere Berechtigungen","Vorbereitung von Temporary Exception Entitlements","Kompatibilität mit AppleScript und Systemadministration"],"pt":["Configuração de sandbox com com.apple.security.app-sandbox = true","Gestão de permissões do Info.plist, incluindo NSCameraUsageDescription e NSMicrophoneUsageDescription","Preparação de Temporary Exception Entitlements","Suporte a AppleScript com NSAppleEventsUsageDescription","Acesso a pastas do sistema com NSDesktopFolderUsageDescription e NSDocumentsFolderUsageDescription"],"ru":["Настройка sandbox с com.apple.security.app-sandbox = true","Управление разрешениями Info.plist, включая NSCameraUsageDescription и NSMicrophoneUsageDescription","Подготовка Temporary Exception Entitlements","Поддержка AppleScript с NSAppleEventsUsageDescription","Доступ к системным папкам с NSDesktopFolderUsageDescription и NSDocumentsFolderUsageDescription"],"ar":["إعداد sandbox مع com.apple.security.app-sandbox = true","إدارة سمات Info.plist، بما في ذلك NSCameraUsageDescription و NSMicrophoneUsageDescription","تهيئة Temporary Exception Entitlements","دعم AppleScript مع NSAppleEventsUsageDescription","وصول إلى المجلدات النظامية مع NSDesktopFolderUsageDescription و NSDocumentsFolderUsageDescription"]},"keywords":{"en":["mac-appstore-prep setup guide","how to submit app to Mac App Store","mac-appstore-prep vs manual configuration","mac-appstore-prep install and setup","what is mac-appstore-prep","mac-appstore-prep alternative solutions","Info.plist configuration for Mac App Store","sandbox setup for macOS apps","mac-appstore-prep tutorial and documentation"],"zh":["Mac App Store 申請準備","Sandbox 设置","Info.plist 권限説明","AIエージェント","Mac 应用程序开发","App Store 提交","macOS 开发","Swift 开发","Xcode 开发"],"ja":["Mac App Store 申請準備","Sandbox 設定","Info.plist 権限説明","AIエージェント","Mac アプリケーション開発","App Store 提出","macOS 開発","Swift 開発","Xcode 開発"],"ko":["Mac App Store 준비","Sandbox 설정","Info.plist 권한 설명","AI 에이전트","Mac 애플리케이션 개발","App Store 제출","macOS 개발","Swift 개발","Xcode 개발"],"es":["mac-appstore-prep","preparación de aplicaciones para Mac App Store","sandbox en macOS","permisos de Info.plist","NSCameraUsageDescription","NSMicrophoneUsageDescription","Temporary Exception Entitlements","AppleScript","administración de sistemas"],"fr":["mac-appstore-prep","préparation d''applications pour la Mac App Store","sandbox sous macOS","autorisations d''Info.plist","NSCameraUsageDescription","NSMicrophoneUsageDescription","Temporary Exception Entitlements","AppleScript","administration des systèmes"],"de":["mac-appstore-prep","Vorbereitung von Anwendungen für den Mac App Store","Sandbox unter macOS","Info.plist-Berechtigungen","NSCameraUsageDescription","NSMicrophoneUsageDescription","Temporary Exception Entitlements","AppleScript","Systemadministration"],"pt":["mac-appstore-prep","desenvolvimento de aplicativos","Mac App Store","sandbox","Info.plist","permissões","AppleScript","NSCameraUsageDescription","NSMicrophoneUsageDescription"],"ru":["mac-appstore-prep","разработка приложений","Mac App Store","sandbox","Info.plist","разрешения","AppleScript","NSCameraUsageDescription","NSMicrophoneUsageDescription"],"ar":["mac-appstore-prep","تطوير التطبيقات","متجر تطبيقات Mac","sandbox","Info.plist","سمات","AppleScript","NSCameraUsageDescription","NSMicrophoneUsageDescription"]}},"owner":"miyakawa2449","repo":"KiroBookmark","repoPath":"miyakawa2449/KiroBookmark","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.313Z","topics":[],"category":"community","skillMd":{"name":"mac-appstore-prep","description":"Mac App Store申請前のチェックリスト。Sandbox必須、スクリーンショット、Notarization、権限説明を確認。Use when: Mac App Store、macOS申請、Mac審査 を依頼された時。","bodyPreview":"# Mac App Store 申請準備\n\n## 必須チェック項目\n\n### Sandbox 必須\n- [ ] com.apple.security.app-sandbox = true（Mac App Storeでは必須）\n- [ ] 不要な Entitlements を削除\n- [ ] Temporary Exception Entitlements の説明を準備（使用時）\n\n### Info.plist 権限説明（macOS固有）\n- [ ] NSCameraUsageDescription（カメラ使用時）\n- [ ] NSMicrophoneUsageDescription（マイク使用時）\n- [ ] NSAppleEventsUsageDescription（AppleScript使用時）\n- [ ] NSSystemAdministrationUsageDescription（管理者権限使用時）\n- [ ] NSDesktopFolderUsageDescription（デスクトップアクセス時）\n- [ ] NSDocumentsFolderUsageDescription","body":"# Mac App Store 申請準備\n\n## 必須チェック項目\n\n### Sandbox 必須\n- [ ] com.apple.security.app-sandbox = true（Mac App Storeでは必須）\n- [ ] 不要な Entitlements を削除\n- [ ] Temporary Exception Entitlements の説明を準備（使用時）\n\n### Info.plist 権限説明（macOS固有）\n- [ ] NSCameraUsageDescription（カメラ使用時）\n- [ ] NSMicrophoneUsageDescription（マイク使用時）\n- [ ] NSAppleEventsUsageDescription（AppleScript使用時）\n- [ ] NSSystemAdministrationUsageDescription（管理者権限使用時）\n- [ ] NSDesktopFolderUsageDescription（デスクトップアクセス時）\n- [ ] NSDocumentsFolderUsageDescription（書類フォルダアクセス時）\n- [ ] NSDownloadsFolderUsageDescription（ダウンロードフォルダアクセス時）\n\n### スクリーンショット要件\n| サイズ | 解像度 | 備考 |\n|--------|--------|------|\n| 1280 x 800 | 非Retina | 最小サイズ |\n| 1440 x 900 | 非Retina | 推奨 |\n| 2560 x 1600 | Retina | 推奨 |\n| 2880 x 1800 | Retina | 最大サイズ |\n\n※ 最低1枚、最大10枚\n\n### アセット\n- [ ] App Icon（1024x1024、角丸なし）\n- [ ] macOS用アイコンセット（16x16 〜 512x512@2x）\n\n### ビルド設定\n- [ ] Release 設定でビルド可能\n- [ ] Deployment Target が適切（最低サポートOS）\n- [ ] Architectures に arm64 と x86_64 を含む（Universal Binary推奨）\n\n## App Store Connect 設定\n\n### カテゴリ\n- [ ] 適切なカテゴリを選択\n- [ ] サブカテゴリの設定（該当時）\n\n### 価格と配信\n- [ ] 価格設定\n- [ ] 配信国/地域の設定\n\n### App Privacy\n- [ ] データ収集の回答\n- [ ] プライバシーポリシーURL\n\n## 審査対策\n\n### よくあるリジェクト理由（macOS固有）\n1. Sandbox 違反\n2. 不必要な Entitlements の使用\n3. プライベートAPIの使用\n4. 適切でない Temporary Exception の使用\n\n### テスト確認\n```bash\n# Sandbox テスト\nsandbox-exec -f /path/to/profile YourApp.app/Contents/MacOS/YourApp\n\n# Entitlements 確認\ncodesign -d --entitlements :- YourApp.app\n```\n"},"lastSynced":"2026-03-08T02:02:40.927Z","agentAnalysis":{"suitability":{"en":"Perfect for macOS Development Agents needing streamlined Mac App Store submission configuration.","zh":"适用于需要简化 Mac App Store 提交配置的 macOS 开发代理。","ja":"macOS 開発エージェントが Mac App Store 提出の設定を簡素化する必要がある場合に適しています。","ko":"Mac App Store 제출 구성이 간소화된 macOS 개발 에이전트에 적합합니다.","es":"Perfecto para Agentes de Desarrollo de macOS que necesitan una configuración de envío a la Mac App Store optimizada.","fr":"Parfait pour les agents de développement macOS nécessitant une configuration de soumission à la Mac App Store rationalisée.","de":"Perfekt für macOS-Entwicklungsagenten, die eine optimierte Konfiguration für die Einreichung im Mac App Store benötigen.","pt":"Perfeito para Agentes de Desenvolvimento do macOS que necessitam de configuração de envio simplificada para a Mac App Store.","ru":"Идеально подходит для агентов macOS Development, которым необходима упрощенная настройка отправки в Mac App Store.","ar":"مثالي للوكلاء الذين يحتاجون إلى إعدادات إرسال مبسطة إلى متجر التطبيقات الخاص بالماك"},"recommendation":{"en":"Empowers agents to configure sandbox settings, entitlements, and Info.plist files, ensuring compliance with Apple''s requirements for Mac App Store submission, including setting com.apple.security.app-sandbox to true and managing Temporary Exception Entitlements.","zh":"赋予代理配置沙盒设置、权限和 Info.plist 文件的能力，确保符合 Apple 的 Mac App Store 提交要求，包括将 com.apple.security.app-sandbox 设置为 true 和管理临时异常权限。","ja":"エージェントがサンドボックス設定、エンタイトルメント、Info.plist ファイルを構成する機能を提供し、Mac App Store 提出の要件を満たすことを保証します。com.apple.security.app-sandbox を true に設定し、Temporary Exception Entitlements を管理します。","ko":"에이전트가 샌드박스 설정, 권한 및 Info.plist 파일을 구성하도록 허용하여 Apple의 Mac App Store 제출 요구 사항을 준수하도록 합니다. com.apple.security.app-sandbox를 true로 설정하고 임시 예외 권한을 관리합니다.","es":"Habilita a los agentes a configurar la configuración de sandbox, permisos y archivos Info.plist, asegurando el cumplimiento de los requisitos de Apple para la presentación en la Mac App Store, incluyendo establecer com.apple.security.app-sandbox en true y gestionar permisos de excepción temporal.","fr":"Permet aux agents de configurer les paramètres de sandbox, les autorisations et les fichiers Info.plist, garantissant ainsi le respect des exigences d''Apple pour la soumission à la Mac App Store, y compris la définition de com.apple.security.app-sandbox sur true et la gestion des autorisations d''exception temporaire.","de":"Ermöglicht es Agenten, Sandbox-Einstellungen, Berechtigungen und Info.plist-Dateien zu konfigurieren, um die Einhaltung der Anforderungen von Apple für die Einreichung im Mac App Store sicherzustellen, einschließlich der Festlegung von com.apple.security.app-sandbox auf true und der Verwaltung von temporären Ausnahmegenehmigungen.","pt":"Habilita os agentes a configurarem as configurações de sandbox, direitos e arquivos Info.plist, garantindo o cumprimento dos requisitos da Apple para envio à Mac App Store, incluindo definir com.apple.security.app-sandbox como true e gerenciar Direitos de Exceção Temporária.","ru":"Наделяет агентов возможностью настраивать параметры sandbox, права и файлы Info.plist, обеспечивая соблюдение требований Apple для отправки в Mac App Store, включая установку com.apple.security.app-sandbox в true и управление Временными исключительными правами.","ar":"تمكين الوكلاء من تكوين إعدادات الساند بوكس و الامتيازات وملفات Info.plist، مما يضمن امتثال متطلبات ابل لإرسال التطبيقات إلى متجر التطبيقات الخاص بالماك، بما في ذلك تعيين com.apple.security.app-sandbox على صحيح وإدارة امتيازات الاستثناء المؤقتة"},"useCases":{"en":["Configuring sandbox settings for Mac App Store compliance","Generating and managing entitlements for macOS apps","Preparing Info.plist files with necessary usage descriptions, such as NSCameraUsageDescription and NSMicrophoneUsageDescription"],"zh":["为 Mac App Store 合规性配置沙盒设置","为 macOS 应用生成和管理权限","准备包含必要使用描述的 Info.plist 文件，例如 NSCameraUsageDescription 和 NSMicrophoneUsageDescription"],"ja":["Mac App Store 対応のサンドボックス設定の構成","macOS アプリのエンタイトルメントの生成と管理","必要な使用説明（NSCameraUsageDescription や NSMicrophoneUsageDescription など）を含む Info.plist ファイルの準備"],"ko":["Mac App Store 규정 준수용 샌드박스 설정 구성","macOS 앱의 권한 생성 및 관리","필요한 사용 설명(예: NSCameraUsageDescription 및 NSMicrophoneUsageDescription)을 포함하는 Info.plist 파일 준비"],"es":["Configuración de la configuración de sandbox para el cumplimiento de la Mac App Store","Generación y administración de permisos para aplicaciones macOS","Preparación de archivos Info.plist con descripciones de uso necesarias, como NSCameraUsageDescription y NSMicrophoneUsageDescription"],"fr":["Configuration des paramètres de sandbox pour la conformité à la Mac App Store","Génération et gestion des autorisations pour les applications macOS","Préparation des fichiers Info.plist avec des descriptions d''utilisation nécessaires, telles que NSCameraUsageDescription et NSMicrophoneUsageDescription"],"de":["Konfiguration der Sandbox-Einstellungen für die Einhaltung der Mac App Store-Richtlinien","Erstellung und Verwaltung von Berechtigungen für macOS-Anwendungen","Vorbereitung von Info.plist-Dateien mit erforderlichen Nutzungsbeschreibungen, wie z. B. NSCameraUsageDescription und NSMicrophoneUsageDescription"],"pt":["Configurando as configurações de sandbox para conformidade com a Mac App Store","Gerando e gerenciando direitos para aplicativos macOS","Preparando arquivos Info.plist com descrições de uso necessárias, como NSCameraUsageDescription e NSMicrophoneUsageDescription"],"ru":["Настройка параметров sandbox для соответствия Mac App Store","Генерация и управление правами для приложений macOS","Подготовка файлов Info.plist с необходимыми описаниями использования, такими как NSCameraUsageDescription и NSMicrophoneUsageDescription"],"ar":["تكوين إعدادات الساند بوكس للامتثال لمتجر التطبيقات الخاص بالماك","توليد وإدارة الامتيازات للتطبيقات الخاصة بالماك","إعداد ملفات Info.plist بالوصف اللازم للاستخدام، مثل NSCameraUsageDescription و NSMicrophoneUsageDescription"]},"limitations":{"en":["Requires knowledge of macOS development and Mac App Store guidelines","Limited to preparing apps for Mac App Store submission, not for other platforms"],"zh":["需要 macOS 开发和 Mac App Store 指南的知识","仅限于为 Mac App Store 提交准备应用，不适用于其他平台"],"ja":["macOS 開発と Mac App Store ガイドラインの知識が必要","Mac App Store 提出の準備用アプリのみに限定されており、他のプラットフォームには使用できません"],"ko":["macOS 개발 및 Mac App Store 가이드라인 지식이 필요","Mac App Store 제출 준비 애플리케이션에만 적용되며 다른 플랫폼에는 적용되지 않음"],"es":["Requiere conocimiento de desarrollo de macOS y directrices de la Mac App Store","Limitado a la preparación de aplicaciones para la presentación en la Mac App Store, no para otras plataformas"],"fr":["Nécessite des connaissances en développement macOS et des lignes directrices de la Mac App Store","Limité à la préparation des applications pour la soumission à la Mac App Store, et non pour d''autres plateformes"],"de":["Benötigt Kenntnisse in der Entwicklung von macOS und den Richtlinien des Mac App Store","Begrenzt auf die Vorbereitung von Anwendungen für die Einreichung im Mac App Store, nicht für andere Plattformen"],"pt":["Exige conhecimento de desenvolvimento do macOS e diretrizes da Mac App Store","Limitado à preparação de aplicativos para envio à Mac App Store, não para outras plataformas"],"ru":["Требует знания разработки macOS и руководств Mac App Store","Ограничен подготовкой приложений для отправки в Mac App Store, а не для других платформ"],"ar":["يتطلب معرفة بالتطوير الخاص بالماك و إرشادات متجر التطبيقات الخاص بالماك","محدود لإعداد التطبيقات لإرسالها إلى متجر التطبيقات الخاص بالماك، وليس لمنصات أخرى"]},"version":4},"contentHash":"dcdbcdce920f2351575f3f6bf9894288248c9c4cd6a351c72cf90e75e0e0aed6","qualityScore":33}');
