INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('arkcle83/crewdeck/design-guide', 'design-guide', 'arkcle83', 'crewdeck', 'community', 'design-guide arkcle83 crewdeck community The design-guide skill applies modern, minimal design principles to create clean and minimal layouts, establishing a clear visual hierarchy for improved user experience. 设计指南强调清晰、简洁、专业的设计原则，用于iRacing会话管理器的团队性能跟踪 デザインガイドは、iRacingセッションマネージャーによるチームパフォーマンス追跡のための明確でシンプルでプロフェッショナルな設計原則を強調しています 디자인 가이드는 iRacing 세션 관리자를 통한 팀 성능 추적을 위한 명확하고 간결하고 전문적인 디자인 원칙을 강조합니다 Nuestra guía de diseño se centra en la claridad y la profesionalidad, con un enfoque en la utilización intencional del espacio, el color y la tipografía Notre guide de conception se concentre sur la clarté et la professionnalisme, avec un focus sur l''utilisation intentionnelle de l''espace, de la couleur et de la typographie Unser Design-Leitfaden konzentriert sich auf Klarheit und Professionalität, mit einem Fokus auf die intentionale Verwendung von Raum, Farbe und Typografie O design-guide é uma abordagem moderna e minimalista para o design de interfaces de usuário, com foco em clareza e profissionalismo Дизайн-руководство - это современный и минималистичный подход к设计у интерфейсов пользователя, с фокусом на ясности и профессионализме для ИИ Агентов دليل التصميم هو نهج حديث و بسيط لتصميم واجهات المستخدم، مع التركيز على الوضوح والمهنية how to use design-guide what is design-guide design-guide alternative design-guide vs material design design-guide setup guide modern ui design principles minimal design best practices visual hierarchy in design 设计指南 iRacing会话管理器 团队性能跟踪 现代设计原则 极简设计 清晰设计 专业设计 空白空间 颜色设计 字体设计 Applies modern, minimal design principles for clarity and consistency Utilizes generous padding and margins for clean layouts Establishes a clear visual hierarchy for improved user experience Groups related elements with clear visual separation Removes unnecessary decorative elements for a professional look design-guide is a set of principles and guidelines for creating modern, minimal, and professional user interfaces with intentional use of space, color, and typography.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('yasudaProduct/chord-chart/commit-helper', 'community', 'yasudaProduct', 'chord-chart', 'yasudaProduct/chord-chart', 'commit-helper', 0, 0, 33, '2026-03-08T01:57:15.315Z', '2026-03-08T02:02:46.336Z', 'dcde20b1b53cccc051b44237b6e4b4b608ec7861ba6b64efc0c1a66eeefe3f7a', '{"id":"yasudaProduct/chord-chart/commit-helper","name":"commit-helper","description":{"en":"The commit-helper skill provides a Git workflow guide for the ChordBook project, outlining commit message conventions and types for efficient collaboration among developers.","zh":"Commit Helper 是一个 AI 工具，帮助开发者优化 Git 工作流程，包括提交消息格式化和类型约定","ja":"コミットヘルパーは、Git ワークフローの最適化を支援する AI エージェントです。コミットメッセージのフォーマットとタイプの規約を提供します","ko":"커밋 헬퍼는 Git 작업 흐름을 최적화하는 AI 도구입니다. 커밋 메시지 형식 및 유형 규약을 제공합니다","es":"Commit-helper es una herramienta que ayuda a seguir las convenciones de commit para Git, mejorando la claridad y organización de tus repositorios","fr":"Commit-helper est un outil qui aide à suivre les conventions de commit pour Git, améliorant la clarté et l''organisation de vos dépôts","de":"Commit-helper ist ein Tool, das dabei hilft, die Commit-Konventionen für Git einzuhalten, wodurch die Klarheit und Organisation Ihrer Repositorys verbessert werden","pt":"O Commit Helper é uma ferramenta que ajuda a melhorar a qualidade dos commits seguindo as convenções de commit de Git. Ele fornece um guia de estilo para mensagens de commit","ru":"ИИ Агент Commit Helper - это инструмент, который помогает улучшить качество коммитов, следуя конвенциям коммитов Git. Он предоставляет руководство по стилю для сообщений коммитов","ar":"مساعد Commit هو أداة تساعد على تحسين جودة الإلتزامات اتباعًا لاتفاقيات إلتزام Git. وهو يوفر دليلًا لإسلوب رسائل الإلتزام"},"seo":{"title":{"en":"commit-helper: Git Workflow Guide Setup | AI Agent Skill","zh":"Commit Helper 设置指南：优化 Git 工作流程","ja":"コミットヘルパー設定ガイド：Gitワークフローの最適化","ko":"커밋 헬퍼 설정 가이드: Git 작업 흐름 최적화","es":"Guía de configuración del commit-helper para flujos de tr...","fr":"Guide de mise en place de commit-helper pour les flux de ...","de":"Einrichtungsleitfaden für commit-helper in Git-Workflows","pt":"Commit Helper: Guia de Configuração para Melhores Prática...","ru":"ИИ Агент Commit Helper: Руководство по Настройке для Лучш...","ar":"مساعد Commit: دليل الإعداد لأفضل الممارسات في إدارة الإلت..."},"description":{"en":"Streamline your Git workflow with commit-helper. Learn how to implement conventional commit messages and improve collaboration. Get started now!","zh":"使用 Commit Helper AI 工具来优化您的 Git 工作流程，实现高效的代码提交和管理","ja":"Commit Helper AI エージェントを使用して、Git ワークフローの効率化を実現します","ko":"커밋 헬퍼 AI 도구를 사용하여 Git 작업 흐름을 최적화하고 코드提交 및 관리를 효율화합니다","es":"Aprende a utilizar commit-helper para mejorar tus flujos de trabajo de Git con mensajes de commit personalizados y convenciones de tipo","fr":"Découvrez comment utiliser commit-helper pour améliorer vos flux de travail Git avec des messages de commit personnalisés et des conventions de type","de":"Erfahren Sie, wie Sie commit-helper verwenden, um Ihre Git-Workflows mit benutzerdefinierten Commit-Mitteilungen und Typkonventionen zu verbessern","pt":"Aprenda a configurar o Commit Helper para melhorar a qualidade dos seus commits e seguir as melhores práticas de Git com exemplos de mensagens de commit","ru":"Узнайте, как настроить ИИ Агент Commit Helper для улучшения качества коммитов и следования лучшим практикам Git с примерами сообщений коммитов","ar":"تعرف على كيفية ضبط مساعد Commit لتحسين جودة الإلتزامات واتباع أفضل الممارسات ل Git مع أمثلة على رسائل الإلتزام"},"definition":{"en":"commit-helper is a skill that provides guidelines for Git workflows, including commit message formats and types such as feat, fix, and docs.","zh":"Commit Helper 是一个用于优化 Git 工作流程的 AI 工具，提供提交消息格式化和类型约定","ja":"コミットヘルパーは、Git ワークフローの効率化を支援する AI エージェントであり、コミットメッセージのフォーマットとタイプの規約を提供します","ko":"커밋 헬퍼는 Git 작업 흐름을 최적화하는 AI 도구로, 커밋 메시지 형식 및 유형 규약을 제공합니다","es":"Commit-helper es una herramienta de AI que ayuda a los desarrolladores a seguir las convenciones de commit de Git","fr":"Commit-helper est un outil d''IA qui aide les développeurs à suivre les conventions de commit de Git","de":"Commit-helper ist ein AI-Tool, das Entwicklern hilft, die Commit-Konventionen von Git einzuhalten","pt":"O Commit Helper é uma ferramenta de auxílio ao desenvolvedor que segue as convenções de commit de Git para melhorar a qualidade dos commits","ru":"ИИ Агент Commit Helper - это инструмент помощи разработчику, который следует конвенциям коммитов Git для улучшения качества коммитов","ar":"مساعد Commit هو أداة مساعدة للمطور التي تتبع اتفاقيات إلتزام Git لتحسين جودة الإلتزامات"},"features":{"en":["Generates conventional commit messages using feat, fix, and docs types","Supports refactor, test, and chore commit types for code organization","Provides examples for commit messages, such as feat: add song search functionality","Follows a specific commit message format: <type>: <subject>","Includes guidelines for empty lines and wrapping in commit messages","Defines types for different commit purposes, including style and chore"],"zh":["提交消息格式化","类型约定（feat、fix、docs、style、refactor、test、chore）","代码提交效率优化","Git 工作流程自动化","代码质量提高"],"ja":["コミットメッセージのフォーマット","タイプの規約（feat、fix、docs、style、refactor、test、chore）","コードの提交効率化","Git ワークフローの自動化","コード品質の向上"],"ko":["커밋 메시지 형식화","유형 규약（feat、fix、docs、style、refactor、test、chore）","코드 제출 효율화","Git 작업 흐름 자동화","코드 품질 향상"],"es":["Soporte para mensajes de commit personalizados","Convenciones de tipo para commits (feat, fix, docs, etc.)","Compatibilidad con flujos de trabajo de Git","Mejora de la claridad y organización de los repositorios","Integración con herramientas de desarrollo como ESLint"],"fr":["Prise en charge de messages de commit personnalisés","Conventions de type pour les commits (feat, fix, docs, etc.)","Compatibilité avec les flux de travail Git","Amélioration de la clarté et de l''organisation des dépôts","Intégration avec des outils de développement comme ESLint"],"de":["Unterstützung für benutzerdefinierte Commit-Mitteilungen","Typkonventionen für Commits (feat, fix, docs usw.)","Kompatibilität mit Git-Workflows","Verbesserung der Klarheit und Organisation der Repositorys","Integration mit Entwicklungstools wie ESLint"],"pt":["Suporte a convenções de commit de Git","Guia de estilo para mensagens de commit","Exemplos de mensagens de commit para diferentes tipos de commits (feat, fix, docs, etc.)","Compatibilidade com fluxos de trabalho Git","Melhoria da qualidade dos commits"],"ru":["Поддержка конвенций коммитов Git","Руководство по стилю для сообщений коммитов","Примеры сообщений коммитов для разных типов коммитов (feat, fix, docs и т.д.)","Совместимость с рабочими процессами Git","Улучшение качества коммитов"],"ar":["دعم اتفاقيات إلتزام Git","دليل للأسلوب لرسائل الإلتزام","أمثلة على رسائل إلتزام لمختلف أنواع الإلتزامات (feat, fix, docs, etc.)","التوافق مع سير عمل Git","تحسين جودة الإلتزامات"]},"keywords":{"en":["how to use commit-helper","commit-helper setup guide","git workflow best practices","conventional commit messages","commit-helper vs git flow","install commit-helper","what is commit-helper","commit-helper alternative","git commit message format"],"zh":["Commit Helper","Git 工作流程","AI 工具","提交消息格式化","类型约定","代码提交效率优化","Git 自动化"],"ja":["コミットヘルパー","Git ワークフロー","AI エージェント","コミットメッセージのフォーマット","タイプの規約","コードの提交効率化","Git 自動化"],"ko":["커밋 헬퍼","Git 작업 흐름","AI 도구","커밋 메시지 형식화","유형 규약","코드 제출 효율화","Git 자동화"],"es":["commit-helper","herramientas de AI para desarrolladores","convenciones de commit de Git","flujos de trabajo de Git","mensajes de commit personalizados","ESLint","desarrollo de software","herramientas de desarrollo"],"fr":["commit-helper","outils d''IA pour développeurs","conventions de commit de Git","flux de travail Git","messages de commit personnalisés","ESLint","développement de logiciels","outils de développement"],"de":["commit-helper","AI-Tools für Entwickler","Commit-Konventionen von Git","Git-Workflows","benutzerdefinierte Commit-Mitteilungen","ESLint","Software-Entwicklung","Entwicklungstools"],"pt":["commit helper","guia de commit","melhores práticas de commit","convenções de commit git","ferramentas de desenvolvimento","qualidade de commit","fluxo de trabalho git"],"ru":["ИИ Агент Commit Helper","руководство по коммитам","лучшие практики коммитов","конвенции коммитов Git","инструменты разработки","качество коммитов","рабочий процесс Git"],"ar":["مساعد Commit","دليل الإلتزام","أفضل الممارسات للإلتزام","اتفاقيات إلتزام Git","أدوات التطوير","جودة الإلتزام","سير عمل Git"]}},"owner":"yasudaProduct","repo":"chord-chart","repoPath":"yasudaProduct/chord-chart","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.315Z","topics":[],"category":"community","skillMd":{"name":"commit-helper","description":"Git コミットメッセージ作成とPR作成を支援。コミット、プッシュ、プルリクエスト作成の際に使用。","bodyPreview":"# コミット・PR作成スキル\n\nChordBook プロジェクトの Git ワークフローガイドラインです。\n\n## コミットメッセージ規約\n\n### フォーマット\n```\n<type>: <subject>\n```\n\n### Type 一覧\n| Type | 説明 |\n|------|------|\n| `feat` | 新機能 |\n| `fix` | バグ修正 |\n| `docs` | ドキュメントのみの変更 |\n| `style` | コードの意味に影響しない変更（空白、フォーマット等） |\n| `refactor` | バグ修正でも新機能でもないコード変更 |\n| `test` | テストの追加・修正 |\n| `chore` | ビルドプロセスや補助ツールの変更 |\n\n### 例\n```\nfeat: 楽曲検索機能を追加\nfix: ログイン時のエラーハンドリングを修正\ndocs: API仕様書を更新\nrefactor: Song エンティティのバリデーションを整理\ntest: SongController の単体テストを追加\nchore: ESLint 設定を更新\n```\n\n##","body":"# コミット・PR作成スキル\n\nChordBook プロジェクトの Git ワークフローガイドラインです。\n\n## コミットメッセージ規約\n\n### フォーマット\n```\n<type>: <subject>\n```\n\n### Type 一覧\n| Type | 説明 |\n|------|------|\n| `feat` | 新機能 |\n| `fix` | バグ修正 |\n| `docs` | ドキュメントのみの変更 |\n| `style` | コードの意味に影響しない変更（空白、フォーマット等） |\n| `refactor` | バグ修正でも新機能でもないコード変更 |\n| `test` | テストの追加・修正 |\n| `chore` | ビルドプロセスや補助ツールの変更 |\n\n### 例\n```\nfeat: 楽曲検索機能を追加\nfix: ログイン時のエラーハンドリングを修正\ndocs: API仕様書を更新\nrefactor: Song エンティティのバリデーションを整理\ntest: SongController の単体テストを追加\nchore: ESLint 設定を更新\n```\n\n## コミット作成手順\n\n1. **変更内容を確認**\n   ```bash\n   git status\n   git diff\n   ```\n\n2. **ステージング**\n   ```bash\n   git add <specific-files>  # 特定ファイルを追加（推奨）\n   # または\n   git add -A  # 全ファイル追加\n   ```\n\n3. **コミット**\n   ```bash\n   git commit -m \"<type>: <subject>\"\n   ```\n\n## プルリクエスト作成\n\n### PR タイトル\nコミットメッセージと同じ規約を使用：\n```\nfeat: 楽曲検索機能を追加\n```\n\n### PR 本文テンプレート\n\n```markdown\n## 概要\n<!-- 変更内容の簡潔な説明 -->\n\n## 変更内容\n-\n-\n\n## テスト方法\n- [ ]\n- [ ]\n\n## スクリーンショット（UI変更がある場合）\n\n## 関連Issue\ncloses #\n```\n\n### PR 作成コマンド\n```bash\ngh pr create --title \"<type>: <subject>\" --body \"...\"\n```\n\n## ブランチ運用\n\n### ブランチ命名規則\n```\nfeature/<機能名>    # 新機能\nfix/<バグ名>        # バグ修正\ndocs/<ドキュメント名> # ドキュメント\nrefactor/<対象>     # リファクタリング\n```\n\n### 例\n```\nfeature/song-search\nfix/login-error-handling\ndocs/api-specification\nrefactor/song-validation\n```\n\n## 注意事項\n\n- コミット前に `pnpm lint` (FE) や `dotnet build` (BE) を実行\n- 機密情報（.env, credentials）をコミットしない\n- 大きな変更は小さなコミットに分割\n- コミットは論理的な単位で行う\n"},"lastSynced":"2026-03-08T02:02:46.336Z","agentAnalysis":{"suitability":{"en":"Perfect for Development Agents needing standardized Git workflow management.","zh":"非常适合需要标准化 Git 工作流管理的开发代理。","ja":"開発エージェントが標準化された Git ワークフロー管理を必要とする場合に最適です。","ko":"표준화된 Git 워크플로우 관리가 필요한 개발 에이전트에게 적합합니다.","es":"Perfecto para Agentes de Desarrollo que necesitan una gestión de flujo de trabajo de Git estandarizada.","fr":"Parfait pour les agents de développement ayant besoin d''une gestion de workflow Git standardisée.","de":"Perfekt für Entwicklungsmittel, die eine standardisierte Git-Workflow-Verwaltung benötigen.","pt":"Perfeito para Agentes de Desenvolvimento que necessitam de gerenciamento de fluxo de trabalho Git padronizado.","ru":"Идеально для агентов разработки, требующих стандартизированного управления рабочим процессом Git.","ar":"مثالي لعميل التطوير الذين يحتاجون إلى إدارة تدفق عمل Git معيارية."},"recommendation":{"en":"Empowers agents to enforce commit message conventions and types, such as feat, fix, and docs, for efficient collaboration among developers using Git, streamlining the development process with clear and consistent version control.","zh":"赋予代理人强制执行提交消息约定和类型（如 feat、fix 和 docs）的能力，从而实现使用 Git 的开发人员之间的高效协作，并通过清晰和一致的版本控制简化开发过程。","ja":"Git を使用する開発者間の効率的なコラボレーションを可能にし、クリアで一貫したバージョン管理によって開発プロセスを簡素化するために、feat、fix、docs などのコミットメッセージの規約とタイプを適用するエージェントの能力を提供します。","ko":"feat, fix, docs 등의 커밋 메시지 규약 및 유형을 강제 적용하여 Git을 사용하는 개발자 간의 효율적인 협력을 가능하게 하고, 명확하고 일관된 버전 관리를 통해 개발 프로세스를 간소화합니다.","es":"Habilita a los agentes a aplicar convenciones y tipos de mensajes de confirmación, como feat, fix y docs, para una colaboración eficiente entre desarrolladores que utilizan Git, racionalizando el proceso de desarrollo con un control de versiones claro y coherente.","fr":"Permet aux agents d''appliquer des conventions et des types de messages de validation, tels que feat, fix et docs, pour une collaboration efficace entre les développeurs utilisant Git, en rationalisant le processus de développement avec un contrôle de version clair et cohérent.","de":"Ermächtigt Agenten, Commit-Nachrichten-Konventionen und -Typen wie feat, fix und docs durchzusetzen, für eine effiziente Zusammenarbeit unter Entwicklern, die Git verwenden, und rationalisiert den Entwicklungsprozess mit einem klaren und konsistenten Versionskontrollsystem.","pt":"Habilita os agentes a impor convenções e tipos de mensagem de commit, como feat, fix e docs, para colaboração eficiente entre os desenvolvedores que usam Git, otimizando o processo de desenvolvimento com controle de versão claro e consistente.","ru":"Наделяет агентов возможностью обеспечивать соблюдение соглашений и типов сообщений о коммите, таких как feat, fix и docs, для эффективного сотрудничества между разработчиками, использующими Git, оптимизируя процесс разработки с четким и последовательным управлением версиями.","ar":"تمكّن الوكيل من فرض اتفاقيات و أنواع رسائل الالتزام، مثل feat و fix و docs، من أجل تعاون فعال بين المطورين الذين يستخدمون Git، وضبط عملية التطوير مع سيطرة على الإصدارات واضحة ومستمرة."},"useCases":{"en":["Standardizing commit messages with clear type indicators","Automating commit message validation for Pull Requests","Generating changelogs based on commit history and types"],"zh":["使用清晰的类型指示器标准化提交消息","自动化拉取请求的提交消息验证","根据提交历史记录和类型生成变更日志"],"ja":["明確なタイプインジケーターでコミットメッセージを標準化する","プルリクエストのコミットメッセージの検証を自動化する","コミット履歴とタイプに基づいて変更ログを生成する"],"ko":["명확한 유형 지시자를 사용하여 커밋 메시지를 표준화하는 것","풀 리퀘스트에 대한 커밋 메시지 검증 자동화","커밋 기록 및 유형에 따라 변경 로그 생성"],"es":["Estandarizar mensajes de confirmación con indicadores de tipo claros","Automatizar la validación de mensajes de confirmación para solicitudes de extracción","Generar registros de cambios en función del historial y los tipos de confirmación"],"fr":["Standardiser les messages de validation avec des indicateurs de type clairs","Automatiser la validation des messages de validation pour les demandes d''extraction","Générer des journaux des modifications en fonction de l''historique et des types de validation"],"de":["Standardisieren von Commit-Nachrichten mit klaren Typindikatoren","Automatisieren der Validierung von Commit-Nachrichten für Pull-Requests","Generieren von Änderungsprotokollen auf der Grundlage der Commit-Historie und -Typen"],"pt":["Padronizar mensagens de commit com indicadores de tipo claros","Automatizar validação de mensagens de commit para Solicitações de Pull","Gerar registros de alterações com base na história e tipos de commit"],"ru":["Стандартизировать сообщения о коммите с ясными индикаторами типа","Автоматизировать проверку сообщений о коммите для запросов на включение","Генерировать журналы изменений на основе истории и типов коммитов"],"ar":["تقييس رسائل الالتزام مع указات نوع واضحة","آليّة التحقق من صحة رسائل الالتزام لطلبات السحب","توليد سجلات التغييرات بناءً على تاريخ و أنواع الالتزام"]},"limitations":{"en":["Requires Git version control system","Specific to ChordBook project guidelines and conventions"],"zh":["需要 Git 版本控制系统","特定于 ChordBook 项目指南和约定"],"ja":["Git バージョン管理システムが必要","ChordBook プロジェクトのガイドラインと規約に特有"],"ko":["Git 버전 관리 시스템 필요","ChordBook 프로젝트 가이드라인 및 규약에 특정"],"es":["Requiere el sistema de control de versiones Git","Específico para las pautas y convenciones del proyecto ChordBook"],"fr":["Nécessite le système de contrôle de version Git","Spécifique aux directives et conventions du projet ChordBook"],"de":["Erfordert das Versionskontrollsystem Git","Spezifisch für die Richtlinien und Konventionen des ChordBook-Projekts"],"pt":["Exige sistema de controle de versão Git","Específico para diretrizes e convenções do projeto ChordBook"],"ru":["Требует системы контроля версий Git","Конкретно для руководящих принципов и соглашений проекта ChordBook"],"ar":["يتطلب نظام التحكم في الإصدار Git","محدد لمرشدي و اتفاقيات مشروع ChordBook"]},"version":4},"contentHash":"dcde20b1b53cccc051b44237b6e4b4b608ec7861ba6b64efc0c1a66eeefe3f7a","qualityScore":33}');
