INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('yasudaProduct/chord-chart/commit-helper', 'commit-helper', 'yasudaProduct', 'chord-chart', 'community', 'commit-helper yasudaProduct chord-chart community The commit-helper skill provides a Git workflow guide for the ChordBook project, outlining commit message conventions and types for efficient collaboration among developers. Commit Helper 是一个 AI 工具，帮助开发者优化 Git 工作流程，包括提交消息格式化和类型约定 コミットヘルパーは、Git ワークフローの最適化を支援する AI エージェントです。コミットメッセージのフォーマットとタイプの規約を提供します 커밋 헬퍼는 Git 작업 흐름을 최적화하는 AI 도구입니다. 커밋 메시지 형식 및 유형 규약을 제공합니다 Commit-helper es una herramienta que ayuda a seguir las convenciones de commit para Git, mejorando la claridad y organización de tus repositorios Commit-helper est un outil qui aide à suivre les conventions de commit pour Git, améliorant la clarté et l''organisation de vos dépôts Commit-helper ist ein Tool, das dabei hilft, die Commit-Konventionen für Git einzuhalten, wodurch die Klarheit und Organisation Ihrer Repositorys verbessert werden O Commit Helper é uma ferramenta que ajuda a melhorar a qualidade dos commits seguindo as convenções de commit de Git. Ele fornece um guia de estilo para mensagens de commit ИИ Агент Commit Helper - это инструмент, который помогает улучшить качество коммитов, следуя конвенциям коммитов Git. Он предоставляет руководство по стилю для сообщений коммитов مساعد Commit هو أداة تساعد على تحسين جودة الإلتزامات اتباعًا لاتفاقيات إلتزام Git. وهو يوفر دليلًا لإسلوب رسائل الإلتزام how to use commit-helper commit-helper setup guide git workflow best practices conventional commit messages commit-helper vs git flow install commit-helper what is commit-helper commit-helper alternative git commit message format Commit Helper Git 工作流程 AI 工具 提交消息格式化 类型约定 代码提交效率优化 Git 自动化 Generates conventional commit messages using feat, fix, and docs types Supports refactor, test, and chore commit types for code organization Provides examples for commit messages, such as feat: add song search functionality Follows a specific commit message format: <type>: <subject> Includes guidelines for empty lines and wrapping in commit messages Defines types for different commit purposes, including style and chore commit-helper is a skill that provides guidelines for Git workflows, including commit message formats and types such as feat, fix, and docs.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('takemo101/compose-workflow/iterative-review', 'community', 'takemo101', 'compose-workflow', 'takemo101/compose-workflow', 'iterative-review', 0, 0, 33, '2026-03-08T01:57:15.316Z', '2026-03-08T02:02:49.032Z', '66f2c4157cf399d5f53f439ec27622841599d246d4469a0456d834e8f2fea8d6', '{"id":"takemo101/compose-workflow/iterative-review","name":"iterative-review","description":{"en":"The iterative-review skill ensures quality assurance for OpenCode documentation and settings by implementing a repeatable review process. This benefits developers working with OpenCode repositories.","zh":"迭代审查是一种提高代码质量的方法，通过反复修正和审查来确保问题得到及时解决。","ja":"反復レビューは、コード品質を高めるための方法で、修正とレビューを繰り返して問題を迅速に解決します。","ko":"반복 리뷰는 코드 품질을 높이는 방법으로, 수정과 리뷰를 반복하여 문제를 빠르게 해결합니다.","es":"La revisión iterativa es un proceso de aseguramiento de la calidad para documentos y configuraciones de agentes de IA","fr":"La révision itérative est un processus de garantie de la qualité pour les documents et les configurations d''outils d''IA","de":"Die iterative Überprüfung ist ein Qualitätsicherungsprozess für Dokumente und Konfigurationen von KI-Agents","pt":"O Iterative-Review é um processo de garantia de qualidade para documentos e configurações de Ferramentas de IA","ru":"Итеративный обзор - это процесс обеспечения качества документов и конфигураций ИИ Агентов","ar":"المراجعة المتكررة هي عملية لضمان جودة الوثائق وإعدادات أدوات الذكاء الاصطناعي"},"seo":{"title":{"en":"Iterative-Review: Quality Assurance Workflow Setup Guide ...","zh":"迭代审查设置指南 - AI工具","ja":"反復レビューの設定方法 - AIエージェント","ko":"반복 리뷰 설정 가이드 - AI 에이전트","es":"Guía de configuración para revisión iterativa de agentes ...","fr":"Guide de configuration pour la révision itérative d''outil...","de":"Konfigurationsleitfaden für iterative Überprüfung von KI-...","pt":"Guia de Configuração do Iterative-Review para Ferramentas...","ru":"Настройка ИИ Агентов с помощью Iterative-Review","ar":"دليل إعداد Iterative-Review لأدوات الذكاء الاصطناعي"},"description":{"en":"Streamline your OpenCode workflow with iterative-review. Learn how to implement a repeatable review process for documentation and settings. Get started now!","zh":"了解如何使用迭代审查提高代码质量，自动化审查流程，确保问题得到及时解决 - AI工具","ja":"反復レビューを使用してコード品質を高める方法を学び、レビューを自動化して問題を迅速に解決する - AIエージェント","ko":"반복 리뷰를 사용하여 코드 품질을 높이고 리뷰를 자동화하여 문제를 빠르게 해결하는 방법을 알아보세요 - AI 에이전트","es":"Aprende a configurar la revisión iterativa para agentes de IA y mejora la calidad de tus documentos y configuraciones","fr":"Découvrez comment configurer la révision itérative pour les outils d''IA et améliorer la qualité de vos documents et configurations","de":"Erfahren Sie, wie Sie die iterative Überprüfung für KI-Agents konfigurieren und die Qualität Ihrer Dokumente und Konfigurationen verbessern","pt":"Aprenda a configurar o Iterative-Review para melhorar a qualidade do seu código e documentos de Ferramentas de IA","ru":"Узнайте, как настроить Iterative-Review для повышения качества кода и документов ИИ Агентов","ar":"تعرف على كيفية إعداد Iterative-Review لتحسين جودة رمز وأدلة أدوات الذكاء الاصطناعي"},"definition":{"en":"Iterative-review is a quality assurance workflow that improves OpenCode documentation and settings through a cyclical process of modification, review, and revision.","zh":"迭代审查是一种代码审查方法，通过反复修正和审查来确保代码质量。","ja":"反復レビューは、コードの品質を高めるための手法で、修正とレビューを繰り返します。","ko":"반복 리뷰는 코드 품질을 높이는 위한 방법으로, 수정과 리뷰를 반복합니다.","es":"La revisión iterativa es un proceso que implica la revisión y modificación repetida de documentos y configuraciones hasta que se cumplan los estándares de calidad","fr":"La révision itérative est un processus qui implique la révision et la modification répétée de documents et de configurations jusqu''à ce que les normes de qualité soient respectées","de":"Die iterative Überprüfung ist ein Prozess, der die wiederholte Überprüfung und Modifizierung von Dokumenten und Konfigurationen umfasst, bis die Qualitätsstandards erfüllt sind","pt":"O que é Iterative-Review? Um processo de revisão e melhoria contínua para Ferramentas de IA","ru":"Что такое Итеративный обзор? Процесс непрерывного обзора и улучшения для ИИ Агентов","ar":"ما هي المراجعة المتكررة؟ عملية مراجعة وتحسين مستمرة لأدوات الذكاء الاصطناعي"},"features":{"en":["Supports modification of `.opencode/` directory documents and settings","Enforces review of command definitions in `.claude/commands/*.md` files","Validates skill definitions in `.claude/skills/*.md` files","Reviews agent definitions in `.claude/agents/*.md` files","Checks configuration files in `.opencode/*.json` and `.opencode/*.yml` formats","Verifies README files in `.opencode/README.md`"],"zh":["自动化审查流程","支持多种文件格式（.md, .json, .yml）","可应用于命令定义、技能定义、代理定义和设置文件","提高代码质量和可靠性","减少手动审查的时间和成本"],"ja":["レビューの自動化","複数のファイル形式（.md, .json, .yml）をサポート","コマンド定義、スキル定義、エージェント定義、設定ファイルに適用可能","コード品質と信頼性の向上","手動レビューの時間とコストの削減"],"ko":["리뷰의 자동화","여러 파일 형식（.md, .json, .yml）을 지원","명령어 정의, 스킬 정의, 에이전트 정의, 설정 파일에 적용 가능","코드 품질과 신뢰성의 향상","수동 리뷰의 시간과 비용의 감소"],"es":["Revisión de documentos en `.opencode/`","Revisión de configuraciones en `.claude/commands/*.md`","Revisión de definiciones de habilidades en `.claude/skills/*.md`","Revisión de definiciones de agentes en `.claude/agents/*.md`","Revisión de archivos de configuración en `.opencode/*.json` y `.opencode/*.yml`"],"fr":["Révision de documents dans `.opencode/`","Révision de configurations dans `.claude/commands/*.md`","Révision de définitions de compétences dans `.claude/skills/*.md`","Révision de définitions d''agents dans `.claude/agents/*.md`","Révision de fichiers de configuration dans `.opencode/*.json` et `.opencode/*.yml`"],"de":["Überprüfung von Dokumenten in `.opencode/`","Überprüfung von Konfigurationen in `.claude/commands/*.md`","Überprüfung von Fähigkeitsdefinitionen in `.claude/skills/*.md`","Überprüfung von Agentendefinitionen in `.claude/agents/*.md`","Überprüfung von Konfigurationsdateien in `.opencode/*.json` und `.opencode/*.yml`"],"pt":["Suporte a revisão de documentos em formato Markdown","Integração com arquivos de configuração JSON e YAML","Fluxo de trabalho de revisão em fases para garantir a qualidade","Suporte a revisão de comandos e habilidades de Ferramentas de IA","Compatibilidade com o formato de arquivo README"],"ru":["Поддержка обзора документов в формате Markdown","Интеграция с конфигурационными файлами JSON и YAML","Поток обзора в фазах для обеспечения качества","Поддержка обзора команд и навыков ИИ Агентов","Совместимость с форматом файла README"],"ar":["دعم مراجعة المستندات بصيغة Markdown","التكامل مع ملفات التكوين JSON و YAML","تدفق مراجعة بالمراحل لضمان الجودة","دعم مراجعة الأوامر ومهارات أدوات الذكاء الاصطناعي","التوافق مع صيغة ملف README"]},"keywords":{"en":["how to use iterative-review","what is iterative-review","iterative-review alternative","iterative-review vs code review","iterative-review install","iterative-review setup guide","OpenCode quality assurance","AI agent workflow optimization","iterative-review for developers"],"zh":["迭代审查","AI工具","代码审查","自动化审查","代码质量","可靠性","手动审查","时间和成本的削减"],"ja":["反復レビュー","AIエージェント","コードレビュー","レビューの自動化","コード品質","信頼性","手動レビュー","時間とコストの削減"],"ko":["반복 리뷰","AI 에이전트","코드 리뷰","리뷰의 자동화","코드 품질","신뢰성","수동 리뷰","시간과 비용의 감소"],"es":["revisión iterativa","agentes de IA","configuración de documentos","configuración de habilidades","configuración de agentes","revisión de código","seguridad de la calidad","desarrollo de software","herramientas de IA"],"fr":["révision itérative","outils d''IA","configuration de documents","configuration de compétences","configuration d''agents","révision de code","sécurité de la qualité","développement de logiciels","outils d''IA"],"de":["iterative Überprüfung","KI-Agents","Konfiguration von Dokumenten","Konfiguration von Fähigkeiten","Konfiguration von Agenten","Überprüfung von Code","Qualitätssicherung","Softwareentwicklung","KI-Tools"],"pt":["Iterative-Review","Ferramentas de IA","Garantia de qualidade","Revisão de documentos","Configuração de Ferramentas de IA","Desenvolvimento de software","Engenharia de software","Melhoria contínua"],"ru":["Итеративный обзор","ИИ Агенты","Обеспечение качества","Обзор документов","Конфигурация ИИ Агентов","Разработка программного обеспечения","Инженерия программного обеспечения","Непрерывное улучшение"],"ar":["المراجعة المتكررة","أدوات الذكاء الاصطناعي","ضمان الجودة","مراجعة المستندات","إعدادات أدوات الذكاء الاصطناعي","تطوير البرمجيات","هندسة البرمجيات","التحسين المستمر"]}},"owner":"takemo101","repo":"compose-workflow","repoPath":"takemo101/compose-workflow","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.316Z","topics":[],"category":"community","skillMd":{"name":"iterative-review","description":".opencode/配下のドキュメント・設定を修正する際の品質保証プロセス（修正→レビュー→修正の反復ループ）","bodyPreview":"# OpenCode自己改善ワークフロー（反復レビュー）\n\n`.opencode/` 配下のドキュメント・設定を修正する際の品質保証プロセス。\n修正→レビュー→修正を繰り返し、問題がなくなるまで継続する。\n\n---\n\n## 適用範囲\n\n| 対象 | 例 |\n|------|-----|\n| コマンド定義 | `.claude/commands/*.md` |\n| スキル定義 | `.claude/skills/*.md` |\n| エージェント定義 | `.claude/agents/*.md` |\n| 設定ファイル | `.opencode/*.json`, `.opencode/*.yml` |\n| README | `.opencode/README.md` |\n\n---\n\n## ワークフロー概要\n\n```\n[修正依頼] \n    ↓\n[Phase 1] 修正実施\n    ↓\n[Phase 2] 全体レビュー\n    ↓\n    ├── 問題あり → [Phase 3] 修正 → Phase 2 に戻る\n    │\n    └── 問題なし → [Phase 4] コミット\n```","body":"# OpenCode自己改善ワークフロー（反復レビュー）\n\n`.opencode/` 配下のドキュメント・設定を修正する際の品質保証プロセス。\n修正→レビュー→修正を繰り返し、問題がなくなるまで継続する。\n\n---\n\n## 適用範囲\n\n| 対象 | 例 |\n|------|-----|\n| コマンド定義 | `.claude/commands/*.md` |\n| スキル定義 | `.claude/skills/*.md` |\n| エージェント定義 | `.claude/agents/*.md` |\n| 設定ファイル | `.opencode/*.json`, `.opencode/*.yml` |\n| README | `.opencode/README.md` |\n\n---\n\n## ワークフロー概要\n\n```\n[修正依頼] \n    ↓\n[Phase 1] 修正実施\n    ↓\n[Phase 2] 全体レビュー\n    ↓\n    ├── 問題あり → [Phase 3] 修正 → Phase 2 に戻る\n    │\n    └── 問題なし → [Phase 4] コミット\n```\n\n---\n\n## Phase 1: 修正実施\n\n### 1.1 変更計画\n\n修正前にTodoリストを作成し、変更スコープを明確化する。\n\n```\n□ 変更対象ファイルの特定\n□ 影響範囲の確認（他ファイルとの整合性）\n□ 変更内容の具体化\n```\n\n### 1.2 修正作業\n\n- 1ファイルずつ修正し、都度Todoを更新\n- 関連ファイルの整合性を意識\n- 新規ファイル追加時はgit追跡対象か確認\n\n---\n\n## Phase 2: 全体レビュー\n\n修正完了後、以下の観点で全体をレビューする。\n\n### 2.1 レビュー観点\n\n| 観点 | チェック内容 |\n|------|-------------|\n| **整合性 (Consistency)** | 用語・形式・命名規則が統一されているか |\n| **完全性 (Completeness)** | 必要な情報が全て記載されているか、抜け漏れはないか |\n| **正確性 (Correctness)** | 論理的に正しいか、矛盾がないか |\n| **統合性 (Integration)** | 他ドキュメントとの連携が正しいか |\n\n### 2.2 整合性チェック項目\n\n```\n【形式】\n□ 見出しレベルが統一されているか（### Phase X 等）\n□ テーブル形式が統一されているか\n□ コードブロックの言語指定が適切か\n\n【用語】\n□ 同じ概念に同じ用語を使用しているか\n□ 略称と正式名称の使い分けが一貫しているか\n\n【スキーマ・データ】\n□ JSONスキーマとドキュメント例が一致しているか\n□ 列挙値（enum）が全箇所で一致しているか\n□ 必須/任意フィールドの記載が正確か\n```\n\n### 2.3 完全性チェック項目\n\n```\n【ドキュメント構造】\n□ 冒頭の概要説明がフェーズ構成と一致しているか\n□ 全フェーズが説明されているか\n□ 疑似コードがある場合、本文と一致しているか\n\n【関連定義】\n□ 参照される関数/ツールが定義されているか\n□ エラーハンドリングが網羅されているか\n□ エッジケースが考慮されているか\n```\n\n### 2.4 正確性チェック項目\n\n```\n【論理整合性】\n□ フェーズ番号が順序通りか（0, 0.5, 1, 2, 2.5, 3...）\n□ 条件分岐が矛盾していないか\n□ 前提条件と実行内容が整合しているか\n\n【技術的正確性】\n□ ツール名・関数名が正確か\n□ ファイルパスが正確か\n□ 設定値が有効か\n```\n\n### 2.5 統合性チェック項目\n\n```\n【クロスリファレンス】\n□ 参照先ドキュメントが存在するか\n□ 参照元と参照先で情報が一致しているか\n□ バージョン/変更履歴が更新されているか\n\n【ワークフロー連携】\n□ 前工程・後工程との接続が正しいか\n□ 共有データ形式が一致しているか\n```\n\n### 2.6 レビュー結果出力形式\n\n```markdown\n## レビュー結果\n\n### 発見した問題\n\n| 重要度 | 場所 | 問題 | 修正案 |\n|--------|------|------|--------|\n| 🔴 高 | `file.md` L123 | [問題の説明] | [修正方法] |\n| 🟡 中 | `file.md` L456 | [問題の説明] | [修正方法] |\n| 🟢 低 | `file.md` L789 | [問題の説明] | [修正方法] |\n\n### 良好な点 ✅\n\n| 項目 | 状態 |\n|------|------|\n| [チェック項目] | ✅ [状態説明] |\n\n### 判定\n\n- 問題あり → 修正してください\n- 問題なし → コミット可能です\n```\n\n---\n\n## Phase 3: 修正\n\n### 3.1 優先度に基づく修正\n\n| 重要度 | アクション |\n|--------|-----------|\n| 🔴 高 (Critical) | **必須修正** - 機能に影響、または重大な矛盾 |\n| 🟡 中 (Major) | **修正推奨** - 整合性・完全性の問題 |\n| 🟢 低 (Minor) | **任意修正** - 軽微な改善点 |\n\n### 3.2 修正後の確認\n\n```\n□ 指摘された全ての🔴高を修正したか\n□ 修正により新たな不整合が発生していないか\n□ 関連ファイルも更新したか\n```\n\n### 3.3 Phase 2 へ戻る\n\n修正完了後、再度 Phase 2（全体レビュー）を実施。\n問題がなくなるまで繰り返す。\n\n---\n\n## Phase 4: コミット\n\n### 4.1 コミット前チェック\n\n```\n□ 全てのレビュー指摘が解消されている\n□ git status で変更ファイルを確認\n□ 新規ファイルがある場合、git add 対象か確認\n□ .gitignore 対象のファイルを誤ってコミットしていないか\n```\n\n### 4.2 コミットメッセージ形式\n\n```\nfeat(opencode): [変更の要約]\n\n- [変更点1]\n- [変更点2]\n- [変更点3]\n```\n\n---\n\n## 反復回数の目安\n\n| 修正規模 | 想定反復回数 |\n|---------|-------------|\n| 単一ファイル軽微修正 | 1-2回 |\n| 複数ファイル修正 | 2-3回 |\n| 新機能追加 | 3-5回 |\n| 大規模リファクタリング | 5回以上 |\n\n> **注意**: 5回を超えても問題が解消しない場合、修正方針自体を見直すこと。\n\n---\n\n## アンチパターン\n\n| ❌ やってはいけない | ✅ 正しい方法 |\n|-------------------|-------------|\n| レビューなしでコミット | 必ず全体レビューを実施 |\n| 🔴高を残したままコミット | 全ての🔴高を解消してからコミット |\n| 修正のたびに部分レビュー | 修正後は必ず**全体**レビュー |\n| 問題を先送り（TODO化） | その場で修正を完了 |\n| レビュー観点の省略 | 4観点（整合性/完全性/正確性/統合性）全てを確認 |\n\n---\n\n## 使用例\n\n### ユーザーからの依頼\n\n```\nユーザー: 承認ゲートをワークフローに追加して\n```\n\n### Sisyphusの対応\n\n```\n1. [Phase 1] 修正実施\n   - req-workflow.md に承認ゲート追加\n   - basic-design-workflow.md に承認ゲート追加\n   - detailed-design-workflow.md に承認ゲート追加\n\n2. [Phase 2] 全体レビュー\n   → 問題発見: Phase見出しが不統一（##と###混在）\n\n3. [Phase 3] 修正\n   - 見出しを### に統一\n\n4. [Phase 2] 再レビュー\n   → 問題発見: 疑似コードに承認ゲートが反映されていない\n\n5. [Phase 3] 修正\n   - 疑似コードを更新\n\n6. [Phase 2] 再レビュー\n   → 問題なし ✅\n\n7. [Phase 4] コミット\n```\n\n---\n\n## Sisyphusへの指示\n\n```python\ndef opencode_self_improvement(request):\n    \"\"\"OpenCode自己改善ワークフロー\"\"\"\n    \n    # Phase 1: 修正実施\n    create_todo_list(request)\n    for todo in todos:\n        implement_change(todo)\n        mark_completed(todo)\n    \n    # Phase 2-3: レビュー・修正ループ\n    max_iterations = 5\n    for i in range(max_iterations):\n        # Phase 2: 全体レビュー\n        issues = full_review(\n            aspects=[\"consistency\", \"completeness\", \"correctness\", \"integration\"]\n        )\n        \n        if not issues:\n            break  # 問題なし → Phase 4へ\n        \n        # Phase 3: 修正\n        for issue in issues:\n            fix_issue(issue)\n        \n        # 再度 Phase 2 へ\n    \n    # Phase 4: コミット\n    if not issues:\n        git_add_and_commit()\n    else:\n        escalate_to_user(\"5回の反復後も問題が残っています。修正方針を見直してください。\")\n```\n\n---\n\n## 関連ドキュメント\n\n- [README](./../README.md) - OpenCode全体概要\n- [container-use-guide](./container-use-guide.md) - コンテナ環境ガイド\n"},"lastSynced":"2026-03-08T02:02:49.032Z","agentAnalysis":{"suitability":{"en":"Ideal for AI Agents like Claude, AutoGPT, and LangChain that require rigorous quality assurance for OpenCode documentation and settings through iterative review processes.","zh":"适用于 Claude、AutoGPT 和 LangChain 等需要为 OpenCode 文档和设置提供严格质量保证的 AI Agents，通过迭代审查过程。","ja":"Claude、AutoGPT、LangChain などの、OpenCode ドキュメントと設定の徹底的な品質保証が必要な AI エージェントに適しています。反復的なレビュー プロセスを通じて。","ko":"Claude, AutoGPT, LangChain 등의 OpenCode 문서 및 설정에 대한 엄격한 품질 보증이 필요한 AI 에이전트에게 적합합니다. 반복적 리뷰 프로세스를 통해 제공합니다.","es":"Ideal para agentes de IA como Claude, AutoGPT y LangChain que requieren un control de calidad riguroso para la documentación y la configuración de OpenCode a través de procesos de revisión iterativos.","fr":"Idéal pour les agents IA comme Claude, AutoGPT et LangChain qui nécessitent une assurance qualité rigoureuse pour la documentation et les paramètres OpenCode via des processus de révision itératifs.","de":"Ideal für KI-Agenten wie Claude, AutoGPT und LangChain, die eine strenge Qualitätssicherung für OpenCode-Dokumentation und -Einstellungen durch iterative Überprüfungsprozesse erfordern.","pt":"Ideal para Agentes de IA como Claude, AutoGPT e LangChain que requerem garantia de qualidade rigorosa para documentação e configurações OpenCode por meio de processos de revisão iterativos.","ru":"Идеально подходит для агентов ИИ, таких как Claude, AutoGPT и LangChain, которые требуют тщательного обеспечения качества документации и настроек OpenCode посредством итеративных процессов проверки.","ar":"مثالي لعميل الذكاء الاصطناعي مثل Claude و AutoGPT و LangChain التي تتطلب ضمان جودة صارم لوثائق OpenCode والإعدادات من خلال عمليات مراجعة متكررة."},"recommendation":{"en":"Empowers agents to ensure high-quality OpenCode repositories by implementing a repeatable review process for files such as `.claude/commands/*.md`, `.claude/skills/*.md`, and `.opencode/*.json`, enhancing overall code reliability and maintainability.","zh":"使得代理能够通过为 `.claude/commands/*.md`、`.claude/skills/*.md` 和 `.opencode/*.json` 等文件实现可重复的审查过程，确保 OpenCode 仓库的高质量，从而提高代码的可靠性和可维护性。","ja":"エージェントが `.claude/commands/*.md`、`.claude/skills/*.md`、`.opencode/*.json` などのファイルに対して反復可能なレビュー プロセスを実装することで、OpenCode リポジトリの品質を高め、全体的なコードの信頼性と保守性を向上させることができます。","ko":"에이전트가 `.claude/commands/*.md`, `.claude/skills/*.md`, `.opencode/*.json` 등의 파일에 대해 반복 가능한 리뷰 프로세스를 구현함으로써 OpenCode 리포지토리의 높은 품질을 보장하고, 전체적인 코드의 신뢰성과 유지보수성을 향상시킵니다.","es":"Permite a los agentes asegurar repositorios OpenCode de alta calidad implementando un proceso de revisión repetible para archivos como `.claude/commands/*.md`, `.claude/skills/*.md` y `.opencode/*.json`, lo que mejora la confiabilidad y mantenibilidad general del código.","fr":"Permet aux agents de garantir des référentiels OpenCode de haute qualité en mettant en œuvre un processus de révision répétible pour des fichiers tels que `.claude/commands/*.md`, `.claude/skills/*.md` et `.opencode/*.json`, améliorant ainsi la fiabilité et la maintenabilité globales du code.","de":"Ermöglicht es Agenten, OpenCode-Repositorys mit hoher Qualität sicherzustellen, indem sie einen wiederholbaren Überprüfungsprozess für Dateien wie `.claude/commands/*.md`, `.claude/skills/*.md` und `.opencode/*.json` implementieren, wodurch die Gesamtsicherheit und Wartbarkeit des Codes verbessert wird.","pt":"Habilita os agentes a garantir repositórios OpenCode de alta qualidade implementando um processo de revisão repetível para arquivos como `.claude/commands/*.md`, `.claude/skills/*.md` e `.opencode/*.json`, melhorando a confiabilidade geral do código e a manutenibilidade.","ru":"Наделяет агентов возможностью обеспечивать репозитории OpenCode высокого качества путем реализации повторяемого процесса проверки для файлов, таких как `.claude/commands/*.md`, `.claude/skills/*.md` и `.opencode/*.json`, повышая общую надежность и поддерживаемость кода.","ar":"تمكين الوكلاء من ضمان مستودعات OpenCode عالية الجودة من خلال تنفيذ عملية مراجعة قابلة للتكرار للملفات مثل `.claude/commands/*.md` و `.claude/skills/*.md` و `.opencode/*.json`، مما يعزز موثوقية الكود بشكل عام وسهولة صيانته."},"useCases":{"en":["Automating quality checks for OpenCode documentation","Streamlining the review process for agent definitions and commands","Ensuring consistency across repository settings and README files"],"zh":["自动化 OpenCode 文档的质量检查","简化代理定义和命令的审查过程","确保仓库设置和 README 文件的一致性"],"ja":["OpenCode ドキュメントの品質チェックの自動化","エージェント定義とコマンドのレビュー プロセスの合理化","リポジトリ設定と README ファイルの整合性の確保"],"ko":["OpenCode 문서의 품질 검사 자동화","에이전트 정의 및 명령어의 리뷰 프로세스简化","리포지토리 설정 및 README 파일의 일관성 보장"],"es":["Automatizar controles de calidad para la documentación de OpenCode","Optimizar el proceso de revisión para definiciones y comandos de agentes","Garantizar la coherencia en todo el repositorio de ajustes y archivos README"],"fr":["Automatiser les contrôles de qualité pour la documentation OpenCode","Optimiser le processus de révision pour les définitions et les commandes d''agent","Assurer la cohérence dans tout le référentiel de paramètres et les fichiers README"],"de":["Automatisieren von Qualitätskontrollen für OpenCode-Dokumentation","Optimieren des Überprüfungsprozesses für Agentendefinitionen und -befehle","Sicherstellen der Konsistenz in allen Repository-Einstellungen und README-Dateien"],"pt":["Automatizar verificações de qualidade para documentação OpenCode","Racionalizar o processo de revisão para definições e comandos de agentes","Garantir consistência em configurações de repositório e arquivos README"],"ru":["Автоматизировать проверки качества для документации OpenCode","Упростить процесс проверки для определений и команд агентов","Обеспечить согласованность настроек репозитория и файлов README"],"ar":["الاستفادة من عمليات التأكد الآلية لجودة وثائق OpenCode","تبسيط عملية المراجعة لتعريفات وأوامر الوكلاء","ضمان الاتساق عبر إعدادات المستودع وملفات README"]},"limitations":{"en":["Requires access to OpenCode repositories","Limited to files within the `.opencode/` directory and specified file formats"],"zh":["需要访问 OpenCode 仓库","仅限于 `.opencode/` 目录内的文件和指定的文件格式"],"ja":["OpenCode リポジトリへのアクセスが必要","`.opencode/` ディレクトリ内のファイルと指定されたファイル形式のみに対応"],"ko":["OpenCode 리포지토리 접근이 필요함","`.opencode/` 디렉토리 내의 파일 및 지정된 파일 형식에만 제한됨"],"es":["Requiere acceso a los repositorios de OpenCode","Limitado a archivos dentro del directorio `.opencode/` y formatos de archivo especificados"],"fr":["Nécessite un accès aux référentiels OpenCode","Limité aux fichiers dans le répertoire `.opencode/` et aux formats de fichiers spécifiés"],"de":["Benötigt Zugriff auf OpenCode-Repositorys","Begrenzt auf Dateien im Verzeichnis `.opencode/` und bestimmte Dateiformate"],"pt":["Requer acesso a repositórios OpenCode","Limitado a arquivos dentro do diretório `.opencode/` e formatos de arquivo especificados"],"ru":["Требуется доступ к репозиториям OpenCode","Ограничен файлами внутри директории `.opencode/` и указанными форматами файлов"],"ar":["يتطلب الوصول إلى مستودعات OpenCode","محدود بالملفات داخل الدليل `.opencode/` وتنسيقات الملفات المحددة"]},"version":4},"contentHash":"66f2c4157cf399d5f53f439ec27622841599d246d4469a0456d834e8f2fea8d6","qualityScore":33}');
