INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('takemo101/compose-workflow/iterative-review', 'iterative-review', 'takemo101', 'compose-workflow', 'community', 'iterative-review takemo101 compose-workflow community The iterative-review skill ensures quality assurance for OpenCode documentation and settings by implementing a repeatable review process. This benefits developers working with OpenCode repositories. 迭代审查是一种提高代码质量的方法，通过反复修正和审查来确保问题得到及时解决。 反復レビューは、コード品質を高めるための方法で、修正とレビューを繰り返して問題を迅速に解決します。 반복 리뷰는 코드 품질을 높이는 방법으로, 수정과 리뷰를 반복하여 문제를 빠르게 해결합니다. La revisión iterativa es un proceso de aseguramiento de la calidad para documentos y configuraciones de agentes de IA La révision itérative est un processus de garantie de la qualité pour les documents et les configurations d''outils d''IA Die iterative Überprüfung ist ein Qualitätsicherungsprozess für Dokumente und Konfigurationen von KI-Agents O Iterative-Review é um processo de garantia de qualidade para documentos e configurações de Ferramentas de IA Итеративный обзор - это процесс обеспечения качества документов и конфигураций ИИ Агентов المراجعة المتكررة هي عملية لضمان جودة الوثائق وإعدادات أدوات الذكاء الاصطناعي how to use iterative-review what is iterative-review iterative-review alternative iterative-review vs code review iterative-review install iterative-review setup guide OpenCode quality assurance AI agent workflow optimization iterative-review for developers 迭代审查 AI工具 代码审查 自动化审查 代码质量 可靠性 手动审查 时间和成本的削减 Supports modification of `.opencode/` directory documents and settings Enforces review of command definitions in `.claude/commands/*.md` files Validates skill definitions in `.claude/skills/*.md` files Reviews agent definitions in `.claude/agents/*.md` files Checks configuration files in `.opencode/*.json` and `.opencode/*.yml` formats Verifies README files in `.opencode/README.md` Iterative-review is a quality assurance workflow that improves OpenCode documentation and settings through a cyclical process of modification, review, and revision.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('vocalbridgeai/vocal-bridge-claude-plugin/logs', 'community', 'vocalbridgeai', 'vocal-bridge-claude-plugin', 'vocalbridgeai/vocal-bridge-claude-plugin', 'logs', 0, 0, 33, '2026-03-08T01:57:15.319Z', '2026-03-08T02:02:57.004Z', '42ca1ad69517d6055bb6fb911102107d81797ca12ef47093ab4c59dfdabb3ca7', '{"id":"vocalbridgeai/vocal-bridge-claude-plugin/logs","name":"logs","description":{"en":"The logs skill allows developers to view call logs for voice agents. It provides features like listing recent logs and viewing session details using the vb logs command.","zh":"使用Vocal Bridge查看AI呼叫记录，包括最近的日志和会话详情","ja":"Vocal Bridgeを使用してAIエージェントの通話ログを確認する，最近のログとセッションの詳細を含む","ko":"Vocal Bridge를 사용하여 AI 통화 기록을 확인하십시오. 최근 로그 및 세션 세부 정보 포함","es":"Configura y ve logs de llamadas para agente de voz con Vocal Bridge, utilizando opciones como filtrado por estado y formato de salida JSON","fr":"Configurez et affichez les logs d''appels pour agent vocal avec Vocal Bridge, en utilisant des options telles que le filtrage par état et le format de sortie JSON","de":"Konfigurieren und anzeigen Sie Anruf-Logs für Sprachagenten mit Vocal Bridge, unter Verwendung von Optionen wie Statusfilter und JSON-Ausgabeformat","pt":"Visualize e gerencie logs de chamadas de voz com o CLI do Vocal Bridge. Instale o pacote com pip install --upgrade vocal-bridge.","ru":"Просматривайте и управляйте журналами звонков с помощью CLI Vocal Bridge. Установите пакет с помощью pip install --upgrade vocal-bridge.","ar":"عرض وإدارة سجلات المكالمات الصوتية باستخدام CLI Vocal Bridge. قم بتثبيت الحزمة من خلال pip install --upgrade vocal-bridge."},"seo":{"title":{"en":"logs: Setup Guide for AI Agents | AI Agent Skill","zh":"AI日志设置指南：使用Vocal Bridge查看呼叫记录","ja":"AIエージェントログの設定方法：Vocal Bridgeを使用した通話ログの確認","ko":"AI 로그 설정 가이드: Vocal Bridge를 사용한 통화 기록 확인","es":"Guía de configuración de logs para agente de voz","fr":"Guide de configuration des logs pour agent vocal","de":"Einrichtungsanleitung für Logs von Sprachagenten","pt":"Guia de Configuração de Logs para Agentes de Voz","ru":"Настройка журналов для ИИ Агентов голосовых помощников","ar":"دليل إعداد السجلات لعميل الصوت"},"description":{"en":"Discover how to view call logs for voice agents with our logs skill. Learn to install and use vb logs with JSON output and filtering options.","zh":"了解如何使用Vocal Bridge查看AI呼叫记录，包括最近的日志和会话详情","ja":"Vocal Bridgeを使用してAIエージェントの通話ログを確認する方法，最近のログとセッションの詳細を含む","ko":"Vocal Bridge를 사용하여 AI 통화 기록을 확인하는 방법, 최근 로그 및 세션 세부 정보 포함","es":"Aprende a configurar y ver logs de llamadas para agente de voz con Vocal Bridge, incluyendo opciones de filtrado y formato de salida","fr":"Découvrez comment configurer et afficher les logs d''appels pour agent vocal avec Vocal Bridge, y compris les options de filtrage et de format de sortie","de":"Erfahren Sie, wie Sie Anruf-Logs für Sprachagenten mit Vocal Bridge konfigurieren und anzeigen, einschließlich Filter- und Ausgabeformatoptionen","pt":"Aprenda a visualizar e gerenciar logs de chamadas de voz com o CLI do Vocal Bridge. Instale e configure agora mesmo!","ru":"Узнайте, как просматривать и управлять журналами звонков с помощью CLI Vocal Bridge. Установите и настройте прямо сейчас!","ar":"تعلم كيفية عرض وإدارة سجلات المكالمات الصوتية باستخدام CLI Vocal Bridge. قم بالتثبيت والتهيئة الآن!"},"definition":{"en":"logs is a skill that enables viewing and managing call logs for voice agents using the vocal-bridge CLI tool.","zh":"AI日志是指AI系统的呼叫记录，包括会话详情和日志信息","ja":"AIエージェントログは，AIシステムの通話履歴，セッションの詳細，ログ情報を含む","ko":"AI 로그는 AI 시스템의 통화 기록을 말하며, 세션 세부 정보 및 로그 정보를 포함","es":"Los logs son registros de llamadas para agente de voz que se pueden ver y configurar con Vocal Bridge","fr":"Les logs sont des enregistrements d''appels pour agent vocal qui peuvent être affichés et configurés avec Vocal Bridge","de":"Logs sind Anrufprotokolle für Sprachagenten, die mit Vocal Bridge angezeigt und konfiguriert werden können","pt":"Logs são registros de chamadas de voz que permitem visualizar e gerenciar sessões de voz.","ru":"Журналы - это записи звонков, которые позволяют просматривать и управлять сессиями голосовых помощников.","ar":"السجلات هي سجلات المكالمات الصوتية التي تمكن من عرض وإدارة جلسات الصوت."},"features":{"en":["Lists recent logs using the vb logs command with optional filtering by status","Supports output as JSON with the --json option","Allows viewing session details by providing a UUID (session ID) as an argument","Installs and upgrades using pip with the command pip install --upgrade vocal-bridge","Filters logs by status using options like --status completed","Customizes log output with options like -n 50 for showing 50 logs"],"zh":["使用CLI安装Vocal Bridge","查看最近的日志","根据状态筛选日志（完成、失败、放弃、进行中）","以JSON格式输出日志","查看会话详情"],"ja":["CLIを使用してVocal Bridgeをインストールする","最近のログを表示する","ステータスに基づいてログをフィルタリングする（完了、失敗、放棄、進行中）","JSON形式でログを出力する","セッションの詳細を表示する"],"ko":["CLI를 사용하여 Vocal Bridge를 설치","최근 로그 확인","상태에 따라 로그 필터링（완료, 실패,放棄, 진행 중）","JSON 형식으로 로그 출력","세션 세부 정보 확인"],"es":["Visualización de logs de llamadas recientes","Filtrado por estado (completado, fallido, abandonado, en progreso)","Opción de salida en formato JSON","Configuración de la cantidad de logs a mostrar (hasta 50)","Uso de la CLI de Vocal Bridge para configurar y ver logs"],"fr":["Affichage des logs d''appels récents","Filtrage par état (complété, échoué, abandonné, en cours)","Option de sortie au format JSON","Configuration du nombre de logs à afficher (jusqu''à 50)","Utilisation de la CLI de Vocal Bridge pour configurer et afficher les logs"],"de":["Anzeige von Anruf-Logs","Filtern nach Status (abgeschlossen, fehlgeschlagen, abgebrochen, in Bearbeitung)","Ausgabemöglichkeit im JSON-Format","Konfiguration der Anzahl der anzuzeigenden Logs (bis zu 50)","Verwendung der Vocal Bridge-CLI zum Konfigurieren und Anzeigen von Logs"],"pt":["Listar logs recentes com o comando vb logs","Filtrar logs por status com a opção --status","Saída em formato JSON com a opção --json","Visualizar detalhes de sessão com o comando vb logs <uuid>","Instalar e configurar o CLI do Vocal Bridge"],"ru":["Просматривать недавние журналы с помощью команды vb logs","Фильтровать журналы по статусу с помощью опции --status","Выводить в формате JSON с помощью опции --json","Просматривать детали сессии с помощью команды vb logs <uuid>","Установить и настроить CLI Vocal Bridge"],"ar":["عرض السجلات الأخيرة باستخدام الأمر vb logs","تصفية السجلات حسب الحالة باستخدام الخيار --status","الإخراج في تنسيق JSON باستخدام الخيار --json","عرض تفاصيل الجلسة باستخدام الأمر vb logs <uuid>","تثبيت وتهيئة CLI Vocal Bridge"]},"keywords":{"en":["how to use logs","logs setup guide","logs install","vb logs command","vocal-bridge CLI","JSON output for logs","logs filtering options","viewing session details","what is logs","logs alternative"],"zh":["AI日志","Vocal Bridge","CLI","日志查看","会话详情","JSON输出","AI系统","通话记录"],"ja":["AIエージェントログ","Vocal Bridge","CLI","ログ表示","セッションの詳細","JSON出力","AIシステム","通話履歴"],"ko":["AI 로그","Vocal Bridge","CLI","로그 확인","세션 세부 정보","JSON 출력","AI 시스템","통화 기록"],"es":["logs de agente de voz","configuración de logs","Vocal Bridge","CLI de Vocal Bridge","filtrado de logs","formato de salida JSON","agente de voz","herramientas de AI","desarrollo de agente de voz"],"fr":["logs d''agent vocal","configuration des logs","Vocal Bridge","CLI de Vocal Bridge","filtrage des logs","format de sortie JSON","agent vocal","outils d''IA","développement d''agent vocal"],"de":["Anruf-Logs","Konfiguration von Logs","Vocal Bridge","Vocal Bridge-CLI","Filtern von Logs","Ausgabeformat JSON","Sprachagent","AI-Tools","Entwicklung von Sprachagenten"],"pt":["logs de chamadas de voz","CLI do Vocal Bridge","pip install vocal-bridge","vb logs","visualizar logs","gerenciar logs","filtar logs","saída em JSON"],"ru":["журналы звонков","CLI Vocal Bridge","pip install vocal-bridge","vb logs","просматривать журналы","управлять журналами","фильтровать журналы","вывод в формате JSON"],"ar":["سجلات المكالمات الصوتية","CLI Vocal Bridge","pip install vocal-bridge","vb logs","عرض السجلات","إدارة السجلات","تصفية السجلات","الإخراج في تنسيق JSON"]}},"owner":"vocalbridgeai","repo":"vocal-bridge-claude-plugin","repoPath":"vocalbridgeai/vocal-bridge-claude-plugin","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.319Z","topics":[],"category":"community","skillMd":{"name":"logs","description":"View call logs for the Vocal Bridge voice agent. Can list recent calls or show details of a specific session including transcript.","bodyPreview":"View call logs for the voice agent.\n\nFirst ensure CLI is installed:\n\n```bash\npip install --upgrade vocal-bridge\n```\n\n## List Recent Logs\n\nIf $ARGUMENTS is empty or contains options, list recent logs:\n\n```bash\nvb logs $ARGUMENTS\n```\n\nCommon options:\n- `-n 50` - Show 50 logs (default 20)\n- `--status completed` - Filter by status (completed/failed/abandoned/in_progress)\n- `--json` - Output as JSON\n\n## View Session Details\n\nIf $ARGUMENTS contains a UUID (session ID), show details:\n\n```bash\nvb logs <","body":"View call logs for the voice agent.\n\nFirst ensure CLI is installed:\n\n```bash\npip install --upgrade vocal-bridge\n```\n\n## List Recent Logs\n\nIf $ARGUMENTS is empty or contains options, list recent logs:\n\n```bash\nvb logs $ARGUMENTS\n```\n\nCommon options:\n- `-n 50` - Show 50 logs (default 20)\n- `--status completed` - Filter by status (completed/failed/abandoned/in_progress)\n- `--json` - Output as JSON\n\n## View Session Details\n\nIf $ARGUMENTS contains a UUID (session ID), show details:\n\n```bash\nvb logs <session_id>\n```\n\nThis shows:\n- Session ID and status\n- Start/end time and duration\n- Message count\n- Caller phone and direction\n- Full transcript\n- Error message (if failed)\n- Recording availability (if available, use `/vocal-bridge:download <session_id>` to download)\n\nUse `--json` flag for machine-readable output.\n"},"lastSynced":"2026-03-08T02:02:57.004Z","agentAnalysis":{"suitability":{"en":"Ideal for Voice Agent Monitoring Agents requiring real-time call log analysis and session diagnostics.","zh":"适用于需要实时通话日志分析和会话诊断的语音代理监控代理。","ja":"リアルタイム通話ログ分析およびセッション診断を必要とするボイスエージェント監視エージェントに最適です。","ko":"실시간 통화 로그 분석 및 세션 진단이 필요한 보이스 에이전트 모니터링 에이전트에 적합합니다.","es":"Ideal para monitores de agentes de voz que requieren análisis de registros de llamadas en tiempo real y diagnósticos de sesión.","fr":"Idéal pour les agents de surveillance vocale nécessitant une analyse de journal d''appels en temps réel et des diagnostics de session.","de":"Ideal für Voice Agent-Überwachungsagenten, die eine Echtzeit-Analyse von Anrufprotokollen und Sitzungsdiagnose erfordern.","pt":"Ideal para Agentes de Monitoramento de Voz que exigem análise de registros de chamadas em tempo real e diagnósticos de sessão.","ru":"Идеально подходит для агентов мониторинга голосовых агентов, требующих анализа журналов вызовов в реальном времени и сессионной диагностики.","ar":"مثالي لعمليات مراقبة الوكيل الصوتي التي تتطلب تحليل سجل المكالمات في الوقت الفعلي وتشخيص الجلسة."},"recommendation":{"en":"Provides direct access to voice agent call logs through the Vocal Bridge CLI, enabling automated log retrieval with status filtering (completed/failed/abandoned/in_progress) and JSON output capabilities. This allows agents to perform comprehensive session analysis and monitoring without manual intervention.","zh":"通过Vocal Bridge CLI提供直接访问语音代理通话日志的功能，实现自动日志检索，支持状态过滤（已完成/失败/放弃/进行中）和JSON输出功能，从而使代理能够在无需手动干预的情况下执行全面会话分析和监控。","ja":"Vocal Bridge CLIを介してボイスエージェントの通話ログに直接アクセスし、自動ログ取得を可能にし、ステータスフィルタリング（完了/失敗/放棄/進行中）とJSON出力機能をサポートすることで、エージェントが手動介入を必要とせずに包括的なセッション分析および監視を実行できるようにします。","ko":"Vocal Bridge CLI를 통해 보이스 에이전트의 통화 기록에 직접 접근하여 자동 로그 검색을 가능하게 하고, 상태 필터링(완료/실패/방임/진행 중) 및 JSON 출력 기능을 지원하여, 에이전트가 수동 개입 없이全面적인 세션 분석 및 모니터링을 수행할 수 있도록 합니다.","es":"Proporciona acceso directo a los registros de llamadas de los agentes de voz a través de la CLI de Vocal Bridge, lo que permite la recuperación automatizada de registros con filtrado de estado (completado/fallido/abandonado/en_progreso) y capacidades de salida JSON. Esto permite a los agentes realizar un análisis y seguimiento de sesiones completos sin intervención manual.","fr":"Fournit un accès direct aux journaux d''appels des agents vocaux via la CLI Vocal Bridge, permettant une récupération automatique des journaux avec un filtrage d''état (complété/échoué/abandonné/en_cours) et des capacités de sortie JSON. Cela permet aux agents d''effectuer une analyse et une surveillance de sessions complètes sans intervention manuelle.","de":"Bietet direkten Zugriff auf die Anrufprotokolle der Voice-Agents über die Vocal Bridge-CLI, wodurch eine automatisierte Protokollabfrage mit Statusfilterung (abgeschlossen/fehlgeschlagen/abgebrochen/laufend) und JSON-Ausgabefähigkeiten ermöglicht wird. Dies ermöglicht es den Agenten, eine umfassende Sitzungsanalyse und -überwachung ohne manuelle Eingriffe durchzuführen.","pt":"Fornece acesso direto aos registros de chamadas do agente de voz por meio da CLI do Vocal Bridge, permitindo a recuperação automatizada de registros com filtragem de status (concluído/falha/abandonado/em_andamento) e capacidades de saída JSON. Isso permite que os agentes realizem uma análise de sessão abrangente e monitoramento sem intervenção manual.","ru":"Предоставляет прямой доступ к журналам вызовов голосовых агентов через CLI Vocal Bridge, что позволяет автоматизировать извлечение журналов с фильтрацией статуса (завершено/неудачно/брошено/в_процессе) и возможности вывода JSON. Это позволяет агентам выполнять всесторонний анализ сессии и мониторинг без ручного вмешательства.","ar":"يقدم وصولاً مباشراً إلى سجلات مكالمات الوكيل الصوتي من خلال واجهة سطر الأوامر CLI لجسر الصوت Vocal Bridge، وتمكين استرجاع السجلات التلقائي مع تصفية الحالة (مكتمل/فاشل/مترك/قيد التقدم) وإمكانيات الإخراج JSON. هذا يسمح للوكلاء بإجراء تحليل جلسة شامل ومراقبة بدون تدخل يدوي."},"useCases":{"en":["Monitoring voice agent performance metrics","Debugging failed call sessions","Analyzing call completion patterns","Exporting log data in JSON format for further processing"],"zh":["监控语音代理性能指标","调试失败的通话会话","分析通话完成模式","以JSON格式导出日志数据以进行进一步处理"],"ja":["ボイスエージェントのパフォーマンスメトリックを監視する","失敗した通話セッションをデバッグする","通話完了パターンを分析する","JSON形式でログデータをエクスポートしてさらに処理する"],"ko":["보이스 에이전트 성능 지표 모니터링","실패한 통화 세션 디버깅","통화 완료 패턴 분석","JSON 형식으로 로그 데이터를 내보내기하여 추가 처리"],"es":["Supervisión de métricas de rendimiento de los agentes de voz","Depuración de sesiones de llamadas fallidas","Análisis de patrones de finalización de llamadas","Exportación de datos de registro en formato JSON para un procesamiento posterior"],"fr":["Supervision des métriques de performance des agents vocaux","Débogage des sessions d''appels échouées","Analyse des modèles de fin d''appel","Exportation des données de journal au format JSON pour un traitement ultérieur"],"de":["Überwachung von Leistungsmetriken von Voice-Agents","Fehlerbehebung bei fehlgeschlagenen Anrufsessionen","Analyse von Anrufabschlussmustern","Export von Protokolldaten im JSON-Format für weitere Verarbeitung"],"pt":["Monitoramento de métricas de desempenho do agente de voz","Depuração de sessões de chamadas com falha","Análise de padrões de conclusão de chamadas","Exportação de dados de log em formato JSON para processamento adicional"],"ru":["Мониторинг метрик производительности голосовых агентов","Отладка неудачных сессий вызовов","Анализ законченных шаблонов вызовов","Экспорт данных журнала в формате JSON для дальнейшей обработки"],"ar":["مراقبة معايير أداء وكيل الصوت","تصحيح أخطاء جلسات المكالمات الفاشلة","تحليل أنماط إكمال المكالمات","تصدير بيانات السجل بصيغة JSON لمعالجة إضافية"]},"limitations":{"en":["Requires Vocal Bridge CLI installation","Dependent on voice agent platform availability","Limited to session UUID-based queries for detailed views"],"zh":["需要安装Vocal Bridge CLI","依赖于语音代理平台的可用性","仅限于基于会话UUID的查询以获取详细视图"],"ja":["Vocal Bridge CLIのインストールが必要","ボイスエージェントプラットフォームの可用性に依存する","詳細ビューを取得するためのクエリはセッションUUIDに基づくものに限定される"],"ko":["Vocal Bridge CLI 설치가 필요함","보이스 에이전트 플랫폼의 가용성에 의존함","세부적인 뷰를 얻기 위한 쿼리는 세션 UUID 기반으로 제한됨"],"es":["Requiere la instalación de la CLI de Vocal Bridge","Depende de la disponibilidad de la plataforma de agente de voz","Limitado a consultas basadas en UUID de sesión para vistas detalladas"],"fr":["Nécessite l''installation de la CLI Vocal Bridge","Dépend de la disponibilité de la plate-forme d''agent vocal","Limité aux requêtes basées sur l''UUID de session pour les vues détaillées"],"de":["Benötigt die Installation der Vocal Bridge-CLI","Hängt von der Verfügbarkeit der Voice-Agent-Plattform ab","Begrenzt auf UUID-basierte Abfragen für detaillierte Ansichten"],"pt":["Exige instalação da CLI do Vocal Bridge","Dependente da disponibilidade da plataforma do agente de voz","Limitado a consultas baseadas em UUID de sessão para visualizações detalhadas"],"ru":["Требует установки CLI Vocal Bridge","Зависит от доступности платформы голосовых агентов","Ограничен запросами на основе UUID сессии для подробных представлений"],"ar":["يتطلب تثبيت واجهة سطر الأوامر CLI لجسر الصوت","يعتمد على توافر منصة وكيل الصوت","محدود بالاستفسارات المعتمدة على UUID للجلسة من أجل العروض المفصلة"]},"version":4},"contentHash":"42ca1ad69517d6055bb6fb911102107d81797ca12ef47093ab4c59dfdabb3ca7","qualityScore":33}');
