INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('vocalbridgeai/vocal-bridge-claude-plugin/logs', 'logs', 'vocalbridgeai', 'vocal-bridge-claude-plugin', 'community', 'logs vocalbridgeai vocal-bridge-claude-plugin community The logs skill allows developers to view call logs for voice agents. It provides features like listing recent logs and viewing session details using the vb logs command. 使用Vocal Bridge查看AI呼叫记录，包括最近的日志和会话详情 Vocal Bridgeを使用してAIエージェントの通話ログを確認する，最近のログとセッションの詳細を含む Vocal Bridge를 사용하여 AI 통화 기록을 확인하십시오. 최근 로그 및 세션 세부 정보 포함 Configura y ve logs de llamadas para agente de voz con Vocal Bridge, utilizando opciones como filtrado por estado y formato de salida JSON Configurez et affichez les logs d''appels pour agent vocal avec Vocal Bridge, en utilisant des options telles que le filtrage par état et le format de sortie JSON Konfigurieren und anzeigen Sie Anruf-Logs für Sprachagenten mit Vocal Bridge, unter Verwendung von Optionen wie Statusfilter und JSON-Ausgabeformat Visualize e gerencie logs de chamadas de voz com o CLI do Vocal Bridge. Instale o pacote com pip install --upgrade vocal-bridge. Просматривайте и управляйте журналами звонков с помощью CLI Vocal Bridge. Установите пакет с помощью pip install --upgrade vocal-bridge. عرض وإدارة سجلات المكالمات الصوتية باستخدام CLI Vocal Bridge. قم بتثبيت الحزمة من خلال pip install --upgrade vocal-bridge. how to use logs logs setup guide logs install vb logs command vocal-bridge CLI JSON output for logs logs filtering options viewing session details what is logs logs alternative AI日志 Vocal Bridge CLI 日志查看 会话详情 JSON输出 AI系统 通话记录 Lists recent logs using the vb logs command with optional filtering by status Supports output as JSON with the --json option Allows viewing session details by providing a UUID (session ID) as an argument Installs and upgrades using pip with the command pip install --upgrade vocal-bridge Filters logs by status using options like --status completed Customizes log output with options like -n 50 for showing 50 logs logs is a skill that enables viewing and managing call logs for voice agents using the vocal-bridge CLI tool.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('proyecto26/projectx/nestjs', 'community', 'proyecto26', 'projectx', 'proyecto26/projectx', 'nestjs', 0, 0, 33, '2026-03-08T01:57:15.325Z', '2026-03-08T02:03:01.993Z', 'bf3acb06ea0bad448101612450e23b6f4d04d150fd5069105562ca9af382d06b', '{"id":"proyecto26/projectx/nestjs","name":"nestjs","description":{"en":"NestJS is a framework for building microservices-based applications. It helps developers create scalable and maintainable apps using TypeScript and JavaScript.","zh":"NestJS是一个用于构建可扩展的全栈应用的框架，支持微服务架构","ja":"NestJSは、イベント駆動型アーキテクチャを実現するためのフルスタックアプリケーションフレームワーク","ko":"NestJS는 마이크로サービス 아키텍처를 구축하기 위한 프레임워크로, Temporal 워크플로우를 지원","es":"NestJS es un framework para crear aplicaciones full-stack con microservicios, integrando Temporal y React para una arquitectura de eventos","fr":"NestJS est un framework pour créer des applications full-stack avec des microservices, en intégrant Temporal et React pour une architecture d''événements","de":"NestJS ist ein Framework für die Erstellung von Full-Stack-Anwendungen mit Mikrodiensten, integrierend Temporal und React für eine Ereignisarchitektur","pt":"NestJS é um framework para desenvolver aplicações full-stack com microserviços, incluindo autenticação e gerenciamento de pedidos","ru":"NestJS - это фреймворк для разработки полноценных приложений с микросервисами, включая аутентификацию и управление заказами для ИИ Агентов","ar":"NestJS هو إطار لتطوير التطبيقات الكاملة مع الميكروسيرفس، بما في ذلك المصادقة وإدارة الطلبات"},"seo":{"title":{"en":"NestJS: Microservices Development Setup Guide | AI Agent ...","zh":"NestJS Setup Guide: 构建全栈应用","ja":"NestJSのベストプラクティス: AIエージェントとの統合","ko":"NestJS 개발 가이드: 마이크로サービス 아키텍처","es":"NestJS: Guía de configuración para microservicios","fr":"NestJS: Guide de démarrage pour les microservices","de":"NestJS: Einrichtungsleitfaden für Mikrodienste","pt":"NestJS Microservices Setup Guide","ru":"Настройка микросервисов NestJS для ИИ Агентов","ar":"نظام توجيه NestJS للميكروسيرفس"},"description":{"en":"Unlock the full potential of NestJS for microservices development. Learn how to tame full-stack chaos with Temporal workflows and React wizardry. Get started...","zh":"了解NestJS的技术细节，构建可扩展的全栈应用","ja":"NestJSとAIエージェントを使用して、イベント駆動型アーキテクチャを実現","ko":"NestJS를 사용하여 마이크로サービス 아키텍처를 구축하고, Temporal 워크플로우를 통합","es":"Aprende a crear aplicaciones escalables con NestJS, aprovechando su arquitectura de microservicios y la integración con Temporal","fr":"Découvrez comment créer des applications évolutives avec NestJS, en exploitant son architecture de microservices et l''intégration avec Temporal","de":"Erfahren Sie, wie Sie mit NestJS skalierbare Anwendungen erstellen, indem Sie seine Mikrodienst-Architektur und die Integration mit Temporal nutzen","pt":"Desenvolva aplicações escaláveis com o NestJS e microserviços, incluindo autenticação e gerenciamento de pedidos","ru":"Разработайте масштабируемые приложения с помощью NestJS и микросервисов, включая аутентификацию и управление заказами для ИИ Агентов","ar":"طور تطبيقات قابلة للتوسيع باستخدام NestJS والميكروسيرفس، بما في ذلك المصادقة وإدارة الطلبات"},"definition":{"en":"NestJS is a progressive Node.js framework for building efficient, scalable Node.js server-side applications using TypeScript and JavaScript.","zh":"NestJS是一个用于构建全栈应用的Node.js框架","ja":"NestJSは、フルスタックアプリケーションの構築を支援するNode.jsフレームワーク","ko":"NestJS는 Node.js를 기반으로 하는 프레임워크로, 마이크로サービス 아키텍처를 지원","es":"NestJS es un framework de Node.js para crear aplicaciones con microservicios y arquitectura de eventos","fr":"NestJS est un framework Node.js pour créer des applications avec des microservices et une architecture d''événements","de":"NestJS ist ein Node.js-Framework für die Erstellung von Anwendungen mit Mikrodiensten und Ereignisarchitektur","pt":"NestJS é um framework Node.js para desenvolver aplicações full-stack com microserviços","ru":"NestJS - это фреймворк Node.js для разработки полноценных приложений с микросервисами","ar":"NestJS هو إطار Node.js لتطوير التطبيقات الكاملة مع الميكروسيرفس"},"features":{"en":["Uses NestJS for microservices development with multiple modules","Integrates with Temporal for event-driven architecture","Supports authentication using JWT and Passport","Includes shared modules in packages/core for code reuse","Allows creation of new modules using feature/feature.module.ts","Enables order management and product catalog integration"],"zh":["支持微服务架构","集成Temporal工作流","使用React构建前端","支持JWT和Passport认证","提供可扩展的模块化结构"],"ja":["マイクロサービスアーキテクチャをサポート","Temporalワークフローを統合","Reactを使用してフロントエンドを構築","JWTとPassport認証をサポート","拡張可能なモジュール構造を提供"],"ko":["마이크로서비스 아키텍처를 지원","Temporal 워크플로우를 통합","React를 사용하여 프론트엔드를 구축","JWT와 Passport 인증을 지원","확장 가능한 모듈 구조를 제공"],"es":["Arquitectura de microservicios con NestJS","Integración con Temporal para la gestión de flujos de trabajo","Uso de React para la creación de interfaces de usuario","Autenticación con JWT y Passport","Gestión de pedidos y catálogo de productos"],"fr":["Architecture de microservices avec NestJS","Intégration avec Temporal pour la gestion de flux de travail","Utilisation de React pour la création d''interfaces utilisateur","Authentification avec JWT et Passport","Gestion de commandes et catalogue de produits"],"de":["Mikrodienst-Architektur mit NestJS","Integration mit Temporal für die Workflow-Verwaltung","Verwendung von React für die Erstellung von Benutzeroberflächen","Authentifizierung mit JWT und Passport","Bestell- und Produktkatalogverwaltung"],"pt":["Desenvolvimento de microserviços com NestJS","Autenticação com JWT e Passport","Gerenciamento de pedidos com Temporal","Criação de módulos compartilhados com packages/core","Integração com React para interfaces de usuário"],"ru":["Разработка микросервисов с помощью NestJS","Аутентификация с помощью JWT и Passport","Управление заказами с помощью Temporal","Создание общих модулей с помощью packages/core","Интеграция с React для интерфейсов пользователя"],"ar":["تطوير الميكروسيرفس باستخدام NestJS","المصادقة باستخدام JWT و Passport","إدارة الطلبات مع Temporal","إنشاء وحدات مشتركة مع packages/core","التكامل مع React ل_interfaces المستخدم"]},"keywords":{"en":["how to use nestjs","nestjs microservices development","nestjs vs express","nestjs install","nestjs setup guide","nestjs temporal integration","what is nestjs","nestjs alternative","nestjs tutorial"],"zh":["NestJS","全栈应用","微服务架构","Temporal工作流","React","JWT","Passport","Node.js"],"ja":["NestJS","フルスタックアプリケーション","マイクロサービスアーキテクチャ","Temporalワークフロー","React","JWT","Passport","Node.js","AIエージェント"],"ko":["NestJS","마이크로서비스 아키텍처","Temporal 워크플로우","React","JWT","Passport","Node.js","AI 도구","마이크로サービス 개발"],"es":["NestJS","microservicios","Temporal","React","autenticación","gestión de pedidos","catálogo de productos","arquitectura de eventos","desarrollo de aplicaciones full-stack"],"fr":["NestJS","microservices","Temporal","React","authentification","gestion de commandes","catalogue de produits","architecture d''événements","développement d''applications full-stack"],"de":["NestJS","Mikrodienste","Temporal","React","Authentifizierung","Bestellverwaltung","Produktkatalog","Ereignisarchitektur","Entwicklung von Full-Stack-Anwendungen"],"pt":["NestJS microserviços","desenvolvimento de aplicações full-stack","autenticação com JWT","gerenciamento de pedidos com Temporal","criação de módulos compartilhados","integração com React","desenvolvimento de aplicações escaláveis"],"ru":["NestJS микросервисы","разработка полноценных приложений","аутентификация с помощью JWT","управление заказами с помощью Temporal","создание общих модулей","интеграция с React","разработка масштабируемых приложений"],"ar":["NestJS الميكروسيرفس","تطوير التطبيقات الكاملة","المصادقة باستخدام JWT","إدارة الطلبات مع Temporal","إنشاء وحدات مشتركة","التكامل مع React","تطوير التطبيقات القابلة للتوسيع"]}},"owner":"proyecto26","repo":"projectx","repoPath":"proyecto26/projectx","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.325Z","topics":[],"category":"community","skillMd":{"name":"nestjs","description":"NestJS microservices development. Use when creating controllers, services, modules, guards, interceptors, or working with NestJS patterns in auth, order, or product services.","bodyPreview":"# NestJS Microservices Development\n\n## Project Structure\n\nThis project uses NestJS for three microservices:\n- `apps/auth` - Authentication (JWT, Passport)\n- `apps/order` - Order management (integrates with Temporal)\n- `apps/product` - Product catalog\n\nShared modules are in `packages/core`.\n\n## Creating a New Module\n\n### 1. Create Module File\n\n```typescript\n// feature/feature.module.ts\nimport { Module } from ''@nestjs/common'';\nimport { FeatureController } from ''./feature.controller'';\nimport { Feat","body":"# NestJS Microservices Development\n\n## Project Structure\n\nThis project uses NestJS for three microservices:\n- `apps/auth` - Authentication (JWT, Passport)\n- `apps/order` - Order management (integrates with Temporal)\n- `apps/product` - Product catalog\n\nShared modules are in `packages/core`.\n\n## Creating a New Module\n\n### 1. Create Module File\n\n```typescript\n// feature/feature.module.ts\nimport { Module } from ''@nestjs/common'';\nimport { FeatureController } from ''./feature.controller'';\nimport { FeatureService } from ''./feature.service'';\n\n@Module({\n  controllers: [FeatureController],\n  providers: [FeatureService],\n  exports: [FeatureService],\n})\nexport class FeatureModule {}\n```\n\n### 2. Create Service with Repository Pattern\n\n```typescript\n// feature/feature.service.ts\nimport { Injectable } from ''@nestjs/common'';\nimport { PrismaService } from ''@projectx/db'';\n\n@Injectable()\nexport class FeatureService {\n  constructor(private readonly prisma: PrismaService) {}\n\n  async findAll() {\n    return this.prisma.feature.findMany();\n  }\n\n  async findOne(id: string) {\n    return this.prisma.feature.findUnique({ where: { id } });\n  }\n\n  async create(data: CreateFeatureDto) {\n    return this.prisma.feature.create({ data });\n  }\n}\n```\n\n### 3. Create Controller with Swagger\n\n```typescript\n// feature/feature.controller.ts\nimport { Controller, Get, Post, Body, Param } from ''@nestjs/common'';\nimport { ApiTags, ApiOperation, ApiResponse } from ''@nestjs/swagger'';\nimport { FeatureService } from ''./feature.service'';\n\n@ApiTags(''features'')\n@Controller(''features'')\nexport class FeatureController {\n  constructor(private readonly featureService: FeatureService) {}\n\n  @Get()\n  @ApiOperation({ summary: ''Get all features'' })\n  @ApiResponse({ status: 200, description: ''Returns all features'' })\n  findAll() {\n    return this.featureService.findAll();\n  }\n\n  @Get('':id'')\n  @ApiOperation({ summary: ''Get feature by ID'' })\n  findOne(@Param(''id'') id: string) {\n    return this.featureService.findOne(id);\n  }\n\n  @Post()\n  @ApiOperation({ summary: ''Create a feature'' })\n  create(@Body() createFeatureDto: CreateFeatureDto) {\n    return this.featureService.create(createFeatureDto);\n  }\n}\n```\n\n## DTOs with Validation\n\n```typescript\n// feature/dto/create-feature.dto.ts\nimport { IsString, IsNotEmpty, IsOptional } from ''class-validator'';\nimport { ApiProperty, ApiPropertyOptional } from ''@nestjs/swagger'';\n\nexport class CreateFeatureDto {\n  @ApiProperty({ description: ''Feature name'' })\n  @IsString()\n  @IsNotEmpty()\n  name: string;\n\n  @ApiPropertyOptional({ description: ''Feature description'' })\n  @IsString()\n  @IsOptional()\n  description?: string;\n}\n```\n\n## Authentication Guards\n\nUse guards from `@projectx/core`:\n\n```typescript\nimport { UseGuards } from ''@nestjs/common'';\nimport { JwtAuthGuard } from ''@projectx/core'';\n\n@Controller(''protected'')\n@UseGuards(JwtAuthGuard)\nexport class ProtectedController {\n  // All routes require authentication\n}\n```\n\n## Exception Handling\n\n```typescript\nimport { NotFoundException, BadRequestException } from ''@nestjs/common'';\n\n// In service\nasync findOne(id: string) {\n  const item = await this.prisma.feature.findUnique({ where: { id } });\n  if (!item) {\n    throw new NotFoundException(`Feature with ID ${id} not found`);\n  }\n  return item;\n}\n```\n\n## Testing Services\n\n```typescript\nimport { Test, TestingModule } from ''@nestjs/testing'';\nimport { FeatureService } from ''./feature.service'';\nimport { PrismaService } from ''@projectx/db'';\n\ndescribe(''FeatureService'', () => {\n  let service: FeatureService;\n  let prisma: PrismaService;\n\n  beforeEach(async () => {\n    const module: TestingModule = await Test.createTestingModule({\n      providers: [\n        FeatureService,\n        {\n          provide: PrismaService,\n          useValue: {\n            feature: {\n              findMany: jest.fn(),\n              findUnique: jest.fn(),\n              create: jest.fn(),\n            },\n          },\n        },\n      ],\n    }).compile();\n\n    service = module.get<FeatureService>(FeatureService);\n    prisma = module.get<PrismaService>(PrismaService);\n  });\n\n  it(''should be defined'', () => {\n    expect(service).toBeDefined();\n  });\n});\n```\n\n## Running Services\n\n```bash\n# Run specific service\npnpm dev:auth\npnpm dev:order\npnpm dev:product\n\n# Run all services\npnpm dev\n```\n\n## Best Practices\n\n1. **Always use DTOs** for request/response validation\n2. **Document with Swagger** decorators for API documentation\n3. **Use repository pattern** via Prisma services from `@projectx/db`\n4. **Handle errors** with NestJS built-in exceptions\n5. **Write tests** for services and controllers\n6. **Use guards** from `@projectx/core` for authentication\n"},"lastSynced":"2026-03-08T02:03:01.993Z","agentAnalysis":{"suitability":{"en":"Perfect for Microservices Agents needing scalable TypeScript and JavaScript applications.","zh":"适合需要可扩展TypeScript和JavaScript应用程序的微服务代理。","ja":"マイクロサービスエージェントがスケーラブルなTypeScriptとJavaScriptアプリケーションを必要とする場合に最適です。","ko":"마이크로 서비스 에이전트가 확장 가능한 TypeScript와 JavaScript 애플리케이션이 필요한 경우에 적합합니다.","es":"Perfecto para Agentes de Microservicios que necesitan aplicaciones escalables de TypeScript y JavaScript.","fr":"Parfait pour les Agents de Microservices nécessitant des applications TypeScript et JavaScript évolutives.","de":"Perfekt für Microservices-Agents, die skalierbare TypeScript- und JavaScript-Anwendungen benötigen.","pt":"Perfeito para Agentes de Microsserviços que necessitam de aplicações escaláveis TypeScript e JavaScript.","ru":"Идеально подходит для агентов микросервисов, требующих масштабируемых приложений TypeScript и JavaScript.","ar":"مثالي للوكلاء ميكروسيرفيس الذين يحتاجون إلى تطبيقات قابلة للتوسيع من TypeScript و JavaScript."},"recommendation":{"en":"Empowers agents to build maintainable apps using NestJS, leveraging microservices architecture, TypeScript, and JavaScript, with features like JWT authentication and Temporal integration.","zh":"赋予代理构建可维护的应用程序的能力，使用NestJS，利用微服务架构、TypeScript和JavaScript，并具有JWT身份验证和Temporal集成等功能。","ja":"エージェントがメンテナンス可能なアプリケーションを構築できるようにすることで、NestJSを使用し、マイクロサービスアーキテクチャ、TypeScript、JavaScriptを活用し、JWT認証やTemporal統合などの機能を備えています。","ko":"에이전트가 유지 보수 가능한 애플리케이션을 구축할 수 있는 능력을 부여하여 NestJS를 사용하고 마이크로 서비스 아키텍처, TypeScript, JavaScript를 활용하며 JWT 인증 및 Temporal 통합 등의 기능을 제공합니다.","es":"Habilita a los agentes a construir aplicaciones mantenibles utilizando NestJS, aprovechando la arquitectura de microservicios, TypeScript y JavaScript, con características como autenticación JWT y integración con Temporal.","fr":"Permet aux agents de créer des applications maintenables en utilisant NestJS, en exploitant l''architecture de microservices, TypeScript et JavaScript, avec des fonctionnalités comme l''authentification JWT et l''intégration avec Temporal.","de":"Ermöglicht es den Agenten, wartbare Anwendungen mit NestJS zu erstellen, die Mikroservices-Architektur, TypeScript und JavaScript nutzt, mit Funktionen wie JWT-Authentifizierung und Temporal-Integration.","pt":"Habilita os agentes a construir aplicativos mantidos usando NestJS, aproveitando a arquitetura de microsserviços, TypeScript e JavaScript, com recursos como autenticação JWT e integração Temporal.","ru":"Позволяет агентам создавать поддерживаемые приложения, используя NestJS, используя архитектуру микросервисов, TypeScript и JavaScript, с функциями, такими как аутентификация JWT и интеграция Temporal.","ar":"يمنح الوكلاء بناء تطبيقات قابلة للصيانة باستخدام NestJS، واستخدام هندسة ميكروسيرفيس، وTypeScript وJavaScript، مع ميزات مثل المصادقة JWT وتكامل Temporal."},"useCases":{"en":["Developing scalable authentication microservices with Passport","Creating modular product catalogs with shared core modules","Integrating order management with Temporal for workflow automation"],"zh":["使用Passport开发可扩展的身份验证微服务","使用共享核心模块创建模块化产品目录","使用Temporal进行工作流自动化的订单管理集成"],"ja":["Passportを使用してスケーラブルな認証マイクロサービスを開発する","共有コアモジュールを使用してモジュール化された製品カタログを作成する","Temporalを使用したワークフロー自動化のオーダー管理統合"],"ko":["Passport를 사용하여 확장 가능한 인증 마이크로 서비스를 개발하는 것","공유核心모듈을 사용하여 모듈화된 제품 카탈로그를 생성하는 것","Temporal를 사용한 워크플로 자동화의 주문 관리 통합"],"es":["Desarrollar microservicios de autenticación escalables con Passport","Crear catálogos de productos modulares con módulos core compartidos","Integrar la gestión de pedidos con Temporal para la automatización de flujos de trabajo"],"fr":["Développer des microservices d''authentification évolutifs avec Passport","Créer des catalogues de produits modulaires avec des modules core partagés","Intégrer la gestion des commandes avec Temporal pour l''automatisation des flux de travail"],"de":["Entwicklung von skalierbaren Authentifizierungsmicrodiensten mit Passport","Erstellen von modularen Produktkatalogen mit gemeinsam genutzten Core-Modulen","Integration der Auftragsverwaltung mit Temporal für die Workflow-Automatisierung"],"pt":["Desenvolver microsserviços de autenticação escaláveis com Passport","Criar catálogos de produtos modulares com módulos core compartilhados","Integrar gerenciamento de pedidos com Temporal para automação de fluxo de trabalho"],"ru":["Разработка масштабируемых микросервисов аутентификации с помощью Passport","Создание модульных каталогов продуктов с общими ядровыми модулями","Интеграция управления заказами с Temporal для автоматизации рабочих процессов"],"ar":["تطوير ميكروسيرفيس موثوقية قابلة للتوسيع مع Passport","إنشاء فهرس منتجات قابل للتعديل مع وحدات أساسية مشتركة","دمج إدارة الطلبات مع Temporal للتحكم التلقائي في سير العمل"]},"limitations":{"en":["Requires TypeScript and JavaScript knowledge","NestJS framework dependency","Microservices architecture complexity"],"zh":["需要TypeScript和JavaScript的知识","NestJS框架依赖","微服务架构复杂性"],"ja":["TypeScriptとJavaScriptの知識が必要","NestJSフレームワーク依存","マイクロサービスアーキテクチャの複雑さ"],"ko":["TypeScript와 JavaScript의 지식이 필요함","NestJS 프레임워크 종속","마이크로 서비스 아키텍처의 복잡성"],"es":["Requiere conocimientos de TypeScript y JavaScript","Dependencia del marco de trabajo NestJS","Complejidad de la arquitectura de microservicios"],"fr":["Nécessite des connaissances en TypeScript et JavaScript","Dépendance du framework NestJS","Complexité de l''architecture de microservices"],"de":["Benötigt Kenntnisse in TypeScript und JavaScript","Abhängigkeit vom NestJS-Framework","Komplexität der Mikroservices-Architektur"],"pt":["Requer conhecimento de TypeScript e JavaScript","Dependência do framework NestJS","Complexidade da arquitetura de microsserviços"],"ru":["Требует знаний TypeScript и JavaScript","Зависимость от фреймворка NestJS","Сложность архитектуры микросервисов"],"ar":["يتطلب معرفة باللغة TypeScript و JavaScript","اعتماد على إطار العمل NestJS","تعقيد هندسة ميكروسيرفيس"]},"version":4},"contentHash":"bf3acb06ea0bad448101612450e23b6f4d04d150fd5069105562ca9af382d06b","qualityScore":33}');
