INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Mahaboob26/NEXUS-TRUSAI/building-streamlit-multipage-apps', 'building-streamlit-multipage-apps', 'Mahaboob26', 'NEXUS-TRUSAI', 'community', 'building-streamlit-multipage-apps Mahaboob26 NEXUS-TRUSAI community The building-streamlit-multipage-apps skill enables developers to create complex Streamlit applications with multiple pages, utilizing Python and FastAPI. It benefits AI agent developers seeking to build transparent and auditable credit scoring systems. Streamlit多页应用构建技术，包括目录结构和主模块配置 Streamlitマルチページアプリの構築方法、ディレクトリ構造とメインモジュールの設定 스트림릿 다중 페이지 앱 빌딩 기술, 디렉토리 구조 및 메인 모듈 구성 Construye aplicaciones Streamlit con varias páginas, utilizando un directorio de páginas y un módulo principal para la navegación. Construisez des applications Streamlit à plusieurs pages en utilisant un répertoire de pages et un module principal pour la navigation. Bauen Sie Streamlit-Apps mit mehreren Seiten, indem Sie ein Seitenverzeichnis und ein Hauptmodul für die Navigation verwenden. Construa aplicativos Streamlit com múltiplas páginas, utilizando estrutura e navegação eficazes Создайте многостраничные приложения Streamlit с помощью ИИ Агентов и технологий Python ابني تطبيقات Streamlit متعددة الصفحات باستخدام هيكلة وتنقل فعالين how to use building-streamlit-multipage-apps building-streamlit-multipage-apps setup guide Streamlit multi-page apps tutorial building-streamlit-multipage-apps vs Streamlit what is building-streamlit-multipage-apps building-streamlit-multipage-apps install building-streamlit-multipage-apps alternative building-streamlit-multipage-apps for AI agents Streamlit app development best practices building-streamlit-multipage-apps documentation Streamlit 多页应用 构建指南 AIエージェント Python Streamlit框架 Utilizes a specific directory structure with an `app_pages/` directory Initializes global state shared across pages using `streamlit_app.py` Supports multiple pages, such as `home.py`, `analytics.py`, and `settings.py` Leverages Python and FastAPI for building advanced credit decisioning systems Features a Random Forest model trained on Indian datasets Includes cryptographic audit logging for enhanced security building-streamlit-multipage-apps is a skill for creating multi-page Streamlit applications with a structured directory layout and navigation.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('speakeasy-api/gram/clickhouse', 'community', 'speakeasy-api', 'gram', 'speakeasy-api/gram', 'clickhouse', 0, 0, 33, '2026-03-08T01:57:15.338Z', '2026-03-08T02:03:21.837Z', '5dd4da9995d77837cbf1564009caa10c80262db2f1fbb3ff0b7bf6caccf9ee89', '{"id":"speakeasy-api/gram/clickhouse","name":"clickhouse","description":{"en":"The ClickHouse skill provides a context layer for products, enabling connections to 1st and 3rd party MCP servers. It utilizes the squirrel query builder for high-performance analytics queries.","zh":"ClickHouse用于高性能分析查询，使用squirrel查询构建器进行动态查询构建，适用于AIエージェント的上下文层","ja":"ClickHouseは高性能分析クエリを実行し、squirrelクエリビルダーを使用して動的なクエリを構築します。AIエージェントのコンテキストレイヤーに最適","ko":"ClickHouse는 고성능 분석 쿼리를 실행하고 squirrel 쿼리 빌더를 사용하여 동적 쿼리를 구성합니다. AI 도구의 컨텍스트 계층에 적합","es":"ClickHouse es una capa de contexto para productos que requieren análisis de telemetría de alta velocidad. Utiliza el constructor de consultas squirrel para queries dinámicas.","fr":"ClickHouse est une couche de contexte pour les produits qui nécessitent une analyse de télémétrie à haute performance. Il utilise le constructeur de requêtes squirrel pour des requêtes dynamiques.","de":"ClickHouse ist eine Kontextschicht für Produkte, die Hochgeschwindigkeits-Telemetrie-Analysen erfordern. Es verwendet den squirrel-Abfrage-Builder für dynamische Abfragen.","pt":"O ClickHouse é uma camada de contexto para produtos que conecta agentes e chat a servidores MCP de primeira e terceira parte. Ele usa o pacote de telemetria para consultas de análise de alta performance.","ru":"ClickHouse является контекстным слоем для продуктов, который подключает агентов и чат к серверам MCP первого и третьего уровня. Он использует пакет телеметрии для запросов высокопроизводительного анализа.","ar":"ClickHouse هو طبقة سياقية لمنتجات توفر اتصال بالوكلاء وال دردشة مع خادم MCP من المستوى الأول والثالث. يستخدم حزمة التелеметري لاستفسارات تحليل البيانات عالية الأداء."},"seo":{"title":{"en":"ClickHouse: High-Performance Analytics Queries for AI Age...","zh":"ClickHouse_SETUP GUIDE FOR AIエージェント","ja":"ClickHouse AIエージェント用SETUP GUIDE","ko":"ClickHouse_AI 도구 설정 가이드","es":"Guía de configuración de ClickHouse para análisis de tele...","fr":"Guide de configuration de ClickHouse pour l''analyse de té...","de":"ClickHouse-Konfigurationsleitfaden für Telemetrie-Analysen","pt":"Guia de Configuração ClickHouse para Ferramentas de IA","ru":"Руководство по настройке ClickHouse для ИИ Агентов","ar":"دليل إعداد ClickHouse لأدوات الذكاء الاصطناعي"},"description":{"en":"Unlock fast and efficient data analysis with ClickHouse. Learn how to leverage the squirrel query builder for dynamic query construction and discover the ben...","zh":"了解ClickHouse的高性能分析查询和squirrel查询构建器，用于AIエージェント的上下文层","ja":"ClickHouseの高性能分析クエリとsquirrelクエリビルダーを使用したAIエージェントのコンテキストレイヤー","ko":"ClickHouse의 고성능 분석 쿼리와 squirrel 쿼리 빌더를 사용하여 AI 도구의 컨텍스트 계층을 구축하는 방법","es":"Aprende a configurar ClickHouse para análisis de telemetría de alta velocidad y descubre cómo utilizar el constructor de consultas squirrel para queries diná...","fr":"Découvrez comment configurer ClickHouse pour l''analyse de télémétrie à haute performance et utilisez le constructeur de requêtes squirrel pour des requêtes d...","de":"Erfahren Sie, wie Sie ClickHouse für Hochgeschwindigkeits-Telemetrie-Analysen konfigurieren und den squirrel-Abfrage-Builder für dynamische Abfragen verwenden","pt":"Aprenda a configurar o ClickHouse para análise de dados de alta performance em ferramentas de IA. Descubra como usar o squirrel para construir consultas dinâ...","ru":"Узнайте, как настроить ClickHouse для высокопроизводительного анализа данных в ИИ Агентах. Откройте для себя, как использовать squirrel для построения динами...","ar":"تعلم كيفية تكوين ClickHouse لتحليل البيانات عالية الأداء في أدوات الذكاء الاصطناعي. اكتشف كيفية استخدام squirrel لبناء استفسارات ديناميكية."},"definition":{"en":"ClickHouse is a high-performance analytics database management system that utilizes the squirrel query builder for dynamic query construction","zh":"ClickHouse是一种用于高性能分析查询的数据库，使用squirrel查询构建器进行动态查询构建","ja":"ClickHouseは、高性能分析クエリを実行するためのデータベースであり、squirrelクエリビルダーを使用して動的なクエリを構築します","ko":"ClickHouse는 고성능 분석 쿼리를 실행하는 데이터베이스로, squirrel 쿼리 빌더를 사용하여 동적 쿼리를 구성","es":"ClickHouse es un sistema de gestión de bases de datos para análisis de telemetría de alta velocidad","fr":"ClickHouse est un système de gestion de bases de données pour l''analyse de télémétrie à haute performance","de":"ClickHouse ist ein Datenbankmanagementsystem für Hochgeschwindigkeits-Telemetrie-Analysen","pt":"ClickHouse é um sistema de gerenciamento de banco de dados de alta performance para análise de dados.","ru":"ClickHouse — система управления базами данных высокопроизводительного анализа данных.","ar":"ClickHouse هو نظام إدارة قواعد البيانات عالي الأداء لتحليل البيانات."},"features":{"en":["Utilizes the squirrel query builder for dynamic query construction","Supports high-performance analytics queries","Integrates with the server/internal/telemetry package","Enables connections to 1st and 3rd party MCP servers","Does not use SQLc for auto-generated queries","Specifically designed for ClickHouse queries in the telemetry package"],"zh":["高性能分析查询","squirrel查询构建器","动态查询构建","适用于AIエージェント的上下文层","支持高性能数据处理","与SQLc集成"],"ja":["高性能分析クエリ","squirrelクエリビルダー","動的なクエリ構築","AIエージェントのコンテキストレイヤーに最適","高性能データ処理をサポート","SQLcとの統合"],"ko":["고성능 분석 쿼리","squirrel 쿼리 빌더","동적 쿼리 구성","AI 도구의 컨텍스트 계층에 적합","고성능 데이터 처리를 지원","SQLc와의 통합"],"es":["Análisis de telemetría de alta velocidad","Constructor de consultas squirrel para queries dinámicas","Compatibilidad con servidores MCP de primera y tercera parte","Integración con agentes y chat","Soporte para consultas de ClickHouse no auto-generadas por SQLc"],"fr":["Analyse de télémétrie à haute performance","Constructeur de requêtes squirrel pour des requêtes dynamiques","Compatibilité avec les serveurs MCP de première et de troisième partie","Intégration avec les agents et les chat","Prise en charge des requêtes ClickHouse non générées automatiquement par SQLc"],"de":["Hochgeschwindigkeits-Telemetrie-Analysen","squirrel-Abfrage-Builder für dynamische Abfragen","Kompatibilität mit MCP-Servern von ersten und dritten Parteien","Integration mit Agenten und Chat","Unterstützung für nicht automatisch von SQLc generierte ClickHouse-Abfragen"],"pt":["Suporte a consultas de alta performance com o pacote de telemetria","Uso do squirrel para construir consultas dinâmicas","Conexão a servidores MCP de primeira e terceira parte","Análise de dados em tempo real","Integração com ferramentas de IA"],"ru":["Поддержка высокопроизводительных запросов с пакетом телеметрии","Использование squirrel для построения динамических запросов","Подключение к серверам MCP первого и третьего уровня","Анализ данных в режиме реального времени","Интеграция с ИИ Агентами"],"ar":["دعم استفسارات عالية الأداء مع حزمة التелеметري","استخدام squirrel لبناء استفسارات ديناميكية","اتصال بخادم MCP من المستوى الأول والثالث","تحليل البيانات في الوقت الفعلي","التكامل مع أدوات الذكاء الاصطناعي"]},"keywords":{"en":["how to use clickhouse","clickhouse vs postgresql","clickhouse install","clickhouse setup guide","what is clickhouse","clickhouse alternative","clickhouse squirrel query builder","clickhouse high-performance analytics","clickhouse ai agent integration"],"zh":["ClickHouse","AIエージェント","高性能分析查询","squirrel查询构建器","动态查询构建","SQLc","上下文层","数据处理","AI工具"],"ja":["ClickHouse","AIエージェント","高性能分析クエリ","squirrelクエリビルダー","動的なクエリ構築","SQLc","コンテキストレイヤー","データ処理","AIツール"],"ko":["ClickHouse","AI 도구","고성능 분석 쿼리","squirrel 쿼리 빌더","동적 쿼리 구성","SQLc","컨텍스트 계층","데이터 처리","AI 에이전트"],"es":["ClickHouse","análisis de telemetría","constructor de consultas squirrel","servidores MCP","agentes y chat","SQLc","Herramientas de IA para desarrolladores","tecnologías de análisis de datos"],"fr":["ClickHouse","analyse de télémétrie","constructeur de requêtes squirrel","serveurs MCP","agents et chat","SQLc","Outils d''IA pour les développeurs","technologies d''analyse de données"],"de":["ClickHouse","Telemetrie-Analysen","squirrel-Abfrage-Builder","MCP-Server","Agenten und Chat","SQLc","KI-Tools für Entwickler","Datenanalyse-Technologien"],"pt":["ClickHouse","ferramentas de IA","análise de dados","alta performance","squirrel","telemetria","servidores MCP","construir consultas dinâmicas","integração com ferramentas de IA"],"ru":["ClickHouse","ИИ Агенты","анализ данных","высокопроизводительный","squirrel","телеметрия","серверы MCP","построение динамических запросов","интеграция с ИИ Агентами"],"ar":["ClickHouse","أدوات الذكاء الاصطناعي","تحليل البيانات","عالي الأداء","squirrel","التелеметري","خادم MCP","بناء استفسارات ديناميكية","التكامل مع أدوات الذكاء الاصطناعي"]}},"owner":"speakeasy-api","repo":"gram","repoPath":"speakeasy-api/gram","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.338Z","topics":[],"category":"community","skillMd":{"name":"clickhouse","description":"Rules when working with ClickHouse database in Gram for analytics and telemetry features","bodyPreview":"## ClickHouse Queries (Telemetry Package)\n\nThe `server/internal/telemetry` package uses ClickHouse for high-performance analytics queries. Unlike PostgreSQL queries, **ClickHouse queries are NOT auto-generated by SQLc** (SQLc doesn''t support ClickHouse). We use the **squirrel** query builder for dynamic query construction.\n\n> **CRITICAL:** The squirrel query builder is ONLY permitted for ClickHouse queries in the telemetry package. **DO NOT use squirrel for PostgreSQL queries** - all PostgreSQL","body":"## ClickHouse Queries (Telemetry Package)\n\nThe `server/internal/telemetry` package uses ClickHouse for high-performance analytics queries. Unlike PostgreSQL queries, **ClickHouse queries are NOT auto-generated by SQLc** (SQLc doesn''t support ClickHouse). We use the **squirrel** query builder for dynamic query construction.\n\n> **CRITICAL:** The squirrel query builder is ONLY permitted for ClickHouse queries in the telemetry package. **DO NOT use squirrel for PostgreSQL queries** - all PostgreSQL queries MUST use SQLc-generated code. This is the only acceptable exception to our \"no query builders\" policy.\n\n### File Structure\n\n- **`queries.sql.go`**: Query implementations using squirrel\n- **`pagination.go`**: Cursor pagination helpers (`withPagination`, `withOrdering`, etc.)\n- **`README.md`**: Detailed documentation and patterns specific to ClickHouse\n\n### Adding ClickHouse Queries\n\nWhen asked to add a new ClickHouse query to the telemetry package:\n\n1. **Create a params struct** for query inputs\n2. **Build the query using squirrel** (the `sq` var in queries.sql.go is pre-configured for ClickHouse):\n\n   ```go\n   type GetMetricsParams struct {\n       ProjectID    string\n       DeploymentID string  // optional\n       Limit        int\n   }\n\n   func (q *Queries) GetMetrics(ctx context.Context, arg GetMetricsParams) ([]Metric, error) {\n       sb := sq.Select(\"id\", \"value\", \"timestamp\").\n           From(\"metrics\").\n           Where(\"project_id = ?\", arg.ProjectID)\n\n       // Optional filters - explicit conditionals for clarity\n       if arg.DeploymentID != \"\" {\n           sb = sb.Where(squirrel.Eq{\"deployment_id\": arg.DeploymentID})\n       }\n\n       sb = sb.Limit(uint64(arg.Limit))\n\n       query, args, err := sb.ToSql()\n       if err != nil {\n           return nil, fmt.Errorf(\"building query: %w\", err)\n       }\n\n       rows, err := q.conn.Query(ctx, query, args...)\n       // ... handle rows\n   }\n   ```\n\n3. **Use pagination helpers** from `pagination.go`:\n   - `withPagination(sb, cursor, sortOrder)` - cursor pagination\n   - `withOrdering(sb, sortOrder, primaryCol, secondaryCol)` - ORDER BY\n\n### Testing ClickHouse Queries\n\n- Use `testenv.Launch()` in `TestMain` for infrastructure setup\n- Add `time.Sleep(100 * time.Millisecond)` after inserts (ClickHouse eventual consistency)\n- Use table-driven tests with descriptive \"it\" prefix names\n- Create helper functions for test data insertion\n\nSee `server/internal/telemetry/README.md` for comprehensive documentation.\n"},"lastSynced":"2026-03-08T02:03:21.837Z","agentAnalysis":{"suitability":{"en":"Perfect for Data Analysis Agents needing high-performance analytics queries with ClickHouse","zh":"非常适合需要使用ClickHouse进行高性能分析查询的数据分析代理","ja":"ClickHouseを使用した高性能分析クエリが必要なデータ分析エージェントに最適","ko":"클릭하우스를 사용하여 고성능 분석 쿼리가 필요한 데이터 분석 에이전트에 적합","es":"Perfecto para agentes de análisis de datos que necesitan consultas analíticas de alto rendimiento con ClickHouse","fr":"Parfait pour les agents d''analyse de données nécessitant des requêtes d''analyse haute performance avec ClickHouse","de":"Perfekt für Data-Analytics-Agents, die hochleistungsstarke Analyseabfragen mit ClickHouse benötigen","pt":"Perfeito para Agentes de Análise de Dados que necessitam de consultas analíticas de alto desempenho com ClickHouse","ru":"Идеально для агентов анализа данных, требующих высокопроизводительных аналитических запросов с ClickHouse","ar":"مثالي لعمليات تحليل البيانات التي تحتاج إلى استفسارات تحليلية عالية الأداء مع ClickHouse"},"recommendation":{"en":"Empowers agents to construct dynamic queries using the squirrel query builder for high-performance analytics, leveraging ClickHouse''s capabilities for fast data processing and visualization, and enabling connections to 1st and 3rd party MCP servers","zh":"赋予代理构建动态查询的能力，使用松鼠查询构建器实现高性能分析，利用ClickHouse的高速数据处理和可视化能力，并支持连接到1st和3rd方MCP服务器","ja":"エージェントがダイナミッククエリを構築できるようにし、スクウィレルクエリビルダーを使用して高性能分析を実現し、ClickHouseの高速データ処理とビジュアライゼーション能力を利用し、1stおよび3rdパーティMCPサーバーへの接続を可能にします","ko":"에이전트가 동적 쿼리를构築할 수 있도록 하여, 고성능 분석을 위한 스쿼럴 쿼리 빌더를 사용하고, 클릭하우스의 빠른 데이터 처리 및 시각화 능력을 활용하여 1차 및 3차 MCP 서버에 연결할 수 있습니다","es":"Habilita a los agentes a construir consultas dinámicas utilizando el constructor de consultas squirrel para análisis de alto rendimiento, aprovechando las capacidades de ClickHouse para un procesamiento y visualización de datos rápido, y permitiendo conexiones a servidores MCP de primera y tercera parte","fr":"Permet aux agents de construire des requêtes dynamiques en utilisant le constructeur de requêtes squirrel pour une analyse haute performance, en exploitant les capacités de ClickHouse pour un traitement et une visualisation de données rapides, et en permettant des connexions à des serveurs MCP de première et de troisième partie","de":"Ermächtigt Agenten, dynamische Abfragen mithilfe des Squirrel-Abfragebauers für hochleistungsstarke Analysen zu erstellen, die Fähigkeiten von ClickHouse für schnelles Datenverarbeiten und -visualisieren nutzt und Verbindungen zu MCP-Servern von ersten und dritten Parteien ermöglicht","pt":"Habilita os agentes a construir consultas dinâmicas usando o construtor de consultas squirrel para análise de alto desempenho, aproveitando as capacidades do ClickHouse para processamento e visualização de dados rápidos e permitindo conexões com servidores MCP de 1ª e 3ª partes","ru":"Позволяет агентам создавать динамические запросы с помощью инструмента построения запросов squirrel для высокопроизводительного анализа, используя возможности ClickHouse для быстрой обработки и визуализации данных, а также обеспечивая подключение к серверам MCP 1-го и 3-го уровня","ar":"تمكين الوكلاء من بناء استفسارات ديناميكية باستخدام بناء استفسارات سكويрел لتحليل الأداء العالي، و الاستفادة من إمكانيات ClickHouse لمعالجة البيانات والتصوير السريع، وتمكين الاتصالات بخوادرم MCP من الطبقة الأولى والثالثة"},"useCases":{"en":["Constructing dynamic queries for high-performance analytics","Connecting to 1st and 3rd party MCP servers for data analysis","Utilizing squirrel query builder for efficient query construction"],"zh":["构建高性能分析的动态查询","连接到1st和3rd方MCP服务器进行数据分析","利用松鼠查询构建器实现高效的查询构建"],"ja":["高性能分析のためのダイナミッククエリの構築","1stおよび3rdパーティMCPサーバーへの接続を通じたデータ分析","スクウィレルクエリビルダーを使用した効率的なクエリ構築"],"ko":["고성능 분석을 위한 동적 쿼리 구성","1차 및 3차 MCP 서버에 연결하여 데이터 분석","스쿼럴 쿼리 빌더를 사용한 효율적인 쿼리 구성"],"es":["Construir consultas dinámicas para análisis de alto rendimiento","Conectar a servidores MCP de primera y tercera parte para análisis de datos","Utilizar el constructor de consultas squirrel para una construcción de consultas eficiente"],"fr":["Construire des requêtes dynamiques pour une analyse haute performance","Se connecter à des serveurs MCP de première et de troisième partie pour l''analyse de données","Utiliser le constructeur de requêtes squirrel pour une construction de requêtes efficace"],"de":["Dynamische Abfragen für hochleistungsstarke Analysen erstellen","Verbinden mit MCP-Servern von ersten und dritten Parteien für Datenanalyse","Squirrel-Abfragebauer für effiziente Abfrageerstellung nutzen"],"pt":["Construir consultas dinâmicas para análise de alto desempenho","Conectar-se a servidores MCP de 1ª e 3ª partes para análise de dados","Utilizar o construtor de consultas squirrel para construção eficiente de consultas"],"ru":["Создание динамических запросов для высокопроизводительного анализа","Подключение к серверам MCP 1-го и 3-го уровня для анализа данных","Использование инструмента построения запросов squirrel для эффективного построения запросов"],"ar":["بناء استفسارات ديناميكية لتحليل الأداء العالي","التوصيل بالخوادرم MCP من الطبقة الأولى والثالثة لتحليل البيانات","استخدام بناء استفسارات سكويрел لبناء استفسارات فعال"]},"limitations":{"en":["Requires squirrel query builder for ClickHouse queries","Not compatible with SQLc for auto-generating queries","Specifically designed for ClickHouse, not PostgreSQL"],"zh":["需要松鼠查询构建器来执行ClickHouse查询","不兼容SQLc自动生成查询","专门为ClickHouse设计，不支持PostgreSQL"],"ja":["ClickHouseクエリの実行にはスクウィレルクエリビルダーが必要","SQLcによる自動クエリ生成と互換性がありません","ClickHouse専用設計であり、PostgreSQLはサポートされていません"],"ko":["클릭하우스 쿼리를 실행하려면 스쿼럴 쿼리 빌더가 필요","SQLc 자동 쿼리 생성과 호환되지 않음","클릭하우스専用 설계로 PostgreSQL 지원되지 않음"],"es":["Requiere el constructor de consultas squirrel para consultas ClickHouse","No es compatible con SQLc para la generación automática de consultas","Diseñado específicamente para ClickHouse, no para PostgreSQL"],"fr":["Nécessite le constructeur de requêtes squirrel pour les requêtes ClickHouse","N''est pas compatible avec SQLc pour la génération automatique de requêtes","Conçu spécifiquement pour ClickHouse, et non pour PostgreSQL"],"de":["Benötigt den Squirrel-Abfragebauer für ClickHouse-Abfragen","Nicht kompatibel mit SQLc für die automatische Abfragegenerierung","Speziell für ClickHouse und nicht für PostgreSQL konzipiert"],"pt":["Exige o construtor de consultas squirrel para consultas ClickHouse","Não é compatível com SQLc para geração automática de consultas","Projetado especificamente para ClickHouse, não para PostgreSQL"],"ru":["Требует инструмента построения запросов squirrel для запросов ClickHouse","Не совместим с SQLc для автоматической генерации запросов","Разработан специально для ClickHouse, не для PostgreSQL"],"ar":["يتطلب بناء استفسارات سكويрел لاستفسارات ClickHouse","غير متوافق مع SQLc لتوليد الاستفسارات تلقائيًا","تم تصميمه خصيصًا ل ClickHouse، وليس ل PostgreSQL"]},"version":4},"contentHash":"5dd4da9995d77837cbf1564009caa10c80262db2f1fbb3ff0b7bf6caccf9ee89","qualityScore":33}');
